C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
c       -harvest
C&&*&& include  ../inc/mharvest.f
c      INTEGER MCOLS
C     .. Scalars in common block /CHARVEST/ ..
      CHARACTER HVERSION*100,ProjectName*64,Crystalname*64,
     +          DataSetName*64,HBEAMLINE*10,Precipitant*80,
     +          XNAME_COLS(MCOLS+MAXLATT*3)*64,
     +          DNAME_COLS(MCOLS+MAXLATT*3)*64
C     .. Scalars in common block /IHARVEST/ ..
      LOGICAL USECWD,PNAMEgiven,XNAMEgiven,DNAMEgiven,DOHARVEST
      REAL    PHhar,Hartemp,
     +     HARETA(MAXPAX),HARDIV(MAXPAX),HARDIH(MAXPAX)
      CHARACTER*3 MKDIRMODE,CHMODMODE
      INTEGER KHFLMS
C     ..
C     .. Common block /CHARVEST/ ..
      COMMON /CHARVEST/HVERSION,ProjectName,Crystalname,
     +                 DataSetName,HBEAMLINE,Precipitant,
     +                 XNAME_COLS,DNAME_COLS
C     .. Common block /IHARVEST/ ..
      COMMON /IHARVEST/USECWD,PHhar,Hartemp,KHFLMS,
     +                 PNAMEgiven,XNAMEgiven,DNAMEgiven,DOHARVEST,
     +                 HARETA,HARDIV,HARDIH,MKDIRMODE,CHMODMODE
C     ..
C&&*&& end_include  ../inc/mharvest.f
c       -harvest
C       
C       ..
C       .. Equivalences ..

        character*80 dnafile

        EQUIVALENCE (IRAS(1),NXS), (IRAS(2),NYS), (IRAS(3),NCC)
        EQUIVALENCE (IRAS(4),NRX), (IRAS(5),NRY)
C       ..
        SAVE
C       .. Data statements ..
C       
C----   CENTRS refinement is repeated (once) if initial residual ESTART is
C       greater than ELIMIT (set to 8 below). Outer refinement is repeated
C       (once only) if initial residual is greater than ELIMIT2 or if final
C       residual is greater than ELIMIT3
C       For weighted refinement, the limit is WELIMIT for all 3 cases
C       
        DATA ELIMIT/8.0/,ELIMIT2/3.0/,ELIMIT3/1.5/,WELIMIT/2/
        DATA YSCALERR/0.0/,RPTIMG/.FALSE./,BIGSHIFT/.FALSE./
        DATA FIRSTWARN/.TRUE./, reta/0.0/
        DATA PORTNO /0/
        DATA PRFINISH /.FALSE./
        DATA CALLEDFROM / 'MOSFLM' /
        DATA NFOUND /0/
        DATA finishedblock /.FALSE./
C        CALLEDFROM = 'MOSFLM'
        SAVEDDEBUG = .FALSE.
        SAVEDDUMP = .FALSE.
        THIS = 'MOSFLM'
        INDENT = 1
        CALL CTIMER(STARTTIME)
        CALL CTIMER(MOSTIMEB)
        MODECTRL = 0
        CENTRE = .FALSE.
C       
C----   First check to see if the version of CCP4 supports harvesting
C       
        CALL CCP4_VERSION(CCP4VERSION)
        HARVESTREADY = .TRUE.
C        IF(CCP4VERSION.LT.'4.0')HARVESTREADY = .FALSE.
C       
C----   
C       
        CALL CCPFYP
C
        XMLOPEN = .FALSE.
        CALL UGTENV('XMLFILE',XMLFILE)
        IF(XMLFILE .NE. ' ')THEN
          IF(ONLINE)WRITE(ITOUT,fmt=6450)XMLFILE(1:LENSTR(XMLFILE))
 6450     format('The output XML will be stored in a file called ',A)
          PORTNO = -1
          CALL OPEN_FILE(PORTNO,SERVERFD,XMLFILE,LENSTR(XMLFILE))
          SOCKLO = .TRUE.
          XMLOPEN = .TRUE.
          IISCN = .FALSE.
        ELSE
          PORTNO = CCPE2I('MOSFLMSOCKET',PORTNO)
          IF(PORTNO.NE.0)THEN
C     ..
C     .. i.e. we have a socket open
            CALL UGTENV('REMMOSHOST',REMOTEMOSFLMHOST)
            CALL OPEN_SOCKET(REMOTEMOSFLMHOST,portno,SERVERFD)
            SOCKLO = .TRUE.
            IISCN = .FALSE.

c     WRITE(LONGLINE,FMT=7200)
c     7200     FORMAT('<Mosflm version 7.0.4 3rd March 2008>')
c     CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(LONGLINE),LONGLINE)
          ELSE
            SOCKLO = .FALSE.
          ENDIF
        ENDIF
C
C---- new call to initialize everything
C
        INIT_MODE = 0
C
C---- Print for program flow
C
        CALLED = 'INITIALISE'
        COMMENT = ' '
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
        CALL INITIALIZE(INIT_MODE,GENOPEN,NEWGENF)
        CALL VERSION(IMGP)
        CALL MHARVEST(0)
c     DNA
        call ugtenv('DNA', dnafile)
C     .. some compilers don't like zero length strings indicated by ''
        if(LENSTR(dnafile) .GT. 0) then
           open(file = dnafile, unit = dnafd, status = 'unknown')
           dnaout = .true.
           call dna_start_output('mosflm')
        else
           dnaout = .false.
        end if
C
C----   items which are declared locally in mosflm.f
C
        FIXPARTLS = .FALSE.
        PROCESSA = .FALSE.
        LAST = .FALSE.
        FORCEREAD = .FALSE.
        COORDOPN = .FALSE.
C
C---- g77 compiler wants these initialized - anything _not_ zero 
C     here has already been tried and it seems to make no difference to
C     running the program.
C
        NSINGRPT = 0!1
        NIMAGSV = 0!1
        MINREFS =  0!1
        IROFF = 0
        ITOFF = 0
        NPACKSAVE =  0!1
        CCOMLAST = 0
        ROFFLAST = 0
        PHIXLAST = 0 
        PHIYLAST = 0 
        PHIZLAST = 0 
        CCOMSAVE = 0
        TOFFLAST = 0
        RFP = 0
        NRSOLD =  0!1
C
C---- end of g77 objections - some more initializations
C
        ierr = 0
        istat = 0
        resid = 0.0
C
C---- end of initializations
C
        LDUM = 80
c     initialise this to prevent mosflm from core dumping due to the 
c     fact that this is not initialised - this is most likely a fault 
c     in another variable, but let's do this anyway.
        nfilms = 0
C       
C----   NFLMO is number of films written to MOSFLM.OUT.
C       This is only greater than one when accumulating
C       profiles from A films.
C       
        NFLMO = 1
        ABC = 'ABC'
C
          FIRSTTIME = .TRUE.
          RPTFIRST = .FALSE.
C       
C----   ISEG keeps track of how many times CONTROL has been called, used
C       in multisegment postrefinement
C       
        ISEG = 0
        NREPEAT = 0
C       
C----   Read control information (keyworded) up to next "RUN" card
C       
C       ******************************************************
 30     CONTINUE
C
C---- These initialisations have been moved from just above label 30
C     because they need to be reset for a new processing run.
C     AGWL 9/1/14
C
        DO 20 J = 1,3
          DO 10 I = 1,MAXPAX
            IF (J.EQ.1) THEN
              PRFRPT1(I) = .FALSE.
              PRFRPT2(I) = .FALSE.
              PRFHS(I) = .FALSE.
              PRF(I) = .FALSE.
              PRNEGM(I) = .FALSE.
            END IF
            BADPACK(I,J) = .FALSE.
 10       CONTINUE
 20     CONTINUE   

C
C---- Print for program flow
C
        CALLED = 'CONTROL'
        COMMENT = ' '
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        

        CALL CONTROL(FIRSTTIME,IFIRSTPACK,NEWGENF,GENOPEN,RPTFIRST,
     +       CELLSTR,MODECTRL)
C       ******************************************************
C
C
C----   If only starting debug output after a specified image, save current values
C       for debug and then set all to FALSE.
C
        IF (DEBUG(108).AND.(.NOT.SAVEDDEBUG)) THEN
          SAVEDDEBUG = .TRUE.
          DO 21 I = 1,200
            SAVEDEBUG(I) = DEBUG(I)
            IF (I.NE.108) DEBUG(I) = .FALSE.
 21       CONTINUE
        END IF

C
C----   If only starting debug output after a specified image, save current values
C       for debug and then set all to FALSE.
C
        IF (DUMP(12).AND.(.NOT.SAVEDDUMP)) THEN
          SAVEDDUMP = .TRUE.
          DO 22 I = 1,30
          if (dump(i)) write(iout,fmt=9873) i
          if (online.and.(dump(i))) write(itout,fmt=9873) i
 9873     format(1x,'transfer dump to savedump, true for i=',i3)
            SAVEDUMP(I) = DUMP(I)
            IF (I.NE.12) DUMP(I) = .FALSE.
 22      CONTINUE
        END IF


C
C----   If doing data collection strategy, do it now
C       
        FIRSTWARN = .TRUE.
        FIRSTREF = .TRUE.
        DONEREF = .FALSE.
        NULLPIXTEST = .FALSE.
C
Chrp 15022002
C----   If FIRSTTIME is .TRUE., then ISEG should = 0. This is necessary 
C       for automated jobs run through the Mosflm server, and should be 
C       true anyway.
C
        IF(FIRSTTIME)ISEG = 0
C
C----   If using the new GUI and this is an integration run (not cell 
C       refinement), we need ISEG =0 or else it will not set up
C       NVIRBAT (and NADDMISSET) correctly. At present, for example,
C       ISEG gets incremented every time a prediction is done from
C       the new gui.
        IF (SOCKLO.AND.(.NOT.MULTISEG).AND.(.NOT.STRATEGY)
     +            .AND.(.NOT.TESTGEN)) ISEG = 0
c
c---- Because new gui is invoked by an image keyword, it comes to this point
c     with ISEG=1 instead of zero.
c     (and this was breaking things)
        
chrp 16.04.2007        if(gui_switch) then

 3332      format('Warning - resetting the iseg value to zero',
     +          ' because gui_switch = .true.')

chrp 16.04.2007            if(online) then
chrp 16.04.2007               write(itout, 3332)
chrp 16.04.2007            end if
chrp 16.04.2007            write(iout, 3332)
chrp 16.04.2007            iseg = 0
chrp 16.04.2007         end if
 34     IF (STRATEGY) THEN
           XCEN = 100.0*XCENMM(1,1)
           YCEN = 100.0*YCENMM(1,1)
           SETA = ETA
           SDIVH = DIVH
           SDIVV = DIVV
          SDELCOR = DELCOR
          SDELAMB = DELAMB
          SBLKSIZE = BLKSIZE
C
C---- Print for program flow
C
          CALLED = 'ROTATE'
          COMMENT = ' '
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
          CALL ROTATE
C       
C----   If STRATEGY has more than one run, then ICELL is set to 1.
C       Reset it to zero now so cell is not fixed.
C       
          ICELL = 0
          ETA = SETA
          DIVH = SDIVH
          DIVV = SDIVV
          DELCOR = SDELCOR
          DELAMB = SDELAMB
          BLKSIZE = SBLKSIZE
          FIRSTTIME = .FALSE.
C       
C----   If window display active, return there providing all runs have been
C       generated
C       
          IF (ISTRUN+1.LT.NSTRUN) GOTO 30
          IF (DISPMENU .or. newgui) THEN
            ADDPART = .FALSE.
            SUMPART = .FALSE.
            POWDER = .TRUE.
            STRATEGY = .FALSE.
            FORCEREAD = .TRUE.
            NRUN = 1
C       
C----   Need to set ISEG to zero in case a multiseg refinement run is done
C       
            ISEG = 0
            NIMAG = NIMAGSV
C
C----  If using new gui, have finished strategy now so return to CONTROL.
C
            IF (SOCKLO) GOTO 30            
            GOTO 36
          END IF
          GOTO 30
        END IF
C       
C----   TESTGEN option
C       
        IF (TESTGEN) THEN
C       
          XCEN = 100.0*XCENMM(1,1)
          YCEN = 100.0*YCENMM(1,1)
C
C---- Print for program flow
C
          CALLED = 'TESTOVER'
          COMMENT = ' '
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
C       ********
          CALL TESTOVER
C       ********
          FIRSTTIME = .FALSE.
C       
          TESTGEN = .FALSE.
          GOTO 30
        END IF
C       
C----   Open coordinate file if DENSE image
C       
C       *******************************************************
 36     IF (DENSE) THEN
          IF (COORDOPN) CLOSE(ICOORD)
          CALL CCPDPN(-ICOORD,'COORDS','UNKNOWN','U',0,IFAIL)
          COORDOPN = .TRUE.
        END IF
C       *******************************************************
C       
        ISEG = ISEG + 1
        RPTFIRST = .FALSE.
        DONEONCE = .FALSE.
        CENTRSRPT = .FALSE.
        IRPTPACK = -999
C       
C----   If doing multi-segment post-refinement, set NBLOCK to NADD, and
C       set SUMPART to TRUE as it will have been set FALSE for the last image
C       of the preceeding segment (for second etc segments) in code below.
C       However, if only one segment, set NBLOCK = NADD + 1
C       
 6232   CONTINUE
c       if(online)write(itout,6233)ifirstpack,npack,nblock,naddp
c       write(iout,6233)ifirstpack,npack,nblock,naddp
c       6233 format(/,'Ifirstpack = ',i4,', Npack = ',i4,' Nblock = ',
c       $     I4,' Naddp = ',I4/)
        IF (MULTISEG) THEN
C
C---- Write XML for the "activity" display line in imosflm
C
C
C---- Print for program flow
C  
          CALLED = 'WRITE_SOCKET'
          COMMENT = '*** write XML for cell refinement activity ***'
          IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          IF ((SOCKLO).AND.(ISEG.EQ.1)) THEN
            WRITE(LONGLINE,FMT=6600) NREPEAT+1
 6600       FORMAT('<?xml version="1.0"?>',
     $          '<!DOCTYPE cell_refine_response>',
     $          '<cell_refine_response>','<status>',
     +          '<code>ok</code>',
     +          '</status>','<message>',
     +          'Cell refinement cycle',I2,'</message>',
     $          '</cell_refine_response>')
            CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $          LENSTR(LONGLINE),LONGLINE)
          END IF
          IF (NSEG.GT.1) THEN
            NBLOCK = NADD
          ELSE
            NBLOCK = NADD + 1
          END IF
          IF (.NOT.NEWPREF) SUMPART = .TRUE.
          IF (ISEG.EQ.1) THEN
            DO I = 1,NIMAX
              VALSET(I) = .FALSE.
            ENDDO
          END IF
        END IF
C       
C----   Set up partial summation flag for all packs. Note that this
C       may be changed for an individual pack on calling OPENODS if
C       the required following image does not exit
C       
C       Note that IFIRSTPACK is an image counter, NOT the serial number of the
C       image. Thus it starts at 1 and runs to NPACK/NPACKSAVE
C       
        DO 32 IPACK = IFIRSTPACK,NPACK
          SUMP(IPACK) = SUMPART
          ADDP(IPACK) = ADDPART
 32     CONTINUE
C       
C----   Number of the current block of images
C       
        NUMBLOCK = 0
        IF (NBLOCK.EQ.0) NUMBLOCK = 1
        IF (NBLOCK.NE.0) FIRSTPASS = .FALSE.
        EXTRAIMG  = .FALSE.
C       
C----   IFIRSTP is used as a flag controlling initialisation done in call to
C       POSTREFL and IFIRSTPSEG is used in NEWPREF SINGLE mode to decide if we
C       need to do post-refinement on this image and also go back to the very
C       first image or not
C       
        IF (FIRSTTIME.OR.(.NOT.MULTISEG)) IFIRSTP = IFIRSTPACK
        IFIRSTPSEG = IFIRSTP
        IF (NEWPREF.AND.MULTISEG) IFIRSTPSEG = IFIRSTPACK
        NWRN = 0
        IF (.NOT.MULTISEG) NREPEAT = 0
        PRFIRST = .TRUE.
        ROFFMAX = 0.0
        TOFFMAX = 0.0
        CCOMAX = 0.0
        WRMAX = 0.0
        DELPHIMAX = 0.0
        DELPHIDIFFMAX = 0.0
        NBADMAX = 0
        YSCALERR = 0.0
        IF (DEBUG(1)) THEN
          WRITE(IOUT,FMT=6001) FIRSTTIME,MULTISEG,FIRSTPASS,
     +         SECONDPASS,SUMPART,ADDPART, NEWPREF,POSTREF,
     +         POWDER,IFIRSTPACK,NPACK,NBLOCK,ISEG,NADD,NREPEAT,
     +        IFIRSTP,IFIRSTPSEG,NIMAG
          IF (ONLINE) WRITE(ITOUT,FMT=6001) FIRSTTIME,MULTISEG,
     +         FIRSTPASS,SECONDPASS,SUMPART,ADDPART, NEWPREF,POSTREF,
     +         POWDER,IFIRSTPACK,NPACK,NBLOCK,ISEG,NADD,NREPEAT,
     +        IFIRSTP,IFIRSTPSEG,NIMAG
 6001     FORMAT(//,1X,'In MAIN after calling CONTROL',/,1X,
     $         'FIRSTTIME ',L2,' MULTISEG',L2,' FIRSTPASS',L2,
     +         ' SECONDPASS',L2,' SUMPART',L2,' ADDPART',L2,
     +         ' NEWPREF',L2,' POSTREF',L2,' POWDER',L2,/,1X,
     +         'IFIRSTPACK',I4,'  NPACK',I4,'  NBLOCK',I3,
     +         '  ISEG=',I2,'  NADD=',I2,'  NREPEAT=',I3,/,1X,
     +         'IFIRSTP=',I3,'  IFIRSTPSEG=',I3,
     +         '  NIMAG',I3)
        END IF
C       
C----   Initialisation flags for FINDPACK, OPENODS, storing cell.
        MODEOP = 1
        STORCELL = .FALSE.
C       
C---    Initialize big array for multi-image post-refinement
C
        INTDUM(1) = 0
        INTDUM(2) = 0
        IF(NEWPREF)THEN
          IF (DEBUG(1)) THEN
            WRITE(IOUT,FMT=6566)
            IF (ONLINE) WRITE(ITOUT,FMT=6566)
 6566       FORMAT(/,1X,'In MAIN, calling MODARRAY to initialise')
          END IF
C
C---- Print for program flow
C
          CALLED = 'MODARRAY'
          COMMENT = 'Initialising'
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
          CALL MODARRAY(0, 0.0, 0, 0, INTDUM, INTDUM)
        END IF
C       
C---    If POWDER option, display image etc now
C       
        IF (POWDER) THEN
C       
C----   Always display the image given on IMAGE keyword at MOSFLM prompt
C       even if other images have been read in subsequently in MXDSPL
C       
C       AL        NIMAG = IRSTRT
C       AL        ID = NOIMG(IRSTRT)
C       
C----   In case this is restart after an aborted run, need to reassign
C       PHIBEG, PHIEND. Note that the menu is only put up again after an
C       "Abort" if the IMAGE keyword was used when starting the program
C       (which sets DISPMENU true).
C       
C       AL        PHIBEG = PHISTIM(IRSTRT)
C       AL        PHIEND = PHIBEG + 2.0*(PHI(IRSTRT) - PHIBEG)
          NIMAG = 1
          ID = RESTID
          PHIBEG = RESTPHIB
          PHIEND = RESTPHIE

C was for chunking, changed method           PHIEND = PHIBEG + (CHUNK * (RESTPHIE - RESTPHIB))
          IDENT = RESTIDENT
          WAXFN = IDENT
          IF (TEMPLATE) THEN
            TEMPLSTART = RTEMPLSTART
            TEMPLEND = RTEMPLEND
            NTDIG = RNTDIG
          END IF
C       ********************************************************
C----   OPENODS called in POWDER mode
C     
        sforceread = forceread
        forceread = (forceread.or.reallyforceread)
C
C---- Print for program flow
C
          CALLED = 'OPENODS'
          WRITE(STR,"(I3)") MODEOP
          COMMENT = 'in POWDER mode, LIPROCESS=5 MODE='//STR
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
          LIPROCESS = 5
C
C---- Note use of INVXFORCEREAD here which is set by a keyword sent by iMosflm
C     when changing the INVERTX value via the Experiment settings in iMosflm GUI
C     It is initially set FALSE in CONTROL and only set TRUE if the keyword FORCEREAD
C     is included in commands from iMosflm
C        
          CALL OPENODS(WAXFN,ID,FILM,ODEXT,FDISK,MODEOP,
     +         PACK,ODFILE,SEPCHAR,INVXFORCEREAD,NIMAG,
     +         TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
C---- For Pilatus detectors, need to check what value has been assigned to
C     pixles in the gaps between tiles. This should be -1, but this value is
C     assigned by the beamline software and in some cases it has been assigned
C     a value of zero (eg Campinas 2M, Pilatus 1M for lab testing). agwl 12/4/16
C     Note that NULLPIXTEST is reset FALSE after every call to CONTROL, so
C     NULLPIX will be reset (if necessary) for every task
C     (cell refinement, integration) because iMosflm will always be
C     sending a value of -1
C
          IF (DEBUG(99)) THEN
             WRITE(IOUT,FMT=9876)
             IF (ONLINE) WRITE(ITOUT,FMT=9876)
 9876        FORMAT(1X,'RETURNED FROM CALL TO OPENODS')
             WRITE(IOUT,FMT=9877) (IMAGE(I),I=1,30)
             IF (ONLINE) WRITE(ITOUT,FMT=9877) (IMAGE(I),I=1,30)
 9877        FORMAT(1X,'First 30 values in IMAGE in MOSFLM',/,(1x,10i8))
          END IF

          IF (((MACHINE.EQ.'PILA').OR.(MACHINE.EQ.'EIGE')).AND.
     +         (.NOT.NULLPIXTEST).AND.(.NOT.KEEPNULLPIX)) THEN
C
C     For Pilatus, first gap between tiles extends from X=195-211, so
C     calculate index of a pixel half way along the middle stripe of the
C     gap, for Eiger gaps if from X=514 to 550 
C
              IF (MACHINE.EQ.'PILA') THEN
                I = 203*IYLEN + IYLEN/2
              ELSE IF (MACHINE.EQ.'EIGE') THEN
                I = 532*IYLEN + IYLEN/2
              END IF
              K = INTPXL(IMAGE(I))
              IF (K.NE.NULLPIX) THEN
                WRITE(IOUT,FMT=6477) I,K,NULLPIX
                IF (ONLINE) WRITE(ITOUT,FMT=6477) I,K,NULLPIX
 6477           FORMAT(/,/,1X,'***** WARNING *****',/,1X,
     +            'Pixel value',
     +            ' in the gap between the tiles (element',I8,') is',
     +            I5,' but NULLPIX is',I5,/,1X,'Reflections in which'
     +            ' two adjacent rows or columns at any of the edges',
     +            /,1X,'of the measurement box have zero values will ',
     +            'be treated as "edge" reflections',/,1X,'which ',
     +            'should then be integrated correctly')
C
C---- No longer reassign NULLPIX, this will be done in PROCESS on a reflection
C     by reflection basis
CAL                NULLPIX = K
CAL                IINULL = .TRUE.
                WRONGGAPVALUE = .TRUE.

C
C---- Attempted to send the updated NULLPIX value to iMosflm, but
C     this simply does not work.
C
                LONGLINE = ' '
                WRITE(LONGLINE,FMT=6479) MACHINE,MODEL,NULLPIX,
     $                XODFILE(1:LENSTR(XODFILE)),
     $                TEMPLSAV(1:lenstr(templsav)),ID
 6479           FORMAT('<?xml version=''1.0''?>',
     $         '<!DOCTYPE header_response>',
     $         '<header_response><status><code>ok</code>',
     $         '</status>',
     $         '<detector_manufacturer>',A,'</detector_manufacturer>',
     $         '<detector_model>',A,'</detector_model>',
     $         '<null_pixel_value>',I9,
     $         '</null_pixel_value>',
     $         '<image_filename>',A,'</image_filename>',
     $         '<image_template>',A,'</image_template>',
     $         '<image_number>',I8,'</image_number>',
     $         '</header_response>')
C
C---- Print for program flow
C  
CAL                CALLED = 'WRITE_SOCKET_LENGTH'
CAL                COMMENT = 'write XML header response for new NULLPIX'
CAL                IF (DEBUG(99)) 
CAL     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
CAL                CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(LONGLINE),
CAL     $            LONGLINE)
              END IF
              NULLPIXTEST = .TRUE.
           END IF

        forceread = sforceread
        reallyforceread = .false.
C       *******************************************************
C       
C----   If this is a DIP2, this is the first time the image has been read
C       
C       
C----   If file does not exist, return to CONTROL
C       
          IF (IERR.NE.0)GOTO 30
C
C---- xml to GUI, this is a break between blocks.
C
        IF(SOCKLO.AND.finishedblock)THEN
C
C---- Print for program flow
C  
          CALLED = 'WRITE_SOCKET'
          COMMENT = 'write XML block integrate end (1)'
          IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)

 6446     FORMAT('<?xml version="1.0"?>',
     $          '<!DOCTYPE block_integrate_end SYSTEM "">',
     $          '<block_integrate_end>',
     $          '<status>',
     $          '<code>ok</code>',
     $          '</status>',
     $          '</block_integrate_end>')
           WRITE(LONGLINE,FMT=6446)
           CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $          LENSTR(LONGLINE),LONGLINE)
           finishedblock = .false.
        ENDIF

c
c---- calculate average, rms of this image
c
           CALL DSPSCL(ID,IMAGE,NREC,IYLEN)
           IF(NXDPX.LT.1)NXDPX = NREC
           IF(NYDPX.LT.1)NYDPX = IYLEN
C       
C----   Assign PHIBEG, PHIEND if these are being read from header
C       
          IF ((ISTRT.EQ.0).OR.(IANGLE.EQ.0)) THEN
C     .. HRP 22.03.2004 - DIPS don't seem to have their tail records
C     .. read properly following refinement

            IF((MACHINE.EQ.'DIP2').AND.((ABS(RESTPHIB).GT.1E-3)
     $           .OR.(ABS(RESTPHIE).GT.1E-3)))THEN
              PHIBEG = RESTPHIB
              PHIEND = RESTPHIE
            ELSE
              PHIBEG = HPHIS
C HRP 08.05.2018 for fine phi-sliced eiger
              PHIEND = HPHIE

C was for chunking, changed method               PHIEND = PHIBEG + (CHUNK * (HPHIE - HPHIS))
              RESTPHIB = PHIBEG
              RESTPHIE = PHIEND
            ENDIF
          END IF   
          XCEN = 100.0*XCENMM(1,1) + CCX
          YCEN = 100.0*YCENMM(1,1) + CCY
c          write(iout,fmt=9876) xcen
c          if (online) write(itout,fmt=9876) xcen
c 9876     format(1x,'xcen set in mosflm from xcenmm, now;',F8.2)
          IF (NGR.EQ.7) THEN
C       AL          MODEDISP = 4
C       
C----   Mosaicity estimation immediately prior to starting MXDisplay
C       
C            IF(MOSEST)CALL ESTMOS(NIMAG)


            MODEDISP = 0
C
C---- Print for program flow
C
            CALLED = 'XDISP'
           COMMENT = ' '
            IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
            CALL XDISP(MODEDISP,FIRSTPACK,PACK,IFIRSTPACK,FIRSTFILM,
     +           GENOPEN)
C       
C----   Trap call to integrate images or postref segment
C       
            IF ((MODEDISP.EQ.9).OR.(MODEDISP.EQ.10)) THEN
C       
C----   For post-refinement, set up first image number, as it will not
C       be set below and FIRSTTIME will not necessarily be true
C       
CAL              IF (MODEDISP.EQ.10) IFIRSTP = IFIRSTPACK
              IFIRSTP = IFIRSTPACK
C
C---- Also need to assign IFIRSTPSEG if NOT doing MULTISEG (in which case
C     it is assigned below). Otherwise it will still be set to the value
C    for a previous run (which might be a multiseg post-ref) al 13/1/03
C
              IF (.NOT.MULTISEG) IFIRSTPSEG = IFIRSTP
              POWDER = .FALSE.
              MODEDISP = 0
C       
C----   Need to set up SUMP,ADDP again when integrating via MXDSPL
C       
              DO 37 IPACK = IFIRSTPACK,NPACK
                SUMP(IPACK) = SUMPART
                ADDP(IPACK) = ADDPART
 37           CONTINUE
C       
C----   Open coordinate file if DENSE image
C       
C       *******************************************************
              IF (DENSE.AND.(.NOT.COORDOPN)) 
     +             CALL CCPDPN(-ICOORD,'COORDS','UNKNOWN','U',0,
     +             IFAIL)
C       *******************************************************
              GOTO 31
C       
C----   Trap call to STRATEGY option from window
C       
            ELSE IF (MODEDISP.EQ.20) THEN
              MODECTRL = 10
c
c---- -O2 optimization on DEC Alpha cunningly omits the previous line
C     unless we access the variable...
c
              WRITE(LINE,FMT='(I3)') MODECTRL
              FIRSTTIME = .FALSE.
C       
C----   Set NRUN to zero so that if multiple runs are being used in STRATEGY
C       it will count them correctly
C       
              NRUN = 0
C       
C----   Save the current value of NIMAG as it is set to zero in CONTROL
C       
              NIMAGSV = NIMAG
              GOTO 30
            ELSE IF (MODEDISP.EQ.99) THEN
C
C---- Print for program flow
C
              CALLED = 'MRESET'
              COMMENT = ' '
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
              CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,PRFSUMI)
              IF (DISPMENU) THEN
                GOTO 34
              ELSE
                GOTO 30
              END IF
            END IF
          END IF
          FIRSTTIME = .FALSE.
          GOTO 30 
        END IF
C       
C****** CALL START taken from here
C       
C       
C----   Store initial missettings
C       
 31     DO 33 I = 1,3
          SDELPHI(I) = DELPHI(I)
 33     CONTINUE
C       
C       
C       
C       
C----   Save camera constants etc input by keywords to reinitialise
C       these variables for each new pack. Note that this is NOT done for
C       IP data, where the values should not change from image so the 
C       refined values are better than the input ones.
C       
        SAVECCX = CCX
        SAVECCY = CCY
        SAVECCOM = CCOM
        SXTOFRA = XTOFRA
        SYSCAL = YSCAL
        STILT = TILT
        STWIST = TWIST
        SROFF = ROFF
        SBULGE = BULGE
        SBULGE2 = BULGE2
        STOFF = TOFF
C       
C----   Store input beam parameters, note these are now half-widths in radians
C       (Converted in call to START from CONTROL)
C       
        SETA = ETA
        SDIVH = DIVH
        SDIVV = DIVV
C       
        FIRSTTIME = .FALSE.
C       
C       
C       
C----   Initialise jpack, keeps track of packs in generate file
C       
        JPACK = 0
C       
C----   if using profile fitting, open the "SPOTS" file SPOTOD.OUT
C       but ONLY if NBLOCK.EQ.0, otherwise it is done below.
C       
        IF (PROFILE.AND.(NBLOCK.EQ.0)) THEN
          IF (PROCES) THEN             
            IFAIL = 1
C       
C       **********************************
            IF(.NOT.MULTISEG)THEN
              IF(NUSPOT)THEN
                IF(.NOT.INMOOPEN) THEN
C
C---- Print for program flow
C
                  CALLED = 'QOPEN'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
                  CALL QOPEN(INMO,'SPOTOD','SCRATCH')
                END IF
                INMOOPEN = .TRUE.
              ELSE
                CALL CCPDPN(-INMO,'SPOTOD','SCRATCH','U',0,IFAIL)
              ENDIF
            ENDIF
C       **********************************
C       
            SECONDPASS = .TRUE.
            FIRSTPASS = .FALSE.
            PROCESSA = .TRUE.
            NFLMO = NPACK - IFIRSTPACK + 1
            NOTREAD = .TRUE.
          ELSE
            IFAIL = 1
C       
C       **********************************
c           CALL CCPDPN(-INMO,'SPOTOD','UNKNOWN','U',80,IFAIL)
            IF(.NOT.MULTISEG)THEN
              IF(NUSPOT)THEN
                IF(.NOT.INMOOPEN) THEN
C
C---- Print for program flow
C
                  CALLED = 'QOPEN'
                  COMMENT = ' '
                  IF (DEBUG(99))
     +                CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
                  CALL QOPEN(INMO,'SPOTOD','SCRATCH')
                END IF
                INMOOPEN = .TRUE.
              ELSE
                CALL CCPDPN(-INMO,'SPOTOD','SCRATCH','U',80,IFAIL)
              ENDIF
            ENDIF
C       **********************************
C       
          END IF
        END IF
C       
C----   Loop over packs to be processed from this generate file in
C       this "run"
C       
        IF (MULTISEG) THEN
          IF ((ISEG.EQ.1).AND.(NREPEAT.EQ.0)) NFILMS = 0
          IF (NREPEAT.EQ.0) THEN
            DO 29 I = 1,6
              OLDCELL(I) = CELL(I)
 29         CONTINUE
          END IF
        ELSE
          NFILMS = 0
        END IF
        AVBGRMAX = 0.0
        AVBGRMIN = 10000.0
        ROFFSAVE = -999.0
        TOFFSAVE = -999.0
        NOWRITE = 0
        NFRPT = 0
        NIMGSM = 0
        RESETETA = .FALSE.
        RESETSEP = .FALSE.
C       
C----   Flag for whether profiles have been read in yet
C       
        NOTREAD = .TRUE.
        IFIRSTGOOD = IFIRSTPACK
C       
C----   If processing a large number
C       of packs in a single run, it may be advantageous to accumulate
C       profiles over a block of images rather than all of them (because
C       the profiles may well change on rotating the crystal). This is done
C       using the BLOCK subkeyword on the PROCESS keyword line
C       
        IF (NBLOCK.NE.0) THEN
          IFIRSTPACK = IFIRSTPACK - NBLOCK
          NPACKSAVE = NPACK
          NPACK = 0
        END IF
C
C---- Starting an integration or cell refinement task, send XML to iMosflm
C
        IF (SOCKLO) THEN
C
C---- Print for program flow
C  
          CALLED = 'WRITE_SOCKET'
          COMMENT = 'write XML for processing task begin'
          IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)

C
C---- Start cell refinement or integration task
C       
          WRITE(LONGLINE,FMT=6630)
 6630     FORMAT('<?xml version="1.0"?>',
     +    '<!DOCTYPE processing_task_begin>',
     +    '<processing_task_begin><status><code>ok</code>',
     +    '</status></processing_task_begin>')
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(LONGLINE),LONGLINE) 
        END IF
C
C
 35     CONTINUE
C
C---- Print for program flow
C
        CALLED = ' '
        COMMENT = '*** New block of images ***'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        IF (NBLOCK.NE.0) THEN
          NUMBLOCK = NUMBLOCK + 1
          IFIRSTPACK = IFIRSTPACK + NBLOCK
          NPACK = IFIRSTPACK + NBLOCK - 1
C       
C----   If ADDPART generate one image beyond that being processed so that
C       spatially overlapped partials can be detected. Only generation of
C       the reflection list will be done for this additional image.
C       Note this is NOT necessary when using NEWPREF post-refinement.
C----   Can't get this to work when reading profiles without further effort,
C       leave it for now
C       
          IF (ADDPART.AND.(.NOT.PRREAD).AND.(.NOT.NEWPREF)) THEN
            NPACK = NPACK + 1
            EXTRAIMG = .TRUE.
          END IF
C       
          IF (NPACK.GT.NPACKSAVE) THEN
            NPACK = NPACKSAVE
            EXTRAIMG = .FALSE.
          END IF
          IFIRSTGOOD = IFIRSTPACK
C
C-----  To get PRREAD option to work again, comment out the line below
C       and add the second one, so that FIRSTPASS is always set TRUE.
C       Then add following line so that ACCUMULATE is also TRUE (it is
C       set FALSE in CONTROL if PRREAD is TRUE). If this is not done
C       then it does not transition from FIRSTPASS to SECONDPASS as it 
C       should and the MTZ file is not written. AGWL 26/10/2017
C
CAL          IF (.NOT.PRREAD) FIRSTPASS = .TRUE.
          FIRSTPASS = .TRUE.
          IF (PRREAD) ACCUMULATE = .TRUE.
C
C-----  End of changes to get PRREAD to work
C
          IF (MULTISEG) THEN
            IF ((ISEG.EQ.1).AND.(NREPEAT.EQ.0)) NFILMS = 0
          ELSE
            NFILMS = 0
          END IF

          IF (DEBUG(1)) THEN
            WRITE(IOUT,FMT=6420) NFILMS
            IF (ONLINE) WRITE(ITOUT,FMT=6420) NFILMS
 6420       FORMAT(1X,'NFILMS initialised (or not), now',I3)
          END IF
          AVBGRMAX = 0.0        
          AVBGRMIN = 10000.0
          IFAIL = 1
          NOWRITE = 0
          NOTREAD = .TRUE.
          IF (NREPEAT.EQ.0) WRITE(ISUMMR,FMT=6007)
 6007     FORMAT(/,/)
C       
C       **********************************
C---- When doing a phi profile run, we do not write anything to the SPOTOD file
C     so do not call QOPEN.
C
          IF ((NREPEAT.EQ.0).AND.(.NOT.PHIPROF)) THEN 
            IF(.NOT.MULTISEG)THEN
              IF(NUSPOT)THEN
                IF (.NOT.INMOOPEN) THEN
C
C---- Print for program flow
C
                  CALLED = 'QOPEN'
                  COMMENT = 'Open SPOTOD file '
                  IF (DEBUG(99))
     +                CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
                  CALL QOPEN(INMO,'SPOTOD','SCRATCH')
                END IF
                INMOOPEN = .TRUE.
              ELSE
                CALL CCPDPN(-INMO,'SPOTOD','SCRATCH','U',80,IFAIL)
              ENDIF
            ENDIF
          ENDIF
c     +         CALL CCPDPN(-INMO,'SPOTOD','UNKNOWN','U',80,IFAIL)
C       **********************************
        END IF
C       
C----   Write header to summary file (don't repeat this if repeating
C       processing of first NADD images after post-refinement)
C       
        IF (NREPEAT.EQ.0) THEN
          IF (IMGP) THEN
            IF (.NOT.USEOVRLD) WRITE(ISUMMR,FMT=6096)
 6096       FORMAT(1X,'*** WARNING *** No attempt will be made to',
     +           ' measure overloaded reflections',/,1X,'Use keywo',
     +           'rds PROFILE OVERLOAD to estimate overloads by p',
     +           'rofile fitting')
            WRITE (ISUMMR,FMT=6005) WAVE/DSTMAX
          ELSE
            WRITE (ISUMMR,FMT=6004) WAVE/DSTMAX
          END IF
C       
C----   Film summary heading
C       
 6004     FORMAT(1X,'PACK   CCX   CCY  CCOM  DIST YSCALE TILT TWIST',
     +         ' BULGE RESID  WRESID  FULL  PART OVRL  NEG BAD',
     +         '  I/SIGI   I/SIGI',/,102X,'overall (at',F4.1,'A)')
C       
C----   Image plate summary heading
C       
 6005     FORMAT(1X,'IMAGE    CCX    CCY    CCOM   DIST YSCALE  TILT ',
     +         'TWIST   ROFF   TOFF  RESID  WRESID    FULL   PART   ',
     +         'OVRL  NEG  BAD  I/SIGI  I/SIGI   Rsym  Nsym SDRAT',/,
     $         109X,'overall (at',F4.1,'A)')
        ENDIF
C       
C       
C*****************************************************************************
C       
C----   LOOP OVER PACKS
C       
C*****************************************************************************
 40     CONTINUE

c     can we break here before we start with the actual integration?

        if(socklo .and. proces .and. (nimag .gt. 1)) then
C
C---- Print for program flow
C
              CALLED = 'XDISP'
              COMMENT = ' '
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
           call xdisp(modedisp,firstpack,pack,ifirstpack,
     +                 firstfilm,genopen)
        end if


C       
C       
C----   generate list of spots but don't write generate file...
C       
C       HRP 21121999
C----   Assign oscillation angles
C       
C       
C----   If the spot separation OR raster parameters were not defined
C       by the user, determine appropriate values now from the very first
C       image to be processed.
C       
cdms21.09.2004   Check IFIRSTPACK instead of IPACK.
chrp17.02.2005        IF (IFIRSTPACK.EQ.IFIRSTP) THEN  
        IF (IPACK.EQ.IFIRSTP) THEN
          IF ((ISEP.EQ.0).OR.(IRAST.EQ.0)) THEN
            MODEGSR = 0
C
C---- Print for program flow
C
            CALLED = 'GETSEPRAS'
            COMMENT = 'To set spot separation and/or raster'
            IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
            CALL GETSEPRAS(IRAST,ISEP,IRAS,ID,MINDTX,MINDTY,
     +           IXSEP,IYSEP,MODEGSR,IERR)
            IF (IERR.NE.0) THEN
              NSHUTERR = 1
              CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
            END IF
          END IF
        END IF
C       
C---    need to set up PHI range and beam position before calling GENERATE
C    PHIBEGA,PHIENDA have been set up in CONTROL, based on the phi
C    values for the first image (when header read to determine image size).
C    Note that other values in PHIBEGA,PHIENDA will only be correct if all
C    images have the same oscillation angle. They are updated (in OPENODS)
C    as each image is read in.
C
C---- Call GENERATE in MODE=2 (do not write generate file) to work out
C     NADD, NVIRBAT and whether NEWPREF is required.
C       
        PHIBEG = PHIBEGA(IFIRSTPACK)
        PHIEND = PHIENDA(IFIRSTPACK)
C HRP 08.05.2018 for fine phi-sliced eiger

C was for chunking, changed method         PHIEND = PHIBEGA(IFIRSTPACK) + (CHUNK * (PHIENDA(IFIRSTPACK) - 
C     $  PHIBEGA(IFIRSTPACK)))
C
C---- Assign PARTITION if not already set by keyword to a value that
C     depends on oscillation angle.
C
        IF (IPARTITION.EQ.0) THEN
          IF (ABS(PHIEND-PHIBEG).GE.0.25) THEN
            PARTITION = 0.5
          ELSE IF (ABS(PHIEND-PHIBEG).GE.0.15) THEN
            PARTITION = 0.35
          ELSE
            PARTITION = 0.25
          END IF
        END IF
C
        XCEN = 100.0*XCENMM(1,1)
        YCEN = 100.0*YCENMM(1,1)
c          write(iout,fmt=9877) xcen
c          if (online) write(itout,fmt=9877) xcen
c 9877     format(1x,'xcen set in mosflm-2 from xcenmm, now;',F8.2)
C
C---- Decide whether to use NEWPREF, but only if a keyword has not been
C     set explicitly (POSTREF MULTI or NOMULTI)
C
C     NEWPREF should always be used ! NEWPREF defaults to TRUE and has to be
C     explicitly set false by keywords POSTERF NOMULTI.
C     Change the following test on IMULTI (checks if a MULTI/NOMULTI keyword 
C     has been given) to a test on NEWPREF itself. 
C     This change is necessary because if a list of keywords from the iMosflm
C     batch commands are used in a script, it includes POSTREF MULTI and then
C     the following code to work out NADD etc was not executed. AGWL 11/7/13
C
CAL        IF ((IMULTI.EQ.0).AND.(ISEG.EQ.1).AND.(NUMBLOCK.EQ.1).AND.
        IF ((NEWPREF).AND.(ISEG.EQ.1).AND.(NUMBLOCK.EQ.1).AND.
     +       FIRSTPASS) THEN


C
C---- Move code into the IF block so it is only executed once instead
C     of at the start of every block
        IF (DEBUG(1)) THEN
          WRITE(IOUT,FMT=6421) FIRSTPASS,SECONDPASS
          IF (ONLINE) WRITE(ITOUT,FMT=6421) FIRSTPASS,SECONDPASS
 6421     FORMAT(/,1X,'In MAIN, calling GENERATE in MODE=2 to work out',
     +          ' NADD NVIRBAT NEWPREF: FIRSTPASS',L2,' SECONDPASS',L2)
        END IF
C
C---- Print for program flow
C
        CALLED = 'GENERATE'
        COMMENT = 'MODE=2, work out NADD etc'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
        CALL GENERATE(2,IFIRSTPACK,.true.,.true.,LIMIT,.true.,
     +       NEWPREF,NFGEN,.false.,NFULLF)

C
C---- End of moved code
C
C
          IF (NIVB.GT.2) THEN
            IF (.NOT.NEWPREF) THEN
              NEWPREF = .TRUE.
              IF (ADDPART.AND.(.NOT.PRREAD)) THEN
                NPACK = NPACK -1
                EXTRAIMG = .FALSE.
              END IF
              INTDUM(1) = 0
              INTDUM(2) = 0
C
C---- Print for program flow
C
              CALLED = 'MODARRAY'
              COMMENT = 'All 4 values zero'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C        
              CALL MODARRAY(0, 0.0, 0, 0, INTDUM, INTDUM)
              SUMPART = .FALSE.
            END IF
          END IF
        END IF
        IF (DEBUG(1)) THEN
          WRITE(IOUT,FMT=1234) NEWPREF,ISEG,NUMBLOCK,FIRSTPASS,
     +                         PARTITION,IVIRBAT,NIVB,NVIRBAT,NADD,
     +                         NPACKSAVE,NIMGSUMREF
          IF (ONLINE) WRITE(ITOUT,FMT=1234) NEWPREF,ISEG,NUMBLOCK,
     +       FIRSTPASS,PARTITION,IVIRBAT,NIVB,NVIRBAT,NADD,
     +                         NPACKSAVE,NIMGSUMREF
        END IF
 1234   FORMAT(/,1X,'In MAIN',/,1X,'NEWPREF ',L1,'  ISEG',I3,
     +         '  NUMBLOCK',I3,'  FIRSTPASS ',L1,'  PARTITION',F5.2,
     +         /,1X,'IVIRBAT',I2,' NIVB',I3,' NVIRBAT',I3,' NADD',I3,
     +         ' NPACKSAVE',I4,' NIMGSUMREF',I3)
        IF (NEWPREF.AND.(ISEG.EQ.1).AND.(NUMBLOCK.EQ.1).AND.
     +       FIRSTPASS) THEN
C
C---- Do not assign NVIRBAT if it has been set by a keyword
C
C
          IF (IVIRBAT.EQ.0) NVIRBAT = MAX(NIVB-1,1)
CAGWL          NADDMISSET = NIVB + NIVB/2
C
C---- To be able to handle fine sliced data, make NADDMISSET 3*NVIRBAT
C     by default. this does not seem to adversley affect coarse data
C     AGWL 17 May 2011 
          NADDMISSET = 3*NVIRBAT
C
C---- If NADD keyword given for integration (not cell refinement)
C     use that value for NADDMISSET
C
          IF (PRMODE.AND.(.NOT.MULTISEG)) NADDMISSET = NADD
C
C---- Ensure NADDMISSET is a multiple of NVIRBAT
C
          IF (MOD(NADDMISSET,NVIRBAT).NE.0)
     +       NADDMISSET = (NADDMISSET/NVIRBAT)*NVIRBAT +NVIRBAT
          IF (NADDMISSET.LT.1) NADDMISSET = NVIRBAT
          IF (MULTISEG) THEN
            IFIRSTPSEG = IFIRSTPACK
          ELSE
            NADD = NADDMISSET
          END IF
          WRITE(IOUT,FMT=6400) 
          IF (ONLINE) WRITE(ITOUT,FMT=6400) 
 6400       FORMAT(//,1X,'*** Post-refinement will use partials ',
     +        'extending over several images ***',/,1X,'This is',
     +        ' equivalent to including a POSTREF MULTI keyword.',/,
     +      1X,'(To prevent this, include keywords POSTREF NOMULTI.)')
          IF (NVIRBAT.GT.1) THEN
            WRITE(IOUT,FMT=6402) NVIRBAT
            IF (ONLINE) WRITE(ITOUT,FMT=6402) NVIRBAT
 6402       FORMAT(1X,'Separate missetting angles will be refined for',
     +            ' groups of',I3,' images.')
          END IF
          WRITE(IOUT,FMT=6404) NADDMISSET
          IF (ONLINE) WRITE(ITOUT,FMT=6404) NADDMISSET
 6404       FORMAT(1X,'Reflections from up to',I3,' images will be',
     +       ' used in the refinement of missetting angles.'/,/)
       END IF
C       HRP 21121999
C
C---- Initialise RESETCCOM
C
        RESETCCOM = .FALSE.
C
C---- If doing a cell refinement run, save (first round) or restore
C     parameters required.

        IF (MULTISEG.AND.(NREPEAT.EQ.0).AND.
     +       (ISEG.EQ.1)) THEN
C
C
C---- Print for program flow
C
           CALLED = 'CELLREFSET'
           COMMENT = ' '
           IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
           CALL CELLREFSET(IFIRSTPACK,NREPEAT,ISEG,RPTFIRST,
     +          FIRSTTIME,INERR)
           IF (INERR) THEN
C     
C---- Abort current run
C       
C
C
C---- Print for program flow
C
              CALLED = 'MRESET'
              COMMENT = 'Abort'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,PRFSUMI)
              IF (DISPMENU) THEN
                 GOTO 34
              ELSE
                 GOTO 30
              END IF
           END IF
        end if
C
C
C---- Need to reset large cell error warning flags which may have
C     been set by a previous cycle of this run or by a
C     previous cell refinement run. Need to reset SDs as well
C     otherwise test on inaccurate cell will use sd'd from a previous
C     refinement. AGWL 27/7/07
C
        IF (MULTISEG.AND.(ISEG.EQ.1)) THEN
           WARN(18) = .FALSE.
           DO I = 1,6
             XWARN(I,18) = 0.0
             IWARN(I,18) = 0
             SDCELL(I) = 0.0
           END DO
        END IF
C       
C
C---- xml to GUI, this is a break between postrefining and 
C     integrating in a block.
C
        IF(SOCKLO.AND.PROCES.AND..NOT.MULTISEG)THEN
C
C---- Print for program flow
C  
          CALLED = 'WRITE_SOCKET'
          COMMENT = 'write XML block integrate begin'
          IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)

 6440      FORMAT('<?xml version="1.0"?>',
     $          '<!DOCTYPE block_integrate_begin SYSTEM "">',
     $          '<block_integrate_begin>',
     $          '<status>',
     $          '<code>ok</code>',
     $          '</status>',
     $          '</block_integrate_begin>')
           WRITE(LONGLINE,FMT=6440)
           CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $          LENSTR(LONGLINE),LONGLINE)
        ENDIF
C
        NPHIPROFIMG = 0
        NPHIPROFGOOD = 0
        NPHIPROFMISS = 0
C
C---- Print for program flow
C
        CALLED = ' '
        COMMENT = '*** Loop over images ***'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
        DO 250 IPACK = IFIRSTPACK,NPACK
C was for chunking, changed method ,CHUNK
C
C
C---- Count number of images processed for phi profile where some images missing
C
          NPHIPROFIMG = NPHIPROFIMG + 1       
          FIRSTPACK = (IPACK.EQ.1)
C
C---- Initialise variables for summing images for finding centroids
C 
          IF (FIRSTPACK.AND.FIRSTPASS.AND.(NUMBLOCK.EQ.1)) THEN
            IDOLD = 0
            NIMGSUMOLDREF = 0
          END IF
C
C---- Set pointer to last image in this segment
C
          IF (ISEG.GT.0) LASTFILM(ISEG) = NPACK
C       
C----   CAUTION ! ... be sure that previous packs have not been rejected
C       when assigning firstfilm
C       
          FIRSTFILM = (IPACK.EQ.IFIRSTGOOD)
C
C---- If this is the first image in a new block, then reset NSIG and PTMIN
C     to their default values, so that they will be set to the best value
C     if they were reduced because previous images were weak but now they
C     are strong again    
C
          IF ((IPACK.EQ.IFIRSTPACK).AND.FIRSTPASS) THEN
            IF (ETA.GT.0.0) PTMINDEF = 
     +                      0.5*ABS(PHIEND-PHIBEG)/(2.0*ETA/DTOR)
            PTMINDEF = MAX(PTMINDEF,0.2)
            PTMINDEF = MIN(PTMINDEF,0.5)
            IF (ISIGSET.EQ.0) NSIG = 20
            IF (IPTMINSET.EQ.0) PTMIN = PTMINDEF
          END IF
C       
          IF (DEBUG(1)) THEN
            WRITE(IOUT,FMT=6009) IPACK,IFIRSTPACK,NPACK,FIRSTPASS,
     +           SECONDPASS,THIRDPASS,IFIRSTGOOD,FIRSTPACK,FIRSTFILM,
     +           NSIG,PTMIN
            IF (ONLINE) WRITE(ITOUT,FMT=6009) IPACK,IFIRSTPACK,NPACK,
     +           FIRSTPASS,SECONDPASS,THIRDPASS,IFIRSTGOOD,FIRSTPACK,
     +           FIRSTFILM,NSIG,PTMIN
 6009       FORMAT(1X,'In MAIN, Loop over packs',/,1X,'IPACK=',I3,
     +           ' IFIRSTPACK=',I4,' NPACK=',I4,' FIRSTPASS',L2,
     +           ' SECONDPASS',L2,' THIRDPASS',L2,/,1X,
     +           ' IFIRSTGOOD',I3,' FIRSTPACK',L2,' FIRSTFILM',L2,/,
     +           1X,'NSIG=',I3,'  PTMIN=',F5.2)
          END IF
C       
C----   If this is the final (extra) image which is only processed up
C       to the point of generating the reflection list so that spatially
C       overlapped summed partials can be flagged, then skip to end of
C       this loop if this is the second or third pass (Cannot test on
C       FIRSTPASS because this is never true when reading in profiles)
C       
          IF (EXTRAIMG.AND.(IPACK.EQ.NPACK).AND.
     +         (SECONDPASS.OR.THIRDPASS)) GOTO 250
C       
C----   If this is multi-segment post-refinement, and this is the last pack of
C       the current segment, then there is no need to process it UNLESS using
C       NEWPREF refinement.
          IF ((MULTISEG).AND.(.NOT.NEWPREF).AND.(IPACK.EQ.NPACK))
     +         GOTO 250
C       
C----   NACFLM is the number of films in each pack to be included in
C       profile accumulation. Note that this will depend on
C       whether processing is starting with the A, B or C film
C       (hence NFIRST(IPACK),
C       which is 1, 2 or 3 respectively).
C       
          NACFLM = 1
          IF (PRBFILM) NACFLM = 2 - NFIRST(IPACK) + 1
          IF (PRCFILM) NACFLM = 3 - NFIRST(IPACK) + 1
C       
          ID = IDPACK(IPACK)
C
C---- If debug is only to start at a specified image number, check this now
C     and if image number has been reached, restore original DEBUG values
C     and reset DEBUG(108) so this is only done once.
C
          IF (DEBUG(108)) THEN
            IF (ID.GE.NDEBUG(108)) THEN
              DO 41 I = 1,200
                DEBUG(I) = SAVEDEBUG(I)
 41           CONTINUE
              DEBUG(108) = .FALSE.
            END IF
          END IF
C
C----     Ditto for DUMPing
C
          IF (DUMP(12)) THEN
            IF (ID.GE.IARRDUMP(12)) THEN
              DO 42 I = 1,30
          if (dump(i)) write(iout,fmt=9874) i
          if (online.and.(dump(i))) write(itout,fmt=9874) i
 9874     format(1x,'transfer savedump to dump, true for i=',i3)
                 DUMP(I) = SAVEDUMP(I)
 42          CONTINUE
              DUMP(12) = .FALSE.
            END IF
          END IF
C       
C----   Determine which serial keyword this pack belongs to
C       
          DO 43 I = 1,50
            IF ((ID.GE.IPACK1A(I)).AND.(ID.LE.IPACK2A(I))) THEN
              ISERADD = ISERAR(I)
              GOTO 44
            END IF
 43      CONTINUE
C       
C----   Assign oscillation angles
C       
 44       CONTINUE
          PHIBEG = PHIBEGA(IPACK)
          PHIEND = PHIENDA(IPACK)
C HRP 08.05.2018 for fine phi-sliced eiger

C was for chunking, changed method           PHIEND = PHIBEGA(IPACK) + (CHUNK * (PHIENDA(IPACK) - 
C     $         PHIBEGA(IPACK)))
C       
C----   If on thirdpass, write out summary file information for the
C       A film of this pack
C       
          IF (THIRDPASS) THEN
C       
C----   First check if this film has been rejected, and
C       write message to summary file.
C       
            DO 50 IIF = 1,NACFLM
              IF (BADPACK(IPACK,IIF)) THEN
                IXERRI = IXERR(IPACK)
                X = XERR(IPACK)
C       
C       *****************************************************
                CALL SUMMERR(ISUMMR,ID,NERR(IPACK),NFPACK(IPACK),
     +               NFGEN,IIF,IXERRI,X)
C       *****************************************************
C       
                GO TO 250
              END IF
C       
C       
              NFILMS = NFILMS + 1
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6422) NFILMS
                IF (ONLINE) WRITE(ITOUT,FMT=6422) NFILMS
 6422           FORMAT(1X,'NFILMS set to',I4,' for writing',
     +                ' to summary file')
              END IF
C       
C       
              IF (IMGP) THEN
C       
C----   Writes summary information for ip on detector refinement etc
C       needed for xloggraph
C       
C       IMAGE   CCX  CCY   CCOM  DIST YSCALE TILT TWIST ROFF  TOFF RESID  WRESID
C       FULL  PART OVRL  NEG BAD  I/SIGI   I/SIGI  Rsym Nsym SDRAT
c       -harvest
c       cxEBI if the format 6067 changes then harvest mharvest.f needs to change
c       -harvest
C       
C
C---- Print for program flow
C
                 CALLED = 'DNA_OUTPUT'
                 COMMENT = 'Output data for DNA'
                 IF (DEBUG(99)) 
     +                   CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)

                 write(dna_image, *) isumm(1,nfilms)

                 call dna_output_table_start('summary_information')
                 call dna_output_list_start('summary')
                 call dna_output_integer_item('pack', 
     +                isumm(1,nfilms))
                 call dna_output_real_item('ccx', 
     +                0.01 * isumm(2, nfilms))
                 call dna_output_real_item('ccy', 
     +                0.01 * isumm(3, nfilms))
                 call dna_output_real_item('ccom',
     +                rsumm(1, nfilms))
                 call dna_output_real_item('distance',
     +                0.01 * isumm(4, nfilms))
                 call dna_output_real_item('yscale',
     +                rsumm(2, nfilms))
                 call dna_output_real_item('isigall',
     +                rsumm(5, nfilms))
                 call dna_output_real_item('isigout',
     +                rsumm(6, nfilms))
                 call dna_output_list_end
                 call dna_output_list_start('spots')
                 call dna_output_integer_item('full',
     +                isumm(9, nfilms))
                 call dna_output_integer_item('partial',
     +                isumm(10, nfilms))
                 call dna_output_integer_item('overlap',
     +                isumm(11, nfilms))
                 call dna_output_integer_item('negative',
     +                isumm(12, nfilms))
                 call dna_output_integer_item('bad_spots',
     +                isumm(13, nfilms))
                 call dna_output_list_end
                 call dna_output_table_end


                WRITE (ISUMMR,FMT=6067) ISUMM(1,NFILMS),
     +               (0.01*ISUMM(K,NFILMS),K=2,3),RSUMM(1,NFILMS),
     +               0.01*ISUMM(4,NFILMS),
     +               RSUMM(2,NFILMS),(ISUMM(K,NFILMS),K=5,6),
     +               0.01*ISUMM(7,NFILMS),0.01*ISUMM(19,NFILMS)
     +               ,0.01*RSUMM(3,NFILMS),RSUMM(4,NFILMS),
     +               (ISUMM(K,NFILMS),K=9,13),
     +               (RSUMM(K,NFILMS),K=5,7),
     +               ISUMM(20,NFILMS),RSUMM(8,NFILMS)
                NLSUM1 = NLSUM1 + 1
                WRITE (LINESUM1(NLSUM1),FMT=6067) ISUMM(1,NFILMS),
     +               (0.01*ISUMM(K,NFILMS),K=2,3),RSUMM(1,NFILMS),
     +               0.01*ISUMM(4,NFILMS),
     +               RSUMM(2,NFILMS),(ISUMM(K,NFILMS),K=5,6),
     +               0.01*ISUMM(7,NFILMS),0.01*ISUMM(19,NFILMS)
     +               ,0.01*RSUMM(3,NFILMS),RSUMM(4,NFILMS),
     +               (ISUMM(K,NFILMS),K=9,13),
     +               (RSUMM(K,NFILMS),K=5,7),
     +               ISUMM(20,NFILMS),RSUMM(8,NFILMS)
              ELSE
                WRITE (ISUMMR,FMT=6066) ISUMM(1,NFILMS),
     +               SUMMCH(NFILMS),(0.01*ISUMM(K,NFILMS),K=2,3),
     +               RSUMM(1,NFILMS),0.01*ISUMM(4,NFILMS),
     +               RSUMM(2,NFILMS),(ISUMM(K,NFILMS),K=5,6),
     +               0.01*ISUMM(7,NFILMS),
     +               0.01*RSUMM(3,NFILMS),RSUMM(4,NFILMS),
     +               (ISUMM(K,NFILMS),K=9,13),
     +               (RSUMM(K,NFILMS),K=5,6)
              END IF
C       
C----   Film format
C       PACK ID  CCX   CCY  CCOM  DIST YSCALE TILT TWIST BULGE
C       RESID  WRESID  FULL  PART OVRL  NEG BAD  I/SIGI
C       
 6066         FORMAT (1X,I3,A,3F6.2,F6.1,F6.3,I5,I6,F7.2,
     +             F6.3,F7.1,I7,I6,2I5,I4,2F7.1)
C       
C----   IP format
C       PACK   CCX  CCY   CCOM  DIST YSCALE TILT TWIST ROFF  TOFF RESID  WRESID
C       FULL  PART OVRL  NEG BAD  I/SIGI   I/SIGI  Rsym Nsym SDRAT
C       
cdms21.09.2004   Make columns line up better with heading.
C6067         FORMAT (1X,I4,3F6.2,F7.1,F6.3,2I5,1X,2F6.2,F6.3,F7.1,
C    +             I5,I6,2I4,I4,2F8.1,F8.3,I4,F6.1)
CHRP 09.08.2006 - add explicit spaces between number fields
c 6067         FORMAT (2X,I4,1X,2(F6.2,1X),F7.2,1X,F6.1,1X,F6.3,1X,
c     $             2(I5,1X),2(F6.2,1X),F6.3,1X,F7.1,1X,I7,1X,I6,1X,
c     +             2(I5,1X),I4,1X,2(F7.1,1X),F8.3,1X,I5,1X,F6.1)
 6067         FORMAT (2X,I7,1X,2(F6.2,1X),F7.2,1X,F6.1,1X,F6.3,1X,
     $             2(I5,1X),2(F6.2,1X),F6.3,1X,F7.1,1X,I7,1X,I6,1X,
     +             2(I5,1X),I4,2(F7.1,1X),F8.3,I5,F6.1)      
 50         CONTINUE
          END IF
C       
C----   Test if this pack has been rejected already. This test only
C       necessary when accumulating profiles, and one of the
C       'A' films has been rejected
C       
          IF (BADPACK(IPACK,1)) THEN
            IF (FIRSTFILM) IFIRSTGOOD = IFIRSTGOOD + 1
            GO TO 250
          END IF
C       
C----   Set flags for average spot profile, FILMPLOT,
C       and firstfilm for use in profile accumulation
C       
          AVPROFILE = AVPROF(IPACK)
          FILMPLT = FILMPLOT(IPACK)
C       
C----   Locate the required pack in the generate file
C       
C----   NFIRST(IPACK) stores film number (1,2 or 3) of first
C       film to be processed
C       
          NFIRSTI = NFIRST(IPACK)
C       
C----   If profiles have been accumulated from several a films,
C       then on thirdpass, when b and c films are to be processed
C       we must start with the b film
C       just in case the profiles were actually accumulated using
C       the b films, increment nfirsti rather than setting to 2
C       
          IF (THIRDPASS) THEN
            NFIRSTI = NFIRSTI + 1
C       
C----   If B films were included in forming profiles
C       increment NFIRTSI appropriately.
C       If C films were included there is no more to be done.
C       
            IF (PRBFILM) NFIRSTI = NFIRSTI + 1
            IF (PRCFILM) GO TO 250
          END IF
C       
          STARTA = (NFIRSTI.EQ.1)
          STARTB = (NFIRSTI.EQ.2)
          STARTC = (NFIRSTI.GE.3)
C       
C----   If using profile fitting, must start with the A film
C       
          IF ((.NOT.THIRDPASS) .AND. PROFILE .AND. (.NOT.PRREAD) .AND.
     +         ((STARTB.AND. (.NOT.PRBFILM)).OR.
     +         (STARTC.AND. (.NOT.PRCFILM)))) THEN
            WRITE (IOUT,FMT=6008)
 6008       FORMAT (//1X,'******* FATAL ERROR ******',/1X,'When using',
     +           ' PROFILE FITTING the A film must be processed first ',
     +           'unless profile fitting has been',/1X,'EXPLICITLY ',
     +           'requested for B or C films on PROFILE keyword')
            IF (ONLINE) WRITE (ITOUT,FMT=6008)
            NSHUTERR = 2
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          END IF
C       
          FORCE = ((STARTB.AND.FORCEB(IPACK)) .OR.
     +         (STARTC.AND.FORCEC(IPACK)))
C       
C**********************************************************al
C----   How many films in this pack to be processed?
C       
          NFP = 1
C       
C**********************************************************al
C       
C----   If accumulating profiles and now on thirdpass, check that
C       there is another film in the pack to be processed
C       
          IF (THIRDPASS .AND. (NFP.EQ.NACFLM)) GO TO 250
C       
C       AL
C----   Only call FINDPACK if this pack has already been generated,
C       ie if this is the second pass of accumulate or if this is the
C       B or C film (ie thirdpass), OR if this is the first image of
C       the second or subsequent block of images which has already been
C       generated in order to flag spatially overlapping summed partials.
C       However, I have not yet got this to work if reading profiles,
C       so don't do this when reading profiles
C       
          IF ((SECONDPASS.OR.THIRDPASS).OR.
     +         ((IPACK.EQ.IFIRSTPACK).AND.(ADDPART.AND.(.NOT.NEWPREF))
     +         .AND.(NUMBLOCK.GT.1)
     +         .AND.(.NOT.PRREAD)))  THEN
C
            IF (DEBUG(1)) THEN
              WRITE(IOUT,FMT=6470) ID                
              IF (ONLINE) WRITE(ITOUT,FMT=6470) ID
 6470         FORMAT(1X,' In MAIN, calling FINDPACK for ID=',I4)
            END IF
C
C---- Print for program flow
C
            CALLED = 'FINDPACK'
            WRITE(COMMENT,FMT=6471) ID
 6471       FORMAT(' For image',I7) 
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ***************************************************
            CALL FINDPACK(ID,FILMPLT,NFGEN,JPACK,FORCE,READCC,NOFID,
     +           NPACK)
C       ***************************************************
C       
C----   If running interactively, so that the pattern is regenerated after
C       refinement (MODEG=3), then if this is the first image of a new block
C       and ADDPART is TRUE so that spatial overlaps are checked, then
C       must reposition generate file now to start of this pack, or this
C       image will get generated twice.
C       
            IF (((IPACK.EQ.IFIRSTPACK).AND.(ADDPART.AND.(.NOT.NEWPREF))
     +           .AND.(NUMBLOCK.GT.1).AND.(.NOT.PRREAD)).AND.FILMPLT
     +           .AND.(.NOT.MATCH)) THEN
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6472) IPACKHEAD                
                IF (ONLINE) WRITE(ITOUT,FMT=6472) IPACKHEAD
 6472           FORMAT(1X,' In MAIN, calling QSEEK for record',I6)
              END IF
              CALL QSEEK(IUNIT,IPACKHEAD,1,36)
              IPACKREC = IPACKHEAD
            END IF
          END IF
C       
C       
C----   Check if pack not found in generate file, or previous film not measured
C       
          IF (ID.LT.0) THEN
            BADPACK(IPACK,1) = .TRUE.
C       
C----   If this is a multi-segment refinement, abandon it, and if
C       using iMosflm send an error message and continue.
C       
            IF (MULTISEG) THEN
              WRITE(IOUT,FMT=6210)
              IF (ONLINE) WRITE(ITOUT,FMT=6210)
 6210         FORMAT(//1X,' A multisegment post-refinement will NOT ',
     +             'work if images have been rejected',/,1X,
     $             'Run aborted')
              IF (SOCKLO) THEN
                STRING1 = ' '
                WRITE(STRING1,FMT=62101) 
62101           FORMAT('Cannot find image in the generate file.'
     +          '__nl__The most common reason is that two different',
     +          ' mosflm jobs__nl__are running in the same directory',
     +          ' with the same generate filename.__nl__This should',
     +          ' not normally happen as the generate file name has'
     +          '__nl__a date stamp. Cell refinement abandoned.')
                WRITE(LONGLINE,FMT=62102) STRING1(1:LENSTR(STRING1))
                CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                LENSTR(LONGLINE),LONGLINE)
62102           FORMAT('<?xml version="1.0"?>',
     $             '<!DOCTYPE trapped_error_response>',
     $             '<trapped_error_response>',
     $             '<type>cannot_find_image_in_generate_file</type>',
     $             '<message>',A,'</message>',
     $             '</trapped_error_response>')
C
C----- Allow to continue if using iMosflm. AGWL 11/7/18
C
                CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                GOTO 30
              END IF
              STOP
            END IF
C       
C----   If this was the firstfilm,
C       change pack number of first good film
C       
            IF (FIRSTFILM) IFIRSTGOOD = IFIRSTGOOD + 1
            NWRN = NWRN + 1
C       
C----   If on firstpass of accumulate run, just store the error,
C       otherwise write message to summary file now.
C       
            IF (FIRSTPASS) THEN
              NERR(IPACK) = -ID
            ELSE
              II = 0
C       
C       ****************************************************
              CALL SUMMERR(ISUMMR,ID,-ID,NFPACK(IPACK),NFGEN,FILM,II,X)
C       ****************************************************
C       
            END IF
            GO TO 250
          END IF
C       
C----   Note that if accumulating profiles, proces is set true
C       for the second pass   
C       set NFP=NACFLM if going straight into process
C       
          IF (PROCES) THEN
            NFP = NACFLM
            GO TO 60
          END IF
C       
C----   If accumulating profiles, then on first and second passes
C       only do A films,and on thirdpass do remaining films
C       
          IF (ACCUMULATE) THEN
            IF (FIRSTPASS) THEN
              NFP = NACFLM
            ELSE
              NFP = NFP - NACFLM
            END IF
          END IF
C       
C----   loop over the images to be integrated. Note that in SECONDPASS, this
C       is all the images in the block.
C       
 60       CONTINUE
C       
       
          DO 240 IFILM = 1,NFP
C
            IF (DEBUG(1).AND.(NFP.GT.1)) THEN
              WRITE(IOUT,FMT=6476) IFILM       
              IF (ONLINE) WRITE(ITOUT,FMT=6476) IFILM       
 6476         FORMAT(1X,'In MAIN, loop over films, IFILM=',I2)
            END IF
            LIST = .FALSE.
            RESCAN = .TRUE.
C       
C----   Define initial value of MAXR, required when 'NEXT' is called
C       for central region of film. ONLY assign it for the firstfilm
C       because for subsequent films it has been assigned the correct
C       maximum from RMAXR
            IF (FIRSTFILM) MAXR = NXS*NYS
C       
C----   Is this film an A,B or C?
C       
            FILM = NFIRSTI + IFILM - 1
C       
C       
            ID = IDPACK(IPACK)
C       
C----   Call OPENODS if one film per file
C       Don't read image file if doing PROCES
            IF ((ONEFILE).AND.(.NOT.PROCES)) THEN
C       
C----   If doing SUMPART, don't read images beyond last image to be processed
C       
              IF (SUMPART.AND.(IPACK.EQ.NPACKSAVE)) THEN
                IF (ISTART.EQ.0) THEN
                  ISTART = NREC
                ELSE IF (ISTART.EQ.NREC) THEN
                  ISTART = 0
                END IF
                SUMPART = .FALSE.
C       
C----   set display filename to the PREVIOUS image that was read in.
C       
                CDSPTL = ODFILE
              ELSE
C       
C----   If this is the "extra" image only used to flag spatially overlapped
C       summed partials, then don't read in the image
C       
                IF ((EXTRAIMG).AND.(IPACK.EQ.NPACK)) GOTO 62
                IF (BRIEF) WRITE(IBRIEF,FMT=6204)
 6204           FORMAT(1X,'Reading image into memory')
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6474) ID
                  IF (ONLINE) WRITE(ITOUT,FMT=6474) ID
 6474             FORMAT(1X,'In MAIN, call OPENODS for ID=',I5)
                END IF
C       ********************************************************
C----   OPENODS called in normal mode
C       
C
C---- Print for program flow
C
                CALLED = 'OPENODS'
                WRITE(COMMENT,FMT=6745) ID
 6745           FORMAT('Normal mode, LIPROCESS=3, image ',I7)
                IF (DEBUG(99))CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                LIPROCESS = 3
                IDSAVE = ID
                CALL OPENODS(IDENT,ID,FILM,ODEXT,FDISK,MODEOP,
     +               PACK,ODFILE,SEPCHAR,FORCEREAD,IPACK,
     +               TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
C
C---- xml to GUI, this is a break between blocks.
C
                IF (SOCKLO.AND.finishedblock) THEN
C
C---- Print for program flow
C  
                  CALLED = 'WRITE_SOCKET'
                  COMMENT = 'write XML block integrate end (2)'
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)

 6441             FORMAT('<?xml version="1.0"?>',
     $            '<!DOCTYPE block_integrate_end SYSTEM "">',
     $            '<block_integrate_end>',
     $            '<status>',
     $            '<code>ok</code>',
     $            '</status>',
     $            '</block_integrate_end>')
                   WRITE(LONGLINE,FMT=6441)
                   CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                LENSTR(LONGLINE),LONGLINE)
                  finishedblock = .false.
                ENDIF
C
C---- For Pilatus detectors, need to check what value has been assigned to
C     pixles in the gaps between tiles. This should be -1, but this value is
C     assigned by the beamline software and in some cases it has been assigned
C     a value of zero (eg Campinas 2M, Pilatus 1M for lab testing). agwl 12/4/16
C     Note that NULLPIXTEST is reset FALSE after every call to CONTROL, so
C     NULLPIX will be reset (if necessary) for every task
C     (cell refinement, integration) because iMosflm will always be
C     sending a value of -1
C
                IF (((MACHINE.EQ.'PILA').OR.(MACHINE.EQ.'EIGE')).AND.
     +            (.NOT.NULLPIXTEST).AND.(.NOT.KEEPNULLPIX)) THEN
C     For Pilatus, first gap between tiles extends from X=195-211, so
C     calculate index of a pixel half way along the middle stripe of the
C     gap, for Eiger gaps if from X=514 to 550 
C
                  IF (MACHINE.EQ.'PILA') THEN
                    I = 203*IYLEN + IYLEN/2
                  ELSE IF (MACHINE.EQ.'EIGE') THEN
                    I = 532*IYLEN + IYLEN/2
                  END IF
                  K = INTPXL(IMAGE(I))
                  IF (K.NE.NULLPIX) THEN
                    WRITE(IOUT,FMT=6477) I,K,NULLPIX
                    IF (ONLINE) WRITE(ITOUT,FMT=6477) I,K,NULLPIX
C
C---- No longer reassign NULLPIX, this will be done in PROCESS on a reflection
C     by reflection basis
CAL                   NULLPIX = K
CAL                   IINULL = .TRUE.
                    WRONGGAPVALUE = .TRUE.
C
C---- Attempted to send the updated NULLPIX value to iMosflm, but
C     this simply does not work.
C
                    LONGLINE = ' '
                    WRITE(LONGLINE,FMT=6479) MACHINE,MODEL,NULLPIX,
     $                XODFILE(1:LENSTR(XODFILE)),
     $                TEMPLSAV(1:lenstr(templsav)),ID
C
C---- Print for program flow
C  
CAL                CALLED = 'WRITE_SOCKET_LENGTH'
CAL                COMMENT = 'write XML header response for new NULLPIX'
CAL                IF (DEBUG(99)) 
CAL     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
CAL                CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(LONGLINE),
CAL     $            LONGLINE)
                  END IF
                  NULLPIXTEST = .TRUE.
                END IF

C
C---- hrp 03062008 for calculating average and rms for this image.
C     Add a test that ID>0, as it is set to -999 or more -ve if
C     a problem with reading the image in OPENODS. AGWL 13/6/18
C
                if (ID.gt.0) call dspscl(ID,image,nrec,iylen)
C       *******************************************************
C----   If phi angles are being read from the image header, PHIBEG and
C       PHIEND will not yet have been assigned, so need to do that now.
C       Also need to assign NWMAX, maximum reflection width in images.
C       
                IF ((ISTRT.EQ.0).OR.(IANGLE.EQ.0)) THEN
                  PHIBEG = PHIBEGA(IPACK)
                  PHIEND = PHIENDA(IPACK)
C HRP 08.05.2018 for fine phi-sliced eiger

C was for chunking, changed method                   PHIEND = PHIBEGA(IPACK) + 
C     $                 (CHUNK * (PHIENDA(IPACK) - 
C     $                 PHIBEGA(IPACK)))
                  PHIRNG = PHIEND - PHIBEG
C       
C----   Set maximum reflection width in number of images, hard limit of IPAD
C       
                  IF (PHIRNG.NE.0.0) NWMAX = NINT(WMAX/PHIRNG)
                  IF (NWMAX.GT.10) THEN
                    IPAD = 100
                    WARN(27) = .TRUE.
                  END IF
                  NWMAX = MIN(NWMAX,IPAD)
C       
C----   Limit NWMAX to minimum of 2, otherwise will not integrate partials
C       under any circumstances
C       
                  NWMAX = MAX(NWMAX,2)
                END IF
C
C end of "IF (SUMPART.AND.(IPACK.EQ.NPACKSAVE))" block
C
              END IF
C       

C----   Update SUMPARTIALS flag (may not have next image). Don't need to
C       do this for NEWPREF refinement.
C       
              SUMP(IPACK) = SUMPART
              IF (.NOT.NEWPREF) ADDP(IPACK) = (SUMPART.AND.ADDP(IPACK))
C       
C----   If od file does not exist (id set to -999 in openods), or error in read
C       ID = -1001, or in decoding header (id = -1002) skip to next pack
C       
              IF (ID.LE.-999) THEN
C       
C----   ABANDON job if image file does not exist...otherwise it can get into
C       all sorts of problems.
C       
                IF (ID.EQ.-999) THEN
                  IF (PHIPROF) THEN
                    WRITE(IOUT,FMT=62051)
                    IF (ONLINE) WRITE(ITOUT,FMT=62051)
62051               FORMAT(/,/,1X, 
     +              'Image file not found, profile will be truncated')
                  ELSE
                    WRITE(IOUT,FMT=6205)
                    IF (ONLINE) WRITE(ITOUT,FMT=6205)
 6205             FORMAT(/,/,1X,' ***** FATAL ERROR ***',/,1X,
     +                 'Image file not found, abandoning processing')
                  END IF
                ELSE
                  WRITE(IOUT,FMT=6380)
                  IF (ONLINE) WRITE(ITOUT,FMT=6380)
 6380             FORMAT(/,/,1X,' ***** FATAL ERROR ***',/,1X,
     +                 'Error in reading image, abandoning ',
     $                 'processing')
                END IF
                IF (WINOPEN .AND. DISPMENU) THEN
                  IXM = 200
                  IYM = 200
                  LINELEN = 60
                  NUMLIN = 3
C       
C       Create IO window
C       
                  CALL MXDCIO(0,LINELEN, NUMLIN, IXM,IYM)
                  LINE = ' '
                  IF (ID.EQ.-999) THEN
                    WRITE (LINE, 6207) 
 6207               FORMAT (1X,'Image does not exist (see terminal ',
     +                   'window).   Hit return to continue')
                  ELSE 
                    WRITE (LINE, 6390) 
 6390               FORMAT (1X,'Error reading image (see terminal ',
     +                   'window).   Hit return to continue')
                  END IF
                  CALL MXDWIO(LINE, 1)
                  CALL MXDRIO(LINE2)
                  CALL MXD_FLU(I)
                  CALL MXDCIO(1,0,0,0,0)

                  GOTO 280
                END IF
C
C---- If doing a phi profile integration, trap cases where some images are missing from
C     the dataset.  Skip to next image
C
                IF (PHIPROF) THEN
                  IF (NPHIPROFIMG.EQ.1) STARTTRUNC = .TRUE.
                  IF (NPHIPROFGOOD.GT.0) ENDTRUNC = .TRUE.
                  IFIRSTGOOD = IFIRSTGOOD + 1
C
C---- Go to next image
C
                  IFIRSTP = IFIRSTP + 1
                  NPHIPROFMISS = NPHIPROFMISS + 1
                  IMGMISSING(NPHIPROFMISS) = IDSAVE
                  GOTO 250
                END IF  
                NSHUTERR = 3
                CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
C       
C----   if this was the firstfilm, change pack number of first good film
C       As SHUTDOWN has been called, will it ever get here???
C
                IF (FIRSTFILM) IFIRSTGOOD = IFIRSTGOOD + 1
                BADPACK(IPACK,1) = .TRUE.
                NWRN = NWRN + 1
C       
C       
C----   If this is a multi-segment refinement, abandon it.
C       
                IF (MULTISEG) THEN
                  WRITE(IOUT,FMT=6210)
                  IF (ONLINE) WRITE(ITOUT,FMT=6210)
                  STOP
                END IF
C       
                IF (FIRSTPASS) THEN
                  NERR(IPACK) = 3
                ELSE
                  ID = IDPACK(IPACK)
                  II = 0
C       
C       **************************************************
                  CALL SUMMERR(ISUMMR,ID,3,NFPACK(IPACK),NFGEN,
     $                 FILM,II,X)
C       **************************************************
C       
                END IF
                GO TO 250
              END IF
            END IF
C
            NPHIPROFGOOD = NPHIPROFGOOD + 1       
            AFILM = (FILM.EQ.1)
            BFILM = (FILM.EQ.2)
            CFILM = (FILM.EQ.3)
C       
C----   Go straight to process if keyword has been set
C       
 62         continue
            IF (ONLINE) THEN
C       
              IF (IMGP) THEN
                IF (PROCES) THEN
                  IF(CHUNK.EQ.1)THEN
                    WRITE (ITOUT,FMT=6015) ID,PHIBEG,PHIEND
                    IF (BRIEF) WRITE (IBRIEF,FMT=6015) ID,PHIBEG,
     $                   PHIEND
                  ELSE
                    WRITE (ITOUT,FMT=60150) ID,((ID-1)*CHUNK)+1,
     $                   ID*CHUNK,PHIBEG,PHIEND
                    IF (BRIEF) WRITE (IBRIEF,FMT=60150) ID,
     $                   ((ID-1)*CHUNK)+1,ID*CHUNK,PHIBEG,PHIEND
                  ENDIF
                ELSE
                  IF(CHUNK.EQ.1)THEN
                    WRITE (ITOUT,FMT=6011) ID,PHIBEG,PHIEND
                    IF (BRIEF) WRITE (IBRIEF,FMT=6011) ID,PHIBEG,
     $                   PHIEND
                  ELSE
                    WRITE (ITOUT,FMT=60110) ID,((ID-1)*CHUNK)+1,
     $                   ID*CHUNK,PHIBEG,PHIEND
                    IF (BRIEF) WRITE (IBRIEF,FMT=60110) ID,
     $                   ((ID-1)*CHUNK)+1,
     $                   ID*CHUNK,PHIBEG,PHIEND
                  ENDIF
                END IF
              ELSE
                WRITE (ITOUT,FMT=6010) ID,ABC(FILM:FILM)
              END IF
              IF (EXTRAIMG.AND.(IPACK.EQ.NPACK)) WRITE(ITOUT,FMT=6013)
            END IF
C       
 6010       FORMAT (/1X,'********************',/1X,'PROCESSING FILM',
     +           I4,A,/1X,'********************')
 6011       FORMAT (/1X,'*******************************************',
     +           '*****',/1X,'Processing Image',I7,'  Phi',F8.2,' to',
     +           F8.2,/1X,'*****************************************',
     $           '*******')
60110       FORMAT (/1X,'*******************************************',
     $           '*******************************',
     $           '*******************',
     +           '*****',/1X,'Processing Virtual Image',I6,' which ',
     $           'contains real images ',I6,' to ',I6,'  Phi',
     +           F8.2,' to',F8.2,/1X,'*******************************',
     $           '*******************************',
     $           '*******************************',
     $           '*****')
 6013       FORMAT(/1X,'This image will only be processed up to the ',
     +           'point of generating the reflection list',/,1X,'so ',
     +           'that spatial overlapped summed partials are dealt ',
     $           'with.')
 6015       FORMAT (/1X,'*******************************************',
     +           '*****',/1X,'Integrating Image',I7,'  Phi',F8.2,
     +           ' to',F8.2,/1X,'***********************************',
     $           '*************')
60150       FORMAT (/1X,'*******************************************',
     $           '*******************************',
     $           '*******************',
     +           '*****',/1X,'Integrating Virtual Image',I6,' which ',
     $           'contains real images ',I6,' to ',I6,'  Phi',
     +           F8.2,' to',F8.2,/1X,'******************************',
     $           '*******************************',
     $           '*******************************',
     $           '*****')
C
            IF (DEBUG(1)) THEN
              WRITE(IOUT,FMT=6702) PROCES,FIRSTPASS,SECONDPASS,
     +                             THIRDPASS      
              IF (ONLINE) WRITE(ITOUT,FMT=6702) PROCES,FIRSTPASS,
     +                             SECONDPASS,THIRDPASS  
 6702         FORMAT(1X,'In MAIN, PROCES',L2,'  FIRSTPASS,',
     +                             'SECONDPASS,THIRDPASS',3L3)
            END IF  
            IF (IMGP) THEN
              IF (PROCES) THEN
c     if not proces then we're processing????
                write(dna_image, *) id
                call dna_output_table_start('integrating_image')
                call dna_output_list_start('image')
                call dna_output_integer_item('number', id)
                call dna_output_real_item('phi_start', phibeg)
                call dna_output_real_item('phi_end', phiend)
                call dna_output_list_end
                call dna_output_table_end
                WRITE (IOUT,FMT=6015) ID,PHIBEG,PHIEND
                IF(SOCKLO)THEN
C     HRP 12.05.2015
C---- Print for program flow - new code so that we can keep track of 
C     images being integrated - need this for resetting counters if we have
C     many refinement repeats.
C  
                  CALLED = 'WRITE_SOCKET'
                  COMMENT = 'Write XML image integrate begin'
                  IF (DEBUG(99)) 
     +                 CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
 6070             FORMAT('<?xml version="1.0"?>',
     $                 '<!DOCTYPE image_integrate_begin SYSTEM "">',
     $                 '<image_integrate_begin>',
     $                 '<status>',
     $                 '<code>ok</code>',
     $                 '</status>',
     $                 '<image_name>',A,'</image_name>',
     $                 '<image_template>',A,'</image_template>',
     $                 '<image_number>',I8,'</image_number>',
     $                 '</image_integrate_begin>')
                  WRITE(LONGLINE,FMT=6070)
     $                 SHORTFN(1:LENSTR(SHORTFN)),
     $                 TEMPLSAV(1:lenstr(templsav)),ID
                  CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                 LENSTR(LONGLINE),LONGLINE) 
                ENDIF
                
              ELSE
                   write(dna_image, *) id
                   call dna_output_table_start('processing_image')
                   call dna_output_list_start('image')
                   call dna_output_integer_item('number', id)
                   call dna_output_real_item('phi_start', phibeg)
                   call dna_output_real_item('phi_end', phiend)
                   call dna_output_list_end
                   call dna_output_table_end
                   IF(CHUNK.EQ.1)THEN
                     WRITE (IOUT,FMT=6011) ID,PHIBEG,PHIEND
                   ELSE
                     WRITE (IOUT,FMT=60110) ID,
     $                   ((ID-1)*CHUNK)+1,
     $                   ID*CHUNK,PHIBEG,PHIEND
                   ENDIF
                   IF (EXTRAIMG.AND.(IPACK.EQ.NPACK)) 
     $                 WRITE(IOUT,FMT=6013)
                   IF(TIMER)THEN
                     CALL CTIMER(MOSTIMEA)
                     write(iout,fmt=99999)mostimea-mostimeb
                   ENDIF
99999              FORMAT('Processing image took ',F9.3)
                   IF(SOCKLO)THEN
C
C---- Print for program flow
C  
                      CALLED = 'WRITE_SOCKET'
                      COMMENT = 'Write XML image process begin'
                      IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
 6020                 FORMAT('<?xml version="1.0"?>',
     $                     '<!DOCTYPE image_process_begin SYSTEM "">',
     $                     '<image_process_begin>',
     $                     '<status>',
     $                     '<code>ok</code>',
     $                     '</status>',
     $                     '<image_name>',A,'</image_name>',
     $                     '<image_template>',A,'</image_template>',
     $                     '<image_number>',I8,'</image_number>',
     $                     '</image_process_begin>')
                      WRITE(LONGLINE,FMT=6020)
     $                     SHORTFN(1:LENSTR(SHORTFN)),
     $                     TEMPLSAV(1:lenstr(templsav)),ID
                      CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                     LENSTR(LONGLINE),LONGLINE) 
                   ENDIF
                END IF
             ELSE
                 
                WRITE (IOUT,FMT=6010) ID,ABC(FILM:FILM)
              END IF
              IF (PROCES)THEN
C       
C----   For accumulated profiles this is the second pass.
C       for the firstfilm, the whole of the SPOTOD file will
C       be read and the profiles accumulated. For second and
C       subsequent films, these profiles will be used in measuring.
C       
                ADDPP = ADDP(IPACK)
C       
                IF (WINOPEN) THEN
                  CALL MXD_FLU(I)
                  CALL MXDBSY(0,'Integrating image')
                END IF
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6478)
                  IF (ONLINE) WRITE(ITOUT,FMT=6478)
 6478             FORMAT(1X,'In MAIN, PROCES is TRUE, calling PROCESS',
     +                   ' in SECONDPASS')
                END IF
C
C---- Print for program flow
C
              CALLED = 'PROCESS'
              COMMENT = 'Now in SECONDPASS '
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ******************************************
                IF (.NOT.NOMEAS) CALL PROCESS(NFLMO,IXSHIFT,IYSHIFT,
     +   ADDPP,ISKIPI,LPINTG,NEWPREF,NUSPOT,LPINTG,NOBACK,ID,NUMBLOCK,
     +   XMLABORT)
C       ******************************************
C
C---- Abort run if flag set.
C
                IF (XMLABORT) THEN
C
C---- Print for program flow
C
                  CALLED = 'MRESET'
                  COMMENT = 'Abort '
                  IF (DEBUG(99)) 
     +                       CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,
     +                        PRFSUMI)
                  GOTO 30
                END IF

                IF (WINOPEN) THEN
                  CALL MXD_FLU(I)
                  CALL MXDBSY(-1, ' ')
                END IF
C       
C----   Display residual vectors if requested, allows bad spot changes
C       
                IF (LPINTG.AND.FILMPLT) THEN
C       
C----   If processing more than a single image, need to read in the
C       image again as it will no longer be stored in memory. However,
C       the image must always be read into the same "half" of array
C       IMAGE because we need to keep the last image of the current BLOCK
C       of images in memory because it has not yet been processed.
C       To do this, must disable updating of the pointer ISTART in
C       OPENODS. Do this by setting MODEOP=3
C       
C       Note that ID has to be decremented by 1 (IDTMP=ID-1) when
C       SUMPART is true because OPENODS increments it by one.
C       
                  IF (NPACK.GT.1) THEN
                    IDTMP = ID
                    IF (SUMPART) IDTMP = ID - 1
                    MODEOP = 3
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6480) IDTMP,MODEOP
                      IF (ONLINE) WRITE(IOUT,FMT=6480) IDTMP,MODEOP
 6480                 FORMAT(1X,'In MAIN, call OPENODS for ID=',I4,
     +                          ' MODEOP=',I2,' to display residual',
     +                          ' vectors')
                    END IF
C       ********************************************************
C----   OPENODS called to display residual vectors
C       
C
C---- Print for program flow
C
                    CALLED = 'OPENODS'
                    COMMENT = 'To display residual vectors LIPROCESS=5'
                    IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    LIPROCESS = 5
                    CALL OPENODS(IDENT,IDTMP,FILM,ODEXT,FDISK,
     +                   MODEOP,PACK,ODFILE,SEPCHAR,FORCEREAD,IPACK,
     +                   TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
C       *******************************************************
                    MODEOP = 0
                  END IF
C       
C----   Need to set flag to repredict the pattern
C       ***** Displaying image after integration *****
C       
C       
C
C---- Print for program flow
C
                  CALLED = 'XDISP'
                  COMMENT = 'Display image after integration'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  MODEDISP = 5
                  CALL XDISP(MODEDISP,FIRSTPACK,PACK,IFIRSTPACK,
     +                 FIRSTFILM,GENOPEN)
                  IF (MODEDISP.EQ.99) THEN
C       
C----   Abort current run
C       
C
C---- Print for program flow
C  
                    CALLED = 'MRESET'
                    COMMENT = 'Abort '
                    IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,
     +                          PRFSUMI)
                    IF (DISPMENU) THEN
                      GOTO 34
                    ELSE
                      GOTO 30
                    END IF
                  END IF
                  IF (IPACK.EQ.NPACK) LPINTG = .FALSE.
C       
C----   End of display image block
C       
                END IF
C       
C       
C----   Write MTZ file
C       
c
c---- hrp07052002 - mtzout should have been set properly elsewhere, but
C     it seems not to be set if GENFILE hasn't been set explicity
C     - remind me to fix this properly. 
C
                if(mtzout.lt.1)mtzout = 1
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6482) ID+ISERADD
                  IF (ONLINE) WRITE(ITOUT,FMT=6482) ID+ISERADD
 6482             FORMAT(1X,'in MAIN, call WRMTZ to write MTZ file for',
     +                      ' ID=',I4)
                END IF
C
C---- Print for program flow. Don't do this is getting a phi profile
C  
                IF (.NOT.PHIPROF) THEN
                  CALLED = 'WRMTZ'
                  COMMENT = ' Write MTZ file in IF PROCES block'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL WRMTZ(ID+ISERADD,ADDPP,NEWPREF,
     +                     ALLOUT,NOLP,USEOVRLD,USEDGE,SCALEUP)
                  CALLED = 'RSYMM'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL RSYMM(PROFILE)
                END IF
                WRITE (IOUT,FMT=6142)
 6142           FORMAT (1X,/15 ('@@@@'),/)
                IF (ONLINE) WRITE (ITOUT,FMT=6142)
                IF (BRIEF) WRITE (IBRIEF,FMT=6142)
C       ****************************
                NFLMO = 1
C       
C----   Store information for summary file
C       
                NFILMS = NFILMS + 1
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6424) NFILMS
                  IF (ONLINE) WRITE(ITOUT,FMT=6424) NFILMS
 6424             FORMAT(1X,'NFILMS set to',I4,' for storing',
     +                ' info on integration for summary file')
                END IF
                ISUMM(9,NFILMS) = NOFR
                ISUMM(10,NFILMS) = NREF - NOFR
                ISUMM(11,NFILMS) = NOLO
                ISUMM(12,NFILMS) = NNEG
                ISUMM(13,NFILMS) = NBAD
                ISUMM(14,NFILMS) = NBGRJ
                ISUMM(20,NFILMS) = NRSYM
C----   I/sig(i) overall and in highest resolution bin
                RSUMM(5,NFILMS) = FIOVSDP(9)
                RSUMM(6,NFILMS) = FIOVSDP(8)
C----   If NO fully recorded reflections, use partials
C       
                IF (NRESPF(9).EQ.0) RSUMM(5,NFILMS) = PIOVSDP(9)
                IF (NRESPF(8).EQ.0) RSUMM(6,NFILMS) = PIOVSDP(8)
C----   Rsym
                RSUMM(7,NFILMS) = RFACOV
C----   SDRATIO for symmetry related reflections
                RSUMM(8,NFILMS) = SDRATOV
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6330) AVBGRATIO
                  IF (ONLINE) WRITE(ITOUT,FMT=6330) AVBGRATIO
 6330             FORMAT(1X,' AVBGRATIO =',F8.3)
                END IF
                AVBGRMAX = MAX(AVBGRMAX,AVBGRATIO)
                AVBGRMIN = MIN(AVBGRMIN,AVBGRATIO)
                GO TO 240
C       
C----   End of "IF (PROCES) block
C       
              END IF

C       
C----   Is this film to be treated as an A film ?
C       
              TREAT_AS_AFILM = ((BFILM.AND.FORCEB(IPACK)) .OR.
     +             (CFILM.AND.FORCEC(IPACK)))
C       
C       
              IF (TREAT_AS_AFILM) THEN
                IF (ONLINE) WRITE (ITOUT,FMT=6012)
 6012           FORMAT (1X,'This film will be processed as an ''A'' ',
     $               'FILM for positional refinement')
                WRITE (IOUT,FMT=6012)
              END IF
C       
C----   Assign camera constants for this pack if these have been
C       supplied. Skip this if readcc has been specified because
C       we want to use the values read from generate file.
C       Also skip this if Mar or R-axis image plate data because these
C       parameters should be constant from one image to the next.
C       
C----   Note that when using NOFID option, we want to reassign
C       camera constants for B and C films as well, because
C       they will not normally be the same as the A film.
C       
              IF ((AFILM.OR.TREAT_AS_AFILM.OR.NOFID) .AND.
     +             (.NOT.READCC).AND.(.NOT.IMGP)) THEN
                ICASSP = ICASSET(IPACK)
C       
C       
                IF (ICASSP.NE.0) THEN
                  CCX = CCXA(ICASSP)
                  CCY = CCYA(ICASSP)
                  CCOM = CCOMA(ICASSP)
                  IF (ONLINE) WRITE (ITOUT,FMT=6014) CCX,CCY,CCOM,CBAR
 6014             FORMAT (1X,'Camera constants assigned to this pack',
     $                 /,1X,'CCX=',I4,
     +                 ' CCY=',I4,' CCOM=',F6.3,' CBAR=',I4)
                  WRITE (IOUT,FMT=6014) CCX,CCY,CCOM,CBAR
                ELSE
C       
C----   Reassign values input via keywords
C       
                  CCX = SAVECCX
                  CCY = SAVECCY
                  CCOM = SAVECCOM
                END IF
C       
C----   Re-initialise other parameters
C       
                XTOFRA = SXTOFRA
                YSCAL = SYSCAL
C       
C       
                TILT = STILT
                TWIST = STWIST
                ROFF = SROFF
                BULGE = SBULGE
                BULGE2 = SBULGE2
                TOFF = STOFF
              END IF
C       
C       
              IF (NOFID .AND. READCC) THEN
C       
C----   Assign camera constants from generate file for this film
C       in the pack
C       
                CCX = CCXABC(FILM)
                CCY = CCYABC(FILM)
                CCOM = CCOMABC(FILM)
              END IF
C       
C       
              IF (DEBUG(1)) THEN
                WRITE (IOUT,FMT=6016) FILM,CCX,CCY,CCOM
                IF (ONLINE) WRITE (ITOUT,FMT=6016) FILM,CCX,CCY,CCOM
 6016           FORMAT (1X,'In MAIN, before FIDUS, CCX,CCY,CCOM for ',
     $               'FILM',I3,3X,2I5,F8.3)
              END IF
C       
C----   Update pointer to first strip of ods for film being processed
C       (set originally in openods)  (ONLY FOR IMPC style file format)
C       
C       
c       -vms        if (impc) icurr=(film-1)*nrec
              IF (.NOT.ONEFILE) ICURR = (FILM - 1) * NREC * NBYTE
C       
C       
C       
C----   Set flag to indicate which records of film image have been read
C**     Comment out for present, image all read in OPENODS
C       DO 70 I = 1,IXWDTH
C       RDSTRIP(I) = .FALSE.
C       70     CONTINUE
C       
C----   Set pointer in IMAGE in case image is not being store in core
C       
              IPOINT = 1
C       
C----   DOPROFILE indicates if ods have been stored for average
C       spot profile in centrs. this profile determination is controlled
C       by logical avprofile and is only done after at least one cycle
C       of refinement.
C       
              DOPROFILE = .FALSE.
C       
C----   If no fiducials, assign film centre
C       (in 10 mu units in scanner frame)
C       
              IF (NOFID) THEN
                XCENF = XCENMM(IPACK,FILM)*100.0
                YCENF = YCENMM(IPACK,FILM)*100.0
C       
C       
                IF (DEBUG(1)) THEN
                  IF (ONLINE) WRITE (ITOUT,FMT=6018) XCENF,YCENF,
     +                MACHINE,OMEGAF/DTOR,OMEGAFD,INVERTX,FILMPLT
 6018             FORMAT (1X,'In MAIN,XCENF,YCENF from direct beam ',
     $                 'coords',2F8.1,/,1X,'MACHINE IS ',A,
     +                 /,1X,'Omega (converted to degrees)',F7.2,
     +                 '  Omegafd',F7.3,'  INVERTX',L2,'  FILMPLT',L2)
                  WRITE (IOUT,FMT=6018) XCENF,YCENF,MACHINE,
     +                OMEGAF/DTOR,OMEGAFD,INVERTX,FILMPLT
                END IF
              END IF
C       
C----   Update XTOFRA for B and C films
C       
C----   Note special requirement if starting with the C film,
C       because the value stored on the generate file is for
C       the A film
C       
              IF (FILM.GT.1) XTOFRA = XTOFRA + 
     $             (THICK+THFOIL(FILM))/DTOFD
              IF (STARTC) XTOFRA = XTOFRA + (THICK+THFOIL(2))/DTOFD
C       
C----   Locate fiducial marks
C       
C----   Do this even when NOFID, so that direct beam (if any)
C       can be located.
C----   Note that if READCC is true CCX,CCY are not updated by
C       the position of the direct beam.
C       DO NOT call fidus for NOFID option
C       if READCC is specified (because CCX,CCY are read from
C       generate file),
C       or if using NOFID option and there is no direct beam.
C       
              IF ( (NFID.EQ.0) .AND. (READCC.OR. (MMDB.EQ.0))) GO TO 80
              NFOUND = 0
C
C---- Print for program flow
C  
              CALLED = 'FIDUS'
              COMMENT = ' '
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       
C       **********************************
              CALL FIDUS(NFOUND,ITHRESHF,NOFID,READCC)
C       **********************************
C       
 80           OMEGA0 = CCOM * DTOR + OMEGAF
              COSOM0 = COS(OMEGA0)
              SINOM0 = SIN(OMEGA0)
C       
C----   Must transform ccx,ccy before adding to xcenf,ycenf
C       ***** NOT ANY MORE ****
C       AL          CCXS = CCX*COSOM0 - CCY*SINOM0
C       AL          CCYS = CCX*SINOM0 + CCY*COSOM0
              CCXS = CCX
              CCYS = CCY
C       
              XCEN = XCENF + CCXS
              YCEN = YCENF + CCYS
c          write(iout,fmt=9878) xcen
c          if (online) write(itout,fmt=9878) xcen
c 9878     format(1x,'xcen set in mosflm-3 from xcenff, now;',F8.2)
              ICTF = XTOFD*XTOFRA
C       
              IF (DEBUG(1)) THEN
C       
C       
C                ITILT = TILT/FDIST
C                ITWIST = TWIST/FDIST
                CALL SETDIS(ITILT,ITWIST,2)
                IF (IMGP) THEN
                  IROFF = NINT(ROFF)
C       AL                IROFF2 = NINT(ROFF2)
                ELSE
                  IBULGE = BULGE/FDIST
                END IF
C       
C       
                WRITE (IOUT,FMT=6022) ICURR,NREC,IFILM,NFIRSTI,AFILM,
     +               STARTA,STARTB,STARTC,CCX,CCY,CCOM,CBAR,XTOFRA,
     +               YSCAL,IRAS,XCENF,YCENF,XCEN,YCEN
 6022           FORMAT (1X,'ICURR=',I6,'  NREC=',I6,' IFILM=',I3,
     +               ' NFIRSTI=',I3,'  AFILM=',L1,'  STARTA=',L1,
     +               ' STARTB=',L1,' STARTC=',L1,/1X,'CAMERA CONSTANTS',
     +               /1X,'CCX=',I4,' CCY=',I4,' CCOM=',F6.4,' CBAR=',I4,
     +               /1X,'XTOFRA=',F6.4,' YSCAL=',F6.4,/,1X,'IRAS',5I4,
     $               ' XCENF,YCENF',2F8.1,'XCEN,YCEN',2F8.1)
C       
C       
                WRITE (IOUT,FMT=6026) ITILT,ITWIST,IBULGE,
     +                      2.0*ETA/DTOR,2.0*SETA/DTOR
 6026           FORMAT (2X,'ITILT=',I4,' ITWIST=',I4,' IBULGE=',I4,
     +                  '  mosaic',F6.3,' saved mosaic',F6.3)
C       
C       
                IF (ONLINE) THEN
                  WRITE (ITOUT,FMT=6022) ICURR,NREC,IFILM,NFIRSTI,AFILM,
     +                 STARTA,STARTB,STARTC,CCX,CCY,CCOM,CBAR,XTOFRA,
     $                 YSCAL
C       
C       
                  WRITE (ITOUT,FMT=6026) ITILT,ITWIST,IBULGE,
     +                      2.0*ETA/DTOR,2.0*SETA/DTOR
                END IF
              END IF
C       
C----   Check all fiducials have been found, if not go to next pack
C       
              IF ((NFOUND.LT.NFID) .AND. (.NOT.NOFID)) THEN
C       
C----   If this was the firstfilm, change pack number of first good film
C       
                IF (FIRSTFILM) IFIRSTGOOD = IFIRSTGOOD + 1
                BADPACK(IPACK,IFILM) = .TRUE.
                NWRN = NWRN + 1
C       
C       
C----   If this is a multi-segment refinement, abandon it.
C       
                IF (MULTISEG) THEN
                  WRITE(IOUT,FMT=6210)
                  IF (ONLINE) WRITE(ITOUT,FMT=6210)
                  STOP
                END IF
C       
                IF (FIRSTPASS) THEN
                  NERR(IPACK) = 4
                  IXERR(IPACK) = NFOUND
                ELSE
C       
C       ****************************************************
                  CALL SUMMERR(ISUMMR,ID,4,NFPACK(IPACK),NFGEN,FILM,
     +                 NFOUND,X)
C       ****************************************************
C       
                END IF
                GO TO 250
              END IF
C       AL
C----   Generate the reflections for this pack
C       
 85           GWRITE = .TRUE.
              UPDATE = .TRUE.
              NRS = 0
C       
C----   If the spot separation OR raster parameters were not defined
C       by the user, determine appropriate values now from the very first
C       image to be processed.
C       
              IF (IPACK.EQ.IFIRSTP) THEN
                IF ((ISEP.EQ.0).OR.(IRAST.EQ.0)) THEN
                  MODEGSR = 0
C
C---- Print for program flow
C  
                  CALLED = 'GETSEPRAS'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL GETSEPRAS(IRAST,ISEP,IRAS,ID,MINDTX,MINDTY,
     +                 IXSEP,IYSEP,MODEGSR,IERR)
                  IF (IERR.NE.0) THEN
                    NSHUTERR = 4
                    CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                  END IF
                END IF
              END IF
C     
C----   If using "WIDTH" option, and this is a repeat run for the first
C       BLOCK of NADD images (because of an excessive shift in cell or
C       missetting angle), then pick up the refined missets for each image
C       rather than starting at beginning.
C       Introduce different tests for a MULTISEG run and an integration run
C       that uses a WIDTH.
C       
C       However, do not reassign missets if we are repeating this image
C       
              IF ((MULTISEG.AND.(NREPEAT.GT.0).AND.
     +             (.NOT.FIXED).AND.(.NOT.RPTIMG)).OR.
     +             ((NREPEAT.GT.0).AND.(.NOT.FIXED).AND.
     +             (IPACK.LE.NADD).AND.(.NOT.RPTIMG)))THEN
                ISUB = ISEG
                DO 83 I = 1,3
                  DELPHI(I) = DELPHIV((IPACK-ISUB)*3+I)
                  IF (NEWPREF) DELPHI(I) = RMISSETS(IPACK,I)
 83             CONTINUE
C       
C----   Reset direct beam coords
C       
                XCEN = SVXCEN(IPACK)
                YCEN = SVYCEN(IPACK)
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6027) NREPEAT,NADD,IPACK,DELPHI,XCEN,
     +                 YCEN            
                  IF (ONLINE) WRITE(ITOUT,FMT=6027) NREPEAT,NADD,
     +                 IPACK,DELPHI,XCEN,YCEN
                END IF
 6027           FORMAT(1X,'On repeat run number',I3,' over',I5,' ima',
     +               'ges reset the missets and beam coords for pack',
     +               I4,/,1X,'New missets:',3F9.3,'   New XCEN,YCEN',
     $               2F10.2)
              END IF
C
C----   Save detector parameters for use in smoothing. These will (in general)
C       be those for the previous image, or starting values for the first image.
C
              SMTWIST = TWIST
              SMTILT = TILT
              SMROFF = ROFF
              SMTOFF = TOFF
              SMOMEGA0 = ATAN2(SINOM0,COSOM0)
              SMXTOFRA = XTOFRA
              SMYSCAL = YSCAL
C       
C----   Generate the reflection list for this image, unless this is the first
C       image of the second (or subsequent) block of images which has
C       already been generated in order to allow for spatial overlap of
C       summed partials. In this case, FINDPACK will have been called (above).
C       Note that if NEWPREF post refinement is being done, this image will
C       NOT have been generated
C       
              IF ((IPACK.EQ.IFIRSTPACK).AND.(ADDPART.AND.(.NOT.NEWPREF))
     +             .AND.(NUMBLOCK.GT.1)) GOTO 87
C       
              IF (IFILM.EQ.1) THEN
C
C---- If not doing automatic reduction of mosaic spread or separation
C     to ensure not too many overlaps, skip the following.
C
                IF ((.NOT.CONTROLM).AND.(.NOT.CONTROLS)) GOTO 78                
C
C---- Set MODE for GENERATE. This call is just to check for an acceptable
C     number of overlaps, so do not write the generate file at this stage.
C
                MODEG = 2
                NADD_STORE = NADD
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6484) ID,MODEG
                  IF (ONLINE) WRITE(ITOUT,FMT=6484) ID,MODEG
 6484             FORMAT(/1X,'In MAIN, calling GENERATE with MODE=',I2,
     +                   ' (ie not writing genfile) for ID=',I4,
     +                   ' to check for excessive overlaps')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'GENERATE'
                COMMENT = 'MODE = 2, check acceptable overlaps,no write'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************************
 89             CALL GENERATE(MODEG,ID,GWRITE,UPDATE,LIMIT,POSTREF,
     +               NEWPREF,NFGEN,LOVERLAP,NFULLF)
C       ****************************************
                IF (NOVRLAP.GT.NINT(OVERLAPMAX*MSPOT)) THEN
C
C---- First check if this is due to overlap of adjacent spots
C     Get min spot separation from cell and check against actual spot size
C
C
C---- Print for program flow
C  
                  CALLED = 'GETSEPN'
                  COMMENT = 'get min sepn from cell, check spot size'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL GETSEPN(DSEP)
                  SPOTSIZ = MAX(0.01*MINDTX,0.01*MINDTY)
                  IF (DEBUG(1)) THEN
                    WRITE(IOUT,FMT=6025) NOVRLAP,MSPOT,2.0*ETA/DTOR,
     +                     DSEP,0.01*MINDTX,0.01*MINDTY,TOLMIN,TOL
                    IF (ONLINE) WRITE(ITOUT,FMT=6025) NOVRLAP,MSPOT,
     +                     2.0*ETA/DTOR,DSEP,0.01*MINDTX,0.01*MINDTY,
     +                     TOLMIN,TOL
 6025               FORMAT(1X,'Number of overlaps',I5,
     +              ' number of spots',I6,' mosaic',F5.2,/,1X,
     +              'Min spot separation based on cell',
     +              ' parameters',F5.2,'mm, spot size',2F5.2,'mm',
     +              '. Tolerance values',2F5.2)
                  END IF
                  IF ((DSEP.LE.SPOTSIZ).AND.CONTROLS) THEN
                   WARN(31) = .TRUE.
                   IF (MINDTX.GT.100*DSEP) MINDTX = MINDTX - 0.1*MINDTX
                   IF (MINDTY.GT.100*DSEP) MINDTY = MINDTY - 0.1*MINDTY
C
C---- Increment tolerance to try to keep the spot size small
C
                   IF (TOLMIN.LT.0.03) THEN
                     TOLMIN = TOLMIN + 0.01
                     TOL = TOL + 0.01
                   END IF
                   RESETSEP = .TRUE.
                   IF (DEBUG(1)) THEN
                     WRITE(IOUT,FMT=6486) 0.01*MINDTX,0.01*MINDTY,
     +                                    TOLMIN,TOL
                     IF (ONLINE) WRITE(ITOUT,FMT=6486) 0.01*MINDTX,
     +                            0.01*MINDTY,TOLMIN,TOL
 6486                FORMAT(1X,'In MAIN, go back and repeat GENERATE',
     +                     ' with min separation',2F5.2,'mm',
     +                     ' Tolerance values',2F5.2)
                   END IF  
                   GOTO 89
                  END IF
C
C---- If not due to adjacent reflection overlap, then must be due to lune
C     overlap. This can be overcome in two possible ways, either decreasing
C     minimum spot separation or decreasing mosaic spread. Try decreasing 
C     mosaic spread in steps of 5%.
C
                  IF (CONTROLM) THEN
                    WARN(30) = .TRUE.
                    ETA = ETA - 0.05*ETA
                    ETAMOD = ETA
                    RESETETA = .TRUE.
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6488) 2.0*ETA/DTOR
                      IF (ONLINE) WRITE(ITOUT,FMT=6488) 2.0*ETA/DTOR
 6488                 FORMAT(1X,'In MAIN, go back and repeat GENERATE',
     +                     ' with ETA set to',F6.2)
                    END IF  
                    GOTO 89
                  END IF
                END IF
                IF (RESETETA) THEN
                  WRITE(IOUT,FMT=6226) 2.0*ETA/DTOR
                  IF (ONLINE) WRITE(ITOUT,FMT=6226) 2.0*ETA/DTOR
 6226             FORMAT(/,1X,'Mosaic spread reset to',F6.2,' to avoid',
     +            ' spot overlap')
                END IF
C
C---- If overlaps were not being checked, above code is bypassed an GENERATE done here.
C     If overlaps are OK, now repeat generate but write the generate file this time
C
 78             MODEG = 1
                IF (FILMPLT) MODEG = 2
C       
C----   If this image is only being generated to allow for spatial overlap,
C       must write the generate file even if display option is being used.
C       
                IF (EXTRAIMG.AND.(IPACK.EQ.NPACK)) MODEG = 1
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6490) MODEG
                  IF (ONLINE) WRITE(ITOUT,FMT=6490) MODEG
 6490             FORMAT(/,1X,'In MAIN, calling GENERATE with MODE=',I2,
     +            /,1X,'Current cell',3F8.2,/)
                END IF
C
C---- Print for program flow
C  
                CALLED = 'GENERATE'
                IF (MODEG.EQ.1) THEN
                  WRITE(COMMENT,FMT=6491) MODEG
 6491             FORMAT('MODE = ',I1,' predict and write genfile')
                ELSE IF (MODEG.EQ.2) THEN
                  WRITE(COMMENT,FMT=6493) MODEG
 6493             FORMAT('MODE = ',I1,' predict but NOT write genfile')
                END IF
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************************
                CALL GENERATE(MODEG,ID,GWRITE,UPDATE,LIMIT,POSTREF,
     +               NEWPREF,NFGEN,LOVERLAP,NFULLF)
C       ****************************************

C
C---- Trap zero reflections predicted (can happen if resolution range is very restricetd)
C
                IF (NSPOT.EQ.0) THEN
                  STRING1 = ' '
                  WRITE(STRING1,FMT=64211) RES,RESLOW
64211             FORMAT(1X,'No reflections have been generated!__nl__',
     +              'Current resolution limits are',F8.2, 'to',F8.2,
     +           '__nl__If these look sensible, check detector limits.')
                  WRITE(LONGLINE,FMT=64212) STRING1(1:LENSTR(STRING1))
                  CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $              LENSTR(LONGLINE),LONGLINE)
64212             FORMAT('<?xml version="1.0"?>',
     $            '<!DOCTYPE trapped_error_response>',
     $            '<trapped_error_response>',
     $            '<type>No reflections generated</type>',
     $            '<message>',A,'</message>',
     $            '</trapped_error_response>')
C
                   CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                  PRFSUM,PRFSUMI)
                   GOTO 30
                END IF

C
C---- Assign number of refections that could be used over the entire image
C     for detector parameter refinement
C
                NUSEFUL = MSPOT - NOVRLAP - NWIDE - NLATTOVRLAP

C       
C----   If this is the very first image to be processed, and there is
C       an insufficient number of fully recorded reflections, set flag
C       to use partials in refinement.
C       
                IF (FIRSTPACK) THEN
                  IF (NSPOT.GT.0) RFP = REAL(NFULL)/REAL(NSPOT)
                  IF (RFP.LT.FULLFRAC) FIXPARTLS = .TRUE.
                  IF (FIXPARTLS) THEN
                    WRITE(IOUT,FMT=6230) FULLFRAC
                    IF (ONLINE) WRITE(ITOUT,FMT=6230) FULLFRAC
                  END IF
 6230             FORMAT(/,/,1X,'***** WARNING *****',/,1X,
     +                 '***** WARNING *****',/,1X,
     +                 '***** WARNING *****',/,1X,
     +                 'Because the fraction of fully recorded ',
     +                 'reflections is less than',F5.2,', partials',
     +                 /,1X,' will be included in the positional ',
     +                 'refinement.',/,1X,'This fraction can be ',
     +                 'reset with keywords REFINE FULLFRAC eg:',/,1X,
     +                 '"REFINE FULLFRAC 0.5" will change it to 0.5')
                  IF (WARN(26).AND.POSTREF.AND..NOT.NEWPREF) THEN
                    WRITE(IOUT,FMT=6360) NPRMIN
                    IF (ONLINE) WRITE(ITOUT,FMT=6360) NPRMIN
                  END IF
 6360             FORMAT(/,1X,1X,'***** WARNING *****',/,1X,
     +                 '***** WARNING *****',/,1X,
     +                 '***** WARNING *****',/,1X,
     +                 'There are fewer than ',I3,
     +                 ' partials extending over only',/,1X,'2 images.',
     +                 'Post-refinement can ONLY be carried out using ',
     +                 'reflections that extend',/,1X,'over 2 images.',
     +                 ' Thus if the mosaic spread (plus beam divereg',
     +                 'ence) is more than',/,1X,'twice the oscillati',
     +                 'on angle, post-refinement is not possible.',/,
     +                 1X,'You may want',' to use a larger oscillatio',
     $                 'n angle.')
                END IF
C       
C----   Store the pack header record number for this image. Note that NFILMS
C       has not yet been incremented, so use NFILMS+1 as pointer
C       
                IPACKSTART(NFILMS+1) = IPACKHEAD
C       
C----   If osc angle not specified, give NWMAX
C       
                IF ((ISTRT.EQ.0).OR.(IANGLE.EQ.0)) THEN
                  WRITE(IOUT,FMT=6031) NWMAX
                  IF (ONLINE) WRITE(ITOUT,FMT=6031) NWMAX
 6031             FORMAT(1X,'Partial reflections spanning more than',
     +                 I3,' images',' will NOT be integrated.',/,1X,
     +                 '(use MAXWIDTH to change).')
                END IF
C       
C----   If using ADDPART option, then spatially overlapped reflections occuring
C       at the start of the rotation range must be flagged as spatial overlaps
C       on the previous image. Do this by updating the IR flag in the 
C       generate file for the previous image if NPOVL > 0.
C       Do NOT need to do this if using NEWPREF postrefinement.
C       
                IF (ADDPART.AND.(NPOVL.GT.0).AND.(NFILMS.GT.0)
     +               .AND.(.NOT.NEWPREF)) THEN
                  IF (DEBUG(1)) THEN
                    WRITE(IOUT,FMT=6029) NPOVL,ID,NFILMS
                    IF (ONLINE) WRITE(ITOUT,FMT=6029) NPOVL,ID,NFILMS
 6029               FORMAT(1X,I5,' partial spatial overlaps for image ',
     +                   I7,'  NFILMS=',I3)
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'OVERLAP2'
                  COMMENT = '*** should never happen, ADDPART only ****'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL OVERLAP2(IPACKSTART(NFILMS))
                END IF
C       
C----   If this is the "extra" image, jump to end of loop now
C       
                IF (EXTRAIMG.AND.(IPACK.EQ.NPACK)) GOTO 250
C       
C----   If not yet done, store starting cell parameters. These are only
C       calculated after call to GENERATE.
C       
                IF (.NOT.STORCELL) THEN
                  DO 86 I=1,6
                    SCELL(I) = CELL(I)
 86               CONTINUE
                  STORCELL = .TRUE.
                END IF
              END IF
C       
C----   Badstart indicates if the starting residual in refinement
C       was poor. if this is the case, centrs will be repeated,
C       but only once.
C       
 87           BADSTART = .FALSE.
C       
C----   For B and C films, choose refinement spots using intensities
C       measured on the A film
C       This option can be overridden in online version
C       If no fiducials, use CENTRS on B and C films.
C       
              IF (FILM.GT.1 .AND. (.NOT.TREAT_AS_AFILM) .AND.
     +             (.NOT.NOFID)) GO TO 210
C       
              IF (FILMPLT) THEN
C       
                IF (NGR.EQ.7) THEN
                  MODEDISP = 0
C       
C----   ***** Display image prior to refinement
C       
                  imageno = id
C
C---- Print for program flow
C  
                  CALLED = 'XDISP'
                  COMMENT = ' Display image prior to refinement'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL XDISP(MODEDISP,FIRSTPACK,PACK,IFIRSTPACK,
     +                 FIRSTFILM,GENOPEN)
C       
                  IF (MODEDISP.EQ.99) THEN
C       
C----   Abort current run
C       
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,
     +                          PRFSUMI)
                    IF (DISPMENU) THEN
                      GOTO 34
                    ELSE
                      GOTO 30
                    END IF
                  END IF
C       
C----   If mosaic spread has changed, store new values
C       
                  IF (FIRSTPACK) THEN
                    SETA = ETA
                    SDIVH = DIVH
                    SDIVV = DIVV
                  END IF
                  IF ((MODEDISP.EQ.1).OR.(MODEDISP.EQ.3)) MATCH = .TRUE.
                END IF
C       
              END IF
C       
C
C---- Add images for use in centroid determination (for fine sliced Pilatus)
C     Only works for Pilatus, Eiger and TIMEpix images at present. Summed images
C     are storedin array IMAGES2. When working with first image it will add 
C     NIMGSUMREF images together. Do not call SUMIMG for the last NIMGSUMREF-1
C     images as the extra images will not exist (unless a partial integration is 
C     being carried out). For the very first image, we want to zero array IMAGE2
C     that is used to store summed images
C
              IF ((NIMGSUMREF.GT.1).AND.FIRSTPACK) THEN
                IF (DEBUG(92)) THEN
                  WRITE(IOUT,FMT=6704)
                  IF (ONLINE) WRITE(ITOUT,FMT=6704)
                END IF
 6704           FORMAT(/,1X,'Zeroing array IMAGE2 for summed images')
                NPIXTOT = NREC*IYLEN
                DO 84 K = 1,NPIXTOT
                  IMAGE2(K) = 0
 84             CONTINUE
              END IF
              IF ((NIMGSUMREF.GT.1).AND.
     +               ((NPACKSAVE-IPACK).GT.NIMGSUMREF-2)) THEN
                SUMIMGFORREF = .TRUE.
                COMMENT = ' '
                WRITE(COMMENT,FMT=6720) NIMGSUMREF
 6720           FORMAT('to add',I3,' images for centroid determination')
                IF (HDF5FILE) THEN
C
C---- Print for program flow
C  
                  CALLED = 'EIGER'
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
C---- Call EIGER with MODE=5 to sum images
C
                  CALL EIGER(IERR,5,ID,CHUNK,NIMGSUMREF)

                  IF (INVERTX) THEN
C     
C---- Print for program flow
C
                    CALLED = 'IMGINV'
                    COMMENT = 'because INVERTX is TRUE'
                    IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    CALL IMGINV(IMAGE2,NREC,IYLEN,0)
                  END IF
                ELSE          
                  CALLED = 'SUMIMG'
                  IF (DEBUG(99)) 
     +                CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL SUMIMG(ID,IDOLD,NIMGSUMREF,NIMGSUMOLDREF,
     +                      MPIXMIN,MPIXMAX,IREVERSE)
                END IF
              END IF
C       
C----   Automatic pattern matching option
C       

 88           IF (MATCH) THEN
C       
                ADDPP = ADDP(IPACK)
C
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6492) ID      
                  IF (ONLINE) WRITE(ITOUT,FMT=6492) ID       
 6492             FORMAT(1X,'In MAIN, calling AUTOMATCH for ID=',I4)
                END IF
C
C---- Print for program flow
C  
                CALLED = 'AUTOMATCH'
                COMMENT = ' '
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       
C       ******************************************************
                CALL AUTOMATCH(ID,DOPROFILE,NSIG,IXSHIFT,IYSHIFT,
     +               NPROFL,LIMIT,SEP,VLIM,FAIL,LIST,USEBOX,
     +               ADDPP,RWEIGHT,PTMIN,
     +               REFREJ,THICK,FIRSTFILM,NUMBLOCK,MOSEST,
     +               NIMGSUMREF,NUSEFUL,IERR2)
C       ******************************************************
C
C---- Write XML document to send refined missets back to iMosflm
C
                IF (SOCKLO) THEN
                  WRITE(LONGLINE,FMT=6670) ODFILE(1:LENSTR(ODFILE)),
     $                 TEMPLSAV(1:lenstr(templsav)),ID,
     +                 (DELPHI(I),I=1,3)
                  CALL WRITE_SOCKET_LENGTH
     $              (SERVERFD,LENSTR(LONGLINE),LONGLINE)
 6670             FORMAT('<?xml version="1.0"?>',
     +            '<!DOCTYPE pattern_matching_response>',
     +            '<pattern_matching_response>',
     +            '<status><code>ok</code></status><imagefile>',A,
     +                 '</imagefile>',
     $                 '<image_template>',A,'</image_template>',
     $                 '<image_number>',I8,'</image_number>',
     $                 '<phi_x>',f8.3,'</phi_x><phi_y>',f8.3,
     +            '</phi_y><phi_z>',f8.3,'</phi_z>',
     +            '</pattern_matching_response>')
                END IF
                prfsum(IFIRSTPACK,1) = DELPHI(1)
                prfsum(IFIRSTPACK,2) = DELPHI(2)
                prfsum(IFIRSTPACK,3) = DELPHI(3)
                DELPHIV(1) = DELPHI(1)
                DELPHIV(2)= DELPHI(2)
                DELPHIV(3) = DELPHI(3)
C       
C----   Don't generate reflection list if refining mosaic spread, or if
C       orientation refinement has failed
C       
                IF (FAIL.OR.RMOSAIC) GO TO 260
                UPDATE = .FALSE.
                GWRITE = .TRUE.
C       
C----   Reposition the generate file to start of first pack
C       NB This assumes AUTOMATCH is only ever run on the FIRST image in
C       the generate file, and not for subsequent images. In principle 
C       there is no reason why it should not be run on every image, but
C       this is not yet implemented
C       
C
C---- Print for program flow
C  
                CALLED = 'QSEEK'
                COMMENT = ' Reposition genfile to start of first pack'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL QSEEK(IUNIT,21,1,36)
                IPACKREC = 21
                IPACKHEAD = IPACKREC
                MODEG = 4
C       
C----   If using X-window display, do not want to write the generate file yet
C       as parameters may be updated.
C       
                IF (FILMPLT) MODEG = 2
C
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6494) MODEG       
                  IF (ONLINE) WRITE(IOUT,FMT=6494) MODEG
 6494             FORMAT(1X,'In MAIN, after AUTOMATCH, call GENERATE',
     +                   ' with MODE=',I2)
                END IF
C
C---- Print for program flow
C  
                CALLED = 'GENERATE'
                WRITE(COMMENT,FMT=6491) MODEG
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************************
                CALL GENERATE(MODEG,ID,GWRITE,UPDATE,LIMIT,POSTREF,
     +               NEWPREF,NFGEN,LOVERLAP,NFULLF)
C       ****************************************
C       
                IF (WINOPEN) CALL MXD_FLU(I)
C
C---- If not going on to integrate this image, must send integration_response
C     XML back to iMosflm to clear the "Integration" task for the job queue.
C
                IF (SOCKLO.AND.NOMEAS) THEN
                  WRITE(LONGLINE,FMT=6680) SHORTFN(1:LENSTR(SHORTFN)),
     $                 TEMPLSAV(1:lenstr(templsav)),ID
                  CALL WRITE_SOCKET_LENGTH
     $              (SERVERFD,LENSTR(LONGLINE),LONGLINE)
 6680             FORMAT ('<?xml version="1.0"?>',
     +                 '<!DOCTYPE integration_response>',
     +                 '<integration_response><status>',
     +                 '<code>pattern_match</code>',
     +                 '</status><image_name>',A,'</image_name>',
     $                 '<image_template>',A,'</image_template>',
     $                 '<image_number>',I8,'</image_number>',
     +                 '</integration_response>')
                  MATCH = .FALSE.
                  NOMEAS = .FALSE.
                  GOTO 260
                END IF
C
C---- Have moved this next line to above rather than after the "GOTO 260"
C     otherwise MATCH did not get set FALSE when image was not actually
C     integrated AGWL 4/11/14

                MATCH = .FALSE.
                IF (NOMEAS) GO TO 260
C       
C----   If at least 10 fully recorded reflections in newly generated
C       reflection list don't bother to call CENTRS again
                IF (NFULLF.GT.10) GO TO 140
              END IF
C       
C----   Find refinement spots in central portion of film
C       cycle through the refinement of central part of film
C       NCYC times (default=2)
C       
C----   If NOFID, select refinement spots for B and C films based on
C       measured intensities of preceeding film for CENTRS.
C       
              GENLIST = (NOFID .AND. (FILM.GT.1))
 90           CONTINUE
C       
              IF (BRIEF) WRITE(IBRIEF,FMT=6206)
 6206         FORMAT(1X,'Refining detector parameters using spots from',
     +             ' centre of image')
C       
C----   Do initial call to set up standard profiles and to RMAXR to
C       calculate box sizes, as these are needed by NEXT. For IP data,
C       only need to do this once, but for film data the position of
C       the direct beam in the digitised image can vary from one
C       pack to the next, so need to set it up for every pack.
C       (Same will be true for IP data from an offline scanner)
C       
              IF (.NOT.IMGP) THEN
                CALL PRSETUP
C       ***********************
                IF (FIRSTFILM) CALL RMAXR(LIMIT,THICK,IERR2)
C       ***********************
              ELSE
                IF (FIRSTFILM.AND.NUMBLOCK.EQ.1) THEN
C
C---- Print for program flow
C  
                  CALLED = 'PRSETUP and RMAXR'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL PRSETUP
                  CALL RMAXR(LIMIT,THICK,IERR2)
                  IF ((IERR2.EQ.1).AND.DISPMENU.and.winopen) THEN
                    WRITE(LINE,FMT=6208) IRAS(1),IRAS(2)
 6208               FORMAT('Overall dimensions of measurement box ',
     $                   'reduced to:',2I4)
                    L = LENSTR(LINE)
                    IXP = 400
                    IYP = 400
                    CALL MXD_POP(IXP,IYP, XDLSTR(LINE),L,
     +                   XDLSTR(' '),0,XDLSTR('OK'),2,XDLSTR(' '),
     +                   -1,3,0,IBUTTON)
                  END IF
                  IF (IERR2.EQ.2) THEN
C
C---- Print for program flow
C  
                    CALLED = 'MRESET'
                    COMMENT = 'Meas box too big, reset or shutdown'
                    IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    IF (DISPMENU) THEN
C       
C----   If running interactively, trap measurement box being too big
C       
                      CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,
     +                            PRFSUMI)
                      GOTO 34
                    ELSE
                      NSHUTERR = 5
                      CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                    END IF
                  END IF
                END IF
              END IF
C       
              IF (WINOPEN) CALL MXDBSY(0,'Refining detector parameters')
C       
C----   Initialise RRWEIGHT true if using peak/background mask, else false
C       
              RRWEIGHT = USEBOX
C
C----  If calculating phi profile skip all spot fiding etc
C
              IF (PHIPROF) GOTO 224
C       
              DO 110 ICYC = 1,NCYC
C       
                IF (WINOPEN) CALL MXD_FLU(I)
C
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6496) ICYC       
                  IF (ONLINE) WRITE(ITOUT,FMT=6496) ICYC       
 6496             FORMAT(/,1X,'In MAIN, doing refinement cycle',I2)
                END IF
                FINAL = (ICYC.EQ.NCYC)
                IF (ONLINE) THEN
C       
                  WRITE (ITOUT,FMT=6028) ICYC
 6028             FORMAT (/1X,'Refinement cycle',I3)    
                END IF
C       
C       
                WRITE (IOUT,FMT=6028) ICYC
C       
C----   In CENTRS, the background definition of the measurement box
C       is not used to determine the centre of gravity (the c of g over
C       the whole measurement box is calculated...this gives a greater
C       range of convergence). in second and subsequent cycles, if the
C       final residual of the previous cycle is less then rmslim
C       (default value 6.0, can be changed by keyword "resid"), use the
C       same list of reflections and s/r 'next' to evaluate the true
C       c of g for these reflections
C       
                IF (RRWEIGHT) THEN
                  OKREF = (WRMSRES.LE.WRMSLIM)
                ELSE
                  OKREF = (RMSRES.LE.RMSLIM)
                END IF
 104            IF (ICYC.EQ.1) OKREF = .FALSE.
C       
                IF ((ICYC.GT.1) .AND. (OKREF)) THEN
C       
C----   For 2nd and subsequent cycles use NEXT if refinement is OK
C       
                  LIST = .TRUE.
C       
C----   Restore original list of reflections from CENTRS so they are 
C       all remeasured by NEXT
C       
                  NRS = NRSOLD
                  DO 106 I = 1,NRS
                    RRS(I) = IRSAVE(I)
 106              CONTINUE
                  IF (USEBOX) THEN
                    WRITE(IOUT,FMT=6100) NRS
                    IF (ONLINE) WRITE(ITOUT,FMT=6100) NRS
 6100               FORMAT(/1X,'Repeating refinement using the same ',
     +                   'list of',I4,' reflections')
                  ELSE
                    IF (ONLINE) WRITE (ITOUT,FMT=6058) NRS
 6058               FORMAT (/1X,'Repeating refinement using the ',
     $                   'same list of',I4,' Reflections and using',/,
     $                   1X,'the peak/background mask')
                    WRITE (IOUT,FMT=6058) NRS
                  END IF
C       
                  CENTRAL = .TRUE.
                  IF (DEBUG(1)) THEN
                    WRITE(IOUT,FMT=6498) NRS
                    IF (ONLINE) WRITE(ITOUT,FMT=6498) NRS
 6498               FORMAT(1X,'In MAIN, calling NEXT, NRS=',I4)
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'NEXT'
                  WRITE(COMMENT,FMT=6497) ICYC
6497              FORMAT('Cycle ',I1)
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       *****************************************************
                  CALL NEXT(LIST,IXSHIFT,IYSHIFT,PRECESS,MATCH,IFAIL,
     +                 PARTLS,ADDPP,CENTRAL,NSIG,NIMGSUMREF)
C       *****************************************************
C       
                  USEWEIGHT = .TRUE.
C       
C----   If not enough reflections now, go back to CENTRS, but only allow
C       this to happen once.
C       
                  IF ((NRS.LT.MINREF).AND.(.NOT.DONEONCE)) THEN
                    MINREFS = MINREF
                    CENTRSRPT = .TRUE.
                    DONEONCE = .TRUE.
C
C---- Cannot understand why MINREF is increased here, so comment out
C     AGWL 6/5/15
C                    MINREF = MINREF + MINREF/2
                    OKREF = .FALSE.
                    GOTO 104
                  END IF
C       
                ELSE
C       
C----   otherwise use CENTRS
C       
                  USEWEIGHT = .TRUE.
                  MATCH = .FALSE.
                  PARTLS = .FALSE.
                  OVRLDS = .FALSE.
                  OLDLIST = (ICYC.NE.1)
                  IF (FIXPARTLS) THEN
                    PARTLS = .TRUE.
                    FIXPARTLS = .FALSE.
                  END IF
                  IF (USEPAR) PARTLS = .TRUE.
                  IF (USEOVR) OVRLDS = .TRUE.
                  IF (.NOT.USEBOX) THEN
                    WRITE(IOUT,FMT=6057)
                    IF (ONLINE) WRITE(ITOUT,FMT=6057)
C       
C----   If not using the box, can't get sd's of centroids so refinement
C       must be unweighted
C       
                    USEWEIGHT = .FALSE.
C       
C----   If doing weighted refinement, set RMSLIM high so that on next
C       cycle it will use the peak/background mask and weighted refinement.
C       
                    IF (RWEIGHT) RMSLIM = 100.0
                  END IF
 6057             FORMAT(1X,'The peak/background mask will not be ',
     +                 'used in determining centroids and the',/,1X,
     +                 'refinement will not be weighted')
C       
C----   Set ADDPART flag for this image (will always be false for last
C       image to be measured)
C       
                  ADDPP = ADDP(IPACK)
                  IF (DEBUG(1)) THEN
                    WRITE(IOUT,FMT=6499)
                    IF (ONLINE) WRITE(ITOUT,FMT=6499)
 6499               FORMAT(1X,'In MAIN, calling CENTRS')
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'CENTRS'
                  WRITE(COMMENT,FMT=6497) ICYC
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ***************************************************
                  CALL CENTRS(DOPROFILE,NSIG,IXSHIFT,IYSHIFT,NPROFL,
     +                 LIMIT,SEP,VLIM,MATCH,PARTLS,OVRLDS,MINREF,
     +                 OLDLIST,GENLIST,USEBOX,ADDPP,PTMIN,NIMGSUMREF,
     +                 NUSEFUL)
C       ***************************************************
C       
C----   If this was a repeat of CENTRS because a previous call to NEXT
C       did not find enough reflections, restore MINREF to true value
C       
                  IF (CENTRSRPT) THEN
                    MINREF =  MINREFS
                    CENTRSRPT = .FALSE.
                  END IF
C       
C----   IF this is the first image and PARTLS is true and the user has
C       not explicitly requested inclusion of partials in forming profiles,
C       then set flag for including partials in profile fitting also.
C       
                  IF (PARTLS.AND.FIRSTPACK.AND.(.NOT.ADDPART)
     +                 .AND.(.NOT.PRPART)
     +                 .AND.(.NOT.PRFULLS)) THEN
                    IF (USEPAR) THEN
                      WRITE(IOUT,FMT=6102)
                      IF (ONLINE) WRITE(ITOUT,FMT=6102)
                    ELSE
                      WRITE(IOUT,FMT=6103)
                      IF (ONLINE) WRITE(ITOUT,FMT=6103)
                    END IF
 6102               FORMAT(1X,'***** WARNING *****',/,1X,
     +                   '***** WARNING *****',/,1X,
     +                   '***** WARNING *****',/,1X,
     +                   'Because you have requested inclusion ',
     +                   'of partials in refinement (REFINEMENT',
     +                   ' INCLUDE PARTIALS)',/,1X,'partials wi',
     +                   'll be used in forming the standard pr',
     $                   'ofiles.',/,1X,'This is equivalent to ',
     +                   'including keywords: PROFILE PARTIALS',
     +                   /,1X,'If you do NOT want to include pa',
     +                   'rtials in forming profiles, use keywo',
     +                   'rds:  PROFILE FULLS')
C       
 6103               FORMAT(1X,'***** WARNING *****',/,1X,
     +                   '***** WARNING *****',/,1X,
     +                   '***** WARNING *****',/,1X,
     +                   'Because there are very few fully reco',
     +                   'rded reflections in the central region',
     +                   /,1X,'of the image, partials will be u',
     +                   'sed in forming the standard',/,1X,'pr',
     +                   'ofiles. This is equivalent to includi',
     +                   'ng keywords: PROFILE PARTIALS',/,1X,
     +                   'If you do NOT want to include partial',
     +                   's in forming profiles, use keywords: ',
     +                   ' PROFILE FULLS')
                    PRPART = .TRUE.
                    WTPROFILE = .FALSE.
                    WARN(23) = .TRUE.
                  END IF
C       
C----   Update USEPAR if PARTLS has been set true in CENTRS because not enough
C       fully recorded reflections have been found
C       Set warning flag if use of partials was not requested by user
C       
                  IF (PARTLS.AND.(.NOT.WARN(22).AND.(.NOT.USEPAR))) THEN
                    USEPAR = .TRUE.
                    WARN(22) = .TRUE.
                    IWARN(1,22) = ID
                  END IF
                  NRSOLD = NRS
C       
C----   Save this list of reflections for use in subsequent refinement using
C       NEXT
C       
                  DO 108 I = 1,NRS
                    IRSAVE(I) = RRS(I)
 108              CONTINUE
                END IF
C       
C---- Jump forward if enough reflections found
C       
                IF (NRS.GE.MINREF) GO TO 100
C
C---- If NRS has dropped below MINREF when using a list of reflections
C     using NEXT instead of CENTRS, this means that it did find enough reflections
C     in the first cycle (using CENTRS) so is probably OK as only a very few
C     reflections will have been rejected. So allow to continue providing there
C     are at least 5 reflections.
C
                IF (LIST.AND.(NRS.GT.5)) GOTO 100
C
                WRITE (IOUT,FMT=6030) NRS
 6030           FORMAT (' Only',I6,' Refinement SPOTS found')
                IF (BRIEF) WRITE (IBRIEF,FMT=6030) NRS
                IF (ONLINE) WRITE (ITOUT,FMT=6030) NRS
C       
C----   if online, do FILMPLOT, otherwise go on to the next pack
C       
                IF (ONLINE) THEN
C
C---- If using iMosflm, send warning message and prepare for more input
C
                  IF (SOCKLO) THEN
                    STRING1 = ' '
                    WRITE(STRING1,FMT=60301) NRS,ID
60301               FORMAT('Only',I3,' reflections found for detector ',
     +              'parameter refinement for image ',I7,'.__nl__Check',
     +              ' that the prediction looks OK for this image',
     +              '__nl__and the measurement box size matches the',
     +              ' spots.',
     +              '__nl__If prediction is bad, try reindexing.',
     +              '__nl__If measurement box size is wrong, reset via',
     +              '__nl__Settings -> Processing options -> Advanced ',
     +              'integration tab__nl__')
                    IF (NRS.GT.5) THEN
                      STRING2 = ' '
                      WRITE(STRING2,FMT=60302) MINREF
60302                 FORMAT('If prediction is OK, try reducing the ',
     +                'minimum number of reflections __nl__',
     +                'currently set to:',I4,'__nl__',
     +                '(Use Settings -> Processing options -> Advanced',
     +                ' refinement tab)')
                      STRING1 = STRING1(1:LENSTR(STRING1))//
     +                          STRING2(1:LENSTR(STRING2))
                    END IF
                    WRITE(LONGLINE,FMT=60304) STRING1(1:LENSTR(STRING1))
                    CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                LENSTR(LONGLINE),LONGLINE)
60304               FORMAT('<?xml version="1.0"?>',
     $             '<!DOCTYPE trapped_error_response>',
     $             '<trapped_error_response>',
     $             '<type>too_few_refinement_reflections</type>',
     $             '<message>',A,'</message>',
     $             '</trapped_error_response>')
C
C---- Must set MULTISEG to FALSE, otherwise if doing a cell refinement, it 
C     will simply try to process the next block of images and then crash.
C
                   MULTISEG = .FALSE.
                   CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                   GOTO 30
                  END IF




                  WRITE (ITOUT,FMT=6032)
                  IF (BRIEF) WRITE (IBRIEF,FMT=6032)
 6032             FORMAT (1X,'You may either abandon this image or ',
     +                 'inspect the image',/1X,'Do you want to insp',
     $                 'ect the image (Y/N) ? ',$)
C       
C       **********        
c
c     server interaction modifications ...
                  CALL YESNO(YES)
C       **********
C       
                  IF (YES) THEN
C       
                    MODEDISP = 0
C       
C----   ***** Display after failure of refinement *****
C       
C
C---- Print for program flow
C  
                    CALLED = 'XDISP'
                    COMMENT = 'Refinement failed '
                    IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    CALL XDISP(MODEDISP,FIRSTPACK,PACK,IFIRSTPACK,
     +                   FIRSTFILM,GENOPEN)
C       
                    IF ((MODEDISP.EQ.1).OR.(MODEDISP.EQ.3)) THEN
                      MATCH = .TRUE.
                      GOTO 88
                    ELSE IF (MODEDISP.EQ.99) THEN
C       
C----   Abort current run
C       
                      CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,
     +                            PRFSUMI)
                      IF (DISPMENU) THEN
                        GOTO 34
                      ELSE
                        GOTO 30
                      END IF
                    END IF
C       
C       
C----   Repeat CENTRS for adjusted pattern
C       
                    GO TO 90
                  END IF
                ELSE
                  WARN(4) = .TRUE.
                  IWARN(1,4) = IWARN(1,4) + 1
                  I = IWARN(1,4) + 1
                  IF (I.LE.MAXIWARN) IWARN(I,4) = ID
                  IF (LIST) THEN
                    WRITE(IOUT,FMT=6033) MINREF
 6033               FORMAT(1X,'If there were only just over',I4,' re',
     +                   'flections in the list, try increasing LIMIT',
     $                   ' or',/,1X,'decreasing',
     +                   ' NSIG on the REFINEMENT keyword',/,1X,
     +                   '*****  ABANDONING PROCESSING, going on to',
     +                   ' next image *****',//)
                  ELSE
                    WRITE (IOUT,FMT=6034) MINREF
 6034               FORMAT (///1X,'The failure to find at least',I4,
     +                   ' spots may mean that there i',
     $                   's an',/,1X,'error in the predicted pattern',
     +                    /,1X,'for ',
     +                   'this image'/,1X,'You are strongly advised',
     +                   ' to use the iMosflm GUI to s',
     +                   'ee what ',/,1X,'is wrong',/,1X,
     +                   '*****  ABANDONING PROCESSING, going on to',
     +                   ' next image *****',//)
                  END IF
                END IF
C       
C----   If this was the firstfilm, change pack number of first good film
C       
                IF (FIRSTFILM) IFIRSTGOOD = IFIRSTGOOD + 1
                BADPACK(IPACK,IFILM) = .TRUE.
                NWRN = NWRN + 1
C       
C       
C----   If this is a multi-segment refinement, abandon it, but trap this error
C       (too few reflections) if using iMosflm.
C       
                IF (MULTISEG) THEN
                  WRITE(IOUT,FMT=62120)
                  IF (ONLINE) WRITE(ITOUT,FMT=62120)
62120             FORMAT(//1X,' A multisegment post-refinement will ',
     +                 'NOT work if images have been rejected',/,1X,
     $                 'Use the interactive graphics to find out why',
     $                 ' so few reflections are found for this image.')
                  IF (SOCKLO) THEN
                    STRING1 = ' '
                    WRITE(STRING1,FMT=6211) NRS,IPACK
 6211               FORMAT('Only',I3,' reflections found for detector ',
     +              'parameter refinement for image ',I7,'.__nl__Check',
     +              ' that the prediction looks OK for this image.',
     +              '__nl__')
                    IF (NRS.GT.10) THEN
                      STRING2 = ' '
                      WRITE(STRING2,FMT=6213)
 6213                 FORMAT('If prediction is OK, try reducing the ',
     +                'minimum number of reflections __nl__',
     +                '(Processing options -> Advanced refinement tab)')
                      STRING1 = STRING1(1:LENSTR(STRING1))//STRING2
                    END IF
                    WRITE(LONGLINE,FMT=6215) STRING1(1:LENSTR(STRING1))
                    CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                LENSTR(LONGLINE),LONGLINE)
 6215              FORMAT('<?xml version="1.0"?>',
     $             '<!DOCTYPE trapped_error_response>',
     $             '<trapped_error_response>',
     $             '<type>too_few_refinement_reflections</type>',
     $             '<message>',A,'</message>',
     $             '</trapped_error_response>')
                  END IF
                  STOP
                END IF
C       
                IF (FIRSTPASS) THEN
                  NERR(IPACK) = 5
                  IXERR(IPACK) = NRS
                ELSE
C       
C       ***************************************************
                  CALL SUMMERR(ISUMMR,ID,5,NFPACK(IPACK),NFGEN,FILM,
     $                 NRS,X)
C       ***************************************************
C       
                END IF
C       
C       
                GO TO 250
C       
C----   REFINEMENT
C       ==========
C       
 100            CONTINUE
                IF (.NOT.NOREF) THEN
C       
C----   In CENTRS, only spots within 'LIMIT' 10 micron units (default 25mm)
C       of film centre are used
C       These limits can be changed by keywords 'limit'
C       in centrs if all central reflections are overloads.
C       
                   CENTRE = .TRUE.
                   XMLONLY = .FALSE.
C       
C       
C       
C       
                   RRWEIGHT = (RWEIGHT.AND.USEWEIGHT)
C       
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6500)
                      IF (ONLINE) WRITE(ITOUT,FMT=6500)
 6500                 FORMAT(/,1X,'In MAIN, calling RDIST')
                    END IF
C
C---- Print for program flow
C  
                    CALLED = 'RDIST'
                    WRITE(COMMENT,FMT=6497) ICYC
                    IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ******************************************
                   CALL RDIST(IPACK,ID,NIMGSM,CENTRE,FINAL,WELIMIT,
     +                  ELIMIT,ELIMIT2,ELIMIT3,BADSTART,RRWEIGHT,
     +                  REFREJ,XMLONLY,RESCALE)
C       ******************************************
C     
                   CENTRE = .FALSE.
                ENDIF
C       
C----   End of loop over refinement cycles
C       
 110         CONTINUE
C       
              IF (RWEIGHT) THEN 
                IF (WRMSRES.LT.WRMSLIM) GO TO 130
              ELSE
                IF (RMSRES.LT.RMSLIM) GO TO 130
              END IF
C
C---- Positional residual exceeds limit. If running interactively,
C     give user possible options (abort or continue with limits reset).
C     If running with new gui, take no action, as options will be given
C     explicitly by the GUI.
C     In fact the "DOCTYPE refinement_error" is not currently processed by
C     iMosflm so it will have no effect at all. AGWL 12/6/18
C
              IF (SOCKLO) THEN
C
C---- Print for program flow
C  
                CALLED = 'WRITE_SOCKET'
                COMMENT = 'Write XML refinement error'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                LONGLINE = ' '
 7300           FORMAT('<?xml version="1.0"?>',
     $               '<!DOCTYPE refinement_error>',
     $               '<refinement_error>',
     $               '<status>',
     $               '<code>ok</code>',
     $               '</status>',
     $               '<type>weighted_residual</type>',
     $               '<image_name>',A,'</image_name>',
     $               '<image_template>',A,'</image_template>',
     $               '<image_number>',I8,'</image_number>',
     $               '<absolute_rms_residual>',F8.3,
     $               '</absolute_rms_residual>',
     $               '<absolute_rms_residual_limit>',F8.3,
     $               '</absolute_rms_residual_limit>',
     $               '<weighted_rms_residual>',F7.2,
     $               '</weighted_rms_residual>',
     $               '<weighted_rms_residual_limit>',F7.2,
     $               '</weighted_rms_residual_limit>',
     $               '</refinement_error>')
                WRITE(LONGLINE,FMT=7300)SHORTFN(1:LENSTR(SHORTFN)),
     $               TEMPLSAV(1:lenstr(templsav)),ID,
     $               RMSRES,RMSLIM,WRMSRES,WRMSLIM
                CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $               LENSTR(LONGLINE),LONGLINE)
                GOTO 130
              ENDIF
C
              IF (ONLINE) THEN
                IF (WINOPEN) THEN
                  IXM = 200
                  IYM = 200
                  LINELEN = 75
                  NUMLIN = 9
C       
C       Create IO window
C       
                  CALL MXDCIO(0,LINELEN, NUMLIN, IXM,IYM)
                  LINE = ' '
                  WRITE(LINE,FMT=6320) WRMSRES
 6320             FORMAT('Final weighted residual (',F4.1,') is too ',
     $                 'large.')
                  CALL MXDWIO(LINE,1)
                  LINE = ' '
                  WRITE(LINE,FMT=6322) WRMSLIM
 6322             FORMAT('(Maximum is',F5.1,' set by subkeyword RESID',
     +                 ' of keyword REFINEMENT)')
                  CALL MXDWIO(LINE,1)
                  LINE = ' '
                  WRITE(LINE,FMT=6324)
 6324             FORMAT('You can either reset the maximum value and ',
     +                 'continue or abort processing.')
                  CALL MXDWIO(LINE,1)
                  LINE = ' '
 112              WRITE(LINE,FMT=6326)
 6326             FORMAT('Do you want reset the maximum residual (Y):')
                  CALL MXDWIO(LINE, 1)
                  CALL MXDRIO(LINE2)
C       
C----   Parse reply
C       
C       ******************************************
                  CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C       ******************************************
                  IF (NTOK.EQ.0) THEN
                    STR1 = 'Y'
                  ELSE
                    STR1 = LINE2(IBEG(1):IEND(1))
                    CALL CCPUPC(STR1)
                  END IF
                  IF (STR1.EQ.'Y') THEN
C       
C----   Get max residual
C       
                    LINE = ' '
                    WRMSLIM = 100.0
 114                WRITE (LINE, 6328) WRMSLIM
 6328               FORMAT(1X,'New maximum residual (',F6.1,') :')
                    CALL MXDWIO(LINE, 0)
                    CALL MXDRIO(LINE2)
C       
C----   Get numbers using PARSER
C       
C       ******************************************
                    CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C       ******************************************
                    IF (NTOK.EQ.0) THEN
                      CONTINUE
                    ELSE 
                      CALL MKEYNM(1,1,LINE2,IBEG,IEND,ITYP,NTOK)
                      IF (IOERR) GOTO 114
                      WRMSLIM = VALUE(1)
                    END IF
                    RMSLIM = WRMSLIM
                    ELIMIT = WRMSLIM
                    ELIMIT2 = WRMSLIM
                    ELIMIT3 = WRMSLIM
                    CALL MXDCIO(1,0,0,0,0)
                    GOTO 130
                  ELSE
C       
C----   Do NOT want to reset max residual
C       
                    LINE = ' '
                    WRITE(LINE,FMT=6340)
 6340               FORMAT('Do you want abandon processing (Y):')
                    CALL MXDWIO(LINE, 1)
                    CALL MXDRIO(LINE2)
C       
C----   Parse reply
C       
C       ******************************************
                    CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C       ******************************************
                    IF (NTOK.EQ.0) THEN
                      STR1 = 'Y'
                    ELSE
                      STR1 = LINE2(IBEG(1):IEND(1))
                      CALL CCPUPC(STR1)
                    END IF
                    IF (STR1.EQ.'Y') THEN
C       
C---    ABANDON
C       

                      CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,PRFSUM,
     +                            PRFSUMI)
                      CALL MXDCIO(1,0,0,0,0)
                      IF (DISPMENU) THEN
                        GOTO 34
                      ELSE
                        GOTO 30
                      END IF
                    ELSE
C       
C----   Repeat query
C       
                      GOTO 112
                    END IF
                  END IF
C       
C       

                ELSE
C       
C----   This block if NOT WINOPEN
C       
                  IF (RWEIGHT) THEN
                    WRITE (ITOUT,FMT=6037) WRMSLIM
                    IF (BRIEF) WRITE (IBRIEF,FMT=6037) WRMSLIM
                  ELSE
                    WRITE (ITOUT,FMT=6036) RMSLIM
                    IF (BRIEF) WRITE (IBRIEF,FMT=6036) RMSLIM
                  END IF
 6036             FORMAT (1X,'Final  residual too large',/,1X,'(Max',
     +                 'imum ',F4.1,' defined by subkeyword RESID o',
     +                 'f REFINEMENT keyword)',/1X,'Do you want to ',
     +                 'do more cycles of refinement (Y/N) ?',$)
 6037             FORMAT (1X,'Final weighted residual too large',/,
     +                 1X,'(Maximum ',F4.1,' defined by subkeyword ',
     $                 'RESID of REFINEMENT keyword)',/1X,
     +                 'Do you want to do more cycles of refinement',
     $                 ' (Y/N) ?',$)
C       
C       **********
c     "NOSTOP" option.

                  if (nostop) then
                     yes = .false.
                  else
                     CALL YESNO(YES)
                  end if
C       **********
C       
                  IF (YES) GO TO 90
                  WRITE (ITOUT,FMT=6038)
                  IF (BRIEF) WRITE (IBRIEF,FMT=6038)
 6038             FORMAT (1X,'Do you want to inspect the image (Y/N)',
     $                 '? ',$)
C       
C       **********
c       "NOSTOP" option.
                  if (nostop) then
                     yes = .false.
                  else
                     CALL YESNO(YES)
                  end if
C       **********
C       

                  

                  IF (YES) THEN
C       
                    MODEDISP = 0
                    CALL XDISP(MODEDISP,FIRSTPACK,PACK,IFIRSTPACK,
     +                   FIRSTFILM,GENOPEN)
                    IF (MODEDISP.EQ.99) THEN
C       
C----   Abort current run
C       
                      CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                            PRFSUM,PRFSUMI)
                      IF (DISPMENU) THEN
                        GOTO 34
                      ELSE
                        GOTO 30
                      END IF
                    END IF
C       
C       
C----   Repeat CENTRS for adjusted pattern
C       
                    GO TO 90
                  END IF
                  WRITE (ITOUT,FMT=6040)
                  IF (BRIEF) WRITE (IBRIEF,FMT=6040)
 6040             FORMAT (1X,'You may either abandon this image or car',
     $                 'ry on',/1X,'Do you want to carry on (Y/N) ? ',$)
C       
C       **********
c     "NOSTOP" option.
                  if (nostop) then
                     yes = .true.
                  else
                     CALL YESNO(YES)
                  end if
C       **********
C       
                  IF (YES) THEN
                    RMSLIM = 100.0
                    WRMSLIM = 100.0
                    ELIMIT = 100.0
                    ELIMIT2 = 100.0
                    ELIMIT3 = 100.0
                    WRITE (ITOUT,FMT=6042)
                    IF (BRIEF) WRITE (IBRIEF,FMT=6042)
 6042               FORMAT (/1X,'** WARNING, All RMS residual limits ',
     $                   'set to 100.0 to continue',
     +                   /1X,'**They will not be RESET**')
                    GO TO 130
                  END IF
C       
C----   End of IF (WINOPEN) block
                END IF

C       
C----   If in batch mode
C       

              ELSE
                IF (RWEIGHT) THEN
                  WRITE (IOUT,FMT=6045) WRMSRES,WRMSLIM
 6045             FORMAT (//1X,'The FINAL weighted residual of',F6.1,
     +                 ' is greater than the maximum allowed (',
     $                 F4.1,')',/1X,'(Defined by ',
     +                 'RESID keyword on REFINEMENT card)',/1X,
     +                 'Going on to next image')
                ELSE
                  WRITE (IOUT,FMT=6044) RMSRES,RMSLIM
 6044             FORMAT (//1X,'The FINAL refined residual of',F6.1,
     $                 ' is greater than the maximum allowed (',F4.1,
     $                 ')',/1X,'(Defined by ',
     +                 'RESID keyword on REFINEMENT card)',/1X,
     +                 'Going on to next image')
                END IF
C
C---- Set a warning and count the number of images skipped and store 
C     some of the image numbers. Slot 100 is for total number of images
C
                WARN(42) = .TRUE.
                XWARN(1,42) = WRMSLIM
                IWARN(100,42) = NPACKSAVE
                IWARN(1,42) = IWARN(1,42) + 1
                IF (IWARN(1,42).LE.50) IWARN(1+IWARN(1,42),42) = ID
              END IF
C       
C----   If this was the firstfilm, change pack number of first good film
C       
              IF (FIRSTFILM) IFIRSTGOOD = IFIRSTGOOD + 1
              BADPACK(IPACK,IFILM) = .TRUE.
              NWRN = NWRN + 1
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6043) IPACK,FIRSTFILM,IFIRSTGOOD
                IF (ONLINE) WRITE(ITOUT,FMT=6043) IPACK,FIRSTFILM,
     +                                            IFIRSTGOOD
 6043           FORMAT(1X,'ipack=',i3,'  FIRSTFILM',L2,' IFIRSTGOOD=',
     +                 I3)
              END IF
C       
C---- Blank lines here (for time being) to keep lines numbers the same
C     Redundant code has been removed. AGWL 18/6/18


























C       
              IF (FIRSTPASS) THEN
                NERR(IPACK) = 6
                XERR(IPACK) = RMSRES
              ELSE
                II = 0
C       
C       *******************************************************
                CALL SUMMERR(ISUMMR,ID,6,NFPACK(IPACK),NFGEN,FILM,II,
     $               RMSRES)
C       *******************************************************
C       
              END IF
C       
C       
              GO TO 250
C       
C----   if centrs has already been repeated due to poor initial residual
C       do not allow a second repeat.
C       
 130          CONTINUE
              IF (BADSTART) GO TO 140
              IF (RWEIGHT) THEN
                BADSTART = (WESTART.GT.WELIMIT)
              ELSE
                BADSTART = (ESTART.GT.ELIMIT)
              END IF
C       
C----   Repeat centrs if initial residual high
C       
              IF (BADSTART) THEN
                IF (RWEIGHT) THEN
                  XLIMIT = WELIMIT
                ELSE
                  XLIMIT = ELIMIT
                END IF
                WRITE (IOUT,FMT=6046) XLIMIT
 6046           FORMAT (/1X,'Repeat refinement because INITIAL RESID',
     $               'UAL is greater than ',F5.1)
                IF (ONLINE) WRITE (ITOUT,FMT=6046) XLIMIT
                GO TO 90
              END IF
C       
 140          IF ((.NOT.AVPROFILE).OR.(NOREF)) GO TO 170
C       
C       
              DOPROFILE = .TRUE.
              NRSOLD = NRS
C       
C----   Repeat centrs to accumulate average spot profile
C       
 150          IF (ONLINE) WRITE (ITOUT,FMT=6048)
 6048         FORMAT (1X,'Accumulating spots for SPOT PROFILE')
              MATCH = .FALSE.
              PARTLS = .FALSE.            
              OVRLDS = .FALSE.
              MINREFAV = MIN(MINREF,10)
              IF (MINREF.EQ.0) MINREFAV = 0
              OLDLIST = .FALSE.
              IF (USEPAR) PARTLS = .TRUE.
              IF (USEOVR) OVRLDS = .TRUE.
C       
C----   Set ADDPART flag for this image (will always be false for last
C       image to be measured)
C       
              ADDPP = ADDP(IPACK)
C       
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6502)
                IF (ONLINE) WRITE(ITOUT,FMT=6502)
 6502           FORMAT(/,1X,'In MAIN, calling CENTRS to get average ',
     +                    'spot profile')
              END IF
C
C---- Print for program flow
C  
              CALLED = 'CENTRS'
              COMMENT = 'Accumulate data for average spot profile'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ********************************************************
              CALL CENTRS(DOPROFILE,NSIG,IXSHIFT,IYSHIFT,NPROFL,LIMIT,
     +             SEP,VLIM,MATCH,PARTLS,OVRLDS,MINREFAV,OLDLIST,
     +             GENLIST,USEBOX,ADDPP,PTMIN,NIMGSUMREF,NUSEFUL)
C       ********************************************************
C       
C----   Check on measurement box dimensions by displaying average
C       spot profile
C       
              IF (NPROFL.GT.0) THEN
C       
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6504)
                  IF (ONLINE) WRITE(ITOUT,FMT=6504)
 6504             FORMAT(/,1X,'In MAIN, calling CHKRAS')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'CHKRAS'
                COMMENT = 'Calculate average central spot profile'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       *****************************************************
                CALL CHKRAS(ID,AVPROFILE,MAXR,FIRSTFILM,FILM,FINAL,
     +                      NUMBLOCK)
C       *****************************************************
C       
              ELSE
                AVPROFILE = .FALSE.
              END IF
C       
              NRS = NRSOLD
C       
C----   AVPROFILE is updated in CHKRAS and set false if running
C       in batch mode or if the measurement box is not to be
C       changed
C       
              IF (AVPROFILE) GO TO 150
C       
C----   if the "FINDCC" option has been set (used to determine
C       camera constants using FILMPLOT and write them back
C       to generate file without going on to measure the film)
C       then do that here
C       
 170          IF (FINDCC) THEN
                MODEWR = 3
                IF (NOFID) MODEWR = 2 + FILM
C       
                ADDPP = ADDP(IPACK)
C       
C       ****************************
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6506) MODEWR
                  IF (ONLINE) WRITE(ITOUT,FMT=6506) MODEWR
 6506             FORMAT(/,1X,'In MAIN, calling WRGEN with MODE=',I2,
     +                       ' to store camera constants')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'WRGEN'
                COMMENT = 'Store camera constants '
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL WRGEN(MODEWR,PROFILE,ADDPP)
C       ****************************
C       
                MODEWR = 0
                WRITE (ITOUT,FMT=6050)
 6050           FORMAT (/1X,'Refined camera constants and distortion',
     +               ' parameters written to generate file')
C       
C----   For NOFID option, need to write separate CCX,CCY
C       for each film in pack
C       
                IF (NOFID) GO TO 240
                GO TO 250
              END IF
C       
C       
C----   For NOFID option and B or C film, goto NEXT to refine whole film
C       
              IF (NOFID .AND. (FILM.GT.1)) GO TO 210
C       
C----   Recalculate the box sizes, as size of measurement box may have
C       changed in CHKRAS
C       
C       ***********************
C       ***********************
              IF (FIRSTFILM) THEN
C
C---- Print for program flow
C  
                CALLED = 'RMAXR'
                COMMENT = 'Recalculate box sizes'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL RMAXR(LIMIT,THICK,IERR2)
C       ***********************
                IF ((IERR2.EQ.1).AND.DISPMENU.and.winopen) THEN
                  WRITE(LINE,FMT=6208) IRAS(1),IRAS(2)
                  L = LENSTR(LINE)
                  IXP = 400
                  IYP = 400
                  CALL MXD_POP(IXP,IYP, XDLSTR(LINE),L,
     +                 XDLSTR(' '),0,XDLSTR('OK'),2,XDLSTR(' '),
     +                 -1,3,0,IBUTTON)
                END IF
                IF (IERR2.EQ.2) THEN
                  IF (DISPMENU) THEN
C       
C----   If running interactively, trap measurement box being too big
C       
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    GOTO 34
                  ELSE
                    NSHUTERR = 6
                    CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                  END IF
                END IF
              END IF
C       
C----   Go straight to gensort if not refining (NOREF)
C       
              IF (NOREF) GOTO 224
C       
C----   select 20 refinement spots from centrs prior to choosing
C       spots for refinement from the outside of the film
C       
C       ***********
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6508)
                IF (ONLINE) WRITE(ITOUT,FMT=6508)
 6508           FORMAT(/,1X,'In MAIN, calling MSELECT')
              END IF
C
C---- Print for program flow
C  
              CALLED = 'MSELECT'
              COMMENT = 'Select spots from centre'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL MSELECT
C       ***********
C       
C----   If not already done in central refinement area, find true
C       centre of gravity for selected 20 spots. Skip this if
C       NOREF is true
C       
              IF (.NOT.LIST) THEN
                LIST = .TRUE.
                CENTRAL = .TRUE.
C       
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6510)
                  IF (ONLINE) WRITE(ITOUT,FMT=6510)
 6510             FORMAT(/,1X,'In MAIN, calling NEXT to find c.of.g')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'NEXT'
                COMMENT = ' Find c. of g.'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       *****************************************************
                CALL NEXT(LIST,IXSHIFT,IYSHIFT,PRECESS,MATCH,IFAIL,
     +               PARTLS,ADDPP,CENTRAL,NSIG,NIMGSUMREF)
C       *****************************************************
C       
              END IF
C       
C----   Sort fully recorded (or partial) spots from generate file on scanner
C       coordinates prior to selection of refinement spots. Limits
C       reflections to area outside that used in 'centrs' (ie defined
C       by 'limit')
C       
C----   If partials are to be used in SEEKRS, set MODE to 3
C       
              MODE = 0
              IF (USEPAR) MODE = 3
C       
              IF (WINOPEN) CALL MXD_FLU(I)
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6512) MODE
                IF (ONLINE) WRITE(ITOUT,FMT=6512) MODE
 6512           FORMAT(/,1X,'In MAIN, calling GENSORT with MODE=',I3,
     +          ' to provide spot list for use in refinement')
              END IF
C
C---- Print for program flow
C  
              CALLED = 'GENSORT'
              WRITE(COMMENT,FMT=6513) MODE 
 6513         FORMAT(' MODE=',I2,' Reflections in outer regions')
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************************************
              CALL GENSORT(MODE,FORCE,LIMIT,VLIM,NMR,ADDPP,PTMIN,LAST)
C       ****************************************************
C       
              FORCE = .FALSE.
C       
C----   Test for no spots found in gensort, mode set to 999
C       Go straight on to measurement.               
              IF (MODE.EQ.999) THEN
                WRITE(IOUT,FMT=6051)
                IF (ONLINE) WRITE(ITOUT,FMT=6051)
 6051           FORMAT(1X,'No spots found outside central region of',
     +               ' image',/,1X,'(defined by REFINEMENT LIMIT key',
     +               'word) no additional refinement will be performed')
C
C---- Write residual to XDL average spot profile window
C
                IF (WINOPEN.AND.DISP_IO3) THEN
                  WRITE(LINE,FMT=6053) 0.01*RMSRES,WRMSRES
 6053             FORMAT('Rms residual',F6.2,'mm, weighted residual',
     +                 F6.1)
                  CALL MXDWIO(LINE,22)
                END IF        
C
C---- Need to write XML for positional refinement (normally done after
C     refinement over whole image).
C
                IF (SOCKLO.AND..NOT.XMLOPEN) THEN
                  XMLONLY = .TRUE.
C       
C       
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6514)
                  IF (ONLINE) WRITE(ITOUT,FMT=6514)
 6514             FORMAT(/,1X,'In MAIN, no suitable reflections from',
     +                ' GENSORT, do refinement now, calling RDIST')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'RDIST'
                COMMENT = 'No suitable reflections from GENSORT' 
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       
C       ******************************************
                  CALL RDIST(IPACK,ID,NIMGSM,CENTRE,FINAL,WELIMIT,
     +               ELIMIT,ELIMIT2,ELIMIT3,BADSTART,RWEIGHT,REFREJ,
     +               XMLONLY,RESCALE)
C       ******************************************
C
C---- NB Special case where no spots for refinement in outer region of detector
C     For new GUI, at this point, xml for positional refinement has just
C     been written (from RDIST) and MOSFLM needs to read from socket to see
C     if user has requested display of image, predictions or an abort.
C
 188              CONTINUE
C
C---- Print for program flow
C  
                  CALLED = ' *** READ_SOCKET ***'
                  COMMENT = 'Special case where no suitable reflections'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL READ_SOCKET(SERVERFD,LINE400,IFAIL)
C Socket is broken
                  IF(IFAIL.EQ.-2)THEN
                    NSHUTERR = 10
                    CALL SHUTDOWN('MOSFLM',NSHUTERR)
                  ENDIF
                  IF (DEBUG(89)) THEN
                    WRITE(IOUT,FMT=6610) LINE400(1:120)
                    IF (ONLINE) WRITE(ITOUT,FMT=6610) LINE400(1:120)
 6610               FORMAT(1X,'Socket read in MOSFLM1:',A)
                  END IF
                  CALL MPARSE(LINE400,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
                  KEY6 = LINE400(IBEG(1):IEND(1))
C
                  DO I = 1, NTOK
                     ARGV(I) = LINE400(IBEG(I):IEND(I))
                  END DO
C
C---- 'continue'  continue processing
C
                  IF (KEY6(1:4).EQ.'cont') THEN
                    GOTO 200
C       
C----   'abort' ...  Abort current run
C       
                  ELSE IF (KEY6(1:5).EQ.'abort') THEN
                     CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                     GOTO 30
C
C----    'create_grey_image' ..Create a jpeg and send to GUI
C
                  ELSE IF (KEY6.EQ.'create') THEN
c                    CALL CREATE_GREY_IMAGE(NTOK, ARGV, ITYP, VALUE,IERR) 
C
C---- HRP once complete, CREATE_IMAGE will replace CREATE_GREY_IMAGE - 26.09.2008
                    NTOK = NTOK + 1
                    ARGV(NTOK) = 'COLOURS'
                    ITYP(NTOK) = 2
                    VALUE(NTOK) = 1
C
C---- Print for program flow
C  
                    CALLED = 'CREATE_IMAGE'
                    COMMENT = 'No suitable reflections in GENSORT'
                    IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    CALL CREATE_IMAGE(NTOK, ARGV, ITYP, VALUE,IERR)  
C
C----    'predict' ... Create a list of predictions for GUI
C
                  ELSE IF (KEY6.EQ.'predic') THEN
                    PRDFLAG = 1
C
C---- Print for program flow
C  
                    CALLED = 'PREDICT_SPOTS'
                    COMMENT = 'No suitable reflections in GENSORT'
                    IF (DEBUG(99))
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    CALL PREDICT_SPOTS(NTOK, ARGV, ITYP, VALUE,
     +                                 PRDFLAG, IERR)
                  END IF
                  GOTO 188
                END IF
C       
C----   Save the direct beam coords, in case this is a multi-segment
C       post refinement, or if a POSTREF WIDTH run which might be repeated
C       because of a large cell shift
C       
                IF (IPACK.LE.NIMAX) THEN
                  SVXCEN(IPACK) = XCEN
                  SVYCEN(IPACK) = YCEN
                END IF
                GOTO 224
              END IF
C       
C----   Search for refinement spots over whole of film
C       
              NRSOLD = NRS
              BADSTART = .FALSE.
              NRS = NRSOLD
              IF (BRIEF) WRITE (IBRIEF,FMT=6052)
              IF (ONLINE) WRITE (ITOUT,FMT=6052)
 6052         FORMAT (/1X,'Refinement using reflections over entire',
     $             ' image',/)
              WRITE (IOUT,FMT=6052)
              OVRLDS = .FALSE.
              IF (USEOVR) OVRLDS = .TRUE.
C       
              IF (WINOPEN) CALL MXD_FLU(I)
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6516)
                IF (ONLINE) WRITE(ITOUT,FMT=6516)
 6516           FORMAT(/,1X,'In MAIN, calling SEEKRS to find spots',
     +                ' for refinement')
              END IF
C
C---- Print for program flow
C  
              CALLED = 'SEEKRS'
              COMMENT = 'Find spots over whole image' 
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ********************************************
              CALL SEEKRS(IRFMIN,IRFINC,IXSHIFT,IYSHIFT,OVRLDS,
     +             ADDPP,NIMGSUMREF)
C       ********************************************
              IF (WINOPEN) CALL MXD_FLU(I)
C       
              FINAL = .FALSE.
              XMLONLY = .FALSE.
C       
C       
C       
C       ******************************************
 190          CONTINUE
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6518)
                IF (ONLINE) WRITE(ITOUT,FMT=6518)
 6518           FORMAT(/,1X,'In MAIN, calling RDIST for refinement')
              END IF
C
C---- Print for program flow
C  
              CALLED = 'RDIST'
              COMMENT = 'Using spots over whole image' 
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL RDIST(IPACK,ID,NIMGSM,CENTRE,FINAL,WELIMIT,
     +             ELIMIT,ELIMIT2,ELIMIT3,BADSTART,RWEIGHT,REFREJ,
     +             XMLONLY,RESCALE)
C       ******************************************
C       
C---- For new GUI, at this point, xml for positional refinement has just
C     been written (from RDIST) and MOSFLM needs to read from socket to see
C     if user has requested image display, prediction display, or an abort.
C
              IF (SOCKLO.AND..NOT.XMLOPEN) THEN
                NODISPLAY = .TRUE.
C
C---- Print for program flow
C  
                CALLED = 'READ_SOCKET'
                COMMENT = '*** Check for display, predict, abort ***' 
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
 192            CALL READ_SOCKET(SERVERFD,LINE400,IFAIL)
C Socket is broken
                IF(IFAIL.EQ.-2)THEN
                  NSHUTERR = 11
                  CALL SHUTDOWN('MOSFLM',NSHUTERR)
                ENDIF
                IF (DEBUG(89)) THEN
                   WRITE(IOUT,FMT=6620) LINE400(1:120)
                   IF (ONLINE) WRITE(ITOUT,FMT=6620) LINE400(1:120)
 6620              FORMAT(1X,'Socket read in MOSFLM2:',A)
                END IF

C     ..
Chrp 05.10.2009 should do something sensible if EOF on read
                IF(IFAIL.LT.0)GOTO 200
                CALL MPARSE(LINE400,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
                if(ntok.gt.0)KEY6 = LINE400(IBEG(1):IEND(1))
C
                DO I = 1, NTOK
                   ARGV(I) = LINE400(IBEG(I):IEND(I))
                END DO
C
C---- 'continue'  continue processing
C
                IF (KEY6(1:4).EQ.'cont') THEN
                  GOTO 200
C       
C----   'abort' ...  Abort current run
C       
                ELSE IF (KEY6(1:5).EQ.'abort') THEN
                   CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                   GOTO 30
C
C----    'create_grey_image' ..Create a jpeg and send to GUI
C
                ELSE IF (KEY6.EQ.'create') THEN
c                    CALL CREATE_GREY_IMAGE(NTOK, ARGV, ITYP, VALUE,IERR) 
C
C---- HRP once complete, CREATE_IMAGE will replace CREATE_GREY_IMAGE - 26.09.2008
                  NTOK = NTOK + 1
                  ARGV(NTOK) = 'COLOURS'
                  ITYP(NTOK) = 2
                  VALUE(NTOK) = 1
C
C---- Print for program flow
C  
                  CALLED = 'CREATE_IMAGE'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL CREATE_IMAGE(NTOK, ARGV, ITYP, VALUE,IERR) 
C
C----    'predict' ... Create a list of predictions for GUI
C
                ELSE IF (KEY6.EQ.'predic') THEN
c                  write(iout,*)'NSPOT is : ',nspot
c                  do i=1,60
c                    write(iout,*)'before: ',i,xg(i),yg(i)
c                  enddo
                  PRDFLAG = 1
C
C---- Print for program flow
C  
                  CALLED = 'PREDICT_SPOTS'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL PREDICT_SPOTS(NTOK, ARGV, ITYP, VALUE,
     +                                 PRDFLAG, IERR)
c                  write(iout,*)'NSPOT is : ',nspot
cc                  do i=1,60
c                    write(iout,*)'after: ',i,xg(i),yg(i)
c                  enddo
                END IF
                GOTO 192
              END IF
C       
C----   Only allow one repeat due to poor
C       
 200          CONTINUE
              IF (BADSTART) GO TO 220
C       
C----   Repeat refinement if either initial or final residuals too high
C       
              IF (RWEIGHT) THEN
                BADSTART = ((WESTART.GT.WELIMIT).OR.
     $               (WRMSRES.GT.WELIMIT))
              ELSE
                BADSTART = ((ESTART.GT.ELIMIT2) .OR. 
     $               (RMSRES.GT.ELIMIT3))
              END IF
              IF (BADSTART) THEN
C       
C----   Repeat refinement using 'next' and existing list of reflections
C       
                IF (RWEIGHT) THEN
                  IF (ONLINE) WRITE (ITOUT,FMT=6060) WELIMIT
 6060             FORMAT(/1X,'Repeat refinement because initial or ',
     +                 'final residual is greater than ',F5.1)
                  WRITE (IOUT,FMT=6060) WELIMIT
                ELSE
                  IF (ONLINE) WRITE (ITOUT,FMT=6055) ELIMIT2,ELIMIT3
 6055             FORMAT(/1X,'Repeat refinement because initial resi',
     +                 'dual is greater than ',F5.1,' or final resid',
     $                 'ual greater than ',F5.1)
                  WRITE (IOUT,FMT=6055) ELIMIT2,ELIMIT3
                END IF
                LIST = .TRUE.
                CENTRAL = .FALSE.
                IF(SOCKLO)THEN
C
C---- Print for program flow
C  
                  CALLED = 'WRITE_SOCKET'
                  COMMENT = 'Write XML refinement repeat'
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  LONGLINE = ' '
 7000             FORMAT('<?xml version="1.0"?>',
     $                 '<!DOCTYPE refinement_repeat SYSTEM "">',
     $                 '<refinement_repeat>',
     $                 '<status>',
     $                 '<code>ok</code>',
     $                 '</status>',
     $                 '<image_name>',A,'</image_name>',
     $                 '<image_template>',A,'</image_template>',
     $                 '<image_number>',I8,'</image_number>',
     $                 '</refinement_repeat>')
                  WRITE(LONGLINE,FMT=7000)SHORTFN(1:LENSTR(SHORTFN)),
     $                 TEMPLSAV(1:lenstr(templsav)),ID
                  CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                 LENSTR(LONGLINE),LONGLINE)
                ENDIF
C       
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6520)
                  IF (ONLINE) WRITE(ITOUT,FMT=6520)
 6520             FORMAT(/,1X,'In MAIN, after a BADSTART calling NEXT')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'NEXT'
                COMMENT = 'After BADSTART'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       *****************************************************
                CALL NEXT(LIST,IXSHIFT,IYSHIFT,PRECESS,MATCH,IFAIL,
     +               PARTLS,ADDPP,CENTRAL,NSIG,NIMGSUMREF)
C       *****************************************************
C       
C----   Repeat refinement using new spot positions from next
C       
                GO TO 190
              END IF
C       
              GO TO 220
C       
C----   Measure refinement spots on 'B' or 'C' film in a pack
C       
C       ***********************
 210          IF (FIRSTFILM) CALL RMAXR(LIMIT,THICK,IERR2)
C       ***********************
C       
              LIST = .FALSE.
              IF (USEPAR) PARTLS = .TRUE.
              CENTRAL = .FALSE.
C       
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6522)
                IF (ONLINE) WRITE(ITOUT,FMT=6522)
 6522           FORMAT(/,1X,'In MAIN, calling NEXT for B and C films')
              END IF
C       *****************************************************
              CALL NEXT(LIST,IXSHIFT,IYSHIFT,PRECESS,MATCH,IFAIL,
     +             PARTLS,ADDPP,CENTRAL,NSIG,NIMGSUMREF)
C       *****************************************************
C       
              PARTLS = .FALSE.
C       
C----   If insufficient refinement spots found go on to next pack
C       
              IF (IFAIL.LT.0) THEN
                II = 0
C       
C       **************************************************
                CALL SUMMERR(ISUMMR,ID,7,NFPACK(IPACK),NFGEN,FILM,II,X)
C       **************************************************
C       
                GO TO 250
              END IF
C       
C       
              IF (ONLINE) WRITE (ITOUT,FMT=6052)
              WRITE (IOUT,FMT=6052)
              XMLONLY = .FALSE.
C       
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6524)
                IF (ONLINE) WRITE(ITOUT,FMT=6524)
 6524           FORMAT(/,1X,'In MAIN, calling RDIST for B and C films')
              END IF
C       
C       ******************************************
              CALL RDIST(IPACK,ID,NIMGSM,CENTRE,FINAL,WELIMIT,
     +             ELIMIT,ELIMIT2,ELIMIT3,BADSTART,RWEIGHT,REFREJ,
     +             XMLONLY,RESCALE)
C       ******************************************
C       
C----   Only allow one repeat
C       
              IF (BADSTART) GO TO 220
              IF (RWEIGHT) THEN
                BADSTART = ((WESTART.GT.WELIMIT).OR.
     $               (WRMSRES.GT.WELIMIT))
              ELSE
                BADSTART = ((ESTART.GT.ELIMIT2) .OR. 
     $               (RMSRES.GT.ELIMIT3))
              END IF
              IF (BADSTART) GO TO 210
C       
C       
 220          CONTINUE
C       
C----   Save the direct beam coords, in case this is a multi-segment
C       post refinement, or if a POSTREF WIDTH run which might be repeated
C       because of a large cell shift
C       
              IF (IPACK.LE.NIMAX) THEN
                SVXCEN(IPACK) = XCEN
                SVYCEN(IPACK) = YCEN
              END IF
C       
C----   Test final residual
C       
              IF (RWEIGHT) THEN
                OKREF = (WRMSRES.LE.WRMSLIM)
              ELSE
                OKREF = (RMSRES.LE.RMSLIM)
              END IF
              IF (.NOT.OKREF) THEN
                IF (WINOPEN) THEN


                  IXM = 200
                  IYM = 200
                  LINELEN = 75
                  NUMLIN = 9
C       
C       Create IO window
C       
                  CALL MXDCIO(0,LINELEN, NUMLIN, IXM,IYM)
                  LINE = ' '
                  WRITE(LINE,FMT=6320) WRMSRES
                  CALL MXDWIO(LINE,1)
                  LINE = ' '
                  WRITE(LINE,FMT=6322) WRMSLIM
                  CALL MXDWIO(LINE,1)
                  LINE = ' '
                  WRITE(LINE,FMT=6324)
                  CALL MXDWIO(LINE,1)
                  LINE = ' '
 212              WRITE(LINE,FMT=6326)
                  CALL MXDWIO(LINE, 1)
                  CALL MXDRIO(LINE2)
C       
C----   Parse reply
C       
C       ******************************************
                  CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C       ******************************************
                  IF (NTOK.EQ.0) THEN
                    STR1 = 'Y'
                  ELSE
                    STR1 = LINE2(IBEG(1):IEND(1))
                    CALL CCPUPC(STR1)
                  END IF
                  IF (STR1.EQ.'Y') THEN
C       
C----   Get max residual
C       
                    LINE = ' '
                    WRMSLIM = 100.0
 214                WRITE (LINE, 6328) WRMSLIM
                    CALL MXDWIO(LINE, 0)
                    CALL MXDRIO(LINE2)
C       
C----   Get numbers using PARSER
C       
C       ******************************************
                    CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C       ******************************************
                    IF (NTOK.EQ.0) THEN
                      CONTINUE
                    ELSE 
                      CALL MKEYNM(1,1,LINE2,IBEG,IEND,ITYP,NTOK)
                      IF (IOERR) GOTO 214
                      WRMSLIM = VALUE(1)
                    END IF
                    RMSLIM = WRMSLIM
                    ELIMIT = WRMSLIM
                    ELIMIT2 = WRMSLIM
                    ELIMIT3 = WRMSLIM
                    CALL MXDCIO(1,0,0,0,0)
                    GOTO 216
                  ELSE
C       
C----   Do NOT want to reset max residual
C       
                    LINE = ' '
                    WRITE(LINE,FMT=6340)
                    CALL MXDWIO(LINE, 1)
                    CALL MXDRIO(LINE2)
C       
C----   Parse reply
C       
C       ******************************************
                    CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C       ******************************************
                    IF (NTOK.EQ.0) THEN
                      STR1 = 'Y'
                    ELSE
                      STR1 = LINE2(IBEG(1):IEND(1))
                      CALL CCPUPC(STR1)
                    END IF
                    IF (STR1.EQ.'Y') THEN
C       
C---    ABANDON
C       
                      CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                      IF (DISPMENU) THEN
                        GOTO 34
                      ELSE
                        GOTO 30
                      END IF
                    ELSE
C       
C----   Repeat query
C       
                      GOTO 212
                    END IF
                  END IF
C       
                ELSE
C
C----             this block for .NOT. WINOPEN
C
                  IF (RWEIGHT) THEN
                    IF (BRIEF) WRITE (IBRIEF,FMT=6045) WRMSRES,WRMSLIM
                    IF (ONLINE) WRITE (ITOUT,FMT=6045) WRMSRES,WRMSLIM
                    WRITE (IOUT,FMT=6045) WRMSRES,WRMSLIM
                  ELSE
                    IF (BRIEF) WRITE (IBRIEF,FMT=6044) RMSRES,RMSLIM
                    IF (ONLINE) WRITE (ITOUT,FMT=6044) RMSRES,RMSLIM
                    WRITE (IOUT,FMT=6044) RMSRES,RMSLIM
                  END IF
C
C---- Set a warning and count the number of images skipped and store 
C     some of the image numbers
C
                  WARN(42) = .TRUE.
                  XWARN(1,42) = WRMSLIM
                  IWARN(1,42) = IWARN(1,42) + 1
                  IWARN(100,42) = NPACKSAVE
                  IF (IWARN(1,42).LE.50) IWARN(1+IWARN(1,42),42) = ID
                END IF
C       
C----   If this was the firstfilm, change pack number of first good film
C       
                IF (FIRSTFILM) IFIRSTGOOD = IFIRSTGOOD + 1
                BADPACK(IPACK,IFILM) = .TRUE.
                NWRN = NWRN + 1
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6043) IPACK,FIRSTFILM,IFIRSTGOOD
                  IF (ONLINE) WRITE(ITOUT,FMT=6043) IPACK,FIRSTFILM,
     +                                            IFIRSTGOOD
                END IF
C       
C       
C----   If this is a multi-segment refinement, abandon it unless
C       using iMosflm, in which case send XML and continue.
C       
                IF (MULTISEG) THEN
                  WRITE(IOUT,FMT=62128)
                  IF (ONLINE) WRITE(ITOUT,FMT=62128)
62128             FORMAT(//1X,' A multisegment post-refinement will ',
     +                 'NOT work if images have been rejected',/,1X,
     $                 'Use the interactive graphics to find out why',
     $                 ' the refinement residual is so high.')
                  IF (SOCKLO) THEN
                    STRING1 = ' '
                    WRITE(STRING1,FMT=62130) IPACK,WRMSRES,WRMSLIM
62130               FORMAT('The weighted residual for detector ',
     +              'parameter refinement on image',I5,' is',F5.1,
     +              '__nl__which is larger than the allowed limit of',
     +              F5.1,'.__nl__Check the prediction and if OK ', 
     +              'increase the limit__nl__Processing options->',
     +              ' Advanced refinement Max weighted residual')  
                    WRITE(LONGLINE,FMT=62132) STRING1(1:LENSTR(STRING1))
                    CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                LENSTR(LONGLINE),LONGLINE)
62132               FORMAT('<?xml version="1.0"?>',
     $             '<!DOCTYPE trapped_error_response>',
     $             '<trapped_error_response>',
     $             '<type>too_high_refinement_residual</type>',
     $             '<message>',A,'</message>',
     $             '</trapped_error_response>')
C
C----- Allow to continue if using iMosflm. AGWL 15/6/18
C
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    GOTO 30
                  END IF
C
C---- If not using iMosflm, just stop
C
                  STOP
                END IF
C       
                IF (FIRSTPASS) THEN
                  NERR(IPACK) = 8
                  XERR(IPACK) = RMSRES
                ELSE
                  II = 0
C       
C       ************************************************
                  CALL SUMMERR(ISUMMR,ID,8,NFPACK(IPACK),NFGEN,FILM,II,
     +                 RMSRES)
C       ************************************************
C       
                END IF
C       
C       
                GO TO 250
              END IF
C       
C----   Sort all reflexions  (fulls and partials) in generate file
C       
C----   First check box size after final refinement
C       
C       ****************************
 216          IF (FIRSTFILM) THEN
                CALL RMAXR(LIMIT,THICK,IERR2)
                IF ((IERR2.EQ.1).AND.DISPMENU.and.winopen) THEN
                  WRITE(LINE,FMT=6208) IRAS(1),IRAS(2)
                  L = LENSTR(LINE)
                  IXP = 400
                  IYP = 400
                  CALL MXD_POP(IXP,IYP, XDLSTR(LINE),L,
     +                 XDLSTR(' '),0,XDLSTR('OK'),2,XDLSTR(' '),
     +                 -1,3,0,IBUTTON)
                END IF
                IF (IERR2.EQ.2) THEN
                  IF (DISPMENU) THEN
C       
C----   If running interactively, trap measurement box being too big
C       
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    GOTO 34
                  ELSE
                    NSHUTERR = 7
                    CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                  END IF
                END IF
              END IF
C       ****************************
C       
              IF (DEBUG(1)) THEN
                IF (ONLINE) WRITE (ITOUT,FMT=6062) MAXR,IRAS
 6062           FORMAT (/1X,'At end of refinement, MAXR from RMAXR ',I6,
     +               /1X,'IRAS',5I4)
                WRITE (IOUT,FMT=6062) MAXR,IRAS
              END IF
C       
C----   Replot image if requested. Always replot if SEPARATION was not
C       given explicitly and this is the first image because SEPARATION
C       will have been updated in CHKRAS and number of overlaps may have
C       changed.
C       
 224          IF ((LPREF).OR.(FILMPLT.AND.FIRSTFILM.AND.(ISEP.NE.2)))
     $             THEN
                MODEDISP = 4
                imageno = id
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6526) MODEDISP
                  IF (ONLINE) WRITE(ITOUT,FMT=6526) MODEDISP
 6526             FORMAT(/,1X,'In MAIN, calling XDISP with MODE',I3)
                END IF
C
C---- Print for program flow
C  
                CALLED = 'XDISP'
                COMMENT = ' '
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL XDISP(MODEDISP,FIRSTPACK,PACK,IFIRSTPACK,
     +               FIRSTFILM,GENOPEN)
                IF (MODEDISP.EQ.99) THEN
C       
C----   Abort current run
C       
                  CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                  IF (DISPMENU) THEN
                    GOTO 34
                  ELSE
                    GOTO 30
                  END IF
                END IF
              END IF
C       
C       
C----   If using interactive display, write the generate file now
C       Also write it if we want all reflections (including spatial
C       overlaps) written to output MTZ file (selected by keyword ALLOUT.
C       
              IF ((FILMPLT.AND.(.NOT.MATCH)).OR.ALLOUT) THEN
                WRITE(ITOUT,FMT=6200)
 6200           FORMAT(/,1X,'Generating new reflection list')
                MODEG = 3
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6527) MODEG
                  IF (ONLINE) WRITE(ITOUT,FMT=6527) MODEG
 6527             FORMAT(/,1X,'In MAIN, calling GENERATE with MODE',I3,
     +            ' to write generate file')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'GENERATE'
                WRITE(COMMENT,FMT=6513) MODEG
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL GENERATE(MODEG,ID,GWRITE,UPDATE,LIMIT,POSTREF,
     +               NEWPREF,NFGEN,LOVERLAP,NFULLF)
C       ****************************************
C----   Store the pack header record number for this image. Note that NFILMS
C       has not yet been incremented, so use NFILMS+1 as pointer
C       
                IPACKSTART(NFILMS+1) = IPACKHEAD
              END IF
C       
              IF (WINOPEN) CALL MXD_FLU(I)
C       AL          IF (NOMEAS) CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
              MODE = 1
C       
C----   If summing partials over adjacent images, set MODE = 4
C       otherwise if doing post-refinement, set MODE = 5.
C       Set LAST true if the is the last image in a run processed
C       with POSTREF or ADDPART
              ADDPP = ADDP(IPACK)
C       
              LAST = ((IPACK.EQ.NPACKSAVE).AND.(ADDPART.OR.POSTREF))
              IF (ADDPART) THEN
                MODE = 4
              ELSE IF (SUMPART) THEN
                MODE = 5
              END IF
C       
              IF (NEWPREF) MODE = 1
C       
              FORCE = (PRBFILM.AND.FILM.EQ.2.OR.PRCFILM.AND.FILM.EQ.3)
C       
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6528) MODE
                IF (ONLINE) WRITE(ITOUT,FMT=6528) MODE
 6528           FORMAT(/,1X,'In MAIN, calling GENSORT with MODE',I3,
     +          ' to get sorted list for integration')
              END IF
C
C---- Print for program flow
C  
              CALLED = 'GENSORT'
              WRITE(COMMENT,FMT=6529) MODE
 6529         FORMAT('MODE=',I2,' Get sorted list for integration')
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************************************
              CALL GENSORT(MODE,FORCE,LIMIT,VLIM,NMR,ADDPART,PTMIN,LAST)
C       ****************************************************
              IF (WINOPEN) CALL MXD_FLU(I)
C       
              FORCE = .FALSE.
C       
C----   Select optical densities for all reflections in file.
C       if not using profile fitting, extract integrated intensity
C       etc for each spot once all its ods have been collected.
C       
C       
C----   If refining (cell), orientation using postrefinement, initialise
C       by calling POSTREFL with MODE=0. Have to test SUMPART as well,
C       because for the last image of a series there will be no
C       information to refine orientation
C       
              IF (POSTREF.AND.(SUMPART.OR.NEWPREF)) THEN
                MODE = 0
                MODE2(1) = 0
                MODE2(2) = 0
C       
C----   If this is the very first pack, set MODE negative so that NIMAG is set
C       to zero in POSTREFL (can't use FIRSTPACK as it is incremented when
C       using blocks of data)
C       
                IF (IPACK.EQ.IFIRSTP) THEN
                  MODE = -1
                  MODE2(1) = -1
                  MODE2(2) = -1
                ENDIF
C       
C----   initialize
C       
C
C---- To protect against mosaic spread refining negative because of
C     innacurate cell parameters, if this is the first cycle of cell
C     refinement do not refine mosaic spread until all images have
C     been integrated and a cell refinement is going to be done.
C     Need to do this now, as NS is set to PRNS in POSTREFL
C
                IF (MULTISEG.AND.((NREPEAT.EQ.0).AND.
     +                ((IPACK.LT.NPACK).OR.(ISEG.LT.NSEG)))) THEN
                  PRNSAVE = PRNS
                  PRNS = 0
                END IF
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6444) NREPEAT,IPACK,NPACK,ISEG,NSEG,
     +               PRNS,USEBEAM
                  IF (ONLINE) WRITE(ITOUT,FMT=6444) NREPEAT,IPACK,
     +               NPACK,ISEG,NSEG,PRNS,USEBEAM
 6444             FORMAT(1X,'Call POSTREFL to initialise',/,1X,
     +             'NREPEAT=',I3,' IPACK=',I3,' NPACK=',I3,' ISEG=',
     +             I3,' NSEG=',I3,' PRNS=',I3,' USEBEAM',L2)
                END IF
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6530) MODE
                  IF (ONLINE) WRITE(ITOUT,FMT=6530) MODE
 6530             FORMAT(/,1X,'In MAIN, calling POSTREFL with MODE',I3,
     +            ' for initialisation')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'POSTREFL'
                COMMENT = 'For initialisation'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL POSTREFL(MODE,MODE2,MODE2,TEMP,RESID,RETA,RDIVH,
     +           RDIVV,FIXED,ISTAT,LASTREC,NEWPREF,iseg,MULTISEG,
     +           RESETETA,ETAMOD)
C
C---- Restore PRNS
C
                IF (MULTISEG.AND.((NREPEAT.EQ.0).AND.
     +                ((IPACK.LT.NPACK).OR.(ISEG.LT.NSEG)))) THEN
                  PRNS = PRNSAVE
                END IF
                
              END IF
C       
C----   Keep track of number of images written by MEAS to SPOTOD. If an image
C       is repeated as a result of a large shift in postrefinement, then
C       PROCESS must skip the redundant image from SPOTOD
C       
              NOWRITE = NOWRITE + 1
              ISKIPI(NOWRITE) = 0
C       
              IF (WINOPEN) CALL MXD_FLU(I)

              IF (WINOPEN) THEN
                CALL MXDBSY(-1, ' ')
                CALL MXD_FLU(I)
                CALL MXDBSY(0,
     $               'Writing measurement boxes to scratch file')
              END IF
C       
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6532)
                IF (ONLINE) WRITE(ITOUT,FMT=6532)
 6532           FORMAT(/,1X,'In MAIN, calling MEAS')
              END IF
C
C---- Print for program flow
C  
              CALLED = 'MEAS'
              COMMENT = ' For collection and writing meas. boxes'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       *******************************************************
              IERR = 0
              CALL MEAS(MAXR,PROFILE,INTERPOL,IXSHIFT,IYSHIFT,ADDPP,
     +             POSTREF,ID+ISERADD,MULTISEG,LASTREC,NEWPREF,NUSPOT,
     &             IERR)
C       *******************************************************
C       
C----   Reflections to be used for postrefinement have been accumulated in
C       MEAS. Now call POSTREFL again to actually do the refinement.
C       Note that if adding data from several images, refinement only
C       starts once NADD images have been processed
C       If doing NEWPREF mode, don't attempt to do refinement for the
C       first image
C       
          IF (POSTREF.AND.(SUMPART.OR.
     +               (NEWPREF.AND.(IPACK.NE.IFIRSTPSEG)))) THEN
                MODE = -999
                IF (WINOPEN) THEN
                  CALL MXDBSY(-1, ' ')
                  CALL MXD_FLU(I)
                  CALL MXDBSY(0,'Doing post-refinement')
                  CALL MXD_FLU(I)
                END IF
                MODE2(1) = ID
                MODE2(2) = IPACK
C
C---- To protect against mosaic spread refining negative because of
C     innacurate cell parameters, if this is the first cycle of cell
C     refinement do not refine mosaic spread until all images have
C     been integrated and a cell refinement is going to be done.
C
                IF (MULTISEG.AND.((NREPEAT.EQ.0).AND.
     +                ((IPACK.LT.NPACK).OR.(ISEG.LT.NSEG)))) THEN
                  PRNSAVE = PRNS
                  PRNS = 0
                END IF
C
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6442) MODE,NREPEAT,IPACK,NPACK,ISEG,
     +               NSEG,PRNS,USEBEAM
                  IF (ONLINE) WRITE(ITOUT,FMT=6442) MODE,NREPEAT,IPACK,
     +               NPACK,ISEG,NSEG,PRNS,USEBEAM
 6442             FORMAT(/,1X,'In MAIN, calling POSTREFL with MODE=',I5,
     +                 ' to carry out post-refinement',/,1X,
     +             'NREPEAT=',I3,' IPACK=',I3,' NPACK=',I3,' ISEG=',
     +             I3,' NSEG=',I3,' PRNS=',I3,' USEBEAM',L2)
                END IF
C
C---- Print for program flow. Do not do refinement if collecting data for phi profile.
C  
                CALLED = 'POSTREFL'
                WRITE(COMMENT,FMT=6443) MODE
 6443           FORMAT('MODE=',I5,' for actual refinement')
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                IF (.NOT.PHIPROF) CALL POSTREFL(MODE,MODE2,MODE2,TEMP,
     +           RESID,RETA,RDIVH,RDIVV,FIXED,ISTAT,LASTREC,NEWPREF,
     +           ISEG,MULTISEG,RESETETA,ETAMOD)
C
C---- Set flag for refinement carried out
C
                IF (ISTAT.EQ.1) THEN
                  DONEREF = .TRUE.
                  ISTAT = 0
                END IF
C
C---- Restore PRNS
C
                IF (MULTISEG.AND.((NREPEAT.EQ.0).AND.
     +                ((IPACK.LT.NPACK).OR.(ISEG.LT.NSEG)))) THEN
                  PRNS = PRNSAVE
                END IF
C       
C----   Check for error return (singular equations etc).
C       
                IF (ISTAT.NE.0) THEN
                  IF (DISPMENU) THEN
C       
C----   If running interactively, trap failure of postrefinement
C       
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    GOTO 34
                  ELSEIF(SOCKLO)THEN
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    LONGLINE = ' '
                    WRITE(LONGLINE,FMT=7100)
                    CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                      LENSTR(LONGLINE),LONGLINE)
 7100               FORMAT('<?xml version="1.0"?>',
     $                   '<!DOCTYPE ',
     $                   'integration_postrefinement>',
     $                   '<integration_postrefinement>',
     $                   '<status><code>error</code><message>',
     $                   'Fewer data than parameters - check',
     $                   ' mosaicity is not too small and spot',
     +                   ' prediction looks OK',
     $                   '</message></status>',
     $                   '</integration_postrefinement>')
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
C
C---- Is setting XMLABORT TRUE really what we want to do here ?
C     I don't think so, this is a flag to allow a user to
C     abort an integration/refinement run. AGWL 24Jan14
C
CAL                    XMLABORT = .TRUE.
C
C---- Must reset ISTAT or subsequent postrefinement may fail
C
                    ISTAT = 0
                    GOTO 30
                  ELSE
                    NSHUTERR = 8
                    CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                  END IF
                END IF
C       
                IF (WINOPEN) THEN
                  CALL MXD_FLU(I)
                  CALL MXDBSY(-1, ' ')
                END IF
                IF ((RESID.GT.RESIDMAX).OR.(FRCSHIFT.GT.0.10)) THEN
                  IF (RESID.GT.RESIDMAX) THEN
                    WARN(41) = .TRUE.
                    CALL WARNINGS
                    WRITE(IOUT,FMT=6061) RESID,RESIDMAX
                    IF (ONLINE) WRITE(ITOUT,FMT=6061) RESID,RESIDMAX
                    IF (BRIEF) WRITE(IBRIEF,FMT=6061) RESID,RESIDMAX
                    IF(SOCKLO)THEN
                      LONGLINE = ' '
                      WRITE(LONGLINE,FMT=7120)
                      CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                     LENSTR(LONGLINE),LONGLINE)
 7120                 FORMAT('<?xml version="1.0"?>',
     $                     '<!DOCTYPE ',
     $                     'integration_postrefinement>',
     $                     '<integration_postrefinement>',
     $                     '<status><code>error</code><message>',
     $                     'Refinement residual is more than allowed;',
     $                     ' check that the prediction still matches ',
     $                     'the observed spots on the images',
     $                     '</message></status>',
     $                     '</integration_postrefinement>')
C
C---- Is setting XMLABORT TRUE really what we want to do here ?
C     I don't think so, this is a flag to allow a user to
C     abort an integration/refinement run. AGWL 24Jan14
C
CAL                      XMLABORT = .TRUE.
                    END IF
                  END IF
                  IF (FRCSHIFT.GT.0.10) THEN

                     call dna_output_table_start('error')
                     call dna_output_list_start('integration_error')
                     call dna_output_real_item('cell_parameter_shift', 
     +                    frcshift)
                     call dna_output_list_end
                     call dna_output_table_end
                     call dna_end_output

                    WARN(40) = .TRUE. 
                    CALL WARNINGS
                    WRITE(IOUT,FMT=6130)
                    IF (ONLINE) WRITE(ITOUT,FMT=6130)
                    IF(SOCKLO)THEN
                      LONGLINE = ' '
                      WRITE(LONGLINE,FMT=7140)
                      CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                     LENSTR(LONGLINE),LONGLINE)
 7140                 FORMAT('<?xml version="1.0"?>',
     $                   '<!DOCTYPE ',
     $                   'integration_postrefinement>',
     $                   '<integration_postrefinement>',
     $                   '<status><code>error</code><message>',
     $                   'One or more cell parameters has shifted by',
     $                ' more than 10%. Either refinement is unstable',
     $                ' or initial distance is wrong, see warnings',
     $                   '</message></status>',
     $                   '</integration_postrefinement>')
C
C     We need to reset FRCSHIFT, CELLSHIFT otherwise the next
C     postrefinement that does not actually refine the cell will fail,
C     ie if just orientation is refined.
C
                      FRCSHIFT = 0.0
                      CELLSHIFT = 0.0 
C
C---- Is setting XMLABORT TRUE really what we want to do here ?
C     I don't think so, this is a flag to allow a user to
C     abort an integration/refinement run. AGWL 24Jan14
C
CAL                      XMLABORT = .TRUE.
                    END IF
                  ENDIF
 6130             FORMAT(//1X,'***** SERIOUS ERROR ****',/,1X,'One ',
     +                 'or more cell parameters has changed by more ',
     $                 'than 10%.',/,1X,'This means the refinement i',
     $                 's unstable. Try using more images.')

 6061             FORMAT(//1X,'***** SERIOUS ERROR ****',1X,'Refine',
     +                 'ment residual from POSTCHK is',F6.3,' which',
     $                 ' is greater than',/,1X,'maximum allowed val',
     +                 'ue of',F6.3,' (subkeyword MAXRESID on POSTR',
     $                 'EF keyword).',/,1X,'Processing stopped.',/,1X,
     +                 'Check that you are using a sensible value of ',
     +                 'the mosaic spread/beam divergence',/,1X,
     $                 'by predicting the pattern and checking',/,1X,
     +                 'that you are predicting all observed spots.')
C       
                  WRITE(ISUMMR,FMT=6059) ID,RESID,RESIDMAX
 6059             FORMAT(/1X,'The post-refinement residual for pack',I4,
     +                 ' is',F6.3,' which exceeds maximum allowed valu',
     $                 'e of',F6.3,' (set using POSTREF MAXRESID)',/,1X,
     +                 'Check that you are using a sensible value of t',
     +                 'he mosaic spread/beam divergence',/,1X,'by pre',
     $                 'dicting the pattern and checking (using the X',
     +                 '-window graphics)',/,1X,
     +                 'that you are predicting all observed spots.')
                  IF(SOCKLO)THEN
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    GOTO 30
                  ENDIF
                  IF (DISPMENU) THEN
C       
C----   Abort current run
C       
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    GOTO 34
                  END IF
                  NSHUTERR = 9
                  CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                END IF
C       
C----   Test for refined mosaic spread being less than 0.25*starting value
C       need to check that it has been refined, ie has a non-zero value.
C
                WARN(19) = (WARN(19).OR.
     +             (USEBEAM.AND.(ABS(RETA).GT.0.00001)
     +              .AND.(RETA.LT.0.25*2.0*SETA)))
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6109) WARN(19),RETA/DTOR,2.0*SETA/DTOR       
                  IF (ONLINE) WRITE(ITOUT,FMT=6109) WARN(19),RETA/DTOR,
     +               2.0*SETA/DTOR       
                END IF
 6109           FORMAT(1X,'WARN(19) ',L1,' RETA',F5.2,' saved ETA',F5.2) 
C       
C----   Test for negative (mosaic spread + divergence)
C       
                IF (((RETA+RDIVH).LT.0.0).OR.((RETA+RDIVV).LT.0.0)) THEN
C
C---- Only set warning flag if the refined mosaic spread is being used
C
                  IF (USEBEAM) WARN(16) = .TRUE.
                  PRNEGM(NFILMS+1) = .TRUE.
                  WRITE(IOUT,FMT=6110)
                  IF (ONLINE) WRITE(ITOUT,FMT=6110)
 6110             FORMAT(/1X,'***** WARNING ****',/,1X,'The refined ',
     +                 'mosaic spread plus beam divergence is negati',
     +                 've',/,1X,'This may be indicative of split ',
     +                 'spots or an inaccurate cell.')
                  IF (USEBEAM) THEN
                    IF (PRNS.EQ.1) THEN
                      WRITE(IOUT,FMT=6112)
                      IF (ONLINE) WRITE(ITOUT,FMT=6112)
 6112                 FORMAT(1X,'The mosaic spread has been set to ',
     +                     '0.05',/,1X,'It may be advisable NOT to ',
     +                     'use the refined  mosiac spread (use',
     $                     ' POSTREF FIX MOSAIC keywords)')
                      ETA = 0.5*DTOR*0.05
                    ELSE IF (PRNS.EQ.2) THEN
                      IF (RDIVH.LT.0.0) THEN
                        DIVH = 0.5*DTOR*0.05
                        WRITE(IOUT,FMT=6114)
                        IF (ONLINE) WRITE(ITOUT,FMT=6114)
 6114                   FORMAT(1X,'The horizontal divergence has b',
     +                       'een reset to 0.05',/,1X,'It may be a',
     +                       'dvisable NOT to use the refined beam',
     +                   ' parameters (POSTREF USEBEAM OFF keywords)')
                      END IF
                      IF (RDIVV.LT.0.0) THEN
                        DIVV = 0.5*DTOR*0.05
                        WRITE(IOUT,FMT=6116)
                        IF (ONLINE) WRITE(ITOUT,FMT=6116)
 6116                   FORMAT(1X,'The vertical divergence has ',
     +                       'been reset to 0.05',/,1X,'It may ',
     +                       'be advisable NOT to use the refin',
     +                       'ed  beam parameters (POSTREF USEBEAM OFF'
     +                       ,' keywords)')
                      END IF
                    END IF
                  END IF
                END IF
C       
C----   Test for large difference between input and refined mosaic spread
C       or beam divergence. Comment out as now this test is done by chacking if
C       refined value is less than 0.25*input value ... this test is done above
C       and generates a serious warning. AGWL 11/7/13
C       
CAL                IF (PRNS.EQ.1) THEN
CAL                  WARN(19) = (WARN(19).OR.
CAL     +                 (ABS(RETA-2.0*SETA).GT.0.1*2.0*SETA))
CAL                ELSE IF (PRNS.EQ.2) THEN
CAL                  WARN(19) = (WARN(19).OR.
CAL     +                 (ABS(RDIVH-2.0*SDIVH).GT.0.1*2.0*SDIVH)
CAL     +                 .OR.(ABS(RDIVV-2.0*SDIVV).GT.0.1*2.0*SDIVV))
CAL                END IF
                PRF(NFILMS+1) = .TRUE. 
C       
C----   Since we have now done a post-refinement, set UMATCELL(1) to zero
C       so that it does not check for inconsistency due to a different
C       wavelength being used when deriving the AMATRIX to the integration run.
C       
                UMATCELL(1) = 0.0
C       
C       
C----   Test orientation shifts. Need shift to be greater than SHIFTMAX
C       AND also greater than SHIFTFAC*SD to be treated as a large shift.
C       
                BIGSHIFT = .FALSE.
                RPTIMG = .FALSE.
C       
C----   If not using "fixed" mode, where all images are constrained to have
C       the same missets, there are only 2 refined angles and sds (PSIY,PSIZ)
C       so change setup of SDDELPHI
C       
                DO 226 I = 1,3
                  SDMISS = SDDELPHI(I)
                  IF (.NOT.FIXED) THEN
                    IF (I.EQ.2) SDMISS = SDDELPHI(1)
                    IF (I.EQ.3) SDMISS = SDDELPHI(2)
                  END IF
                  IF ((ABS(SHIFT(I)).GT.SHIFTMAX).AND.
     +                 (ABS(SHIFT(I)).GT.SHIFTFAC*SDMISS))
     $                 BIGSHIFT=.TRUE.
 226            CONTINUE
C       
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6118) NADD,IPACK,NADDMISSET,
     +              (SHIFT(I),I=1,3),
     +                 (SHIFTFAC*SDDELPHI(I),I=1,3),SHIFTMAX,BIGSHIFT
                  IF (ONLINE) WRITE(ITOUT,FMT=6118) NADD,IPACK,
     +                  NADDMISSET,(SHIFT(I),I=1,3),
     +                 (SHIFTFAC*SDDELPHI(I),I=1,3),SHIFTMAX,BIGSHIFT
 6118             FORMAT(1X,'NADD=',I4,' IPACK=',I4,' NADDMISSET=',I4,
     +                  ' Shift in',
     +                 ' missets',3F7.3,/,1X,'Shiftfac*sd(delphi)',
     +                 3F7.3,/,1X,'Max allowed shift before repeat',
     +                 F7.3,' Logical bigshift is ',L1)
                  IF (NEWPREF) THEN
                    CONTINUE
                  ELSE
                    WRITE(IOUT,FMT=6119) (DELPHIV(I),I=1,3*NADD)
                    IF (ONLINE) WRITE(ITOUT,FMT=6119)
     $                 (DELPHIV(I),I=1,3*NADD)
 6119             FORMAT(1X,'Values in DELPHIV',/,(1X,3F10.3))
                  END IF
                END IF
C
C---- If cell refinement was due to be carried out, it will have been
C     done and tests for errors have been made (above).
C     For multilattice case, need to update CRYSTALUBREF at this point
C     for the lattice (and solution) being refined, as AMAT is reset
C     to CRYSTALUBREF for the main lattice after generating reflections
C     for other lattices in GENERATE.
C     First need to extract the lattice and solution number for
C     the lattice being refined.
                IF ((NLATTICE.GT.1).AND.(CELLSHIFT.GT.0.0)) THEN
                  ISOL = BESTSOLAR(ILATTICE)
C
C---- Now transfer the A matrix for this solution and lattice
C
                  DO J =1,3
                    DO K =1,3
                      CRYSTALUBREF(J,K,ISOL,ILATTICE) = AMAT(J,K)
                    ENDDO
                  ENDDO
                  IF (DEBUG(1)) THEN
                    WRITE(IOUT,FMT=6121) ILATTICE,ISOL
                    IF (ONLINE) WRITE(ItOUT,FMT=6121) ILATTICE,ISOL
 6121               FORMAT(1X,'Resetting CRYSTALUBREF for lattice',I3,
     +                     ' solution',I3)
                  END IF
                END IF
C       
C----   Single image case, or initial images (up to NADD) of multiple 
C       image case (flagged by setting MODE=-990 in postrefl)
C---    I think this should be Ok to repeat an image even after NADD have
C       been processed in "width" mode...lets try and see.
C----   Special case. If using a block of images to refine (NADD) and this
C       is the NADD'th image, then we must first test for a large shift in
C       cell parameters because if this has happened we want to repeat
C       processing of the whole block of data and not just the current
C       image. Note that when using "NEWPREF" refinement, the condition is
C       that this is the NADD+1'th image rather than NADD'th
C       
                IF ((NADD.GT.1) .AND.
     +               (((IPACK.EQ.NADD).AND.(.NOT.NEWPREF)) .OR.
     +               ((IPACK.EQ.NADD+NSEG).AND.NEWPREF))    .AND.
     +               (CELLSHIFT.GT.SHIFTFAC))GOTO 228
C       
C----   Do the same if this is a multisegment post-refinement
C       
                IF (MULTISEG.AND.(CELLSHIFT.GT.SHIFTFAC)) GOTO 228
C       
C---    Test for large shifts
C       
                IF ((BIGSHIFT).OR.
     +               ((NADD.EQ.1).AND.(CELLSHIFT.GT.SHIFTFAC))) THEN
C       
C----   First deal with orientation shift
C       
                  IF (BIGSHIFT) THEN
                    WRITE(IOUT,FMT=6063)SHIFTMAX,SHIFTFAC
                    IF (ONLINE) WRITE(ITOUT,FMT=6063) 
     +                   SHIFTMAX,SHIFTFAC
                    IF (BRIEF) WRITE(IBRIEF,FMT=6063) 
     +                   SHIFTMAX,SHIFTFAC
 6063               FORMAT(//1X,'*****  shift in one or more missett',
     +                   'ing angles exceeds limit of',F6.3,' degree',
     +                   's  or',F5.2,' standard deviations *****',/,
     +                   1X,' Repeat measurement of this image using',
     +                   ' refined missetting angles')
                    PRFRPT1(NFILMS+1) = .TRUE.
                    INTDUM(1) = 0
                    INTDUM(2) = 0
                    IF (NEWPREF) THEN
C
C---- Print for program flow
C  
                      CALLED = 'MODARRAY'
                      COMMENT = 'MODE=3'
                      IF (DEBUG(99)) 
     +                        CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                      CALL MODARRAY(3, 0.0, 0, 0,INTDUM,INTDUM)
                    END IF
                    IF(SOCKLO)THEN
                       WRITE(LONGLINE,FMT=7000)
     $                     SHORTFN(1:LENSTR(SHORTFN)),
     $                     TEMPLSAV(1:lenstr(templsav)),ID
                       CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                      LENSTR(LONGLINE),LONGLINE)
                    ENDIF
                  END IF
C       
C----   Now deal with cell shift
C       
                  IF (CELLSHIFT.GT.SHIFTFAC) THEN
                    WRITE(IOUT,FMT=6065) CELLSHIFT,SHIFTFAC
                    IF (ONLINE) WRITE(ITOUT,FMT=6065) CELLSHIFT,
     $                   SHIFTFAC
                    IF (BRIEF) WRITE(IBRIEF,FMT=6065) CELLSHIFT,
     $                   SHIFTFAC
 6065               FORMAT(//,1X,'***** Cell parameter shift (',F5.1,
     +                   ' sds) exceeds limit of',F5.1,' sds *****',
     +                   /,1X,'Repeat measurement of this image')
                    PRFRPT2(NFILMS+1) = .TRUE.
                  END IF
C
C---- If in NEWPREF mode, want to go back to the first image, not just
C     repeat measurement of the second one !
C
                IF ((.NOT.NEWPREF).OR.(NEWPREF.AND.
     +               (IPACK.GT.(2*NVIRBAT)))) THEN
C
C---- Need to trap oscillating missetting angles, which would result
C     in repeating this image indefinately.
C
                   IF (IPACK.EQ.IRPTPACK) THEN
                     NSINGRPT = NSINGRPT + 1
C
C---- Check shifts against those in previous round
C
                     BIGSHIFT = .FALSE.
                     DO 229 I = 1,3
                       IF ((ABS(SHIFT(I)+RPTSHIFT(I,NSINGRPT-1)).GT.
     +                      SHIFTMAX).AND.
     +                     (ABS(SHIFT(I)+RPTSHIFT(I,NSINGRPT-1))
     +                      .GT.SHIFTFAC*SDMISS)) BIGSHIFT = .TRUE.
 229                 CONTINUE
C
C---- Do not repeat image if shifts are oscillating
C
                     IF (.NOT.BIGSHIFT) THEN
                       WRITE(IOUT,FMT=6412)
                       IF (ONLINE) WRITE(ITOUT,FMT=6412)
 6412                  FORMAT(//,1X,'*** Missets are oscillating ***',
     +                        /,1X,'Going on to the next image.')
                       PRFRPT1(NFILMS+1) = .FALSE.
                       GOTO 232
                     END IF
C
C---- Do not allow more than 5 repeats anyway
C
                     IF (NSINGRPT.GT.5) THEN
                       WRITE(IOUT,FMT=6410)
                       IF (ONLINE) WRITE(ITOUT,FMT=6410)
 6410                  FORMAT(//,1X,'***** TOO MANY REPEATS *****',/,
     +                         1X,'Check orientation. Going on to the',
     +                          ' next image.')
                       PRFRPT1(NFILMS+1) = .FALSE.
                       GOTO 232
                     END IF
                   ELSE
                     IRPTPACK = IPACK
                     NSINGRPT = 1
                     DO 227 I = 1,3
                       RPTSHIFT(I,1) = SHIFT(I)
 227                 CONTINUE
                   END IF
C       
C----   Only set flag to skip an image in SPOTOD if accumulating profiles
C       because if not, then SPOTOD is rewound by MEAS, so the second
C       pass on the image will overwrite the first in SPOTOD
                  IF (FIRSTPASS) ISKIPI(NOWRITE) = 1
                  DOPROFILE = .FALSE.
C       
C----   Reset AVPROFILE as this was set false in CHKRAS
C       
                  AVPROFILE = AVPROF(IPACK)
C       
C----   Position generate file to write pack header
C       
C
C---- Print for program flow
C  
                  CALLED = 'QSEEK'
                  COMMENT = 'Position to write pack header'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       *******************************
                  CALL QSEEK(IUNIT,IPACKHEAD,1,36)
C       *******************************
                  IPACKREC = IPACKHEAD
                    RPTIMG = .TRUE.
                    GOTO 85
C       
C----   Restart
C       
                  ELSE
                    NFRPT = NFRPT + 1
                    IF (NFRPT.LE.5) THEN
                      WRITE(IOUT,FMT=6351)
                      IF (ONLINE) WRITE(ITOUT,FMT=6351)
 6351                 FORMAT(/,1X,'*** As this is near to the start, '
     +               ,'repeat integration from the first image ***')
C
C---- Need to trap the situation where a block of images has already been integrated
C     and written to the MTZ file. Repeating integration of these images will
C     give an MTZ library file write error because the same batch file has
C     already been written.
C     Get around this by adding 1000 to batch numbers
C
                      IF (NUMBLOCK.GT.1) THEN
                         ISERAr(1) = ISERAR(1) + 1000
                         WRITE(IOUT,FMT=6355) ISERAR(1)
                         IF (ONLINE) WRITE(ItOUT,FMT=6355) ISERAR(1)
 6355                    FORMAT(1X,'To avoid problems with the MTZ',
     +                    ' library,',I6,' will be added to the batch',
     +                    ' numbers')
                      END IF
                    ELSE
                      WRITE(IOUT,FMT=6352)
                      IF (ONLINE) WRITE(ITOUT,FMT=6352)
 6352                 FORMAT(/,1X,'*** Too many repeats ***',/,1X,
     +                    'Go on to the next image.')
                      IF(SOCKLO)THEN
                        LONGLINE = ' '
 7010                   FORMAT('<?xml version="1.0"?>',
     $                       '<!DOCTYPE refinement_repeat SYSTEM "">',
     $                       '<refinement_repeat>',
     $                       '<status>',
     $                       '<code>error</code>',
     $                       '</status>',
     $                       '<image_name>',A,'</image_name>',
     $                       '<image_template>',A,'</image_template>',
     $                       '<image_number>',I8,'</image_number>',
     $                       '</refinement_repeat>')
                        WRITE(LONGLINE,FMT=7010)
     $                       SHORTFN(1:LENSTR(SHORTFN)),
     $                       TEMPLSAV(1:lenstr(templsav)),ID
                        CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                       LENSTR(LONGLINE),LONGLINE)
                        
                      ENDIF
                      GOTO 232
                    END IF
                    SHIFT(1) = 0.0
                    SHIFT(2) = 0.0
                    SHIFT(3) = 0.0
                    CELLSHIFT = 0.0
C
C---- If this is the first segment, reset the mosaic spread to the starting 
C     value. This is because a poor initial orientation can cause the
C     mosaicity to refine to a very small value, which will then prevent
C     the post-refinement from working on the second run through.
C
                    IF (ISEG.EQ.1) THEN
                      ETA = SETA
C
C---- If mosiac spread has been reduce to avoid overlap, set it to
C     the reduced value
C
                      IF (RESETETA) ETA = MIN(ETA,ETAMOD)
                    END IF
C
C---- Reset warnings about refined mosaicity going negative or less than
C     0.25(input value), as this may have been due to poor initial orientation
C
                    WARN(16) = .FALSE.
                    WARN(19) = .FALSE.
C
C---- Reset NSIG to its default value (it may have been reduced to
C     a small value because initial orientation was poor.
C
                    IF (ISIGSET.EQ.0) THEN
                      NSIG = 20
                    ELSE
                      NSIG = NSIGSAVE
                    END IF
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6353) 2.0*ETA/DTOR,NSIG
                      IF (ONLINE) WRITE(ItOUT,FMT=6353) 2.0*ETA/DTOR,
     +                   NSIG
 6353                 FORMAT(/,/,1X,'Mosaic spread reset to ',F6.3,
     +                ' and NSIG set to',I3)
                    END IF
                    IF ((ISEG.EQ.1).AND.(NREPEAT.EQ.0)) THEN
                      NFILMS = 0
                    ELSE
                      NFILMS = NFILMS - (IPACK - IFIRSTPACK)
                    END IF
                    NOWRITE = 0
C
C---- Need to reset NIMAG in POSTREFL if not the first segment,
C     and also adjust PHIIM and IDLAST
C
                   IF (ISEG.GT.1) THEN
                     MODE = -9999
                     MODE2(1) = IPACK - IFIRSTPACK
                     IF (DEBUG(1)) THEN
                       WRITE(IOUT,FMT=6534)
                       IF (ONLINE) WRITE(ITOUT,FMT=6534)
 6534                  FORMAT(/,1X,'In MAIN, calling POSTREFL with ',
     +                   'MODE=',I6,' to do partial reinitialisation')
                     END IF
C
C---- Print for program flow
C  
                     CALLED = 'POSTREFL'
                     WRITE(COMMENT,FMT=6535) MODE
 6535                FORMAT('MODE=',I2,' For partial reinitialisation')
                     IF (DEBUG(99)) 
     +                       CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                     CALL POSTREFL(MODE,MODE2,MODE2,TEMP,RESID,RETA,
     +                            RDIVH,RDIVV,FIXED,ISTAT,LASTREC,
     +                         NEWPREF,ISEG,MULTISEG,RESETETA,ETAMOD)
                   END IF
                    IFIRSTGOOD = IFIRSTPACK
                    IF (NBLOCK.NE.0) THEN
                      IFIRSTPACK = IFIRSTPACK - NUMBLOCK*NBLOCK
                      NPACK = 0
                    END IF
C       
C----   Initialisation flags for FINDPACK, OPENODS and reposition 
C       generate file
C       
                    MODEOP = 1
C
C---- Print for program flow
C  
                    CALLED = 'QSEEK'
                    COMMENT = 'Reposition to record 21 '
                    IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ********************
                    CALL QSEEK(IUNIT,21,1,36)
C       ********************
C       
                    JPACK = 0
                    IPACKREC = 21
                    IPACKHEAD = 21
C       
C----   Close the current image file. Note is is opened with DISKIO
C       under Unix, Fortran under VMS, but if packed the file has already
C       been closed.
C       
C       HRP                   IF (VAXVMS()) THEN
C       *************
C       AL                    CLOSE (UNIT=INOD)
C       *************
C       HRP                   ELSE
C       *****************************
C       AL                    IF (.NOT.PACK) CALL QCLOSE(INOD)
C       *****************************
C       HRP                   END IF
C       
C----   Rewind SPOTOD file (contains measurement boxes)
C       
                    IF(.NOT.MULTISEG)THEN
                      IF (DEBUG(1)) THEN
                        WRITE(IOUT,FMT=6536)
                        IF (ONLINE) WRITE(ITOUT,FMT=6536)
 6536                   FORMAT(/,1X,'In MAIN, rewind SPOTOD')
                      END IF
                      IF(NUSPOT)THEN
C
C---- Print for program flow
C  
                        CALLED = 'QSEEK'
                        COMMENT = 'Rewind SPOTDOD file'
                        IF (DEBUG(99)) 
     +                        CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                        CALL QSEEK(INMO,1,1,1)
                      ELSE
                        REWIND(INMO)
                      ENDIF
                    ENDIF
                    IF (DENSE) REWIND(ICOORD)
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6350) IFIRSTPACK,NUMBLOCK,NBLOCK
                      IF (ONLINE) WRITE(ITOUT,FMT=6350) IFIRSTPACK,
     +                     NUMBLOCK,NBLOCK
 6350                 FORMAT(1X,'RESTART, IFIRSTPACK reset to',I5,
     +                     '  NUMBLOCK, NBLOCK',2I5)
                    END IF
C       
C----   Reset NUMBLOCK
C       
                    NUMBLOCK = 0
C
C---- Call MODARRAY for statistics for this image, then to clear arrays.
                    INTDUM(1) = 0
                    INTDUM(2) = 0
                    IF (NEWPREF) THEN
                      IF (DEBUG(1)) THEN
                        WRITE(IOUT,FMT=6538)
                        IF (ONLINE) WRITE(ITOUT,FMT=6538)
 6538                   FORMAT(/,1X,'In MAIN, call MODARRAY for ',
     +                   'statistics on this image and then again',
     +                   ' to clear arrays')
                      END IF
C
C---- Print for program flow
C  
                      CALLED = 'MODARRAY'
                      COMMENT = 
     +                    'Get statistics this image then clear arrays'
                      IF (DEBUG(99)) 
     +                        CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                      CALL MODARRAY(1, 0.0, 0,0,INTDUM,INTDUM)
                      CALL MODARRAY(0,0.0,0,0,INTDUM,INTDUM)
                    END IF
                    GOTO 35      
                  END IF
                END IF
C       
C----   Multiple image case
C       Only repeat measurement if this is the FIRST postrefinement and
C       in this case remeasure the first NADD packs again, up to a total
C       of NRPT repeats. Note that in NEWPREF mode we need to process
C       the first NADD+1 packs again.
C       Otherwise just print a warning message
C       
 228            IF (MULTISEG.OR.
     +               ((IPACK.EQ.NADD).AND.(.NOT.NEWPREF)).OR.
     +               ((IPACK.EQ.NADD+NSEG).AND.NEWPREF)) THEN
C       
C----   This is the first postref for a "width" case or any image in
C       a "single" case. Tests on cell shifts...no test on
C       orientation required because it is tested for each image.
C       
                  IF (CELLSHIFT.GT.SHIFTFAC) THEN
                    IF (MULTISEG) THEN
C
C---- Reset mosaic spread to original value, as refinement is unreliable
C     if cell is inaccurate and mosaicity tends to refine to zero.
C     Store the original eta in SAVETA at the end of the first round 
C     of cell refinement 
C     AGWL 8/12/11
                      IF (NREPEAT.EQ.0) THEN
                        SAVETA = SETA
                      END IF
                      ETA = SAVETA
C
C---- Reset NSIG to its default value (it may have been reduced to
C     a small value because initial orientation was poor) or to
C     the user defined value if set by a keyword. Also reset PTMIN
C     to 0.5
C
                      IF (ISIGSET.EQ.0) THEN
                        NSIG = 20
                      ELSE
                        NSIG = NSIGSAVE
                      END IF
                      PTMIN = 0.5
                      WRITE(IOUT,FMT=6168) CELLSHIFT,SHIFTFAC,
     +                     2.0*ETA/DTOR
                      IF (ONLINE) WRITE(ITOUT,FMT=6168) CELLSHIFT,
     $                     SHIFTFAC,2.0*ETA/DTOR
                      IF (BRIEF) WRITE(IBRIEF,FMT=6168) CELLSHIFT,
     $                     SHIFTFAC,2.0*ETA/DTOR
                      IF (DEBUG(1)) THEN
                        WRITE(IOUT,FMT=6169) NSIG,PTMIN
                        IF (ONLINE) WRITE(ITOUT,FMT=6169) NSIG,PTMIN
 6169                   FORMAT(1X,'In MAIN, NSIG reset to',I4,' PTMIN',
     +                  ' reset to',F5.2)
                      END IF
                    ELSE
                      NADDP = NADD
                      IF (NEWPREF) NADDP = NADDP + 1
                      WRITE(IOUT,FMT=6167) CELLSHIFT,SHIFTFAC,NADDP
                      IF (ONLINE) WRITE(ITOUT,FMT=6167) CELLSHIFT,
     $                     SHIFTFAC,
     +                     NADDP
                      IF (BRIEF) WRITE(IBRIEF,FMT=6167) CELLSHIFT,
     $                     SHIFTFAC,
     +                     NADDP
                    END IF
 6167               FORMAT(//,1X,'***** Cell parameter shift (',F5.1,
     +                   ' sds) exceeds limit of',F5.1,' sds *****',
     +                   /,1X,'Repeat measurement of first',I3,
     $                   ' images')
 6168               FORMAT(//,1X,'***** Cell parameter shift (',F5.1,
     $                   ' sds) exceeds limit of',F5.1,' sds *****',
     $                   /,1X,'Repeating the entire run, using the ',
     +                   'refined cell parameters as given above',
     +                   /,1X,'Mosaic spread reset to',F5.2)
C       
C       AL              IF (NADD.GT.1) NREPEAT = NREPEAT + 1
                    IF (MULTISEG.OR.(NADD.GT.1)) NREPEAT = NREPEAT + 1
C       
C----   Write the matrix anyway
C       
                    WRITE(IOUT,FMT=6302) NEWMATNAM(1:LENSTR(NEWMATNAM))
                    IF (ONLINE) WRITE(ITOUT,FMT=6302) 
     +                   NEWMATNAM(1:LENSTR(NEWMATNAM))
 6302               FORMAT(/1X,'New orientation matrix written to',
     +                   ' (keyword NEWMAT): ',A,/,1X,
     +                   'The missetting angles in this file are the',
     +                   ' refined missets for the FIRST image',/,1X,
     +                   'in the post-refinement.')
                    CALL CCPDPN (12,NEWMATNAM,'UNKNOWN','F',80,IFAIL)
                    IF (NEWPREF) THEN
                    WRITE(12,FMT=6300) ((AMAT(I,J),J=1,3),I=1,3),
     +                   (RMISSETS(1,J),J=1,3),
     +                   ((UMAT(I,J),J=1,3),I=1,3),CELL,
     +                   (RMISSETS(1,J),J=1,3),SPGNAM
                    ELSE
                    WRITE(12,FMT=6300) ((AMAT(I,J),J=1,3),I=1,3),
     +                   (DELPHIV(J),J=1,3),
     +                   ((UMAT(I,J),J=1,3),I=1,3),CELL,
     +                   (DELPHIV(J),J=1,3),SPGNAM
                    END IF
 6300               FORMAT(3(3F12.8/),(3F12.3/),3(3F12.8/),6F12.4,/,
     $                   3F12.4,/,'SYMM ',A)
                    CLOSE (UNIT=12)

                    IF (DISPMENU) THEN
                      SAVMATSTR = 'postrefinement'
                    END IF
C       
C----   Trap too many repeats of entire run
C       
                    IF (NREPEAT.GT.NRPT) THEN
                      WRITE(IOUT,FMT=6073) NRPT
                      IF (ONLINE) WRITE(ITOUT,FMT=6073) NRPT
                      IF (BRIEF) WRITE(IBRIEF,FMT=6073) NRPT
 6073                 FORMAT(//,1X,'****** Only',I3,' repeats allow',
     +                     'ed ***** Processing will be aborted',/,
     +                     1X,'Check if the refinement is unstable',
     +                     ', and if so increase the number of imag',
     $                     'es used',/,1X,'(keywords ADD or WIDTH ',
     +                     'on POSTREF keyword)',/,1X,
     +                     'The number of repeats can be changed ',
     +                     'with keyword REPEAT under POSTREF')
C       
                      IF (MULTISEG) THEN
C       
C----   Abort current run
C       
                        PRFINISH = .TRUE.
                        GOTO 230
                      END IF
                    END IF
C       
C----   If this is a postref segment run, start again by calling CONTROL
C       In this case the generate file is closed in CONTROL.
C       
                    IF (MULTISEG) THEN
                      RPTFIRST = .TRUE.
                      FIRSTTIME = .TRUE.
                      ISEG = 0
                      PRFINISH = .TRUE.
                      SHIFT(1) = 0.0
                      SHIFT(2) = 0.0
                      SHIFT(3) = 0.0
                      GOTO 230
                    END IF
C       
C       
C----   Restart
C       
                    SHIFT(1) = 0.0
                    SHIFT(2) = 0.0
                    SHIFT(3) = 0.0
                    CELLSHIFT = 0.0
                    NFILMS = 0
                    NOWRITE = 0
                    IFIRSTGOOD = IFIRSTPACK
                    IF (NBLOCK.NE.0) THEN
                      IFIRSTPACK = IFIRSTPACK - NUMBLOCK*NBLOCK
                      NPACK = 0
                    END IF
C       
C----   Initialisation flags for FINDPACK, OPENODS and reposition 
C       generate file
C       
                    MODEOP = 1
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6540)
                      IF (ONLINE) WRITE(ITOUT,FMT=6540)
 6540                 FORMAT(/,1X,'In MAIN, call QSEEK to reset to',
     +                       ' record 21')
                    END IF
C
C---- Print for program flow
C  
                    CALLED = 'QSEEK'
                    COMMENT = 'Reposition to first pack (restart)'
                    IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ********************
                    CALL QSEEK(IUNIT,21,1,36)
C       ********************
C       
                    JPACK = 0
                    IPACKREC = 21
                    IPACKHEAD = 21
C       
C----   If the BLOCK size is less than the WIDTH, some images will have been
C       integrated and written to MTZ file when the post-refinement is done.
C       In this case, need to close and re-open the MTZ file
C       
                    IF (NBLOCK.LT.NADD) THEN
                      IF (MTZOPEN) THEN
                        MTZPRT = 0
C       *********************
C
                        IF (DEBUG(1)) THEN
                          WRITE(IOUT,FMT=6542)
                          IF (ONLINE) WRITE(ITOUT,FMT=6542)
 6542                     FORMAT(/,1X,'In MAIN, call LWCLOS to close',
     +                    ' MTZ and then call STARTMTZ')
                        END IF
C
C---- Print for program flow
C  
                        CALLED = 'LWCLOS and STARTMTZ'
                        COMMENT = 'Close MTZ file then call STARTMTZ'
                        IF (DEBUG(99)) 
     +                        CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                        CALL LWCLOS(MTZOUT,MTZPRT)
                        IF(LBEST.AND.BESTOPEN)THEN
                          CLOSE(BESTHKL)
                          BESTOPEN = .FALSE.
                        ENDIF
C       *********************
                        CALL STARTMTZ
                        NLSUM1 = 0
                        NLSUM2 = 0
                      END IF
                    END IF
C       
C----   Close the current image file. Note is is opened with DISKIO
C       under Unix, Fortran under VMS, but if packed the file has already
C       been closed.
C       
                    IF (VAXVMS()) THEN
C       *************
C       AL                CLOSE (UNIT=INOD)
C       *************
                    ELSE
C       *****************************
C       AL                IF (.NOT.PACK) CALL QCLOSE(INOD)
C       *****************************
                    END IF
C       

C       
C----   Rewind SPOTOD file (contains measurement boxes)
C       
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6544)
                      IF (ONLINE) WRITE(ITOUT,FMT=6544)
 6544                 FORMAT(/,1X,'In MAIN, rewind SPOTOD (if not ',
     +                 'MULTISEG) and COORD files (if DENSE)')
                    END IF
                    IF(.NOT.MULTISEG)THEN
                      IF(NUSPOT)THEN
C
C---- Print for program flow
C  
                        CALLED = 'QSEEK'
                        COMMENT = 'Rewind SPOTDOD file (and COORD)'
                        IF (DEBUG(99)) 
     +                        CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                        CALL QSEEK(INMO,1,1,1)
                      ELSE
                        REWIND(INMO)
                      ENDIF
                    ENDIF
                    IF (DENSE) REWIND(ICOORD)
                    IF (DEBUG(1)) THEN
                      WRITE(IOUT,FMT=6350) IFIRSTPACK,NUMBLOCK,
     $                     NBLOCK
                      IF (ONLINE) WRITE(ITOUT,FMT=6350) IFIRSTPACK,
     +                     NUMBLOCK,NBLOCK
                      WRITE(IOUT,FMT=6119) (DELPHIV(I),I=1,3*NADD)
                      IF (ONLINE)WRITE(ITOUT,FMT=6119)(DELPHIV(I),
     $                     I=1,3*NADD)
                    END IF
C       
C----   Reset NUMBLOCK
C       
                    NUMBLOCK = 0
C
C---- Reinitialize arrays if doing NEWPREF
C
                    IF (NEWPREF) THEN
                      IF (DEBUG(1)) THEN
                        WRITE(IOUT,FMT=6538)
                        IF (ONLINE) WRITE(ITOUT,FMT=6538)
                      END IF
C
C---- Print for program flow
C  
                      CALLED = 'MODARRAY'
                      COMMENT = 
     +                    'Get statistics this image then clear arrays'
                      IF (DEBUG(99)) 
     +                      CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
C---- Call MODARRAY for statistics for this image, then to clear arrays.
                      INTDUM(1) = 0
                      INTDUM(2) = 0
                      CALL MODARRAY(1, 0.0, 0,0,INTDUM,INTDUM)
                      CALL MODARRAY(0,0.0,0,0,INTDUM,INTDUM)
                    END IF
                    GOTO 35      
                  END IF
                ELSE
C       
C----   Not the first post-refinement, give warning if shift large but
C       do not repeat
                  IF ((BIGSHIFT).OR.(CELLSHIFT.GT.SHIFTFAC)) THEN
                    WRITE(IOUT,FMT=6069) SHIFTMAX,SHIFTFAC
                    IF (ONLINE) WRITE(ITOUT,FMT=6069) SHIFTMAX,
     $                   SHIFTFAC
                    IF (BRIEF) WRITE(IBRIEF,FMT=6069) SHIFTMAX,
     $                   SHIFTFAC
 6069               FORMAT(/,1X,'***** WARNING *****',/,1X,'Shift',
     +                   ' in missetting angles exceeds',F6.3,
     +                   ' degrees',/,1X,'or cell parameter shift',
     +                   ' exceeds',F5.1,' sds',/,1X,'Consider us',
     +                   'ing a smaller angular width (WIDTH or A',
     $                   'DD) if crystal is slipping',/,1X,'or ',
     +                   'a larger angular width if refinement is',
     $                   ' unstable')
                    PRFHS(NFILMS+1) = .TRUE.
                  END IF
                END IF
C       
              END IF
C----   Above is end of IF (POSTREF.AND.SUMPART) block
C       
C       
C----   If this is a multi-segment post-refinement run, stop once refinement is
C       complete for the last pack
C       
 232          CONTINUE
              IF (MULTISEG.AND.(ISEG.EQ.NSEG).AND.
     +             (((IPACK.EQ.NPACK-1).AND.(.NOT.NEWPREF)).OR.
     +             ((IPACK.EQ.NPACK).AND.NEWPREF))) THEN
                
C       
C----   Write new orientation matrix
C       
                WRITE(IOUT,FMT=6302) NEWMATNAM(1:LENSTR(NEWMATNAM))
                IF (ONLINE) WRITE(ITOUT,FMT=6302) 
     +               NEWMATNAM(1:LENSTR(NEWMATNAM))
                CALL CCPDPN (12,NEWMATNAM,'UNKNOWN','F',80,IFAIL)
                IF (NEWPREF) THEN
                WRITE(12,FMT=6300) ((AMAT(I,J),J=1,3),I=1,3),
     +               (RMISSETS(1,J),J=1,3),
     +                   ((UMAT(I,J),J=1,3),I=1,3),CELL,
     +               (RMISSETS(1,J),J=1,3),SPGNAM
                ELSE
                WRITE(12,FMT=6300) ((AMAT(I,J),J=1,3),I=1,3),
     +               (DELPHIV(J),J=1,3),
     +               ((UMAT(I,J),J=1,3),I=1,3),CELL,
     +               (DELPHIV(J),J=1,3),SPGNAM
                END IF
                CLOSE (UNIT=12)
                IF (DISPMENU) THEN
                  SAVMATSTR = 'postrefinement'
                END IF
                PRFINISH = .TRUE.
                GOTO 230
              END IF
C       
              IF (DEBUG(1)) THEN
                IF (ONLINE) WRITE (ITOUT,FMT=6064) MAXR,NOWRITE,
     +               ISKIPI(NOWRITE),IRAS
 6064           FORMAT (/1X,'After calling MEAS,MAXR= ',I6,' NOWRITE=',
     +               I3,' ISKIPI',I3,/1X,'IRAS',5I4)
                WRITE (IOUT,FMT=6064) MAXR,NOWRITE,ISKIPI(NOWRITE),IRAS
              END IF
C       
              IF (FIRSTPASS) THEN
C       
C----   Write refined camera constants back to generate file
C       
                MODEWR = 1
C       
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6546) MODEWR
                  IF (ONLINE) WRITE(ITOUT,FMT=6546) MODEWR
 6546             FORMAT(/,1X,'In MAIN, call WRGEN with MODE=',I3,
     +                   ' to write back refined camera constants')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'WRGEN'
                COMMENT = 'Store camera constants '
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************
                CALL WRGEN(MODEWR,PROFILE,ADDPP)
C       ****************************
C       
                MODEWR = 0
C       
C----   If DENSE, (many close spots) write a list of spot coordinates, sorted
C       on scanner X coordinate, to a file (written from GENSORT)
C       
                IF (DENSE) THEN
                  MODE = -2
                  IF (NEWPREF.AND.LAST) LAST = .FALSE.
                  IF (DEBUG(1)) THEN
                    WRITE(IOUT,FMT=6548) MODE
                    IF (ONLINE) WRITE(ITOUT,FMT=6548) MODE
 6548               FORMAT(/,1X,'In MAIN, call GENSORT with MODE=',I4,
     +                   ' to create COORDS file')
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'GENSORT'
                  COMMENT = 'Create COORDS file'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************************************
                  CALL GENSORT(MODE,FORCE,LIMIT,VLIM,NMR,ADDPART,
     $                 PTMIN,LAST)
C       ****************************************************
                END IF
                GO TO 230
              END IF
C       
C-----  If not integrating the image, skip call to PROCESS
C       
              IF (NOMEAS) GOTO 230



C
C ***** When using PROFILE READ, it will never create the COORDS file
C       so need to create and rewind it now. This change added
C       when testing multilattice work. It should not affect normal integration.
C       AGWL Aug 2013.
C       To avoid any possible issue sfor 7.1.0 release, comment out this code
C       for the release.
C
CAL             IF (DENSE) THEN
CAL               MODE = -2
CAL               IF (NEWPREF.AND.LAST) LAST = .FALSE.
CAL               IF (DEBUG(1)) THEN
CAL                 WRITE(IOUT,FMT=6548) MODE
CAL                 IF (ONLINE) WRITE(ITOUT,FMT=6548) MODE
CAL               END IF
C
C---- Print for program flow
C  
CAL               CALLED = 'GENSORT'
CAL               COMMENT = 'Create COORDS file'
CAL               IF (DEBUG(99)) 
CAL     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ****************************************************
CAL               CALL GENSORT(MODE,FORCE,LIMIT,VLIM,NMR,ADDPART,
CAL     $                 PTMIN,LAST)
C       ****************************************************
CAL               REWIND ICOORD
CAL             END IF

C
C ***** END of fix to enable PROFILE READ to work.
C
C       
C----   Process the measurements for each spot if in profile mode
C       unless in second pass of accumulated profile processing
C       
              IF (PROFILE) THEN
C       
C       
                ADDPP = ADDP(IPACK)
cdms21.09.2004   Let user know what is happening.
                IF (IMGP) WRITE (IOUT,FMT=6015) ID,PHIBEG,PHIEND
                IF(SOCKLO)THEN
                  WRITE(LONGLINE,FMT=6070)
     $                 SHORTFN(1:LENSTR(SHORTFN)),
     $                 TEMPLSAV(1:lenstr(templsav)),ID
                  CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $                 LENSTR(LONGLINE),LONGLINE) 
                ENDIF
                IF (WINOPEN) THEN
                  CALL MXD_FLU(I)
                  CALL MXDBSY(0,'Integrating image')
                END IF       
C       
                IF (DEBUG(1))THEN
                  WRITE(IOUT,FMT=6550)              
                  IF (ONLINE) WRITE(ITOUT,FMT=6550)              
 6550             FORMAT(/,1X,'In MAIN, call PROCESS')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'PROCESS'
                COMMENT = 'Integrating image '
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ******************************************
                CALL PROCESS(NFLMO,IXSHIFT,IYSHIFT,ADDPP,ISKIPI,
     +                LPINTG,NEWPREF,NUSPOT,LPINTG,NOBACK,ID,NUMBLOCK,
     +                XMLABORT)
C       ******************************************
C
C---- Abort run if flag set.
C
                IF (XMLABORT) THEN
                  CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                  GOTO 30
                END IF
C
                IF (WINOPEN) THEN
                  CALL MXD_FLU(I)
                  CALL MXDBSY(-1, ' ')
                END IF
C       
C----   Display residual vectors if requested, allows bad spot changes
C
cdms21.09.2004    Use OPENODS to display if FILMPLT is set.
                IF (LPINTG.AND.FILMPLT) THEN
C
C----   If processing more than a single image, need to read in the
C       image again as it will no longer be stored in memory. However,
C       the image must always be read into the same "half" of array
C       IMAGE because we need to keep the last image of the current BLOCK
C       of images in memory because it has not yet been processed.
C       To do this, must disable updating of the pointer ISTART in
C       OPENODS. Do this by setting MODEOP=3
C
C       Note that ID has to be decremented by 1 (IDTMP=ID-1) when
C       SUMPART is true because OPENODS increments it by one.
C
                  IF (NPACK.GT.1) THEN
                    IDTMP = ID
                    IF (SUMPART) IDTMP = ID - 1
                    MODEOP = 3
                  IF (DEBUG(1))THEN
                    WRITE(IOUT,FMT=6551) MODEOP              
                    IF (ONLINE) WRITE(ITOUT,FMT=6551)MODEOP              
 6551               FORMAT(/,1X,'In MAIN, call OPENODS with MODE=',I2,
     +                    ' for display of residual vectors')
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'OPENODS'
                  COMMENT = 'Display residual vectors on image'//
     +                      ' LIPROCESS=5'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ********************************************************
C----   OPENODS called to display residual vectors
C
                    LIPROCESS = 5
                    CALL OPENODS(IDENT,IDTMP,FILM,ODEXT,FDISK,
     +                   MODEOP,PACK,ODFILE,SEPCHAR,FORCEREAD,IPACK,
     +                   TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
C       *******************************************************
                    MODEOP = 0
                  END IF
C       
C       
C----   Need to set flag to repredict the pattern
C       ***** Displaying image after integration *****
C       
                  MODEDISP = 5
                  IF (DEBUG(1))THEN
                    WRITE(IOUT,FMT=6552) MODEDISP              
                    IF (ONLINE) WRITE(ITOUT,FMT=6552) MODEDISP              
 6552               FORMAT(/,1X,'In MAIN, call XDISP with MODE=',I2,
     +                    ' for display of image after integration')
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'XDISP'
                  COMMENT = ' After integration'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL XDISP(MODEDISP,FIRSTPACK,PACK,IFIRSTPACK,
     +                 FIRSTFILM,GENOPEN)
                  IF (MODEDISP.EQ.99) THEN
C       
C----   Abort current run
C       
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    IF (DISPMENU) THEN
                      GOTO 34
                    ELSE
                      GOTO 30
                    END IF
                  END IF
                  IF (IPACK.EQ.NPACK) LPINTG = .FALSE.
C
C----   End of display image block
C
                END IF
C       
C       
                IF (.NOT.SECONDPASS) THEN
                  IF (DEBUG(1)) THEN
                    WRITE(IOUT,FMT=6544)
                    IF (ONLINE) WRITE(ITOUT,FMT=6544)
                  END IF
                  IF(.NOT.MULTISEG)THEN
                    IF(NUSPOT)THEN
C
C---- Print for program flow
C  
                      CALLED = 'QSEEK'
                      COMMENT = 'Rewind SPOTDOD file (and COORD)'
                      IF (DEBUG(99)) 
     +                        CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                      CALL QSEEK(INMO,1,1,1)
                    ELSE
                      REWIND(INMO)
                    ENDIF
                  ENDIF
                  IF (DENSE) REWIND ICOORD
                END IF
              END IF
C       
C----   Write summary information
C       
 230          CONTINUE

              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6700) FIRSTPASS, SECONDPASS,THIRDPASS
                IF (ONLINE) WRITE(ITOUT,FMT=6700) FIRSTPASS, 
     +             SECONDPASS,THIRDPASS
 6700           FORMAT(1X,'Got to label 230',/,1x,
     +                 'FIRSTPASS, SECONDPASS,THIRDPASS',3L3)
              END IF
              ICTF = NINT(XTOFRA*XTOFD)
C              ITILT = TILT/FDIST
C              ITWIST = TWIST/FDIST
              CALL SETDIS(ITILT,ITWIST,2)
              IF (IMGP) THEN
                IROFF = NINT(ROFF)
C       AL              IROFF2 = NINT(ROFF2)
                ITOFF = NINT(TOFF)
              ELSE
                IBULGE = BULGE/FDIST
              END IF
C       
C       
              IF (.NOT.FIRSTPASS) THEN
                IF (DEBUG(1))THEN
                  WRITE(IOUT,FMT=6554)
                  IF (ONLINE) WRITE(ITOUT,FMT=6554)
 6554             FORMAT(/,1X,'In MAIN, write summary file ISUMMR')
                END IF
C       
C----   Store maximum shifts in ROFF,TOFF,CCOMEGA, number bad spots,weighted 
C       residual etc
C       
                IF (ROFFSAVE.GT.-998.0) THEN
                  ROFFMAX = MAX(ROFFMAX,ABS(0.01*IROFF - ROFFSAVE))
                  TOFFMAX = MAX(TOFFMAX,ABS(0.01*ITOFF - TOFFSAVE))
                  X = CCOM-CCOMSAVE
                  IF (X.GT.180) X = X - 360.0
                  IF (X.LT.-180) X = X + 360.0
                  CCOMAX = MAX(CCOMAX,ABS(X))
                END IF
                WRMAX = MAX(WRMAX,WRMSRES)
                NBADMAX = MAX(NBADMAX,NBAD)
                AVBGRMAX = MAX(AVBGRMAX,AVBGRATIO)
                AVBGRMIN = MIN(AVBGRMIN,AVBGRATIO)
                ROFFSAVE = 0.01*IROFF
                TOFFSAVE = 0.01*ITOFF
                CCOMSAVE = CCOM
                IF (IMGP) THEN
                  WRITE (ISUMMR,FMT=6067) ID,0.01*CCX,0.01*CCY,CCOM,
     +                 0.01*ICTF,YSCAL,ITILT,ITWIST,0.01*IROFF,
     +                 0.01*ITOFF,0.01*RMSRES,WRMSRES,
     +                 NOFR,(NREF-NOFR),NOLO,NNEG,NBAD,FIOVSDP(9),
     +                 FIOVSDP(8),RFACOV,NRSYM,SDRATOV
                ELSE
                  WRITE (ISUMMR,FMT=6066) ID,ABC(FILM:FILM),0.01*CCX,
     +                 0.01*CCY,CCOM,0.01*ICTF,YSCAL,ITILT,ITWIST,
     +                 0.01*IBULGE,
     +                 0.01*RMSRES,WRMSRES,NOFR,(NREF-NOFR),NOLO,NNEG,
     +                 NBAD,FIOVSDP(9),FIOVSDP(8)
                END IF
              END IF
cdms21.09.2004    Write summary here in case where we have read in profiles.
                IF (PRREAD) THEN
C
C----   Store information for summary file
C
                  ISUMM(1,NFILMS+1) = ID
                  SUMMCH(NFILMS+1) = ABC(FILM:FILM)
                  ISUMM(2,NFILMS+1) = CCX
                  IF (INVERTX) ISUMM(2,NFILMS+1) = -CCX
                  ISUMM(3,NFILMS+1) = CCY
                  ISUMM(4,NFILMS+1) = ICTF
                  ISUMM(5,NFILMS+1) = ITILT
                  ISUMM(6,NFILMS+1) = ITWIST
                  ISUMM(7,NFILMS+1) = IBULGE
                  IF (IMGP) ISUMM(7,NFILMS+1) = IROFF
                  ISUMM(8,NFILMS+1) = (NRS-NREJS)
                  ISUMM(15,NFILMS+1) = CBAR
                  IF (IMGP) THEN
                    ISUMM(19,NFILMS+1) = ITOFF
                  END IF
                  RSUMM(1,NFILMS+1) = CCOM
C
C---- If CCOM has been reset to TRUECCOM in REFRT1, want to store the
C     actual refined value in summary file.
                  IF (RESETCCOM) RSUMM(1,NFILMS+1) = DPSIX + TRUECCOM
                  IF ((ABS(RSUMM(1,NFILMS+1)).GT.100.0).AND.
     +             (RSUMM(1,NFILMS+1).LT.0))
     +              RSUMM(1,NFILMS+1) = RSUMM(1,NFILMS) + 360.0
                  IF (RSUMM(1,NFILMS+1).GT.100.0)
     +              RSUMM(1,NFILMS+1) = RSUMM(1,NFILMS) - 360.0
                  RSUMM(2,NFILMS+1) = YSCAL
                  YSCALERR = MAX(ABS(YSCAL - YSCALIN),YSCALERR)
                  RSUMM(3,NFILMS+1) = RMSRES
                  IF (RWEIGHT) RSUMM(4,NFILMS+1) = WRMSRES
                  RSUMM(12,NFILMS+1) = TOFF
                  IF (IMGP) THEN
                    NLSUM1 = NLSUM1 + 1
                    WRITE (LINESUM1(NLSUM1),FMT=6067)
     1               ISUMM(1,NFILMS+1),
     +               (0.01*ISUMM(K,NFILMS+1),K=2,3),RSUMM(1,NFILMS+1),
     +               0.01*ISUMM(4,NFILMS+1),
     +               RSUMM(2,NFILMS+1),(ISUMM(K,NFILMS+1),K=5,6),
     +               0.01*ISUMM(7,NFILMS+1),0.01*ISUMM(19,NFILMS+1)
     +               ,0.01*RSUMM(3,NFILMS+1),RSUMM(4,NFILMS+1),
     +               (ISUMM(K,NFILMS+1),K=9,13),
     +               (RSUMM(K,NFILMS+1),K=5,7),
     +               ISUMM(20,NFILMS+1),RSUMM(8,NFILMS+1)
                  ENDIF
                  IF (.NOT.POSTREF) NFILMS=NFILMS+1
                ENDIF
cdms21.09.2004    End addition for PRREAD true.
C       
C----   If accumulating profiles, on first pass do not call process
C       store XCEN,YCEN etc
C       
              IF (FIRSTPASS) THEN
                NFILMS = NFILMS + 1
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6426) NFILMS,ID,NREPEAT,ISEG
                  IF (ONLINE) WRITE(ITOUT,FMT=6426) NFILMS,ID,
     +                                  NREPEAT,ISEG
 6426             FORMAT(/,1X,'In MAIN, NFILMS set to',I4,' for stor',
     +              'ing detector parameters for image ',I7,'  nrepeat',
     +                 I2,' iseg',I2)
                END IF
C       
C----   Store information for summary file
C       
                ISUMM(1,NFILMS) = ID
                SUMMCH(NFILMS) = ABC(FILM:FILM)
                ISUMM(2,NFILMS) = CCX
                IF (INVERTX) ISUMM(2,NFILMS) = -CCX
                ISUMM(3,NFILMS) = CCY
                ISUMM(4,NFILMS) = ICTF
                ISUMM(5,NFILMS) = ITILT
                ISUMM(6,NFILMS) = ITWIST
                ISUMM(7,NFILMS) = IBULGE
                IF (IMGP) ISUMM(7,NFILMS) = IROFF
                ISUMM(8,NFILMS) = (NRS-NREJS)
                ISUMM(15,NFILMS) = CBAR
                IF (IMGP) THEN
                  ISUMM(19,NFILMS) = ITOFF
                END IF
                RSUMM(1,NFILMS) = CCOM
C
C---- If CCOM has been reset to TRUECCOM in REFRT1, want to store the
C     actual refined value in summary file.
C
                IF (RESETCCOM) RSUMM(1,NFILMS) = DPSIX + TRUECCOM
                IF ((ABS(RSUMM(1,NFILMS)).GT.100.0).AND.
     +               (RSUMM(1,NFILMS).LT.0)) 
     +               RSUMM(1,NFILMS) = RSUMM(1,NFILMS) + 360.0
                IF (RSUMM(1,NFILMS).GT.100.0)
     +               RSUMM(1,NFILMS) = RSUMM(1,NFILMS) - 360.0
                RSUMM(2,NFILMS) = YSCAL
                YSCALERR = MAX(ABS(YSCAL - YSCALIN),YSCALERR)
                RSUMM(3,NFILMS) = RMSRES
                IF (RWEIGHT) RSUMM(4,NFILMS) = WRMSRES
                RSUMM(12,NFILMS) = TOFF
              END IF
C       
C----   Store summary information on post-refinement. 
C       
              IF ((FIRSTPASS.OR.PRREAD).AND.POSTREF) THEN
C       
C---    If reading profiles, then FIRSTPASS is never true, so must
C       increment NFILMS here.
C       
                IF (PRREAD) NFILMS = NFILMS + 1
                ISUMM(1,NFILMS) = ID                             
C       
C----   POSTREF summary information. If NADD>1 AND FIXED, then the parameters
C       for the FIRST NADD images will be identical (because the first postref
C       run is only done once NADD images have been processed). So when the
C       first post-refinement has been done, set postref summary parameters
C       for all these images. NOTE there will be problems if NADD is greater
C       than NBLOCK !! IF NOT FIXED, then all missetting angles and sds
C       will be different, so must pick them up from DELPHIV and SDDELPHI
C       from /POSTCHK/. Note that we also need to check on SUMPART, because
C       if there are only NADD images in total, then even when IPACK=NADD
C       the post-refinement will not have been carried out because the next
C       image was not present !
C       
C       AL             IPT = 0
C       AL             IPTR = 0
C       
C----   IPT is the pointer into DELPHIV to pick up refined missets. If NADD is
C       greater than the number of images in a BLOCK, then we must not start
C       IPT at zero, but 3*NBLOCK*(NADD/NBLOCK)
C       
                IPT = 3*NBLOCK*((NADD-1)/NBLOCK)
                IPTR = IPT
                JSTART = NFILMS
C
C--- NOTE need to take account of multiple segments when working out
C    when to set JSTART to 1 to store all missets. Note this is ONLY
C    done when using POSTREF NOMULTI (ie NOT NEWPREF) 7/10/03
C
                IF ((NADD.GT.1).AND.
     +               (IPACK.EQ.(NADD+ISEG-1)).AND.SUMPART.AND.
     +               (.NOT.NEWPREF)) JSTART = 1

CAL     +               (.NOT.NEWPREF)).OR.((IPACK.EQ.NADD+1)
CAL     $               .AND.NEWPREF)) JSTART = 1
C
                IF (NEWPREF) JSTART = NFILMS
C
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6310) JSTART,NFILMS,IPACK,NADD,NBLOCK,
     +                 NUMBLOCK,IPT
                  IF (ONLINE) WRITE(ITOUT,FMT=6310) JSTART,NFILMS,
     +                 IPACK,NADD,NBLOCK,NUMBLOCK,IPT
                END IF
 6310        FORMAT(/,1X,'In MAIN, storing postref info for summary',
     +              ' file, JSTART=',I4,'  NFILMS=',I4,'  IPACK=',I4,
     +               '  IADD=',I4,' NBLOCK=',I3,'  NUMBLOCK=',I3,
     +               ' IPT=',I3)
                DO 237 JFILMS = JSTART,NFILMS
                  DO 234 I = 1,3
                    PRFSUM(16+I,JFILMS) = SDCELL(I)*CELL(I)
                    PRFSUM(19+I,JFILMS) = SDCELL(I+3)
                    PRFSUM(22+I,JFILMS) = SDBEAM(I)/DTOR
                    XWARN(I,18) = MAX(XWARN(I,18),SDCELL(I)*CELL(I))
                    XWARN(I+3,18) = MAX(XWARN(I+3,18),SDCELL(I+3))
C       
C----   Monitor large standard deviations in any cell parameter for
C       warning message. Test for sd in cell edge greater than 0.1A and
C       in cell angle greater than 0.1 degrees
C       

                    IF (SDCELL(I)*CELL(I).GT.0.1) THEN
                      WARN(18) = .TRUE.
                      IWARN(I,18) = 1
                    END IF
                    IF (SDCELL(I+3).GT.0.1) THEN
                      WARN(18) = .TRUE.
                      IWARN(I+3,18) = 1
                    END IF
C       
CAL                 IF ((NADD.GT.1).AND.(.NOT.FIXED).AND.
CAL     +              ((IPACK.EQ.NADD).AND.SUMPART.AND.(.NOT.POSTHOC)
CAL     +               .OR. ((IPACK.EQ.NADD+1).AND.POSTHOC))) THEN
                    IF ((NADD.GT.1).AND.
     +                   (IPACK.EQ.(NADD+ISEG-1)).AND.SUMPART.AND.
     +                   (.NOT.NEWPREF)) THEN
C       
C----   Store values for first NADD images
C       
                      IPT = IPT + 1
                      PRFSUM(I,JFILMS) = DELPHIV(IPT)
                      IF (I.GT.2) GOTO 234
                      IPTR = IPTR + 1
                      PRFSUM(13+I,JFILMS) = SDDELPHI(IPTR)
                    ELSE
C       
C----   Have not yet done a complete post-refinement, get missets from
C       DELPHI
                      PRFSUM(I,JFILMS) = DELPHI(I)
                      IF (I.LT.3) PRFSUM(13+I,JFILMS) = SDDELPHI(I)
                    END IF
C
C---- Special case for NREWPREF refinement
C
                    IF (NEWPREF) THEN
C
C---- In case where NVIRBAT>1, store missets for first images once a
C     refinement has actually been done. 
C
CAL                   IF ((NVIRBAT.GT.1).AND.(IPACK.EQ.(NVIRBAT+1))) THEN
                     IF (DEBUG(1)) THEN
                       WRITE(IOUT,FMT=6696) NVIRBAT,DONEREF,
     +                                      FIRSTREF,JFILMS
                       IF (ONLINE) WRITE(ITOUT,FMT=6696) NVIRBAT,
     +                                      DONEREF,FIRSTREF,JFILMS
 6696                  FORMAT(1X,'NVIRBAT=',I3,' DONEREF',L2,
     +                    '  FIRSTREF',L2,'  JFILMS',I3)
                     END IF
                   IF ((NVIRBAT.GT.1).AND.DONEREF.AND.
     +                                    (FIRSTREF)) THEN
c
c----Reset FIRSTREF flag but only after all 3 missets have been dealt with.
C

                     IF (I.EQ.3) FIRSTREF = .FALSE.
C
C---- First need to see if this is already in the second block of images
C     in which case the missets for the first block need to be assigned as well.
C     in order that the loggraph output stored in LINESUM2 (line 7124) is correct.
C     NUMBLOCK is the number of the current block
C     IPACK loops from IFIRSTPACK to NPACK, which starts at 1 and NBLOCK (number 
C     of images in a block) and are incremented by NBLOCK for each block of images.
C     JFILMS loops from JSTART to NFILMS where JSTART runs from 1 to NBLOCK
C     and NFILMS is the same as JFILMS, as long as NEWPREF is TRUE which
C     it now always is, ie one stored at a time.
C     So the summary values are stored for one block of images, then these are 
C     overwritten by values for the next block of images etc etc.

                     DO 233 J = 1,JFILMS-1
CAL                       PRFSUM(I,J) = RMISSETS(J,I)
                       PRFSUM(I,J) = SAVEDELPHI(I)
                       IF (DEBUG(1)) THEN
                         WRITE(IOUT,FMT=6690) I,IPACK,J,SAVEDELPHI(I)
                         IF (ONLINE) WRITE(ITOUT,FMT=6690) 
     +                                 I,IPACK,J,SAVEDELPHI(I)
 6690                    FORMAT(1X,'Storing misset',I2,' for unrefined',
     +                      'image',I5,' into element',I3,' value',F8.3)
                       END IF
                       IF (I.LT.3) PRFSUM(13+I,J) = SDMISSETS(J,I)
 233                 CONTINUE
C
C---- Now have to deal with situation where the first image to be refined is 
C     not in the first block of images. Need to correct "LINESUM2" so that values
C     written for loggraph part of summary file are correct.
C
                     IF ((NUMBLOCK.GT.1).AND.(I.EQ.3)) THEN
                       L = 0
                       DO 231 J = 1,NUMBLOCK-1
                         DO 2311 K = 1,NBLOCK
                           L = L + 1
                           IF (DEBUG(1)) THEN
                             WRITE(IOUT,FMT=6699) L,LINESUM2(L)
                             IF (ONLINE) WRITE(ITOUT,FMT=6699) 
     +                                   L,LINESUM2(L)
 6699                        FORMAT(1X,'For image ',I7,
     +                              ' initial linesum2',/,A)
                           END IF
                           STRING3 = LINESUM2(L)(1:9)
                           WRITE(STRING4,FMT=6698)
     +                          (SAVEDELPHI(II),II=1,3)
 6698                      FORMAT(3(1X,F8.2))
                           LINESUM2(L) = STRING3//STRING4//
     +                                   LINESUM2(L)(37:200)
                           IF (DEBUG(1)) THEN
                             WRITE(IOUT,FMT=6697) LINESUM2(L)
                             IF (ONLINE) WRITE(ITOUT,FMT=6697) 
     +                                   LINESUM2(L)
 6697                        FORMAT(1X,'Final linesum2',/,A)
                           END IF
 2311                    CONTINUE
 231                   CONTINUE
                     END IF
                   END IF
                   IF (DEBUG(1)) THEN
                     WRITE(IOUT,FMT=6692) I,IPACK,JFILMS,
     +                              SAVEDELPHI(I) 
                     IF (ONLINE) WRITE(ITOUT,FMT=6692) 
     +                   I,IPACK,JFILMS,SAVEDELPHI(I)
 6692                FORMAT(1X,'Storing misset',I2,' for image ',
     +                          I7,' into element',I3,
     +                        '  savedelphi value',F8.3)
                   END IF
C
C---- Now use SAVEDELPHI because RMISSETS does not store the smoothed values.
C
CAL                   PRFSUM(I,JFILMS) = RMISSETS(IPACK,I)
                   PRFSUM(I,JFILMS) = SAVEDELPHI(I)
                   IF (I.LT.3) PRFSUM(13+I,JFILMS) = SDMISSETS(IPACK,I)
CAL                   IF (I.LT.3) PRFSUM(13+I,JFILMS) = SDMISSETS(IPACK,I)
                 END IF
 234              CONTINUE
c     
c----   missets seem to go missing for last image of first batch if newpref 
C       is this really needed ??? 11/5/15
c     
                  if(newpref.and.(ipack.eq.nadd+1))then
                    if (debug(1)) then
                      write(iout,fmt=6694) jfilms
                      if (online) write(itout,fmt=6694) jfilms
 6694                 format(/,1X,'Special write of prfsum jfilms=',I4)
                    end if
                    do 235 i=1,3,1
                      PRFSUM(I,JFILMS) = SAVEDELPHI(I)
 235                continue
                  endif
                  DO 236 I = 1,6
                    PRFSUM(I+3,JFILMS) = CELL(I)
 236              CONTINUE
                  PRFSUM(10,JFILMS) = RETA/DTOR
                  PRFSUM(11,JFILMS) = RDIVH/DTOR
                  PRFSUM(12,JFILMS) = RDIVV/DTOR
                  PRFSUM(13,JFILMS) = RESID
                  PRFSUMI(JFILMS) = NREFPR
 237            CONTINUE
              END IF
C
C---- If finished a multiseg run, go back
C
              IF (PRFINISH) THEN
                PRFINISH = .FALSE.
                IF (RPTFIRST) THEN
C
C---- Do not call CONTROL, get stored information
C
                  ISEG = 1
                  IF (DEBUG(1))THEN
                    WRITE(IOUT,FMT=6556) ISEG
                    IF (ONLINE) WRITE(ITOUT,FMT=6556) ISEG
 6556               FORMAT(/,1X,'In MAIN, call CELLREFSET, ISEG=',I3)
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'CELLREFSET'
                  COMMENT = 'Get stored information for ISEG=1'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL CELLREFSET(IFIRSTPACK,NREPEAT,ISEG,
     +                            RPTFIRST,FIRSTTIME,INERR)
                  IF (INERR) THEN
C       
C----   Abort current run
C       
                    CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                    IF (DISPMENU) THEN
                      GOTO 34
                    ELSE
                      GOTO 30
                    END IF
                  END IF
                  ISEG = 0
                  GOTO 36
                END IF

C
C---- Check if cell has actually been refined by testing SD's of cell
C     parameters. WORKED is set rue if ANY sd > 0.0
C
                WORKED = .FALSE.
                DO 6559 I = 1,6
                  IF (I.LE.3) THEN
                    X = CELL(I)
                  ELSE
                    X = 1.0
                  END IF
                  IF (X*SDCELL(I).GT.0.0001) WORKED = .TRUE.
 6559          CONTINUE
                IF ((.NOT.WORKED).AND.SOCKLO) THEN
                  STRING1 = ' '
                  WRITE(STRING1,FMT=6714)
 6714             FORMAT('No refinement of cell parameters has',
     +            ' been carried out.__nl__Usually this is because ',
     +            'there are not enough reflections.__nl__This could',
     +            ' be because the indexing is wrong or the images',
     +            ' are very weak.__nl__If the indexing is OK, try',
     +            ' including more images or reducing the__nl__',
     +            '"Threshold for using reflections" in Postrefinement',
     +            '__nl__Processing options->Advanced refinement')
                  WRITE(LONGLINE,FMT=6716) STRING1(1:LENSTR(STRING1))
                  CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $              LENSTR(LONGLINE),LONGLINE)
 6716             FORMAT('<?xml version="1.0"?>',
     $            '<!DOCTYPE trapped_error_response>',
     $            '<trapped_error_response>',
     $            '<type>No_cell_refinement</type>',
     $            '<message>',A,'</message>',
     $            '</trapped_error_response>')
                END IF
C
C---- Display summary of refinement
C
                IF (DEBUG(1)) THEN
                  WRITE(IOUT,FMT=6558)
                  IF (ONLINE) WRITE(ITOUT,FMT=6558)
 6558             FORMAT(/,1X,'In MAIN, call PRSUMMARY')
                END IF
C
C---- Print for program flow
C  
                CALLED = 'PRSUMMARY'
                COMMENT = 'Print summary of cell refinement'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
C---- PRSUMMARY sends XML for results of post refinement
C
                CALL PRSUMMARY(NREPEAT,NSEG,LASTFILM,RSUMM,ISUMM,
     +               PRFSUM,CELL,OLDCELL,DELPHI,NEWPREF,DISPMENU,
     +               newgui,NTDIG)
                SAVMATSTR = 'postrefinement'
                SAVMATNAM = NEWMATNAM
C
C---- If MINREF has been changed, restore original value
C
                IF (MINREFRESET) THEN
                  MINREF = MINREFSAVE
                  MINREFRESET = .FALSE.
                END IF
C
C---- Refinement task has finished so call MRESET to reset parameters
C     and send XML that refinement task has finished.
C 
C
C---- Print for program flow
C  
                CALLED = 'MRESET'
                COMMENT = 'Reset variables after finishing'//
     +                    ' cell refinement'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                IF (DISPMENU) THEN
                  GOTO 34
                ELSE
                  GOTO 30
                END IF
              END IF
C       
C----   Make call to MODARRAY to remove finished reflections
C       
              INTDUM(1) = 0
              INTDUM(2) = 0
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6560)
                IF (ONLINE) WRITE(ITOUT,FMT=6560)
 6560           FORMAT(/,1X,'In MAIN, call MODARRAY to remove finished',
     +                    ' reflections')
              END IF
C
C---- Note, if getting phi profiles, do NOT remove finished reflections
C
CAL              IF (NEWPREF.AND.(.NOT.PHIPROF)) THEN
              IF (NEWPREF) THEN
C
C---- Print for program flow
C  
                CALLED = 'MODARRAY'
                COMMENT = 'Remove finished reflections'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL MODARRAY(1, 0.0, 0,0,INTDUM,INTDUM)
              END IF
C       
C----   end of PROCESS section from MOSES2 = .TRUE.
C
chrp06122001            ENDIF

C       
C----   End of loop over films in this pack
C       
 240      CONTINUE
C
C
          IF (DEBUG(1)) THEN
            WRITE(IOUT,FMT=6562)
            IF (ONLINE) WRITE(ITOUT,FMT=6562)
 6562       FORMAT(/,1X,'In MAIN, end of loop over films')
          END IF
C
C---- Print for program flow
C  
          CALLED = ''
          COMMENT = '*** End of current image (image loop) ***'
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)

C       
C----   Close the image file. Note is is opened with DISKIO
C       under Unix, Fortran under VMS, but if file is packed it has
C       been closed automatically
C       
          IF (VAXVMS()) THEN
C       *************
C       AL          CLOSE (UNIT=INOD)
C       *************
          ELSE
C       ****************************
C       AL          IF (.NOT.PACK) CALL QCLOSE(INOD)
C       ****************************
          END IF
C       
C----   End of loop over images in this generate file
C       
c       -harvest
          KHFLMS = KHFLMS + 1
          HARETA(KHFLMS) = RETA/DTOR
          HARDIH(KHFLMS) = RDIVH/DTOR
          HARDIV(KHFLMS) = RDIVV/DTOR
c       -harvest
 250    CONTINUE
C
C
 2501   IF (DEBUG(1)) THEN
          WRITE(IOUT,FMT=6564) ACCUMULATE, FIRSTPASS, SECONDPASS
          IF (ONLINE) WRITE(ITOUT,FMT=6564) ACCUMULATE, FIRSTPASS,
     +               SECONDPASS
 6564     FORMAT(/,1X,'In MAIN end of loop over images, ACCUMULATE',L2,
     +       '  FIRSTPASS',L2,'  SECONDPASS',L2)
        END IF
C       
C----   If accumulating profiles, prepare for next pass
C       
chrp06122001        IF(MOSES2)THEN
          IF (ACCUMULATE) THEN
            IF (FIRSTPASS) THEN
C
C---- If collecting data for a phi profile, do not go to SECONDPASS, call
C     REFLFIND to extract the phi profile information for arrays in MODARRAY
C
C---- Print for program flow
C  
              IF (PHIPROF) THEN
                CALLED = 'REFLFIND'
                COMMENT = 'MODE=2, extract data for phi profile'
                IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                MODEPHI = 2
                CALL REFLFIND(IMOSFLMX,IMOSFLMY,IMOSFLMIMG,PROFPHIS,
     +                 PROFPHIE,IMOSFIRSTIMG,IMOSLASTIMG,PROFWIDTH,
     +                PHIREF,PHIWREF,IPACKF,IPACKL,NSER,
     +                NSERRUN,IFIRSTPACK,MODEPHI,IERR)

                IF(GENOPEN)THEN
C
C---- Print for program flow
C
                  CALLED = 'QCLOSE'
                  COMMENT = 'Close generate file after REFLFIND MODE=2'
                  IF(DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL QCLOSE(IUNIT)
                  GENOPEN = .FALSE.
                  NEWGENF = .TRUE.
                  PHIPROF = .FALSE.
                  NPHIPROFIMG = 0
                END IF
                GO TO 30
              END IF
C       
C----   Position generate file to first pack
C       
              FIRSTPASS = .FALSE.
              SECONDPASS = .TRUE.
C
C---- Print for program flow
C  
              CALLED = 'QSEEK'
              COMMENT = 'Reposition to first pack'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C       ********************
              CALL QSEEK(IUNIT,21,1,36)
C       ********************
C       
              JPACK = 0
              IPACKREC = 21
              IPACKHEAD = 21  
              PROCES = .TRUE.
              NFLMO = NFILMS
              IF (.NOT.MULTISEG) NFILMS = 0
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6428) NFILMS,PROCES
                IF (ONLINE) WRITE(ITOUT,FMT=6428) NFILMS,PROCES
 6428           FORMAT(/,1X,'In MAIN, reposition genfile to record 21',
     +                 /1X,'NFILMS  at end of FIRSTPASS',I4,
     +                 ' PROCES is: ',L1)
              END IF
C       
C----   Rewind mosflm.out, containing "A" film images of all packs
C       plus B/C films if PRBFILM/PRCFILM
C       
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6544)
                IF (ONLINE) WRITE(ITOUT,FMT=6544)
              END IF
              IF(.NOT.MULTISEG)THEN
                IF(NUSPOT)THEN
C
C---- Print for program flow
C  
                  CALLED = 'QSEEK'
                  COMMENT = 'Rewind SPOTDOD file'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL QSEEK(INMO,1,1,1)
                ELSE
                  REWIND(INMO)
                ENDIF
              ENDIF
              IF (DENSE) REWIND ICOORD
C       
C----   If doing multi-segment post-refinement, get stored keywords for
C       the next segment of data.
C
              IF (MULTISEG) THEN
                FIRSTPASS = .TRUE.
                SECONDPASS = .FALSE.
                PROCES = .FALSE.
C
C---- Do not call CONTROL, interpret stored keywords
C
                ISEG = ISEG + 1
                IF (DEBUG(1))THEN
                  WRITE(IOUT,FMT=6556) ISEG
                  IF (ONLINE) WRITE(ITOUT,FMT=6556) ISEG
                END IF
C
C---- Print for program flow
C  
                CALLED = 'CELLREFSET'
                WRITE(COMMENT,FMT=6557) ISEG
 6557           FORMAT('Get stored information for ISEG=',I2)
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL CELLREFSET(IFIRSTPACK,NREPEAT,ISEG,
     +                            RPTFIRST,FIRSTTIME,INERR)
                IF (INERR) THEN
C       
C----   Abort current run
C       
                  CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
                  IF (DISPMENU) THEN
                    GOTO 34
                  ELSE
                    GOTO 30
                  END IF
                END IF
                ISEG = ISEG - 1
                GOTO 36
              END IF
C       
C
C---- xml to GUI, this is a break between blocks.
C
        IF(SOCKLO.AND.PROCES.AND..NOT.MULTISEG)finishedblock = .true.
C       
C----   Measure all "A" films using accumulated profiles
C       
              GO TO 40
            ELSE IF (SECONDPASS) THEN

              IF (PROCESSA) GO TO 260
              SECONDPASS = .FALSE.
              THIRDPASS = .TRUE.
              PROCES = .FALSE.
              NFILMS = 0
              IF (DEBUG(1).OR.DEBUG(99)) THEN
                WRITE(IOUT,FMT=6430)
                IF (ONLINE) WRITE(ITOUT,FMT=6430)
 6430           FORMAT(/,1X,'In MAIN, NFILMS set to zero at end',
     +                    ' of SECONDPASS')
              END IF
C       
C----   Rewind mosflm.out
C       
              IF (DEBUG(1)) THEN
                WRITE(IOUT,FMT=6544)
                IF (ONLINE) WRITE(ITOUT,FMT=6544)
              END IF
              IF(.NOT.MULTISEG)THEN
                IF(NUSPOT)THEN
C
C---- Print for program flow
C  
                  CALLED = 'QSEEK'
                  COMMENT = 'Rewind SPOTDOD file (and COORD)'
                  IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL QSEEK(INMO,1,1,1)
                ELSE
                  REWIND(INMO)
                ENDIF
              ENDIF
              IF (DENSE) REWIND ICOORD
C       
C----   Position generate file to first pack
C       
C       ********************
              CALL QSEEK(IUNIT,21,1,36)
C       ********************
C       
              JPACK = 0
              IPACKREC = 21
              IPACKHEAD = 21
C       
C----   Measure subsequent films in each pack
C       
C
C---- xml to GUI, this is a break between postrefining and 
C     integrating in a block.
C
        IF(SOCKLO.AND.PROCES.AND..NOT.MULTISEG)finishedblock = .true.

              GO TO 40
            ELSE IF (THIRDPASS) THEN
              THIRDPASS = .FALSE.
            END IF
          END IF
chrp06122001        ENDIF
C       
C----   Read next set of control data
C       
C       *********
 260    IF (ONLINE.AND.LBELL) CALL BELL
C       *********
C       
C----   Close mosflm.out file
C       
        IF(.NOT.MULTISEG)THEN
          IF(NUSPOT)THEN
            IF(INMOOPEN)CALL QCLOSE(INMO)
            INMOOPEN = .FALSE.
          ELSE
            CLOSE (UNIT=INMO)
          ENDIF
        ENDIF
C       
C----   If doing postrefinement, write results to summary file
C       
        IF (POSTREF) THEN
          WRITE (ISUMMR,FMT=6074)
          IF (PRFIRST) THEN
            PRFIRST = .FALSE.
            IF (NADD.GT.1) THEN
              IF (FIXED) THEN
                WRITE (ISUMMR,FMT=6090) NADD,SCELL,SDELPHI
              ELSE
                WRITE (ISUMMR,FMT=6079) NADD,SCELL,SDELPHI
              END IF
            ELSE
              WRITE (ISUMMR,FMT=6085) SCELL,SDELPHI
            END IF
            IF (REFCELL) THEN
              WRITE (ISUMMR,FMT=6080) CELLSTR
            ELSE
              WRITE (ISUMMR,FMT=6082)
            END IF
            IF (PRNS.GT.0) THEN
              IF (USEBEAM) THEN
                WRITE (ISUMMR,FMT=6084) 2.0*SETA/DTOR,2.0*SDIVH/DTOR,
     +               2.0*SDIVV/DTOR
              ELSE
                WRITE (ISUMMR,FMT=6086) 2.0*SETA/DTOR,
     +               2.0*SDIVH/DTOR,2.0*SDIVV/DTOR
              END IF
            ELSE
              WRITE (ISUMMR,FMT=6088) 2.0*SETA/DTOR,
     +             2.0*SDIVH/DTOR,2.0*SDIVV/DTOR
            END IF
          END IF
 6082     FORMAT(1X,'Cell parameters are not refined')
 6080     FORMAT(1X,'The following cell parameters are being refi',
     $         'ned: ',A)
 6088     FORMAT(1X,'Beam parameters are not refined',/,1X,'Input',
     +         ' values (degrees): mosaic spread (EPS)',F6.3,' ho',
     +         'rizontal divergence (DIVH)',F6.3,' vertical diver',
     +         'gence (DIVV)',F6.3)
 6086     FORMAT(1X,'Beam parameters are being refined but input ',
     +         'values will be used',/,1X,'Input values (degrees)',
     +         ': mosaic spread (EPS)',F6.3,' horizontal divergen',
     +         'ce (DIVH)',F6.3,' vertical divergence (DIVV)',
     +         F6.3)
 6084     FORMAT(1X,'Beam parameters are being refined',/,1X,'Inp',
     +         'ut values (degrees): mosaic spread (EPS)',F6.3,
     +         ' horizontal divergence (DIVH)',F6.3,' vertical di',
     $         'vergence (DIVV)',F6.3)
 6074     FORMAT(//1X,'RESULTS OF POSTREFINEMENT')
 6079     FORMAT(1X,I2,' successive pairs of images will be used',
     +         /,1X,'Each image will have its own missetting angl',
     $         'es',/,1X,'Initial cell ',
     +         'parameters',3F8.3,3F7.2,/,1X,'Initial missetting',
     +         ' angles',3F9.3)
 6090     FORMAT(1X,I2,' successive',
     +         ' pairs of images will be used',/,1X,'The missett',
     +         'ing angles will be constrained to be identical f',
     +         'or all images',/,1X,'Initial cell ',
     +         'parameters',3F8.3,3F7.2,/,1X,'Initial missetting',
     +         ' angles',3F9.3)
 6085     FORMAT(1X,'A single',
     +         ' pair of images will be used',/,1X,'Initial cell ',
     +         'parameters',3F8.3,3F7.2,/,1X,'Initial missetting',
     +         ' angles',3F9.3)
          WRITE (ISUMMR,FMT=6075)
cdms21.09.2004    Line up headings with numbers.
 6075     FORMAT(1X,'Image     PHIX     PHIY     PHIZ        A      ',
     +         '  B        C      ALPHA     BETA    GAMMA   MOSAIC   ',
     $         'DIVH   DIVV    Resid      NR')
          IF (NREPEAT.NE.0) WRITE(ISUMMR,FMT=6071) NADD,NREPEAT
 6071     FORMAT(1X,'The first',I3,' images have been remeasured',
     +         I3,' times because of shifts in missetting angles',
     +         ' or cell parameters')
          NREPEAT = 0
          DO 270 I = 1, NFILMS
            IF (PRF(I)) THEN
C       
C----   Needed for xloggraph, post-refinement results
C       
              WRITE(ISUMMR,FMT=6072) ISUMM(1,I),(PRFSUM(K,I),
     +             K=1,13),PRFSUMI(I)
              NLSUM2 = NLSUM2 + 1
              WRITE(LINESUM2(NLSUM2),FMT=6072) ISUMM(1,I),
     +             (PRFSUM(K,I),K=1,13),PRFSUMI(I)
C       
C----   Now sd's
C       
              IF ((NADD.GT.1).AND.(FIXED)) THEN
                WRITE(ISUMMR,FMT=6081) (PRFSUM(K,I),K=14,25)
              ELSE
                WRITE(ISUMMR,FMT=6083) (PRFSUM(K,I),K=14,15),
     +               (PRFSUM(K,I),K=17,25)
              END IF
              IF (PRFRPT1(I)) THEN
                IF (PRFRPT2(I)) THEN
                  WRITE(ISUMMR,FMT=6122) ISUMM(1,I),SHIFTMAX,
     $                 SHIFTFAC
                  PRFRPT2(I) = .FALSE.
                ELSE
                  WRITE(ISUMMR,FMT=6076) ISUMM(1,I),SHIFTMAX
                END IF
                PRFRPT1(I) = .FALSE.
              END IF
              IF (PRFRPT2(I)) THEN
                WRITE(ISUMMR,FMT=6124) ISUMM(1,I),SHIFTFAC
                PRFRPT2(I) = .FALSE.
              END IF
              IF (PRNEGM(I)) WRITE(ISUMMR,FMT=6120)
              PRNEGM(I) = .FALSE.
              IF (PRFHS(I)) WRITE(ISUMMR,FMT=6077) 
              PRFHS(I) = .FALSE.
            ELSE
              WRITE(ISUMMR,FMT=6078) ISUMM(1,I)
            END IF
 270      CONTINUE
c       -harvest
c       cxEBI if this format changes then mharvest.f needs to know
C was 6072     FORMAT(1X,I4,1X,3(1X,F8.2),2X,6(1X,F7.2),1X,3(1X,F6.2),
C     $         1X,F7.3,1X,I5)
 6072     FORMAT(1X,I7,1X,3(1X,F8.2),2X,6(1X,F7.2),1X,3(1X,F6.2),
     $         1X,F7.3,1X,I5)
c       -harvest
 6081     FORMAT(1X,'   sds',3(1X,F8.2),2X,6(1X,F7.2),1X,3(1X,F6.2))
 6083     FORMAT(1X,'   sds PSIY',F7.2,' PSIZ',F7.2,2X,6(1X,F7.2),1X,
     $         3(1X,F6.2))
 6076     FORMAT(1X,'Image ',I7,' was remeasured because the shift',
     +         ' in orientation was greater than ',F5.2,' degrees')
 6122     FORMAT(1X,'Image ',I7,' remeasured, shift in',
     +         ' orientation > ',F5.2,' degrees and in cell >',
     +         F5.1,' sds')
 6124     FORMAT(1X,'Image ',I7,' was remeasured because the shift',
     +         ' in cell was greater than ',F5.2,' sds')
 6077     FORMAT(1X,'** Warning ** large shift in cell or missett',
     +         'ing angles, consult logfile')
 6078     FORMAT(1X,I4,5X,'Post refinement was not performed for ',
     +         'this image')
 6120     FORMAT(1X,'** Warning ** negative (mosaic spread+beam d',
     +         'ivergence). May be large crystal slippage or inpu',
     +         't oscillation angle is wrong')
        END IF
C       
C----   Find largest shift in CCOM, ROFF,TOFF or missets between adjacent images
C       and the largest weighted residual and number of badspots
C       
C       AL      WRITE(6,*),'NUMBLOCK,NFILMS',NUMBLOCK,NFILMS
C
        J = 0
        DELPHISUMX = 0
        DELPHISUMY = 0
        DELPHISUMZ = 0
        DO 274 I=1,NFILMS
          WRMAX = MAX(WRMAX,RSUMM(4,I))
          NBADMAX = MAX(NBADMAX,ISUMM(13,I))
          IF (I.EQ.1) GOTO 274
          ROFFMAX =  MAX(ROFFMAX,0.01*ABS(ISUMM(7,I)-ISUMM(7,I-1)))
          TOFFMAX =  MAX(TOFFMAX,0.01*ABS(ISUMM(19,I)-ISUMM(19,I-1)))
          X = RSUMM(1,I)-RSUMM(1,I-1)
          IF (X.GT.180) X = X - 360.0
          IF (X.LT.-180) X = X + 360.0
          CCOMAX = MAX(CCOMAX,ABS(X))
C
C---- Dont do a check for image 2 vs image 1 because image 1 may
C     not have been assigned missets because officially it was not
C     refined.
C
          IF ((NUMBLOCK.EQ.1).AND.(NEWPREF).AND.(I.LT.3)) GOTO 274
          X = DELPHIMAX
          DELPHIMAX = MAX(DELPHIMAX,ABS(PRFSUM(1,I)-PRFSUM(1,I-1)),
     +         ABS(PRFSUM(2,I)-PRFSUM(2,I-1)),
     +         ABS(PRFSUM(3,I)-PRFSUM(3,I-1)))
          IF (DELPHIMAX.GT.X) IWARN(1,5) = ID
C       AL        WRITE(6,*),'ROFFMAX,CCOMAX,DELPHIMAX',ROFFMAX,CCOMAX,DELPHIMAX
          IF (DEBUG(1)) THEN
            WRITE(IOUT,6650) I,X,DELPHIMAX
            IF (ONLINE) WRITE(ITOUT,6650) I,X,DELPHIMAX
 6650       FORMAT(1X,'NFILMS',I4,' Previous DELPHIMAX',F6.1,
     +              '  current DELPHIMAX',F6.1)
          END IF
          J = J + 1
          DELPHISUMX = DELPHISUMX + ABS(PRFSUM(1,I)-PRFSUM(1,I-1))
          DELPHISUMY = DELPHISUMY + ABS(PRFSUM(2,I)-PRFSUM(2,I-1))
          DELPHISUMZ = DELPHISUMZ + ABS(PRFSUM(3,I)-PRFSUM(3,I-1))
 274    CONTINUE
C
C---- Calculate average image to image shift in missets
C
        IF (J.GT.0) THEN
          DELPHISUMX = DELPHISUMX/J
          DELPHISUMY = DELPHISUMY/J
          DELPHISUMZ = DELPHISUMZ/J
          IF ((DELPHISUMX.GT.0.1).OR.(DELPHISUMY.GT.0.1).OR.
     +       (DELPHISUMZ.GT.0.1)) THEN
            WARN(33) = .TRUE.
            DELPHIDIFFMAX = MAX(DELPHIDIFFMAX,DELPHISUMX,DELPHISUMY,
     +                        DELPHISUMZ)           
            XWARN(1,33) = MAX(XWARN(1,33),DELPHIDIFFMAX)
            IWARN(1,33) = IWARN(1,33) + 1
            K = MIN(IWARN(1,33),11)
            IWARN(K+1,33) = NUMBLOCK
          END IF
          
        END IF
C       
C----   Now check the first image in this block with the last image in
C       previous block (if any)
C       
        IF (NUMBLOCK.GT.1) THEN
          ROFFMAX = MAX(ROFFMAX,ABS(0.01*ISUMM(7,1)-ROFFLAST))
          TOFFMAX = MAX(TOFFMAX,ABS(0.01*ISUMM(19,1)-TOFFLAST))
          X = RSUMM(1,1)-CCOMLAST
          IF (X.GT.180) X = X - 360.0
          IF (X.LT.-180) X = X + 360.0
          CCOMAX = MAX(CCOMAX,ABS(X))
          X = DELPHIMAX
          DELPHIMAX = MAX(DELPHIMAX,ABS(PRFSUM(1,1)-PHIXLAST),
     +         ABS(PRFSUM(2,1)-PHIYLAST),
     +         ABS(PRFSUM(3,1)-PHIZLAST))
          IF (DEBUG(1)) THEN
            WRITE(IOUT,6660) NUMBLOCK,X,DELPHIMAX
            IF (ONLINE) WRITE(ITOUT,6650) NUMBLOCK,X,DELPHIMAX
 6660       FORMAT(1X,'NUMBLOCK',I4,' Previous DELPHIMAX',F6.1,
     +              '  current DELPHIMAX',F6.1)
          END IF
          IF (DELPHIMAX.GT.X) IWARN(1,5) = ID
        END IF
C       AL        WRITE(6,*),'AFTER COMPARISON WITH LAST ROFFMAX,CCOMAX,DELPHIMAX',
C       AL     +         ROFFMAX,CCOMAX,DELPHIMAX
        IF (NFILMS.GT.0) THEN
          ROFFLAST = 0.01*ISUMM(7,NFILMS)
          TOFFLAST = 0.01*ISUMM(19,NFILMS)
          CCOMLAST = RSUMM(1,NFILMS)
          PHIXLAST = PRFSUM(1,NFILMS)
          PHIYLAST = PRFSUM(2,NFILMS)
          PHIZLAST = PRFSUM(3,NFILMS)
C       AL      WRITE(6,*),'ROFFLAST,CCOLAST,PHIXYZLAST',ROFFLAST,CCOMLAST,
C       AL     +     PHIXLAST, PHIYLAST, PHIZLAST
        END IF
C       
C----   If using blocks of images, go on to next block if required
C       
        IF (NBLOCK.NE.0) THEN
C       
C----   Reset repeat measurement and post-refined flags
C       
          DO 272 I = 1,MAXPAX
            PRFRPT1(I) = .FALSE.
            PRFRPT2(I) = .FALSE.
            PRFHS(I) = .FALSE.
            PRF(I) = .FALSE.
            PRNEGM(I) = .FALSE.
 272      CONTINUE
C       
C----   Position generate file at last record ready for next pack, but NOT if
C       using ADDPART because the first image of the next block has already
C       been generated (to trap spatially overlapped summed partials). IN
C       this case can leave generate file where it was.
C       
C       ********************
          IF ((ADDPART).AND.(NPACK.LT.NPACKSAVE)) THEN
            IF (MULTIMTZ) THEN
              WRITE(IOUT,FMT=6372) MTZNAM(1:LENSTR(MTZNAM))
              IF (ONLINE) WRITE(ITOUT,FMT=6372) 
     $             MTZNAM(1:LENSTR(MTZNAM))
 6372         FORMAT(/,1X,'Closing mtz file: ',A)
              MTZPRT = 0
              CALL LWCLOS(MTZOUT,MTZPRT)
              MTZOPEN = .FALSE.
              IF(LBEST.AND.BESTOPEN)THEN
                CLOSE(BESTHKL)
                BESTOPEN = .FALSE.
              ENDIF
C       
C----   Set up new MTZ filename
C    
              CALLED = 'NEWFN and STARTMTZ'
              COMMENT = 'To generate new MTZ filename and open it'
              IF (DEBUG(99)) 
     +             CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL NEWFN(NUMBLOCK+1,MTZNAM)
              if (debug(1)) then
                write(iout,fmt=7510)
                if (online) write(itout,fmt=7510)
 7510           format(/,1x,'** In MAIN call STARTMTZ to open mtz',
     +                    ' file 2 **')
              end if
              CALL STARTMTZ
            END IF
            GOTO 35
          END IF
C       
C----   Special test for case when there is only a single image in the last
C       block...without this test this last image will never be processed
C       
          IF ((ADDPART).AND.(NPACK.EQ.NPACKSAVE).AND.EXTRAIMG) THEN
            IF (MULTIMTZ) THEN
              WRITE(IOUT,FMT=6372) MTZNAM(1:LENSTR(MTZNAM))
              IF (ONLINE) WRITE(ITOUT,FMT=6372) 
     $             MTZNAM(1:LENSTR(MTZNAM))
              MTZPRT = 0
              if (debug(1))then
                write(iout,fmt=7502)
                if (online) write(itout,fmt=7502)
 7502           format(/,1x,'**In MAIN closing MTZ file 2 ',
     +                'and call STARTMTZ to reopen ***')
              end if
              CALLED = 'LWCLOS, NEWFN and STARTMTZ'
              COMMENT = 'To close MTZ,generate new MTZ filename'
     +                  //' and open it'
              IF (DEBUG(99)) 
     +             CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL LWCLOS(MTZOUT,MTZPRT)
              MTZOPEN = .FALSE.
              IF(LBEST.AND.BESTOPEN)THEN
                CLOSE(BESTHKL)
                BESTOPEN = .FALSE.
              ENDIF
C       
C----   Set up new MTZ filename
C       
              CALL NEWFN(NUMBLOCK+1,MTZNAM)
              CALL STARTMTZ
            END IF
            GOTO 35
          END IF
          CALLED = 'QSEEK'
          COMMENT = 'To reposition generate file'
          IF (DEBUG(99)) 
     +         CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL QSEEK(IUNIT,IRECLAST,1,36)
          IPACKREC = IRECLAST
          IPACKHEAD = IRECLAST
          IF (DEBUG(1)) THEN
            WRITE(IOUT,FMT=6094) IRECLAST
            IF (ONLINE) WRITE(ITOUT,FMT=6094) IRECLAST
 6094       FORMAT(/,1X,'In MAIN, reposition generate file to record',
     $           I6)
          END IF
C       ********************
          IF (NPACK.LT.NPACKSAVE) THEN
            IF (MULTIMTZ) THEN
              WRITE(IOUT,FMT=6372) MTZNAM(1:LENSTR(MTZNAM))
              IF (ONLINE) WRITE(ITOUT,FMT=6372) 
     $             MTZNAM(1:LENSTR(MTZNAM))
              MTZPRT = 0
              if (debug(1))then
                write(iout,fmt=7504)
                if (online) write(itout,fmt=7504)
 7504           format(/,1x,'**In MAIN closing MTZ file 3 ',
     +             'and call STARTMTZ to reopen ***')
              end if
              CALLED = 'LWCLOS, NEWFN and STARTMTZ'
              COMMENT = 'To close MTZ,generate new MTZ filename'
     +                  //' and open it'
              IF (DEBUG(99)) 
     +             CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL LWCLOS(MTZOUT,MTZPRT)
              MTZOPEN = .FALSE.
              IF(LBEST.AND.BESTOPEN)THEN
                CLOSE(BESTHKL)
                BESTOPEN = .FALSE.
              ENDIF
C       
C----   Set up new MTZ filename
C       
              CALL NEWFN(NUMBLOCK+1,MTZNAM)
              CALL STARTMTZ
            END IF
            GOTO 35
          END IF
        END IF
C       
C----   Write number of warning messages to summary file
C       
        WARN(2) = (ROFFMAX.GT.0.10)
        XWARN(1,2) = ROFFMAX
        WARN(12) = (TOFFMAX.GT.0.10)
        XWARN(1,12) = TOFFMAX
        WARN(3) = (CCOMAX.GT.0.10)      
        XWARN(1,3) = CCOMAX

cal        write(iout,fmt=4321) delphimax,eta/dtor,divh/dtor,divv/dtor
cal        if (online) write(itout,fmt=4321) delphimax,eta/dtor,divh/dtor,
cal     +              divv/dtor
cal 4321   format(1x,'SLIPPAGE, DELPHIMAX',F8.3, ' eta',F8.3,
cal     +            ' divh',F8.3,' divv',F8.3)

        WARN(5) = (DELPHIMAX.GT.0.25*(2.0*ETA + MAX(DIVH,DIVV))/DTOR)
        XWARN(1,5) = DELPHIMAX
        WARN(6) = (WRMAX.GT.1.5)
        XWARN(1,6) = WRMAX
        WARN(7) = (NBADMAX.GE.10)
        IWARN(1,7) = NBADMAX
C
C---- Change warning about GAIN agwl 24/6/13
C
CAL        WARN(9)= ((AVBGRMAX.GT.1.1).OR.(AVBGRMIN.LT.0.9))
        WARN(9)= ((AVBGRMAX.GT.1.3).OR.(AVBGRMIN.LT.0.7))
        XWARN(1,9) = AVBGRMIN
        XWARN(2,9) = AVBGRMAX
        WARN(25) = (YSCALERR.GT.0.005)
        XWARN(1,25) = YSCALERR
C
C---- if iMosflm is running this integration, close the MTZ file so 
C     that Pointless has the header there.
C
c        IF(MTZOPEN.AND.SOCKLO)THEN
c          MTZPRT = 1
c          CALL LWCLOS(MTZOUT,MTZPRT)
c          MTZOPEN = .FALSE.
c        ENDIF
C
C---- Check to see if all images have been rejected from integration
C     because weighted residual is too high, if so send trapped_error XML
C
        IF (WARN(42).AND.(IWARN(1,42).EQ.IWARN(100,42)).AND.SOCKLO)
     +                                                            THEN
           STRING1 = ' '
           WRITE(STRING1,FMT=6710)
 6710      FORMAT('All images rejected because positional',
     +            ' residual too high.__nl__Check that the'
     +            ' indexing has worked.__nl__See warnings for',
     +            ' more information')
           WRITE(LONGLINE,FMT=6712) STRING1(1:LENSTR(STRING1))
           CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $       LENSTR(LONGLINE),LONGLINE)
 6712      FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE trapped_error_response>',
     $     '<trapped_error_response>',
     $     '<type>All_images_rejected</type>',
     $     '<message>',A,'</message>',
     $     '</trapped_error_response>')
        END IF
C
C---- Print for program flow
C  
        CALLED = 'WARNINGS'
        COMMENT = 'Write warnings to summary file'
        IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL WARNINGS
C
C---- If MINREF has been changed, restore original value
C
        IF (MINREFRESET) THEN
          MINREF = MINREFSAVE
          MINREFRESET = .FALSE.
        END IF
C
C---- Rezero IWARN and XWARN, although this is supposed to be done
C     in CONTROL (but wasn't for warn(37)?
C
        DO 278 I = 1,100
          WARN(I) = .FALSE.
          DO 277 J = 1,MAXIWARN
            IWARN(J,I) = 0
            IF (J.GT.20) GOTO 277
            XWARN(J,I) = 0.0
 277      CONTINUE
 278    CONTINUE

C
C---- This task has finished, send XML to iMosflm
C
        IF (SOCKLO) THEN
C
C---- Print for program flow
C  
          CALLED = 'WRITE_SOCKET'
          COMMENT = 'Write XML processing task end'
          IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
C---- End integration task
C
          WRITE(LONGLINE,FMT=6640)
 6640     FORMAT('<?xml version="1.0"?>',
     +    '<!DOCTYPE processing_task_end>',
     +    '<processing_task_end><status><code>ok</code>',
     +    '</status></processing_task_end>')
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(LONGLINE),LONGLINE) 
        END IF

c test insert this line here hrp 21.01.2010
        NRLEFT = 0
        CALL GROUT
C       
C----   If running interactively, go back to image display, otherwise
C       Call CONTROL again for next "run" (if any). also if doing
C       newpref integration in background or foreground.
C       
 280    IF (DEBUG(1)) THEN
           WRITE(IOUT,FMT=6730) DISPMENU, SOCKLO
           IF (ONLINE) WRITE(ITOUT,FMT=6730) DISPMENU, SOCKLO
 6730      FORMAT(1X,'DISPMENU',L2,'  SOCKLO',L2)
        END IF
C
        IF (DISPMENU) THEN
C
C---- Print for program flow
C  
          CALLED = 'MRESET'
          COMMENT = 'to re-initialise variables ready for another run'
          IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL MRESET(ISEG,RPTFIRST,GENOPEN,COORDOPN,
     +                          PRFSUM,PRFSUMI)
C
C---- Fix to stop opening the old GUI
C
          IF (SOCKLO) GOTO 30
          GOTO 34
        END IF
        GOTO 30

        END
C
C $Id: reek.f,v 1.33 2021/06/03 09:42:13 andrew Exp $
C
C==   REEK ==
      SUBROUTINE REEK(IHKLSTR,MODE,ILATT)
C     ===================================
C     
      IMPLICIT NONE
C     !
C     !  This routine replaceas an earlier version and provides for 
C     !  generalization of goniostat angles etc. This is adapted from 
C     !  routines in MADNES from which the following comments are drawn;
C     !
C     !  This routine replaces an earlier version written by
C     !  Albrecht Messerschmidt.
C     !  The algorithm uses the geometric treatment of G.N. Reeke.
C     !  The code is derived from that originally written by
C     !  R.M. Sweet for prediction of reflections occuring on
C     !  oscillation photographs, but has been generalised to allow
C     !  for a general X-ray beam direction (defined by vector S0).
C     !
C     !  Harry Powell MRC-LMB Cambridge, 08-Mar-2001
C     !
C     !  Peter Brick, Andrew Leslie, Jean Claude Thierry, Alan J. Wonacott
C     !
C     !  10-Feb-1992   J. W. Pflugrath         Cold Spring Harbor Laboratory
C     !     Add ROTS and ROTE to argument list and remove references to PHIS, PHIE
C     !
C     !  29-Jan-1988   J. W. Pflugrath         Cold Spring Harbor Laboratory
C     !       Last update for floating point reflection positions
C     !
C     !    13-Nov-1987   A. G. W. Leslie, P. Brick, A. J. Wonacott   Imperial College
C     !                  Implementation of Reeke algorithm.
C     !
C     ! ***************************************************************
C---- Modified from subroutine OSCF1 from UCLA SCAN-12 SYSTEM
C     
C---- Contains George Reeke's geometric treatment
C     
C     IHKLSTR      Array containing  reflections for strategy option
C     MODE         Indicates where REEK has been called from
C       0              Most places
C       1              Called from NEWLIST
C       2              Called from TESTOVER
C       3              Called to generate reflections for overlapping lattices,
C                      only reflection indices and coords are stored. 
C     ILATT        Lattice number
C     
C     
C     March 1978    R.M. Sweet
C     
C     On entry:
C     
C     PHIBEG               beginning rotation angle about Z for this pack
C     PHIEND               end rotation angle about Z for this pack
C     DELPHI(I=1,3)        missetting angles for the X, Y and Z axes
C     AMAT(3,3)            contains the orientation matrix X = AMAT . H
C     
C     
C     
C     
C     .. Include files ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     
C     ..
C     .. Scalar Arguments ..
      INTEGER MODE,ILATT
C     ..
C     .. Array Arguments ..
      INTEGER*2 IHKLSTR(MCOLSTR,NREFSTR)
C     
C     
C     .. Local Scalars ..
      real a1,sca1,avecx,vecx,p1,p2,px1,px2
      REAL A,AVEC,DELEPS1,DTEMP,DSTMAX2,FP,FP2,FQ,FR,GAMMAX,PA,PB,
     +     PC,PD,PMAX,PMAXE,PMIN,PMINE,PX,PY,PZ,QMAXE,QMINE,S1,
     +     S1P2R2,S2,S3,S4,S5,S5P,S6,S6P,SIN2T,SINSQ,SINTH,T1,T2,
     +     DELEPS2,DRATIO,PXCEN,PYCEN,EPS,
     +     DSTMIN2,SCHI,CCHI,SOMEGA,COMEGA,FDUM,COSMU1,COSMU2,SINMU1,
     $     SINMU2,PHIEXT,PHIOFF,ETASTORE,X1SAVE,Y1SAVE,Z1SAVE,
     +     PHIWGH
      integer istat,j1,j2
      INTEGER I,IER,IFAIL,IFREC,ILOOP,IP,IPLB,IPLE,IQ,IQLB,IQLE,
     +     IQMAX,IQMIN,IR,IRMAX,IRMIN,ISIGN,J,K,
     +     KT,L,NLOOP,NRT,ICOUNT,ISPOT,INVFLAG,IISWUNG,
     +     ISYSAB,IFLAG
      LOGICAL ABSNT,FOUND,FIRSTTIME
      CHARACTER CALLEDFROM*80
C     ..
C     .. Local Arrays ..
      real pmn(2),pmx(2)
      REAL B0BEG(3,3),B0END(3,3),BBEG(3,3),BEND(3,3),CA(3,3),P(3,3,2),
     +     P0(3,3,2),P0OLD(3,3,2),P1H(2),P1H0(2),P2H(2),P2H0(2),P3H(2),
     +     P3H0(2),POLD(3,3,2),PP(3,4,2),PX0(2),PY0(2),PZ0(2),Q(3,3,2),
     +     QU(2),RLB(2),RLE(2),RMPB(3,3),RMPE(3,3),RS0(2),RS1(2),RT(2),
     +     RU0(2),RU1(2),RU2(2),T(4,4),VEC(3),X12(2),Y12(2),Z12(2),
     $     ORTMAT(3,3),rotmat(3,3),phiaxis(3),phimat(3,3),dummat(3,3),
     $     invphimat(3,3),omegaaxis(3),omegamat(3,3),
     $     invomegamat(3,3),KAPPaaxis(3),MUMAT1(3,3),MUMAT2(3,3),
     $     XYZ(3),XYZNEW(3),XYZAXIS(3)
      INTEGER NRTA(2)
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     ..
C     .. External Subroutines ..
      EXTERNAL DSTAR,JSWTCH,LIMITS,LOOPST,MATMUL3,MINV33,QUAD2,SETAX,
     +     SPTEST,STORSPOT,SURMP,SWITCH,MSYSABS,XYSPOT,WMTZSP,
     +     EPSLON
C     ..
C     .. External Functions ..
      REAL DOT
      EXTERNAL DOT
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS,ATAN,ATAN2,INT,MAX,MIN,MOD,NINT,REAL,SIGN,SIN,SQRT
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/cell.f
C
C $Id: cell.f,v 1.4 2012/11/21 14:41:22 andrew Exp $
C
C--- awk generated include file  cell.h
C---- START of include file cell.h
C
C     CELL cell dimensions (real space)
C     RCELL reciprocal cell parameters in dimensionless rlu
C     LCELL indicator for cell parameters to be refined
C     
C     LCELL(I) = -1  parameter free
C              =  0  parameter fixed
C              >  0, = J  parameter I constrained to = parameter J
C
C     .. Arrays in Common /CELLCOM/ ..
      REAL UMAT,BMAT,GMAT,CELL,RCELL,UMATCELL,SOFTCELL,VOLUME
      INTEGER LCELL,ICRYST,NUMSPG,NLAUE
C     ..
C     .. Common Block /CELLCOM/ ..
      COMMON /CELLCOM/UMAT(3,3),BMAT(3,3),GMAT(3,3),CELL(6),RCELL(6),
     $       UMATCELL(6),SOFTCELL,VOLUME,LCELL(6),ICRYST,NUMSPG,NLAUE
C     ..
C
C
C&&*&& end_include  ../inc/cell.f
C&&*&& include  ../inc/condata.f
C
C $Id: condata.f,v 1.49 2021/02/11 11:30:48 andrew Exp $
C
C--- awk generated include file condata.h 
C---- START of include file condata.h 
C 
C
C     FIXSWAP     Forces reversal of normal byte-swapping choice.
C
C---- SUMPART True if two images are to be stored in memory at the
C               same time. This will be the case if post-refinement
C               (other than POSTHOC post-refinement for off-line
C               scanners) is being performed. Note that SUMPART is NOT
C               used to determine if partials should be added across
C               images (this is ADDPART)
C
C---- NEWPREF True if allowing partials over multiple images in post-
C             refinement.
C
C---- ADDPART True if partials are to be summed across images. This is
C               only appropriate for fixed origin (ie on-line)
C               scanners where the X-ray dose is identical for
C               each image.
C     Direct beam coordinates
C             These are read into XMM(3), YMM(3) where (3) is for A,B,C packs
C             Immediately on reading in, these values are transferred
C             into XCENMM, YCENMM, XCENMMIN(J,3) where J=1->MAXPAX.
C
C             If an IMAGE keyword has been given, XCENMM(1,1)=XMM(1) and
C             YCENMM(1)=YSCAL*YMM(1). If swung out, YCENMM(1,1) is updated.
C             If a BEAM keyword has not been given, XMM,YMM, XCENMM,YCENMM,
C             XCENMMIN are all set to the middle of the image.


C             Then, when reflecting input to logfile, it AGAIN sets up
C             XCENMM,YCENMM for all images using XMM,YMM, this time
C             using YSCAL to set up YCENMM, and updating YCENMM if the
C             detctor is swung out. (label 708), DO loop 710. If image
C             is "inverted", corrects XCENMM for all images.


C             XCEN,YCEN are set in "mosflm" to XCENF, YCENF plus
C             camera constants, and XCENF,YCENF are in turn set from
C             XCENMM,YCENMM. Thus XCENMM,YCENMM are what is actually
C             used to define the beam position.

C
C     LPREF   If TRUE, return to display after refinement over entire
C             image. Only active when integrating interactively. Set by
C             toggle button in Parameter window.
C

C     LOVERLAP  If TRUE, do not call the OVERLAP subroutine

C     ALLOUT  If TRUE, all reflections (whether measured or not, or
C             classified as BADSPOTS or not, will be written to the
C             output MTZ file.
C
C     NTDIG   Number of digits in image number, returned as zero if
C             there is an error in the template. Only used if TEMPLATE
C             keyword given.
C
C     TEMPLATE is TRUE if a TEMPLATE keyword has been given.
C
C     NOLP    If TRUE, do NOT apply the Lorentz Polarisation corrections
C
C     MULTIMTZ True if writing each "block" of images to a separate MTZ file
C
C     DISPMENU True if the run was started with a IMAGE keyword. Not to be
C              confused with WINOPEN which is true if the X-window display
C              is being used, but this is not necessarily starting with
C              a "IMAGE" keyword.
c     newgui - this means that we're talking through the new GUI.
c              except that we can't have it here because the prsummary 
c              subroutine, where we REALLY want it, clashes with this common
C
C     HACTIVEMASK,LACTIVEMASK,LACTIVE - only for Rigaku images which 
C     contain a compressed "active mask" (size=HACTIVEMASK bytes)
C     at the end of the image. Compression uses a modified run length encoding
C     at present (10.01.2003).
C
C     MINBATCH Minimum allowed batch number to be written to an open
C              MTZ file (MTZ library imposes that batch numbers must 
C              increase as file is written).
c
c     MERGELATT If true, prediction lists for multiple lattices will
C               be merged for output to iMosflm
C
C     NIMGSUMREF Number of images to be summed when determining spot
C                centroids for detector parameter refinement. Only
C                works for Pilatus detectors at present.
C     ..
C     .. Arrays in common /CONDATA/ ..
      REAL XCENMM,YCENMM,THFOIL,PHIBEGA,PHIENDA,RSYM,XMM,YMM,
     +     XCENMMIN,YCENMMIN
C     ..
C     .. Arrays in common /CONDATA/ ..
      INTEGER IDPACK,NFPACK,NFIRST,ICASSET
      INTEGER IPACK1A,IPACK2A,ISERAR,PICKER
      LOGICAL AVPROF,FILMPLOT,FORCEB,FORCEC,CONTROLM,CONTROLS
C
C     .. Scalars in common /CONDATA/ ..
C     ..
      REAL RMSLIM,WRMSLIM,VLIM,XMID,SEP,THICK,PTMIN,REFREJ,
     +     YSCALIN,FULLFRAC,WTIME,OVERLAPMAX
      INTEGER NPACK,NCYC,MAXNX,MAXNY,ITHRESHF,NSIG,IRFMIN,
     +        IRFINC,IXSHIFT,IYSHIFT,LIMIT,NBLOCK,INOGEN,NFGEN,MINREF,
     +        ISERADD,NSEG,NSYM,NSYMP,NRUN,NSERTOT,IWAVE,ISWUNG,
     $        IBEAMMU,ITILT,ITWIST,IPIX,IRMINXY,ICUT,IPRCUT,ILIMIT
      INTEGER IMAT,ICELL,IUMAT,LSYMM,IDIST,IBEAM,ISCAN,NLINE,NRLINE,
     +     NTLINE,NTOTLINE,ISTARTP,IRAST,INEWMAT,ISEP,NSAVELINE,IPTIME,
     +     ISTRT,IANGLE,IBACKS,IPOLAR,IDIVH,IDIVV,IGAIN,IBLOCK,
     +     IHKLOUT,IGENF,INRES,NTDIG,DELAY,IMULTI,IMISS,IMISSMAT,
     +     IIDENT,HACTIVEMASK,ITWOTHETA,MINBATCH,ILABVIEW,INVVIEW,
     $     IINVVIEW,IHKLDIR,IBGSIG,NRLEFT,WAIT,IPARTITION,ISIGSET,
     +     NSIGSAVE,ITOL,NIMGSUMREF,IBGFRAC,THISIMG,CHUNK,ICHUNK,
     $     IPTMINSET,IYSCAL
      LOGICAL FINDCC,READCC,NOFID,INTERPOL,CONVOL,NOMEAS,
     +     USEPAR,USEOVR,SUMPART,USEBOX,POSTREF,ADDPART,
     +     FIXED,POWDER,RWEIGHT,NOREF,MULTISEG,FIXSWAP,POSTHOC,
     +     LPREF,LPINTG,DISPMENU,PRMODE,PRCELL,TEMPLATE,
     +     LOVERLAP,ALLOUT,NOLP,NEWPREF,NOBACK,MOSEST,BLKEST,NUSPOT,
     $     NUBACK,NUFIND,HARVESTREADY,HEADINFO,MULTIMTZ,ANDREW, 
     +     spostref,newgui,LACTIVEMASK,USERSPOT,HEADONLY,PHIONLY,
     $     NO_XML,TESTSOCK,PICKLOG,EXPLICIT_CELL,LSIMULATE,
     $     LONGERNAME,TIMER,MERGELATT,NULLPIXTEST,KEEPNULLPIX,CCHUNK,
     +     INVXFORCEREAD
C     ..
C real arrays, then scalars, integer arrays, scalars, logicals
      COMMON /CONDATA/
