C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/ioosum.f
C
C $Id: ioosum.f,v 1.3 2010/10/14 12:47:02 harry Exp $
C
C--- awk generated include file  ioosum.h
C---- START of include file ioosum.h
C
C     .. Scalars in common block /IOOSUM/
      INTEGER NLSUM1,NLSUM2,NSUMSTART1,NSUMSTART2
C
C     .. Arrays in common block /IOOSUMC/ ..
      CHARACTER*200 LINESUM1(MAXPAX),LINESUM2(MAXPAX)
      CHARACTER*101  IOLINE(100)
C     ..
C     .. Common block /IOOSUM/ ..
      COMMON /IOOSUM/ NLSUM1,NLSUM2,NSUMSTART1,NSUMSTART2
C     ..
C     .. Common block /IOOSUMC/ ..
      COMMON /IOOSUMC/ LINESUM1,LINESUM2,IOLINE
C&&*&& end_include  ../inc/ioosum.f
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C***********************************************************************
      DATA      IP/ 1,2,3,4,5,6,  1,2,3,0,0,4,
     1     1,2,3,0,4,0,  1,2,3,0,0,0,
     2     1,1,2,0,0,0,  1,1,1,2,2,2,
     3     1,1,2,0,0,0,  1,1,1,0,0,0,
     4     1,1,1,2,2,2/
      DATA      MCS/  6,4,4,3,2,2,2,1,2/
      DATA      VAR/ 1,1,1,1,1,1,1,1,6*1,    1,0,1,0,1,1,1,1,6*1,
     1     0,0,1,0,1,1,1,1,6*1,    1,0,0,0,0,1,1,1,6*1,
     2     0,0,0,0,0,1,1,1,6*1,    1,1,1,1,0,0,0,0,6*1,
     3     0,0,0,0,0,0,0,0,6*1/
C     
C
C
C
      NACC = 0
      NERR=-3
      SDU=0.0
      DO 10 MY1=1,6
         IF (RCELL(MY1).LE.0.0) RETURN
         IF ((MY1.GT.3).AND.(RCELL(MY1).GT.179.0))RETURN
 10   SDCELL(MY1)=0.0
C     
C----  get number of independent parameters
C
      IF ((ICS.GT.0).AND.(ICS.LT.10))THEN
         M=MCS(ICS)
      ELSE
         M=0
      ENDIF
      MFREE=M+8
C
C----  check for sufficient number of reflections
C
      NERR=0
      IF (NREF.LE.MFREE)RETURN
C
C----  check if crystal orientation and cell parameters
C      should be separated
C
      IF (IC.LT.1)IC=1
      IF (IC.GT.7)IC=7
      IF ((ICS.EQ.1).AND.(IC.LT.6))THEN
        SPLIT=0
      ELSE
        SPLIT=1
      ENDIF
C
C----  check rast,f
C
      IF (RAST.LE.0.0)NERR=-1
      IF (FDIST.le.1e-5)NERR=-2
      IF (NERR.LT.0)RETURN
C
C----  get weights for observational equations
C
      IF (SDPHI.LE.0.0)SDPHI=0.1
      SDPHI0=SDPHI/RAD
      WPHI=1.0/SDPHI0**2
      IF (SDXY.LE.0.0)SDXY=1.0
      SDXY0=SDXY*RAST
      WXY=1.0/SDXY0**2
C
C----  check number of refine cycles
C
      NERR=-6
      IF ((NCYCLE.LT.1).OR.(NCYCLE.GT.10))RETURN
C
C----  check reindexing transformation
C
      NERR=-7
      I=REIDX(1)*(REIDX(6)*REIDX(11)-REIDX(7)*REIDX(10))
     1     -REIDX(2)*(REIDX(5)*REIDX(11)-REIDX(7)*REIDX( 9))
     2     +REIDX(3)*(REIDX(5)*REIDX(10)-REIDX(6)*REIDX( 9))
      IF (I.EQ.0)RETURN
C     
C----  define goniostat system
C
      CALL GONSYS(ACHSE,S0L,S0G,EG,I)
      IF (I.NE.0)THEN
        NERR=-4
        RETURN
      ENDIF
C
C----  renormalize crystal orientation matrix to orthogonal form to
C      prevent accumulation of rounding errors.
C
      CALL UNORM(UMAT,I)
      IF (I.NE.0)THEN
        NERR=-5
        RETURN
      ENDIF
C
C----  get representation of crystal orientation matrix
C      with respect to goniostat system
C
      CALL MINV33(RFXAMAT,EG,R)
      CALL MATMUL3(UG,RFXAMAT,UMAT)
C
C----  get representation of detector orientation matrix
C    * with respect to goniostat system
C
      CALL UNORM(ED,I)
      IF (I.NE.0)THEN
        NERR=-2
        RETURN
      ENDIF
      CALL MATMUL3(EDG,RFXAMAT,ED)
C
C----  save original detector orientation matrix
C
      CALL MATCOP(EDG,EDG0)
C
C----  refinement loop 
C
C     derivatives of sin/cos of spindle position with respect to
C     distance and orientation of the detector are always zero.
C
      DO 20 J=1,4
         DSPHIC(J)=0.0
         DCPHIC(J)=0.0
 20   ENDDO
      DO 570 ICYCLE=1,NCYCLE
      IF(DEBUG(76))THEN
         CALL RECCEL(CELL,RCELL,1.0)
      IF(ONLINE)WRITE(*,6800)ICYCLE
 6800 FORMAT('CELREF CYCLE NUMBER ',I1,' STARTING')
      IF(ONLINE)WRITE(*,6820)NCYCLE,REIDX,NREF,ACHSE,IC,ICS,
     @            RAST,ORGX,ORGY,FDIST,S0L,((ED(I,J),J=1,3),I=1,3),
     1     ((UG(I,J),J=1,3),I=1,3),RCELL,CELL,SDU,SDCELL,SDPHI,
     +     SDXY,NERR
      WRITE(IOUT,6800)ICYCLE
      WRITE(IOUT,6820)NCYCLE,REIDX,NREF,ACHSE,IC,ICS,
     @            RAST,ORGX,ORGY,FDIST,S0L,((ED(I,J),J=1,3),I=1,3),
     1     ((UG(I,J),J=1,3),I=1,3),RCELL,CELL,SDU,SDCELL,SDPHI,
     +     SDXY,NERR
 6820 format(72(1H-),/,'NCYCLE = ',i2,/,'REIDX0 = ',4i2,2(/,9X,4I2),/,
     $     'NREF = ',i5,/,'ACHSE = ',3F5.2,/,
     $     'IC = ',i2,'   ICS = ',i2,'   RAST = ',F8.4,/,
     $     'ORGX = ',F8.2,'  ORGY = ',F8.2,'    XTD = ',F8.2,/,
     $     'S0L = ',3F12.6,/,'ED = ',3F5.2,2(/,5X,3F5.2),/,
     $     'UG =   ',3F10.6,2(/,7X,3F10.6),/,'RCELL = ',
     $     6f9.4,/,'CELL =  ',
     $     6f9.4,/,'SDU = ',f10.6,/,'SDCELL = ',6F10.4,
     $     /,'SDPHI = ',F10.6,'    SDXY = ',F10.6,'  NERR = ',I4,/,
     $     72(1H=),/)
      endif
         ESDPHI=0.0
         ESDXY =0.0
C
C----  clear normal matrix and right hand sides
C
         DO 30 MY1=1,MMFREE
            QD(MY1)=ZERO
 30      ENDDO
         DO 40 MY1=1,MXRIGHT
            RD(MY1)=ZERO
 40      ENDDO
         DO 50 MY1=1,MXFREE
            AVGX(MY1)=ZERO
            AVGY(MY1)=ZERO
 50      ENDDO
         DO 60 MY1=1,NRIGHT
            AVX(MY1)=ZERO
            AVY(MY1)=ZERO
 60      ENDDO
C----  calculate derivative of detector orientation matrix
C
         DO 70 J=1,3
            DEDG(1,J,1)= 0.0
            DEDG(2,J,1)=-EDG(3,J)
            DEDG(3,J,1)= EDG(2,J)
            DEDG(1,J,2)= EDG(3,J)
            DEDG(2,J,2)= 0.0
            DEDG(3,J,2)=-EDG(1,J)
            DEDG(1,J,3)=-EDG(2,J)
            DEDG(2,J,3)= EDG(1,J)
            DEDG(3,J,3)= 0.0
 70      ENDDO
C
C----  calculate derivatives of direct beam wavevector
C
         DS0G(1)= 0.0
         DS0G(2)=-S0G(3)
         DS0G(3)= S0G(2)
C     
C----  calculate derivative of crystal orientation matrix
C
         IF (SPLIT.NE.0)THEN
            DO 80 J=1,3
               DUG(1,J,1)= 0.0
               DUG(2,J,1)=-UG(3,J)
               DUG(3,J,1)= UG(2,J)
               DUG(1,J,2)= UG(3,J)
               DUG(2,J,2)= 0.0
               DUG(3,J,2)=-UG(1,J)
               DUG(1,J,3)=-UG(2,J)
               DUG(2,J,3)= UG(1,J)
               DUG(3,J,3)= 0.0
 80         ENDDO
         ENDIF
C
C----  calculate setting matrix
C
C 90      CONTINUE
         DO 100 I=1,3
            R=RCELL(I+3)/RAD
            B(I)  =COS(R)
            B(I+3)=SIN(R)
            DO 97 J=1,3
               A0(I,J)=0.0
               DO 93 MY1=1,6
                  DA(I,J,MY1)=0.0
 93            ENDDO
 97         ENDDO
 100     ENDDO
         A0(1,1)=RCELL(1)*B(5)
         A0(1,2)=RCELL(2)*(B(3)-B(1)*B(2))/B(5)
         A0(2,2)=SQRT((RCELL(2)*B(4))**2-A0(1,2)**2)
         A0(3,1)=RCELL(1)*B(2)
         A0(3,2)=RCELL(2)*B(1)
         A0(3,3)=RCELL(3)
         IF ((M.GE.1).AND.(SPLIT.NE.0))THEN
C
C----  calculate derivatives of setting matrix with respect to
C       independent cell parameters
C
            DA(1,1,1)=B(5)
            DA(3,1,1)=B(2)
            DA(1,2,2)=A0(1,2)/RCELL(2)
            DA(2,2,2)=A0(2,2)/RCELL(2)
            DA(3,2,2)=A0(3,2)/RCELL(2)
            DA(3,3,3)=1.0
            DA(1,2,4)=RCELL(2)*B(4)*B(2)/B(5)
            DA(2,2,4)=(A0(3,2)*B(4)-A0(1,2)*DA(1,2,4))/A0(2,2)
            DA(3,2,4)=-RCELL(2)*B(4)
            DA(1,1,5)=A0(3,1)
            DA(3,1,5)=-A0(1,1)
            DA(1,2,5)=A0(3,2)-A0(1,2)*B(2)/B(5)
            DA(2,2,5)=-A0(1,2)*DA(1,2,5)/A0(2,2)
            DA(1,2,6)=-RCELL(2)*B(6)/B(5)
            DA(2,2,6)=-A0(1,2)*DA(1,2,6)/A0(2,2)
            DO 130 I=1,3
               DO 127 J=1,3
                  DO 110 MY1=1,M
                     B(MY1)=0.0
 110              ENDDO
                  DO 120 MY1=1,6
                     MY2=IP(MY1,ICS)
                     IF (MY2.GT.0)B(MY2)=B(MY2)+DA(I,J,MY1)
 120              ENDDO
                  DO 123 MY1=1,M
                     DA(I,J,MY1)=B(MY1)
 123              ENDDO
 127           ENDDO
 130        ENDDO
            DO 150 MY1=1,M
               DO 140 I=1,3
                  DO 135 J=1,3
                     RFXAMAT(I,J)=UG(I,1)*DA(1,J,MY1)+UG(I,2)*
     $                    DA(2,J,MY1)+UG(I,3)*DA(3,J,MY1)
 135              ENDDO
 140           ENDDO
               DO 148 I=1,3
                  DO 145 J=1,3
                     DA(I,J,MY1) = RFXAMAT(I,J)
 145              ENDDO
 148           ENDDO
 150        ENDDO
         ENDIF
 160     CALL MATMUL3(RFXAMAT,UG,A0)
C
C----  enter contributions of observational equations 
C
         NACC=0
         SEED=1009
c         DO 165 NY = 1,NREF
c            IF ((IH(NY).EQ.0).AND.(IK(NY).EQ.0).AND.(IL(NY).EQ.0))
c     +           NBAD(1) = NBAD(1) + 1
c 165     ENDDO
         IF(NBAD(1).EQ.NREF)THEN
            NERR = 0
            RETURN
         ENDIF 
         DO 330 NY=1,NREF
C
C----  apply reindexing
C
           IF(USESPOT(NY).EQ.NLATTICE)THEN
            IF ((IH(NY).NE.0).OR.(IK(NY).NE.0).OR.(IL(NY).NE.0))THEN
               FH=REIDX(1)*IH(NY)+REIDX( 2)*IK(NY)+
     $              REIDX( 3)*IL(NY)+REIDX( 4)
               FK=REIDX(5)*IH(NY)+REIDX( 6)*IK(NY)+
     $              REIDX( 7)*IL(NY)+REIDX( 8)
               FL=REIDX(9)*IH(NY)+REIDX(10)*IK(NY)+
     $              REIDX(11)*IL(NY)+REIDX(12)
               XOBS = X_SPOT(NY)-(ORGX*RAST)
               YOBS = Y_SPOT(NY)-(ORGY*RAST)
               R = PHIMEAN(NY)/RAD
               CPHI=COS(R)
               SPHI=SIN(R)
C     
C---- get goniostat coordinates of reflection at phi=0
C
               DO 170 I=1,3
                  X0G(I)=RFXAMAT(I,1)*FH+RFXAMAT(I,2)*FK+RFXAMAT(I,3)*FL
 170           ENDDO
C
C----  get goniostat coordinates of reflection at diffraction
C
               RR=X0G(1)**2+X0G(2)**2+X0G(3)**2
               RHOQ=RR-X0G(2)**2
               XG(3)=-(RR*0.5+X0G(2)*S0G(2))/S0G(3)
               XG(2)=X0G(2)
               XG(1)=RHOQ-XG(3)**2
               IF (XG(1).LE.0.0)GO TO 325
               XG(1)=SQRT(XG(1))
               IF ((X0G(1)*CPHI+X0G(3)*SPHI).LT.0.0)XG(1)=-XG(1)
C     
C----  calculate sin/cos of spindle position at diffraction
C
               CPHIC=(XG(1)*X0G(1)+XG(3)*X0G(3))/RHOQ
               SPHIC=(XG(1)*X0G(3)-XG(3)*X0G(1))/RHOQ
C
C----  get goniostat coordinates of diffracted beam wavevector
C
               DO 180 I=1,3
                  SG(I)=S0G(I)+XG(I)
 180           ENDDO
C
C----  get detector coordinates of diffracted beam wavevector
C
               DO 190 I=1,3
                  SD(I)=EDG(1,I)*SG(1)+EDG(2,I)*SG(2)+EDG(3,I)*SG(3)
 190           ENDDO
               IF (SD(3).le.1e-5)GO TO 325
C     
C----  get detector coordinates of intersection point of diffracted
C       beam with detector surface
C
               XCALC = FDIST * SD(1)/SD(3)
               YCALC = FDIST * SD(2)/SD(3)
c 6840          FORMAT('+++++ DPS ++++++',/,
c     $              '   H   K   L   IP(X)  IP(Y)     X(OBS)',
c     $              '      Y(OBS)      X(CALC)     Y(CALC)')
c 6860          FORMAT(3I4,2I7,4F12.5)
c               IF (DEBUG(76))THEN
c                  IF(NY.EQ.1) THEN
c                     IF(ONLINE)WRITE(*,FMT=6840)         
c                     WRITE(IOUT,FMT=6840) 
c                  ENDIF
c                  IF (NY.LE.10) THEN
c                     IF(ONLINE)WRITE(*,FMT=6860)IH(NY),IK(NY),IL(NY),
c     $                 IX(NY),IY(NY),XOBS,YOBS,XCALC,YCALC
c                     WRITE(IOUT,FMT=6860)IH(NY),IK(NY),IL(NY),IX(NY),
c     $                    IY(NY),XOBS,YOBS,XCALC,YCALC
c                  ENDIF
c               ENDIF
               NACC = NACC+1
C     
C----  derivatives with respect to f
C
               DXCALC(1) = SD(1)/SD(3)
               DYCALC(1) = SD(2)/SD(3)
C
C----  derivatives with respect to detector orientation
C
               DO 200 MY1=1,3
                  T1=DEDG(1,1,MY1)*SG(1)+DEDG(2,1,MY1)*SG(2)+
     $                 DEDG(3,1,MY1)*SG(3)
                  T2=DEDG(1,2,MY1)*SG(1)+DEDG(2,2,MY1)*SG(2)+
     $                 DEDG(3,2,MY1)*SG(3)
                  T3=DEDG(1,3,MY1)*SG(1)+DEDG(2,3,MY1)*SG(2)+
     $                 DEDG(3,3,MY1)*SG(3)
                  DXCALC(MY1+1) = (T1 * FDIST - T3 * XCALC)/SD(3)
                  DYCALC(MY1+1) = (T2 * FDIST - T3 * YCALC)/SD(3)
 200           ENDDO
C
C----  derivatives with respect to kappa
C           ..... derivatives of goniostat coordinates "xg"
C
               DXG(3)=X0G(2)-XG(3)*S0G(2)/S0G(3)
               DXG(1)=-XG(3)*DXG(3)/XG(1)
C
C          ..... derivatives of sin/cos of spindle position
C
               DSPHIC(5)=(DXG(1)*X0G(3)-DXG(3)*X0G(1))/RHOQ
               DCPHIC(5)=(DXG(1)*X0G(1)+DXG(3)*X0G(3))/RHOQ
C
C         ..... derivatives of goniostat coordinates of "sg"
C
               DSG(1)=DXG(1)
               DSG(2)=-S0G(3)
               DSG(3)=DXG(3)+S0G(2)
C
C            ..... detector coordinates of derivatives of 
C            diffracted beam wavevector
C
               DO 210 I=1,3
                  DS D(I)=EDG(1,I)*DSG(1)+EDG(2,I)*
     $                 DSG(2)+EDG(3,I)*DSG(3)
 210           ENDDO
C
C           ..... derivatives of calculated detector coordinates
C
               DXCALC(5)=(DSD(1) * FDIST - DSD(3) * XCALC)/SD(3)
               DYCALC(5)=(DSD(2) * FDIST - DSD(3) * YCALC)/SD(3)
C
C----  derivatives with respect to reciprocal cell setting matrix
C
               IF (SPLIT.NE.1)THEN
                  DO 220 I=1,3
                     DO 215 J=1,M+3
                        DX0G(I,J)=0.0
 215                 ENDDO
 220              ENDDO
                  DO 230 I=1,3
                     DX0G(I,I  )=FH
                     DX0G(I,I+3)=FK
                     DX0G(I,I+6)=FL
 230              ENDDO
                  GO TO 260
C
C----  derivatives with respect to unit cell orientation
C     
               ENDIF
 240           DX0G(1,1)= 0.0
               DX0G(2,1)=-X0G(3)
               DX0G(3,1)= X0G(2)
               DX0G(1,2)= X0G(3)
               DX0G(2,2)= 0.0
               DX0G(3,2)=-X0G(1)
               DX0G(1,3)=-X0G(2)
               DX0G(2,3)= X0G(1)
               DX0G(3,3)= 0.0
               IF (M.GE.1)THEN
C
C        ..... derivatives with respect to independent cell parameters
C
                  DO 250 MY1=1,M
                     DO 245 I=1,3
                        DX0G(I,MY1+3)=DA(I,1,MY1)*FH+DA(I,2,MY1)*
     $                       FK+DA(I,3,MY1)*FL
 245                 ENDDO
 250              ENDDO
C
C         ..... derivatives with respect to unit cell orientation and
C                independent cell parameters
C
               ENDIF
 260           DO 280 J=1,M+3
                  DRR=X0G(1)*DX0G(1,J)+X0G(2)*DX0G(2,J)+X0G(3)*DX0G(3,J)
                  DXG(3)=-(DRR+S0G(2)*DX0G(2,J))/S0G(3)
                  DXG(1)=(DRR-X0G(2)*DX0G(2,J)-XG(3)*DXG(3))/XG(1)
                  DRHOQ=2.0*(X0G(1)*DX0G(1,J)+X0G(3)*DX0G(3,J))
                  DSPHIC(J+5)=(DXG(1)*X0G(3)+XG(1)*DX0G(3,J)
     @                 -DXG(3)*X0G(1)-XG(3)*DX0G(1,J)-SPHIC*DRHOQ)/RHOQ
                  DCPHIC(J+5)=(DXG(1)*X0G(1)+XG(1)*DX0G(1,J)
     @                 +DXG(3)*X0G(3)+XG(3)*DX0G(3,J)-CPHIC*DRHOQ)/RHOQ
C
C         ..... derivatives of goniostat coordinates of "sg"
C
                  DSG(1)=DXG(1)
                  DSG(2)=DX0G(2,J)
                  DSG(3)=DXG(3)
C
C          ..... detector coordinates of derivatives of 
C                diffracted beam wavevector
C
                  DO 270 I=1,3
                     DSD(I)=EDG(1,I)*DSG(1)+EDG(2,I)*
     $                    DSG(2)+EDG(3,I)*DSG(3)
 270              ENDDO
C
C          ..... derivatives of calculated detector coordinates
C
                  DXCALC(J+5) = (DSD(1) * FDIST - DSD(3) * XCALC)/SD(3)
                  DYCALC(J+5) = (DSD(2) * FDIST - DSD(3) * YCALC)/SD(3)
 280           ENDDO
C
C----  calculate residuals
C
               RCPHI(1)=CPHIC-CPHI
               RSPHI(1)=SPHIC-SPHI
               DELX(1)=XCALC-XOBS
               DELY(1)=YCALC-YOBS
C
C----  remove outliers from next refinement round
C
               IF((SQRT((DELX(1)**2)+(DELY(1)**2)).GE.SDCUTOFF*
     $              SDXY*RAST).AND.(ICYCLE.GT.2))THEN
                  IH(NY) = 0
                  IK(NY) = 0
                  IL(NY) = 0
                  NBAD(1) = NBAD(1) + 1
               ENDIF
C
C----  add normally distributed random errors to residuals
C
               R=SQRT(RR/RHOQ)*SDPHI0
               DO 290 MY1=2,NRIGHT
                  SEED=MOD(151*SEED+1,20011)
                  ERROR=(SEED/20011.0-0.5)*R
                  RCPHI(MY1)=RCPHI(1)+SPHI*ERROR
                  RSPHI(MY1)=RSPHI(1)-CPHI*ERROR
                  SEED=MOD(151*SEED+1,20011)
                  DELX(MY1)=DELX(1)-(SEED/20011.0-0.5)*SDXY0
                  SEED=MOD(151*SEED+1,20011)
                  DELY(MY1)=DELY(1)-(SEED/20011.0-0.5)*SDXY0
 290           ENDDO
C
C----  add contributions to determine root-mean-square of residuals
C
               ESDPHI=ESDPHI+(RCPHI(1)**2+RSPHI(1)**2)*RHOQ/RR
               deltax(ny) = DELX(1)
               deltay(ny) = dely(1)
               delsqxy(ny) = DELX(1)**2+DELY(1)**2
               phiobs(ny) = sqrt(xobs*xobs+yobs*yobs)
               phicalc(ny) = sqrt(xcalc*xcalc+ycalc*ycalc)
               ESDXY = ESDXY + delsqxy(ny)
C
C----  add contribution of this reflection to normal equations
C
               MM=0
               DO 310 MY1=1,MFREE
                  AVGX(MY1)=AVGX(MY1)+DXCALC(MY1)
                  AVGY(MY1)=AVGY(MY1)+DYCALC(MY1)
                  T1=DSPHIC(MY1)*WPHI*RHOQ/RR
                  T2=DCPHIC(MY1)*WPHI*RHOQ/RR
                  T3=DXCALC(MY1)*WXY
                  T4=DYCALC(MY1)*WXY
                  J=MY1
                  DO 300 MY2=1,NRIGHT
                     RD(J)=RD(J)-RSPHI(MY2)*T1-RCPHI(MY2)*T2-DELX(MY2)*
     $                    T3-DELY(MY2)*T4
                     J=J+MFREE
 300              ENDDO
                  DO 305 MY2=1,MY1
                     MM=MM+1
                     QD(MM)=QD(MM)+T1*DSPHIC(MY2)+T2*DCPHIC(MY2)
     @                    +T3*DXCALC(MY2)+T4*DYCALC(MY2)
 305              ENDDO
 310           ENDDO
               DO 320 MY2=1,NRIGHT
                  AVX(MY2)=AVX(MY2)+DELX(MY2)
                  AVY(MY2)=AVY(MY2)+DELY(MY2)
 320           ENDDO
            ENDIF
 325        CONTINUE            ! okay for a GOTO target
          ENDIF
 330     ENDDO
C
C---- get estimated standard deviations of observed reflection
C       positions and angles
C
         IF (NACC.LE.MFREE)THEN
            NERR=0
            RETURN
         ENDIF
         SDPHI=RAD*SQRT(ESDPHI/(NACC-MFREE))
         SDXY=SQRT(ESDXY/(NACC-MFREE))/RAST
C     
C----  get mean-values of residuals
C
         DO 340 MY2=1,NRIGHT
            AVX(MY2)=AVX(MY2)/NACC
            AVY(MY2)=AVY(MY2)/NACC
 340     ENDDO
C
C----  get mean-values of gradients
C
         DO 350 MY1=1,MFREE
            AVGX(MY1)=AVGX(MY1)/NACC
            AVGY(MY1)=AVGY(MY1)/NACC
 350     ENDDO
C
C----  correct origin
C
         ORGX=ORGX-AVX(1)/RAST
         ORGY=ORGY-AVY(1)/RAST
C
C----  early termination because goal has already been achieved
C
         IF ((SDPHI.GE.0.01).OR.(SDXY.GT.0.05))THEN

C     IF ((SDPHI.LT.0.01).AND.(SDXY.LE.0.05))GO TO 600
C
C----  subtract mean-values of residuals from right-hand side
C      and tensor product of mean gradients from normal matrix
C
            MM=0
            DO 370 MY1=1,MFREE
               J=MY1
               DO 360 MY2=1,NRIGHT
                  RD(J)=RD(J)+WXY*NACC*(AVX(MY2)*AVGX(MY1)+
     $                 AVY(MY2)*AVGY(MY1))
                  J=J+MFREE
 360           ENDDO
               DO 365 MY2=1,MY1
                  MM=MM+1
                  QD(MM)=QD(MM)-WXY*NACC*(AVGX(MY1)*AVGX(MY2)+
     $                 AVGY(MY1)*AVGY(MY2))
 365           ENDDO
 370        ENDDO
C     
C----  rescale system of equations
C
            MM=0
            DO 380 MY1=1,MFREE
               MM=MM+MY1
               Z=QD(MM)
               IF (Z.GT.ZERO)Z=ONE/DSQRT(Z)
               AVGX(MY1)=Z
               ESD(MY1)=Z
               J=MY1
               DO 375 MY2=1,NRIGHT
                  RD(J)=RD(J)*Z
                  J=J+MFREE
 375           ENDDO
 380        ENDDO
            MM=0
            DO 390 MY1=1,MFREE
               DO 385 MY2=1,MY1
                  MM=MM+1
                  QD(MM)=QD(MM)*AVGX(MY1)*AVGX(MY2)
 385           ENDDO
 390        ENDDO
C     
C----  remove fixed parameters from the normal equations
C
            MM=0
            DO 430 MY1=1,MFREE
               IF (VAR(MY1,IC).EQ.0)THEN
                  J=MY1
                  DO 400 MY2=1,NRIGHT
                     RD(J)=ZERO
                     J=J+MFREE
 400              ENDDO
               ENDIF
 410           DO 420 MY2=1,MY1
                  MM=MM+1
                  IF (((VAR(MY1,IC).EQ.0).OR.(VAR(MY2,IC).EQ.0))
     $                 .AND.(MY2.NE.MY1))
     @                 QD(MM)=ZERO
 420           ENDDO
               QD(MM)=ONE
 430        ENDDO
C
C----  solve normal equations
C
            CALL DGELS(RD,QD,MFREE,NRIGHT,EPS,IRANK,AVGX)
            DO 450 MY1=1,MFREE
               Z=ZERO
               MM=MY1
               DO 440 MY2=1,NRIGHT
                  RD(MM)=RD(MM)*ESD(MY1)
                  Z=Z+(RD(MM)-RD(MY1))**2
                  MM=MM+MFREE
 440           ENDDO
               ESD(MY1)=DSQRT(Z/(NRIGHT-1))
 450        ENDDO
C
C----  get scaling factor for standard deviations of cell parameters
C
            T1=SDPHI/SQRT(SDPHI**2+(SDPHI0*RAD)**2)
C
C            t2=sdxy/sqrt(sdxy**2+(sdxy0/rast)**2)
C
C----  apply corrections and calculate estimated standard deviations
C        for the refined parameters
C
C            ..... detector distance
C
            FDIST = FDIST + RD(1)
C
C            ..... detector orientation
C
            DO 460 J=1,3
               DO 455 I=1,3
                  EDG(I,J)=EDG(I,J)
     @                 +RD(2)*DEDG(I,J,1)+RD(3)*DEDG(I,J,2)+
     $                 RD(4)*DEDG(I,J,3)
 455           ENDDO
 460        ENDDO
            CALL UNORM(EDG,I)
            IF (I.NE.0)THEN
               NERR=-2
               RETURN
            ENDIF
C
C              .....incident x-ray beam (kappa)
C
            R=RD(5)
            CPHI=COS(R)
            SPHI=SIN(R)
            R=S0G(2)*CPHI-S0G(3)*SPHI
            S0G(3)=S0G(3)*CPHI+S0G(2)*SPHI
            S0G(2)=R
            IF (SPLIT.NE.0)THEN
C     
C             .....orientation matrix
C
               DO 470 J=1,3
                  DO 465 I=1,3
                     UG(I,J)=UG(I,J)+RD(6)*DUG(I,J,1)+
     $                    RD(7)*DUG(I,J,2)+RD(8)*DUG(I,J,3)
 465              ENDDO
 470           ENDDO
               CALL UNORM(UG,I)
               IF (I.NE.0)THEN
                  NERR=-5
                  RETURN
               ENDIF
               SDU=RAD*SQRT(ESD(6)**2+ESD(7)**2+ESD(8)**2)
C     
C            .....reciprocal cell dimensions
C
               DO 480 MY1=1,6
                  B(MY1)=RCELL(MY1)
                  RZELLE(MY1)=RCELL(MY1)
                  SDCELL(MY1)=0.0
 480           ENDDO
               IF (M.LT.1)GO TO 565
               DO 500 I=1,NRIGHT
                  DO 490 MY1=1,6
                     MY2=IP(MY1,ICS)
                     IF (MY2.GT.0)THEN
                        IF (MY1.LT.4)THEN
                           R=RD(MY2+8+MFREE*(I-1))
                        ELSE
                           R=RAD*RD(MY2+8+MFREE*(I-1))
                        ENDIF
                        RZELLE(MY1)=B(MY1)+R
                     ENDIF
 485                 CONTINUE
 490              ENDDO
c                  CALL INVCEL(ZELLE,RZELLE,R)
                  CALL RECCEL(ZELLE,RZELLE,1.0)
                  DO 495 MY1=1,6
                     IF (I.EQ.1)THEN
                        CELL(MY1)=ZELLE(MY1)
                        RCELL(MY1)=RZELLE(MY1)
                     ELSE
                        SDCELL(MY1)=SDCELL(MY1)+
     $                       (ZELLE(MY1)-CELL(MY1))**2
                     ENDIF
 495              ENDDO
 500           ENDDO
               GO TO 540
C     
C----    update rec. setting matrix and extract cell parameters and
C        crystal orientation
C
            ENDIF
 510        DO 530 MY1=1,NRIGHT
               DO 520 I=1,3
                  DO 515 J=1,3
                     A0(I,J) = RFXAMAT(I,J)+RD(I+3*(J-1)+5+
     $                   MFREE*(MY1-1))
 515              ENDDO
 520           ENDDO
               IF (MY1.EQ.1)CALL MATCOP(A0,UMAT)
               CALL MINV33(BASIS,A0,R)
               CALL METRIC(BASIS,ZELLE,NERR)
               CALL RECCEL(RZELLE,ZELLE,1.0)
c               CALL INVCEL(RZELLE,ZELLE,R)
               DO 525 I=1,6
                  IF (MY1.EQ.1)THEN
                     CELL(I)=ZELLE(I)
                     RCELL(I)=RZELLE(I)
                  ELSE
                     SDCELL(I)=SDCELL(I)+(ZELLE(I)-CELL(I))**2
                  ENDIF
 525           ENDDO
 530        ENDDO
            CALL RFSETMAT(RCELL,RFXAMAT)
            CALL MINV33(BASIS,RFXAMAT,R)
            CALL MATMUL3(UG,UMAT,BASIS)
 540        DO 550 I=1,6
               SDCELL(I)=SQRT(T1*SDCELL(I)/(NRIGHT-1))
 550        ENDDO
         ELSE
            GOTO 600 !early termination because goal has already been achieved
         ENDIF
 565     CONTINUE
 570  ENDDO
C
C----  end of refinement loop 
C
C
 600  IF (IC.NE.5)THEN
C     
C---- transform back to laboratory coordinate system
C     
         CPHI=0.0
         SPHI=0.0
         DO 610 I=1,3
            CPHI=CPHI+EDG0(3,I)*EDG(3,I)+EDG0(1,I)*EDG(1,I)
            SPHI=SPHI+EDG0(1,I)*EDG(3,I)-EDG0(3,I)*EDG(1,I)
 610     ENDDO
         R=SQRT(CPHI**2+SPHI**2)
         CPHI=CPHI/R
         SPHI=SPHI/R
         DO 620 I=1,3
            R=EG(1,I)*CPHI+EG(3,I)*SPHI
            EG(3,I)=EG(3,I)*CPHI-EG(1,I)*SPHI
            EG(1,I)=R
 620     ENDDO
      ENDIF
 630  CALL MATMUL3(ED,EG,EDG)
      CALL MATMUL3(UMAT,EG,UG)
      DO 640 I=1,3
         S0L(I)=EG(I,2)*S0G(2)+EG(I,3)*S0G(3)
 640  ENDDO
      NERR=NACC
 650  RETURN
      END
      
C $Id: cgfit.f,v 1.17 2020/12/15 20:00:01 andrew Exp $
C== CGFIT ==
C
      SUBROUTINE CGFIT(RAS,IRAS,IDR,DELX,DELY,SPOTINT,SDELX,SDELY,IPART,
     +                 IFLAG)
C     ==============================================================
C
      IMPLICIT NONE
C   Determine the centre of gravity of the spot and its integrated
C   intensity (SPOTINT)
C   Introduce rejection of background pixels 11/3/91
C
C   Returns:
C           DELX, DELY   c. og g. shift from centre of box
C           SPOTINT         Integrated intensity
C           SDELX,SDELY  Standard deviations in centre of gravity coords.
C           IFLAG        = 0 Spot is OK
C                        = 1 Too steep background gradient
C                        = 2 Too many background pixels rejected
C                        = 3 Contains zero value pixels
C                        = 4 Overloaded spot
C
C
C****** DEBUG(82) FOR THIS SUBROUTINE ******
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      REAL DELX,DELY,SPOTINT,SDELX,SDELY
      INTEGER IDR,IPART,IFLAG
C     ..
C     .. Array Arguments ..
      INTEGER IRAS(5)
      INTEGER*2 RAS(*)
C     ..
C     .. Local Scalars ..
      REAL A,B,C,SOD,SPOD,SPP,SQOD,SQQ,TOD,TPOD,TPP,TQOD,TQQ,GRADM,
     +     SP,SQ,SPQ,BGDEVMAX,RMSBG,XSPOT,XFAC,GRAD,ERR,XMULT,XOD
      INTEGER HX,HY,IC,IJ,IOD,IP,IPQ,IQ,IRX,IRY,NXY,NOVER,P,Q,S,T,NBKG,
     +        NRMAX,NRFL,NXX,NYY,I,IODMAX,IODMIN,NPKSIZ,MODE,NPK,
     +        LNBGOUTLIER,MODEBKG
      LOGICAL P1,P2
C     ..
C     .. Local Arrays ..
      INTEGER IA(MAXBOX),MASK(MAXBOX),MASKREJ(NREJMAX)
      REAL PQSUMS(6)
C     ..
C     .. External Subroutines ..
      EXTERNAL BEXPAN4,BGSOLVE,BGTEST
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/lmb.f
C
C $Id: lmb.f,v 1.17 2021/03/30 09:16:05 andrew Exp $
C
C--- awk generated include file  lmb.h
C---- START of include file lmb.h
C ODSCAL is to scale image numbers into the range 0-255 for plotting
C average profiles.
C  GAIN should be equal to the overall gain (image counts per X-ray photon)
C of the system, and is used to evaluate standard deviations based on
C counting statistics assuming independent pixels (ie point spread function
C less than pixel size).
C INVERTX true if image is inverted in the slow (X) direction when read in.
C ISCAL is to scale final integrated intensities and sigmas
C IDIVIDE is the adc offset
C ICONST is a constant to be added to all pixels (normally zero) to
C        allow processing of images with zero pixel values in the scanned
C        area.
C IMGP is true if working with image plate data
C SPIRAL is true for scanners with a spiral readout (Mar, DIP2000)
C ORTHOG is true for scanners with orthogonal scan (FUJI, RAXIS, MD)
C NULLPIX is the value of pixels within the image but not in the active
C area of the detector
C TILED is true if there are inactive areas of the detector within the
C       inscribing circle or square.
C
C NTILEX Number of tiles in X direction
C NTILEY Number of tiles in Y direction
C TILEX  X Coordinates of the midpoints of the null areas between tiles
C TILEY  Y Coordinates of the midpoints of the null areas between tiles
C TILEWX Width of the null areas between tiles in X
C TILEWY Width of the null areas between tiles in Y


C MACHINE and MODEL denote the type of detector.
C DECTRIS_TYPE can be PILATUS, EIGER1 or EIGER2. It is used when setting up
C the positions of the gaps between the tiles.
C
C MACHINE is used in the following subroutines:
C GETBLK, GETHDR, INTPXL, INTPXL2, MXDSPL, OPENODS, PROCESS, PUTPXL
C Currently coded types are:
C
C         MACHINE        MODEL               COMMENTS
C         =======        =====               ========
C         MAR            180, 300, 345
C         RAXI(S)        RAXISII, RAXISIV
C         MD
C         FUJI
C         CCD1           CCD1                Princetown CCD at CHESS,Tiff format
C         CCD2           CCD ?               ESRF CCD detector
C         ADSC           QUAD1               ADSC 2x2 CCD detector
C
C TRUSTED whether or not the image header information can be trusted for 
C         automatic processing
C MICROED indicates whether or not this is electron diffraction data,
C        base on the wavelength being less than 0.05A
C
C
C     .. Scalars in Common Block /LMB/ ..
        REAL ODSCAL,GAIN,LOGA,LOGB
        INTEGER ISCAL,IDIVIDE,ICONST,NULLPIX,NTILEX,NTILEY,
     $       RAXISCOMP,IIDIVIDE,COMPRESSION,GAPVAL,IINVERTX
        LOGICAL IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,TILED,SETADC,
     $       NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,GAPMASK,
     $       WRONGGAPVALUE,MICROED
        CHARACTER MACHINE*4,MODEL*8,LDETECTOR*20,DECTRIS_TYPE*10,
     +       CMACHINE*40

C     ..
C     .. Arrays in common /LMB/
        INTEGER TILEX,TILEY,TILEWX,TILEWY
C
C     .. Common Block /LMB/ ..
        COMMON /LMB/ ODSCAL,GAIN,LOGA,LOGB,ISCAL,IDIVIDE,ICONST,
     $       NULLPIX,NTILEX,NTILEY,RAXISCOMP,IIDIVIDE,COMPRESSION,
     $       GAPVAL,IINVERTX,TILEX(20),TILEY(20),TILEWX(20),TILEWY(20),
     $       IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,
     $       TILED,SETADC,NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,
     $       GAPMASK,WRONGGAPVALUE,MICROED
        COMMON /LMBC/ MACHINE,MODEL,LDETECTOR,DECTRIS_TYPE,CMACHINE

C&&*&& end_include  ../inc/lmb.f
C&&*&& include  ../inc/ovrld.f
C
C $Id: ovrld.f,v 1.1 2002/05/02 10:47:03 harry Exp $
C
C--- awk generated include file  ovrld.h
C---- START of include file ovrld.h
C
C
C     .. Scalars in Common Block /OVRLD/ ..
      INTEGER NPMAX
C     ..
C     .. Common Block /OVRLD/ ..
      COMMON /OVRLD/NPMAX
C     ..
C
C
C&&*&& end_include  ../inc/ovrld.f
C&&*&& include  ../inc/parm1.f
C
C $Id: parm1.f,v 1.4 2021/08/19 10:53:54 andrew Exp $
C
C--- awk generated include file  parm1.h
C---- START of include file parm1.h
C
C     SCALEINT  Can be set by keyword SCALE, used to scale up
C               intensities (and sd's) if they are numerically small
C               eg as in MicroED. Default 1.0, but 10.0 for MicroED
C
C     SCALEUP   Can be set by keyword SCALEUP and is used internally
C               to scale up intensities and sigmas to avoid truncation
C               or rounding errors when dealing with very small intensities
C               (less than 10), intorduced to help avoid BIAS in intensities
C               that should be close to zero. Default 100.0
C
C     .. Scalars in common block /PARM1/ ..
      REAL BGSIG,EFAC,EFACSQ,BGFREJ,GRADMAX,GRADMAXR,BGRAT,PKRAT,
     +     RESD,RESDLOW,SCALEINT,SCALEUP
      INTEGER CUTOFF,NOVPIX,NDSTART,NDTOT,IXDMIN,IXDMAX,IYDMIN,IYDMAX,
     +     IDMIN,IDMAX,IGRADMAX,IGRADMAXR
      LOGICAL DUMPSPOT,BADPLOT,DUMPALL,BADPLOT2
C     ..
C     .. Common Block /PARM1/ ..
      COMMON /PARM1/BGSIG,EFAC,EFACSQ,BGFREJ,GRADMAX,GRADMAXR,
     +     BGRAT,PKRAT,RESD,RESDLOW,CUTOFF,NOVPIX,
     +     NDSTART,NDTOT,IXDMIN,IXDMAX,IYDMIN,IYDMAX,
     +     IDMIN,IDMAX,IGRADMAX,IGRADMAXR,DUMPSPOT,
     $     BADPLOT,DUMPALL,BADPLOT2,SCALEINT,SCALEUP
C     ..
C
C
C&&*&& end_include  ../inc/parm1.f
C&&*&& include  ../inc/scn.f
C
C $Id: scn.f,v 1.5 2014/11/18 14:05:40 andrew Exp $
C
C--- awk generated include file  scn.h
C---- START of include file scn.h
C
C     SCNSZ   is pixel size (in microns) divided by 25
C     RAST    pixel size in slow direction in mm
C     FACT    multiplying by FACT converts from 10 micron units 
C             (the standard unit internal to the program) into pixels
C     IYLEN   The number of pixels in the Y (fastest changing) direction
C             in the digitised image.
C     NREC    The number of pixels in the X (slow) direction in the 
C             digitised image.
C     NWORD   The number of I*2 words in the Y direction.
C     NBYTE   The number of bytes in Y direction = NWORD/2
C     NHBYTE  Number of bytes in header
C
C     ICURR   When several images are stored in a single file, ICURR is the
C             pointer to the first record of the current image in the direct
C             access file (only implemented for film data)
C     NEXTRA  The number of additional (unused) bytes padding the end of
C             each record in image file
C     BYTSWAP True if the "endedness" (Big-endian/Little-endian) of the 
C             machine that MOSFLM is running on is different to that of the
C             machine on which the image was written. This is determined by
C             looking at the value of NXPIX in the header record of the
C             image file (subroutine GETHDR)
C
C     LACTIVE True if using Rigaku active mask, False if ignoring it
C     REALLYFORCEREAD True if we want to display an image where we have
C                     changed the activemask
C
C     ROWREADT Time in seconds that the detector takes to read a row of data,
C              required for rolling shutter mode readout of Tietz detector
C              used for microED.
C     ROTSPEED Spindle rotation rate (degrees per second),required for rolling
C              shutter mode readout of Tietz detector used for microED. 
C
C
C     .. Scalars in common block /SCN/ ..
      REAL FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED
      INTEGER NBYTE,NREC,NWORD,IYLEN,ICURR,NEXTRA,NHBYTE
      LOGICAL BYTSWAP,LACTIVE,REALLYFORCEREAD
C     ..
C     .. Common Block /SCN/ ..
      COMMON /SCN/ FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED,
     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/sums.f
C
C $Id: sums.f,v 1.1 2002/05/02 10:47:21 harry Exp $
C
C--- awk generated include file  sums.h
C---- START of include file sums.h
C
C
C     Elements of ASPOT
C     1 = Summation integration intensity
C     2 = Total background counts under peak assuming peak has mm symmetry
C     3 = Rms variation in background, after rejecting background points.
C         This is evaluated in BGSOLVE called from EVAL.
C     4 = Centre of gravity in X direction (in pixels)
C     5 = Centre of gravity in Y direction (in pixels)
C         These are wrt an origin at the centre of the measurement box
C     6 = sum p*iod for background pixels
C     7 = sum q*iod for background pixels
C     8 = sum iod for background pixels
C     9 = Background plane constant a (gradient in X direction)
C    10 = Background plane constant b (gradient in Y direction)
C    11 = Background plane constant c 
C    12 = Largest deviation from background plane, excluding rejected pixels
C    13 = Profile fitted intensity
C    14 = Variance of profile fitted intensity = sum (deltasq) for peak
C         pixels only. Used to calculate PKRATIO and also profile fitted
C         sigma(I) in unweighted case only.
C    15 = Number of rejected background pixels
C    16 = Variance of profile fitted intensity in weighted case (default)
C    17 = sum W*DELTA**2 for profile fit
C    18   unused
C     .. Arrays in common block /SUMS/ ..
      REAL ASPOT
C     ..
C     .. Common Block /SUMS/ ..
      COMMON /SUMS/ASPOT(18)
C     ..
C
C
C&&*&& end_include  ../inc/sums.f
C     ..
C     ..
C     .. Equivalences ..
      EQUIVALENCE (ASPOT(3),RMSBG)
      EQUIVALENCE (ASPOT(6),SPOD)
      EQUIVALENCE (ASPOT(7),SQOD), (ASPOT(8),SOD), (ASPOT(9),A)
      EQUIVALENCE (ASPOT(10),B), (ASPOT(11),C), (ASPOT(12),BGDEVMAX)
C
C
      SAVE
C     .. Data statements ..
C
C
C---- Mode for EVAL (signifies we have not flagged overlapped background
C                     pixels)
      MODE = 0
      NRFL = 1
      IFLAG = 0
      NXX = IRAS(1)
      NYY = IRAS(2)
C
C---- Only plot pixel values if they are not going to be plotted in EVAL (DEBUG(33))
C
      IF (DEBUG(82).AND.SPOT.AND.(.NOT.DEBUG(33))) THEN
         WRITE(IOUT,FMT=6000)
         IF (ONLINE) WRITE(ITOUT,FMT=6000)
 6000    FORMAT(/,1X,'In CGFIT, pixel values are:')
         CALL ODPLOT(RAS,NXX,NYY,1)
      END IF
      HX = IRAS(1)/2
      HY = IRAS(2)/2
      NXY = (2*HX+1)* (2*HY+1)
C
C          *******************
      CALL BEXPAN4(RAS,IA,NXY)
C          *******************
C
      IC = HX + HY - IRAS(3)
      IRX = HX - IRAS(4)
      IRY = HY - IRAS(5)
C
C---- Mean spot size (ie peak area of box) in X and Y
      NPKSIZ = 0.25*(NXX + NYY - 2*(IRAS(4) + IRAS(5)))
C
      SP = 0.0
      SQ = 0.0
      SPQ = 0.0
      SPP = 0.0
      SQQ = 0.0
      SPOD = 0.0
      SQOD = 0.0                                
      SOD = 0.0
      TPP = 0.0
      TQQ = 0.0
      TOD = 0.0
      TPOD = 0.0
      TQOD = 0.0
      IODMAX = 0
      IODMIN = 9999999
C
C
      S = 0
      T = 0
      IJ = 0
      NOVER = 0
C
C
      DO 10 I=1,6
        PQSUMS(I) = 0.0
 10   CONTINUE
C
      DO 30 P = -HX,HX
        IP = ABS(P)
        P1 = (IP.GT.IRX)
        P2 = (IP.EQ.IRX)
C
C
        DO 20 Q = -HY,HY
          IJ = IJ + 1
          IQ = ABS(Q)
          IOD = IA(IJ)
C
C---- Reject overloads
C
          IF (IOD.GT.CUTOFF) NOVER = NOVER + 1
C
C---- Trap spots that include pixels outside scanned area
C
          IF (IOD.LE.NULLPIX) GOTO 80
C---- These should be values in the peak, not the whole box
C     AGWL 4 Mar 2014
CAL          IF (IOD.GT.IODMAX) IODMAX = IOD
CAL          IF (IOD.LT.IODMIN) IODMIN = IOD
C
C
          IF (NOVER.GT.NPMAX) THEN
            GO TO 70
          ELSE
            IPQ = IP + IQ
C
C
            IF (P1 .OR. IPQ.GT.IC .OR. IQ.GT.IRY) THEN
C
              IF (IRAS(3).NE.0 .OR. IP.LT.IRX .OR. IQ.LT.IRY) THEN
C
C
                IF (IRAS(3).GE.0 .OR. IPQ.LE.IC) THEN
C  Background pixels
              S = S + 1
              SP = P + SP
              SQ = Q + SQ
              SPP = P*P + SPP
              SQQ = Q*Q + SQQ
              SPQ = P*Q + SPQ
              SPOD = P*IOD + SPOD
              SQOD = Q*IOD + SQOD
              SOD = SOD + IOD
              MASK(IJ) = -1
                END IF
              END IF
              ELSE
C
C---- Treat pixels around Peak as OK now, as in integration 16/7/98
CAL            ELSE IF (.NOT.P2 .AND. IPQ.NE.IC .AND. IQ.NE.IRY) THEN
C
C  Peak pixels
              T = T + 1
              TPP = P*P + TPP
              TQQ = Q*Q + TQQ
              TPOD = P*IOD + TPOD
              TQOD = Q*IOD + TQOD
              TOD = TOD + IOD
              MASK(IJ) = 1
C
C---- IODMIN/MAX are for peak pixels only. AGWL 4 Mar 2014
C
              IF (IOD.GT.IODMAX) IODMAX = IOD
              IF (IOD.LT.IODMIN) IODMIN = IOD
            END IF
          END IF
   20   CONTINUE
   30 CONTINUE
C
C  Background constants (no backgound points rejected)
      A = SPOD/SPP
      B = SQOD/SQQ
      C = SOD/S
C
C  Set up PQSUMS
      PQSUMS(1) = SPP
      PQSUMS(2) = SQQ
      PQSUMS(3) = SPQ
      PQSUMS(4) = SP
      PQSUMS(5) = SQ
      PQSUMS(6) = S
      NBKG = S
C
C   Set maximum allowed number of allowed background pixels to be
C   rejected from background plane determination (as fraction of total)
C
      NRMAX = NINT(BGFREJ*NBKG)
      IF (DEBUG(82)) THEN
         WRITE(IOUT,FMT=6002) T,S,A,B,C,NRMAX
         IF (ONLINE) WRITE(ITOUT,FMT=6002) T,S,A,B,C,NRMAX
 6002    FORMAT(/,1X,'In CGFIT, number of peak pixels',I5,
     +   ' background pixels',I5,/,1X,'Background plane constants',
     +   3F8.2,' max allowed rejected background pixels',I5)
      END IF
      LNBGOUTLIER = 0
C
C
C---- Set MODEBKG to 1, so that when INTEG calls EVAL it knows that
C     it is working with summed reflections, not single reflections.
C     This can affect the way it deals with low background values.
C
         MODEBKG = 1
C          ******************************************************
      CALL EVAL(IA(1),MASK(1),IRAS,PQSUMS,BGSIG,NRMAX,NRFL,
     +          MASKREJ,DEBUG(82),MODE,LNBGOUTLIER,MODEBKG)
C          ******************************************************
C
C---- Check that not too many background points have been rejected
C     (Flagged by NRMAX=-999)
C
      IF (NRMAX.EQ.-999) GOTO 90
C
C
C  Check maximum gradient not exceeded
C
              IF (C.GT.0.0) THEN
                GRADM = MAX(ABS(A),ABS(B))/C
              ELSE
                GRADM = 0.0
              END IF
      IF (GRADM.GT.GRADMAXR) GOTO 100
C  Recalculate SPOTINT based on new value of C
C
C
C
      ASPOT(2) = T*C
      SPOTINT  = TOD - ASPOT(2)
C
C---- Catch zero spots
C
      IF (SPOTINT.NE.0.0) THEN
        DELX = (TPOD-A*TPP)/SPOTINT*IDR
        DELY = (TQOD-B*TQQ)/SPOTINT
      ELSE
        DELX = 0.0
        DELY = 0.0
      END IF
C
C---- Calculate errors in c. of g.
C         
C---- Calculate a crude gradient for this spot, used to boost sigma
C     calculation, assuming a scanner error factor of 0.15
C
      GRAD = (FLOAT(IODMAX-IODMIN))/NPKSIZ
      ERR = (GRAD*0.15)**2
      IF ((MACHINE.EQ.'ADSC') .OR. 
     $     ((MACHINE.EQ.'CBF ').AND.(MODEL(1:4).EQ.'ADSC')))THEN
        ERR = (GRAD*0.20)**2
      ENDIF
      IF ((MACHINE.EQ.'MARC').AND.
     $     ((MODEL.EQ.'MOSAIC3').OR.(MODEL.EQ.'MOSAIC4')))
     +     ERR = (GRAD*0.30)**2
      SDELX = 0.0
      SDELY = 0.0
C
C---- remove next two lines before distribution!!!
C
c      SDELX = 1e-5
c      SDELY = 1e-5
      IJ = 0
      IF (SPOTINT.EQ.0.0) GOTO 65
C
      XSPOT = SPOTINT/GAIN
C    
      DO 50 P = -HX,HX
C
          XFAC = (P-DELX)/XSPOT
          XFAC = XFAC*XFAC
C
        DO 40 Q = -HY,HY
          IJ = IJ + 1
CAL          IOD = NINT(REAL(IA(IJ))/GAIN)
CAL          IOD = IOD + NINT(ERR)
          XOD = REAL(IA(IJ))/GAIN
          XOD = XOD + ERR
          IF (MASK(IJ).EQ.1) THEN
CAL            SDELX = SDELX + XFAC*IOD
            SDELX = SDELX + XFAC*XOD
CAL            SDELY = SDELY + ((Q-DELY)/XSPOT)**2*IOD
            SDELY = SDELY + ((Q-DELY)/XSPOT)**2*XOD
          END IF 
 40     CONTINUE
 50   CONTINUE
C
C---- Fudge factor 2.5 boosts sigma estimates to get mean weighted residual
C     of about 1.0. The need for this presumably reflects the fact that the
C     accuracy of the centre of gravity determination is not solely determined
C     by counting statistics. Since the strongest reflections are used in
C     refinement, it may be partially due to scanner errors in regions of
C     high gradients, but this is not yet clear. Another possibility is
C     that the interpolation from the spiral scan to the orthogonal scan
C     introduces errors in Mar Research and Mac Science detectors.
C
      SDELX = 2.5*SQRT(SDELX)
      SDELY = 2.5*SQRT(SDELY)
C
C---- Preliminary tests with RaxisIV images suggest an even larger inflation
C     is required (for 100 micron raster). However, is this just because 
C     the spots are so large that the sd's get unreasonably small ?
C
      IF (((MODEL.EQ.'RAXISIV').OR.(MODEL.EQ.'RAXISV'))
     $     .AND.(RAST.LT.0.15)) THEN
        SDELX = 2.0*SDELX
        SDELY = 2.0*SDELY
      END IF
C
C---- Also need to inflate SDs further for ADSC and NOIR CCDs.
C
      IF ((MACHINE.EQ.'ADSC') .OR. (MACHINE.EQ.'NOIR') .OR.
     $     ((MACHINE.EQ.'CBF ').AND.(MODEL(1:4).EQ.'ADSC')))THEN
        SDELX = 2.0*SDELX
        SDELY = 2.0*SDELY
      END IF
C
C---- Jupiter (Saturn, Mercury) values based only on one set of images
C     from a Jupiter...
C
      IF ((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $     (MACHINE.EQ.'MERC').OR.
     $     (MACHINE.EQ.'A200')) THEN
        SDELX = 2.0*SDELX
        SDELY = 2.0*SDELY
      END IF
C
C---- Mar mosaic 3x3 need to inflate sd's
C
      IF ((MACHINE.EQ.'MARC').AND.
     $     ((MODEL.EQ.'MOSAIC3').OR.(MODEL.EQ.'MOSAIC4'))) THEN
        SDELX = 3.0*SDELX
        SDELY = 3.0*SDELY
      END IF
C
C---- is this really necessary for Bruker images? temporarily sets sdlx,
C     sdely to non-zero... there's a nasty crash with Bruker images
C     that needs to be located..
C     
C
      IF (MACHINE.EQ.'BRUK') THEN
        SDELX = (2.0*SDELX)+0.01
        SDELY = (2.0*SDELY)+0.01
      END IF
C
C---- Inflate standard deviations for partially recorded reflections. There
C     is no obvious way to do this, so the following is highly empirical
C     and may need to be revised. IPART is zero for fully recorded reflections
C     and lies between 1 and 99 for partials, 1 is least fully recorded, 100
C     is again fully recorded.
C
      IF (IPART.NE.0) THEN
        IF (IPART.LE.25) THEN
          XMULT = 7.0
        ELSE IF (IPART.LE.50) THEN
          XMULT = 5.0
        ELSE IF (IPART.LE.75) THEN
          XMULT = 4.0
        ELSE IF (IPART.LE.90) THEN
          XMULT = 2.0
        ELSE
          XMULT = 1.5
        END IF
        SDELX = XMULT*SDELX
        SDELY = XMULT*SDELY
      END IF
C
 65   CONTINUE
C
C
      RETURN
C
C  Overloaded spots
C
   70 IFLAG = 4
      SPOTINT = 0.0
      RETURN
C
C  Spots with zero pixel values
C
   80 IFLAG = 3
      SPOTINT = 0.0
      DELX = 0.0
      DELY = 0.0
      RETURN
C
C  Spots with too many rejected background points
   90 IFLAG = 2
      SPOTINT = 0.0
      DELX = 0.0
      DELY = 0.0
      RETURN
C
C  Spots with too steep a gradient
  100 IFLAG = 1
      SPOTINT = 0.0
      DELX = 0.0
      DELY = 0.0
      END
C== BMATRX ==
C
C
C
      SUBROUTINE BMATRX(B,R,C,WAVE)
C     =============================
      IMPLICIT NONE
C
C---- Build cell orthogonalization matrix B.
C         R are the recip cell parameters
C     and C the real cell parameters.
C
C  Ref: W.R.Busing & H.A.Levy, Acta Cryst. (1967) 22, 457-464
C
C       B =  ( a*       b* cos gamma*   c* cos beta*            )
C            ( 0        b* sin gamma*  -c* sin beta* cos alpha  )
C            ( 0             0            lambda / c            )
C
C
C
C
C
C     .. Scalar Arguments ..
      REAL WAVE
C     ..
C     .. Array Arguments ..
      REAL B(3,3),C(6),R(6)
C     ..
C     .. Local arrays
      DOUBLE PRECISION CD(6),RD(6)
C     ..
C     .. Local Scalars ..
      DOUBLE PRECISION WAVED
      INTEGER I
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC COS,SIN
C     ..
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f

C
C
      WAVED = DBLE(WAVE)
C
      DO 100 I = 1,6
        CD(I) = DBLE(C(I))
        RD(I) = DBLE(R(I))
 100  ENDDO

      B(1,1) = REAL(RD(1))
      B(1,2) = REAL( COS(DTOR_DOUBLE * RD(6)) * RD(2))
      B(1,3) = REAL(COS(DTOR_DOUBLE*RD(5)) * RD(3))
      B(2,1) = 0.0
      B(2,2) = REAL(SIN(DTOR_DOUBLE * RD(6)) * RD(2))
      B(2,3) = REAL(-SIN(DTOR_DOUBLE * RD(5)) * RD(3) * 
     $     COS(DTOR_DOUBLE * CD(4)))
      B(3,1) = 0.0
      B(3,2) = 0.0
      B(3,3) = REAL(WAVED/CD(3))
C
C
      END
C     $Id: centrs.f,v 1.23 2020/12/15 20:04:35 andrew Exp $
C== CENTRS ==
      SUBROUTINE CENTRS(DOPROFILE,NSIG,IXSHIFT,IYSHIFT,NPROFL,LIMIT,SEP,
     +          VLIM,MATCH,PARTLS,OVRLDS,MINREF,OLDLIST,GENLIST,USEBOX,
     +          ADDPART,PTMIN,NIMGSUMREF,NUSEFUL)
C     ==================================================================
C
C
      IMPLICIT NONE
C
C---- Goes through the generate file to
C     find spots suitable for refinement of detector centre,
C     crystal to detector distance and detector orientation
C     If DOPROFILE is true, an average spot profile is
C     accumulated in array IODPROF for display in CHKRAS.
C     See comments in main program about selection of spots
C     for refinement and for average spot profile on vee films.
C
C       MATCH...  true:  Pattern matching, use limited number of
C                        reflections (NSPOT)
C
C       PARTLS... true:  accept partially recorded reflections
C
C       OVRLDS... true:  accept overloaded reflections
C                            
C       MINREF... minimum acceptable number of reflections to be
C                 passed to rdist.
C
C       OLDLIST.. use a list of reflections compiled in a previous
C                 call to centrs
C
C       GENLIST.. select reflections based on intensities measured
C                 on previous film in pack
C
C       USEBOX..  Apply the measurement box peak/background definition
C                 when determining centre of gravity, by calling CGFIT
C                 rather than CGFIND. Usefull if spots are very close.
C
C       ADDPART.. True if partials on adjacent images are added together
C                 during reflection integration.
C                 In this case, if PARTLS is true, select only those
C                 partials at end of current image and add in the other
C                 part of the partial from the next image.
C
C       PTMIN...  If using partials and NOT summing partials (ADDPART)
C                 select ONLY reflections with partiality greater than
C                 PTMIN (range 0 to 1.0)
C       NIMGSUMREF Number of images summed for determinijg centroids. Only
C                  used to decide if BSWAP3 needs to be called.
C       NUSEFUL   Number of reflections that can be used for refinement (total
C                 out to resolution limit)
C
C---- 12/9/81 Change IWORK to I*4 from I*2, and calls to BEXPAN to BEXPAN4
C     to cope with dynamic range up to 64K
C
C     Reflection flags (IR) (Set by SPTEST called from DSTAR)
C
C       IR      =  0  Spot can be measured
C               =  1  Outside R, X, Y limits
C               =  2  Overlapping spot (set later)
C               =  3  Too wide in phi (more than NWMAX images)
C               =  4  DST .GT. DSTMAX  Not included in final detector list -
C                       used only to check for overlaps at edge of detector.
C               = 10  Spot is within cusp, but will be observed...not included
C                     in final spot list but must be included in predicted
C                      pattern
C
C               =  21  Spot present on 2 images, this is 1st
C               =  22  Spot present on 2 images, this is 2nd
C
C               =  31  Spot present on 3 images, this is 1st
C               =  32  Spot present on 3 images, this is 2nd
C               =  33  Spot present on 3 images, this is 3rd
C
C               =  41  Spot present on 4 images, this is 1st
C               =  42  Spot present on 4 images, this is 2nd
C               =  43  Spot present on 3 images, this is 3rd
C               =  44  Spot present on 4 images, this is 4th
C
C                 etc etc
C****** DEBUG(6) FOR THIS SUBROUTINE ******
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
