C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f

C     ..
      SAVE
C
      setsocket = 0
      BIGDUMP = .FALSE.
      PI = 4.0*ATAN(1.0)
      RTOD = 180.0/PI
      RSCAN = SQRT(RSCANSQ)
      IF (RSCAN.EQ.0.0) RSCAN = 1.0
C
C---- Go to write XML if that is all that is wanted
C
      IF (XMLONLY) GOTO 150

c      IF(SOCKLO)THEN
c         WRITE(OUTLINE,FMT=6900)ID
c         CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE),
c     $        OUTLINE)
c      ENDIF
C
C---- XMID, YMID are 10 micron coordinates of centre of image, needed
C     for distortions ROFF and TOFF
C
      XMID = 0.5*REAL(NREC)/FACT
      YMID = 0.5*REAL(IYLEN)/FACT
C
C---- No. of parameters to refine. Additional parameter TOFF
C     for image plates.
C
      NP = 0
      DO 2 I = 1,NRPAR
        IF (.NOT.FIXPAR(I)) NP = NP + 1
 2    CONTINUE
C
C---- For detector centre, do not refine bulge for film data and do
C     not refine radial dependance of TOFF,ROFF for IP data (if these
C     parameters are not fixed)
C
      IF (CENTRE) THEN
        IF (IMGP) THEN
          IF (.NOT.FIXPAR(10)) NP = NP - 1
          IF (.NOT.FIXPAR(11)) NP = NP - 1
        ELSE
          IF (.NOT.FIXPAR(8)) NP = NP - 1
        END IF
      END IF
C
C---- For less than 8 reflections, refine only three params
C
      IF (NRS.LT.8) NP = 3
      NP2 = NP*NP
      IF (DEBUG(11)) THEN
        WRITE(IOUT,FMT=6001) NP,CENTRE,RESCALE,(FIXPAR(I),I=1,NRPAR)
        IF (ONLINE) WRITE(ITOUT,FMT=6001) NP,CENTRE,RESCALE,
     +                         (FIXPAR(I),I=1,NRPAR)
 6001   FORMAT(/,1X,'Subroutine RDIST',/,1X,'Number of parameters',
     +         ' to be refined',I3,/,1X,'CENTRE is ',L1,
     +         '  RESCALE is ',L1,/,1X',FIXPAR flags: ',20L3)
      END IF
C
C
      OMEGA0 = ATAN2(SINOM0,COSOM0)
C
C
      IF (LPRINT(2)) THEN
        WRITE (IOUT,FMT=6000) NRS
 6000 FORMAT (/' Detector distortion refinement using',I4,' SPOTS')
        IF (ONLINE) WRITE (ITOUT,FMT=6000) NRS
      END IF
C
C---- Get coords from generate file
C
      IF (DEBUG(11)) THEN
        IF (ONLINE) WRITE (ITOUT,FMT=6002)
 6002 FORMAT (/1X,'List of reflections used in refinement',/2X,'NO IRE',
     +       'CG    XG    YG  SDX  SDY')
        WRITE (IOUT,FMT=6002)
      END IF
C
C
      DO 10 J = 1,NRS
C  Take ABS in case partials are being used (flagged by -ve RRS)
        IR = ABS(RRS(J))
        XXGEN(J) = XG(IR)
        YYGEN(J) = YG(IR)
        BAD(J) = .FALSE.
        IF (.NOT.RWEIGHT) THEN
          WXRS(J) = 1.0
          WYRS(J) = 1.0
        END IF
C
C
   10 CONTINUE
C
C---- Initial phase angle for radial dependence of ROFF, TOFF
C
      IF (NPHI.EQ.0) THEN
        ROFFPHI = 0.0
        TOFFPHI = 0.0
      ELSE IF (NPHI.EQ.1) THEN
        ROFFPHI = 0.25*PI
        TOFFPHI = 0.25*PI
      ELSE IF (NPHI.EQ.2) THEN
        ROFFPHI = 0.5*PI
        TOFFPHI = 0.5*PI
      ELSE IF (NPHI.EQ.3) THEN
        ROFFPHI = 0.75*PI
        TOFFPHI = 0.75*PI
      END IF
      NOTRY = 0
C
C---- Return here for each new round of refinement cycles
C
   20 CONTINUE
      RESMX = 0
      RESD = 0.0
      WRESMX = 0.0
      WRESD = 0.0
C
C
      DO 30 J = 1,NRS
        XXG = XXGEN(J)
        YYG = YYGEN(J)
        WX = 1.0/WXRS(J)**2
        WY = 1.0/WYRS(J)**2
C
C            *******************************
        CALL MMTOPX(CLCX(J),CLCY(J),XXG,YYG)
C            *******************************
C
          DX = CLCX(J) - XRS(J)
          DY = CLCY(J) - YRS(J)
        IF (.NOT.BAD(J)) THEN
          RES = DX*DX + DY*DY
          RESD = RESD + RES
          WRES = WX*DX*DX + WY*DY*DY
          WRESD = WRESD + WRES
C
C
          IF (RWEIGHT) THEN
            IF (WRES.GE.WRESMX) THEN
              WRESMX = WRES
              MXJ = J
            END IF
          ELSE
            IF (RES.GE.RESMX) THEN
              RESMX = RES
              MXJ = J
            END IF
          END IF
        END IF
C
        IF (DEBUG(11).AND.BIGDUMP) THEN
          IR = ABS(RRS(J))
          IF (ONLINE) WRITE (ITOUT,FMT=6004) J,RRS(J),XG(IR),YG(IR),
     +    XRS(J),YRS(J),WXRS(J),WYRS(J),DX/WXRS(J),DY/WYRS(J),WRESMX,MXJ    
 6004 FORMAT (1X,I3,I6,4F8.1,2F6.3,5X,2F8.2,F8.0,I3)
          WRITE (IOUT,FMT=6004) J,RRS(J),XG(IR),YG(IR),XRS(J),YRS(J),
     +          WXRS(J),WYRS(J),DX/WXRS(J),DY/WYRS(J),WRESMX,MXJ
        END IF
   30 CONTINUE
C
C
      RESMX = SQRT(RESMX)
      RMSRES = SQRT(RESD/ (NRS-NOTRY+1))
      RESLIM = REFREJ*RMSRES
      WRESMX = SQRT(WRESMX)
      SWDELSQ = SQRT(WRESD)
      WRMSRES = SQRT(WRESD/ (NRS-NOTRY+1))
      WRESLIM = REFREJ*WRMSRES
C
C
      IF (NOTRY.EQ.0) THEN
        IF (LPRINT(2)) THEN
          IF (RWEIGHT) THEN
          WRITE (IOUT,FMT=6006) 0.01*RMSRES,WRMSRES
 6006 FORMAT (1X,'Starting residual=',F5.3,'mm; Weighted residual',F6.2)
          IF (ONLINE) WRITE (ITOUT,FMT=6006) 0.01*RMSRES,WRMSRES
          ELSE
          WRITE (IOUT,FMT=6007) 0.01*RMSRES
 6007 FORMAT (1X,'Starting residual=',F5.3,'mm')
          IF (ONLINE) WRITE (ITOUT,FMT=6007) 0.01*RMSRES
          END IF
        END IF
C
C
        IF (RWEIGHT) WESTART = WRMSRES
        ESTART = RMSRES
      ELSE
C
C
        IF (NOTRY.EQ.1) THEN
          IF (LPRINT(2)) THEN
            IF (RWEIGHT) THEN
            WRITE (IOUT,FMT=6012) 0.01*RMSRES,WRMSRES
 6012 FORMAT (1X,'Residual after 1 CYCLE=',F5.3,'mm; Weighted residual',
     +            F6.2)
            IF (ONLINE) WRITE (ITOUT,FMT=6012) 0.01*RMSRES,WRMSRES
            ELSE
            WRITE (IOUT,FMT=6011) 0.01*RMSRES
 6011 FORMAT (1X,'Residual after 1 CYCLE=',F5.3,'mm')
            IF (ONLINE) WRITE (ITOUT,FMT=6011) 0.01*RMSRES
            END IF
          END IF
        END IF
C
C---- Allow maximum of 10% of reflections to be rejected
C
        IF (NOTRY.GT.NRS/10) GO TO 120
        IF (RWEIGHT) THEN
CAL          IF (WRESMX.LT.WRESLIM) GO TO 120
          IF (WRESMX.LT.REFREJ) GO TO 120
        ELSE
          IF (RESMX.LT.RESLIM) GO TO 120
        END IF
        IF (DEBUG(11).AND.BIGDUMP) THEN
          WRITE(IOUT,FMT=6013) MXJ
         IF (ONLINE) WRITE(ITOUT,FMT=6013) MXJ
 6013     FORMAT(1X,'Rejecting reflection',I3,' in list')
        END IF
        BAD(MXJ) = .TRUE.
      END IF
C
C---- Start main loop
C
C---- Start loop for non-linear refinement
C
      DO 110 ICYC = 1,2
C
C---- Initialize sums
C
        DO 40 K = 1,NP
          W(K) = 0.0
   40   CONTINUE
C
C
        DO 50 K = 1,NP2
          RF(K) = 0.0
   50   CONTINUE
C
C---- Set up normal equations
C
        DO 80 J = 1,NRS
C
C
          IF (.NOT.BAD(J)) THEN
            XXG = XXGEN(J)
            YYG = YYGEN(J)
            RG = SQRT(XXG*XXG+YYG*YYG)
            XM = XXG*COSOM0 - YYG*SINOM0
            YM = YYG*COSOM0 + XXG*SINOM0
C
C                ***********************
            CALL MMTOPX(XC1,YC1,XXG,YYG)
C                ***********************
C
            PSI = ATAN2(YCEN+YM-YMID,XCEN+XM-XMID)
            CPSI = COS(PSI)
            SPSI = SIN(PSI)
            RAD = SQRT((XCEN+XM-XMID)**2+(YCEN+YM-YMID)**2)
CAL   IF (J.LT.3) THEN
CAL   WRITE(6,*),'XG,YG',XXG,YYG
CAL   WRITE(6,*),'YCEN,YMID,YM',YCEN,YMID,YM
CAL   WRITE(6,*),'XCEN,XMID,XM',XCEN,XMID,XM
CAL   WRITE(6,*),'PSI,RAD',PSI*57,RAD
CAL   END IF
            IF (IMGP) THEN
              DXTOF = TILT*XXG + XTOFRA + TWIST*YYG
            ELSE
              DXTOF = TILT*XXG + XTOFRA + TWIST*YYG + BULGE*RG
            END IF
            IPT = 0
C
C    XCEN
C
            IF (.NOT.FIXPAR(1)) THEN
              IPT = IPT + 1
              DDX(IPT) = 1.0
              DDY(IPT) = 0.0
            END IF
C
C    YCEN
C
            IF (.NOT.FIXPAR(2)) THEN
              IPT = IPT + 1
              DDX(IPT) = 0.0
              DDY(IPT) = 1.0
            END IF
C
C    OMEGA0
C
            IF (.NOT.FIXPAR(3)) THEN
              IPT = IPT + 1
              DDX(IPT) = -YM*DXTOF
              DDY(IPT) = XM*DXTOF*YSCAL
            END IF
C
C    YSCAL
C
            IF (.NOT.FIXPAR(4)) THEN
              IPT = IPT + 1
              DDX(IPT) = 0.0
              DDY(IPT) = YM*DXTOF
            END IF
C
C    XTOFRA
C
            IF (.NOT.FIXPAR(5)) THEN
              IPT = IPT + 1
              DDX(IPT) = XM
              DDY(IPT) = YSCAL*YM
            END IF
C
C    TILT
C
            IF (.NOT.FIXPAR(6)) THEN
              IPT = IPT + 1
              DDX(IPT) = XXG*XM
              DDY(IPT) = XXG*YM*YSCAL
            END IF
C
C    TWIST
C
            IF (.NOT.FIXPAR(7)) THEN
              IPT = IPT + 1
              DDX(IPT) = YYG*XM
              DDY(IPT) = YYG*YM*YSCAL
            END IF
C
C
C    ROFF or BULGE
C
C
            IF (.NOT.FIXPAR(8)) THEN
              IF (.NOT.IMGP) THEN
C
C----  Film bulge, do not refine for central region
C
                IF (.NOT.CENTRE) THEN
                  IPT = IPT + 1
                  DDX(IPT) = XM*RG
                  DDY(IPT) = YM*YSCAL*RG
                END IF
              ELSE
C
C----  Image plate, radial offset ROFF
C
                IPT = IPT + 1
                DDX(IPT) = CPSI
                DDY(IPT) = SPSI
              END IF
            END IF
C
C  fixed tangential offset TOFF
C
            IF (.NOT.FIXPAR(9)) THEN
              IPT = IPT + 1
              DDX(IPT) = -SPSI
              DDY(IPT) =  CPSI
            END IF
C
C---- Radially dependent TOFF, amplitude RDTOFF
C     Do not refine if using only spots from centre of detector
C
            IF ((.NOT.FIXPAR(10)).AND.(.NOT.CENTRE)) THEN
              IPT = IPT + 1
              DDX(IPT) = -SPSI*SIN(PI*NODES*RAD/RSCAN+TOFFPHI)
              DDY(IPT) =  CPSI*SIN(PI*NODES*RAD/RSCAN+TOFFPHI)
            END IF
C
C
C---- Radially dependent ROFF, amplitude RDROFF
C     Do not refine if using only spots from centre of detector
C
            IF ((.NOT.FIXPAR(11)).AND.(.NOT.CENTRE)) THEN
              IPT = IPT + 1
              DDX(IPT) =  CPSI*SIN(PI*NODES*RAD/RSCAN+ROFFPHI)
              DDY(IPT) =  SPSI*SIN(PI*NODES*RAD/RSCAN+ROFFPHI)
            END IF
C
C
            IF (IPT.GT.NRPAR) THEN
              WRITE(6,*)'* FATAL ERROR, NUMBER OF REFINED PARAMETERS'
              WRITE(6,*)'EXCEEDS PARAMETER NRPAR IN SUBROUTINE RDIST'
              STOP
            END IF
C
            WX = 1.0/WXRS(J)**2
            WY = 1.0/WYRS(J)**2
C
            XO = XRS(J) - XC1
            YO = YRS(J) - YC1
            IK = 0
C
C
            DO 70 I = 1,NP
              W(I) = DDX(I)*XO*WX + W(I) + DDY(I)*YO*WY
C
C
              DO 60 K = 1,NP
                IK = IK + 1
                RF(IK) = DDX(I)*DDX(K)*WX + RF(IK) + DDY(I)*DDY(K)*WY
   60         CONTINUE
   70       CONTINUE
C
C
          END IF
   80   CONTINUE
C
C
cal        IF (DEBUG(11).AND.BIGDUMP) THEN
cal          WRITE (IOUT,FMT=6008)
cal 6008 FORMAT (/1X,'Normal matrix RF')
CAL          WRITE (IOUT,FMT=6010) (RF(JDO),JDO=1,NP)
cal 6010 FORMAT (1X,14(E10.2))
C
C
cal          IF (ONLINE) THEN
CAL            WRITE (ITOUT,FMT=6008)
CAL            WRITE (ITOUT,FMT=6010) (RF(JDO),JDO=1,NP)
CAL          END IF
cal        END IF


         IF (DEBUG(11)) THEN
           WRITE (IOUT,FMT=6008)
           IF (ONLINE) WRITE (ITOUT,FMT=6008)
 6008 FORMAT (/1X,'Normal matrix RF')
           NPERLINE = 8
           IST = 1 - NPERLINE
           NBLOCKS = NP/NPERLINE+1
           IF (MOD(NP,NPERLINE).EQ.0) NBLOCKS = NBLOCKS - 1
           DO 88 NBLK = 1,NBLOCKS
             IST = IST + NPERLINE
             IEND = MIN(IST+NPERLINE-1,NP)
             WRITE(IOUT,FMT=6022) IST,IEND,(I,I=IST,IEND)
             IF (ONLINE) WRITE(ITOUT,FMT=6022) IST,IEND,(I,I=IST,IEND)
 6022        FORMAT(/,1X,'Matrix elements',I3,' to',I3,
     +              /,3X,8I10)
             DO 86 NROW = 1,NP
               IST2 = (NBLK-1)*NPERLINE + (NROW-1)*NP + 1
               IEND2 = MIN(IST2+NPERLINE-1,NP*NROW)
               WRITE(IOUT,FMT=6024) NROW,(RF(I),I=IST2,IEND2)
               IF (ONLINE) WRITE(ITOUT,FMT=6024)NROW,
     +                                   (RF(I),I=IST2,IEND2)
 6024          FORMAT(1X,I3,2X,8E10.3)
 86          CONTINUE
 88        CONTINUE
         END IF

        IF (RESCALE) THEN
C     ..
C
C---- Save normal matrix for error calculation
C
          DO 90 I = 1,NP2
            RFSAVE(I) = RF(I)
 90       CONTINUE
C            ********************
          CALL MINV(RFSAVE,NP,DET,IWRK1,IWRK2)
C            ********************
          DO 91 I = 1,NP2
             RFSAVEINV(I) = RFSAVE(I)
 91       ENDDO
c
C     .. set up rescaling matrices for scaling normal matrix
C     .. *** Need to zero FILTER first. AGWL 16/11/17 ***
          DO 92 I = 1,NRPAR*NRPAR
            FILTER(I) = 0.0
 92       CONTINUE
C
          DO 94 I=1,NP
            IJ = (I-1)*NP + I
            IF(RF(IJ).GT.0.0) FILTER(IJ) = 1.0/SQRT(RF(IJ))
 94       ENDDO
C     ..
C     .. re-scale normal matrix
C
          CALL MATMULSQ(FWORK,RF,FILTER,NP)
          CALL MATMULSQ(RF,FILTER,FWORK,NP)

          IF (DEBUG(11)) THEN
            WRITE (IOUT,FMT=6026)
            IF (ONLINE) WRITE (ITOUT,FMT=6026)
 6026       FORMAT (/1X,'Normal matrix RF after scaling')
            NPERLINE = 8
            IST = 1 - NPERLINE
            NBLOCKS = NP/NPERLINE+1
            IF (MOD(NP,NPERLINE).EQ.0) NBLOCKS = NBLOCKS - 1
            DO 98 NBLK = 1,NBLOCKS
              IST = IST + NPERLINE
              IEND = MIN(IST+NPERLINE-1,NP)
              WRITE(IOUT,FMT=6022) IST,IEND,(I,I=IST,IEND)
              IF (ONLINE) WRITE(ITOUT,FMT=6022) IST,IEND,(I,I=IST,IEND)
              DO 96 NROW = 1,NP
                IST2 = (NBLK-1)*NPERLINE + (NROW-1)*NP + 1
                IEND2 = MIN(IST2+NPERLINE-1,NP*NROW)
                WRITE(IOUT,FMT=6024) NROW,(RF(I),I=IST2,IEND2)
                IF (ONLINE) WRITE(ITOUT,FMT=6024)NROW,
     +                                   (RF(I),I=IST2,IEND2)
 96          CONTINUE
 98        CONTINUE
          END IF
        ENDIF

         IF (RESCALE) THEN
C     
C---- Invert Normal matrix (Q) and obtain eigenvalues
C    
           CALL INVNOR(RF,NP,RFINV)
C     ..
C     .. apply scaling to inverse normal matrix
C
           CALL MATMULSQ(FWORK,RFINV,FILTER,NP)
           CALL MATMULSQ(RFINV,FILTER,FWORK,NP)
         ELSE
C
C---- 
C
C            ********************
           CALL MINV(RF,NP,DET,IWRK1,IWRK2)
C            ********************
           DO 100 I = 1,NP*NP
             RFINV(I) = RF(I)
 100      ENDDO
         ENDIF
C
        IK = 0
C
C---- Print Inverse Normal Matrix if DEBUG set
C
          IF (DEBUG(11)) THEN
            WRITE (IOUT,FMT=6028)
            IF (ONLINE) WRITE (ITOUT,FMT=6028)
 6028       FORMAT (/1X,'Inverse normal matrix RF')
            NPERLINE = 8
            IST = 1 - NPERLINE
            NBLOCKS = NP/NPERLINE+1
            IF (MOD(NP,NPERLINE).EQ.0) NBLOCKS = NBLOCKS - 1
            DO 104 NBLK = 1,NBLOCKS
              IST = IST + NPERLINE
              IEND = MIN(IST+NPERLINE-1,NP)
              WRITE(IOUT,FMT=6022) IST,IEND,(I,I=IST,IEND)
              IF (ONLINE) WRITE(ITOUT,FMT=6022) IST,IEND,(I,I=IST,IEND)
              DO 102 NROW = 1,NP
                IST2 = (NBLK-1)*NPERLINE + (NROW-1)*NP + 1
                IEND2 = MIN(IST2+NPERLINE-1,NP*NROW)
                IF (RESCALE) THEN
                  WRITE(IOUT,FMT=6024) NROW,(RFSAVEINV(I),I=IST2,IEND2)
                  IF (ONLINE) WRITE(ITOUT,FMT=6024)NROW,
     +                                   (RFSAVEINV(I),I=IST2,IEND2)
                ELSE
                  WRITE(IOUT,FMT=6024) NROW,(RFINV(I),I=IST2,IEND2)
                  IF (ONLINE) WRITE(ITOUT,FMT=6024)NROW,
     +                                   (RFINV(I),I=IST2,IEND2)
                END IF
 102          CONTINUE
 104        CONTINUE
          END IF
C
        DO 108 I = 1,NP
          R(I) = 0.0
C
C
          DO 106 K = 1,NP
            IK = IK + 1
            R(I) = RFINV(IK)*W(K) + R(I)
 106      CONTINUE
 108    CONTINUE
C
C---- Update parameters, taking account of error estimates to damp shifts
C     where appropriate
C
C     First, determine sigmas, first copy RFSAVEINV into RFINV if required
C
        IF (RESCALE) THEN
          DO 109 I = 1,NP2
            RFINV(I) = RFSAVEINV(I)
 109      CONTINUE
        END IF

C
        IPT = 1
        XCENSIG = 0.0
        YCENSIG = 0.0
        OMEGASIG = 0.0
        YSCALSIG = 0.0
        XTOFRASIG = 0.0
        TILTSIG = 0.0
        TWISTSIG = 0.0
        TILTFAC = 1.0
        TWISTFAC = 1.0
C
        IF (.NOT.FIXPAR(1)) THEN
          XCENSIG = 0.01*SQRT(RFINV(IPT))
          IPT = IPT + NP + 1
        END IF
        IF (.NOT.FIXPAR(2)) THEN
          YCENSIG = 0.01*SQRT(RFINV(IPT))
          IPT = IPT + NP + 1
        END IF
        IF (.NOT.FIXPAR(3)) THEN
          OMEGASIG = RTOD*SQRT(RFINV(IPT))
          IPT = IPT + NP + 1
        END IF
        IF (.NOT.FIXPAR(4)) THEN
          YSCALSIG = SQRT(RFINV(IPT))
          IPT = IPT + NP + 1
        END IF
        IF (.NOT.FIXPAR(5)) THEN
          XTOFRASIG = SQRT(RFINV(IPT))
          IPT = IPT + NP + 1
        END IF
        IF (.NOT.FIXPAR(6)) THEN
          TILTSIG = SQRT(RFINV(IPT))/FDIST
          ITILTSIG = NINT(TILTSIG)
C
C---- damping factor = min(1.0, 1.0/(10*error_in_deg))
C
          IF (DAMPREF) TILTFAC = MIN(1.0, 1.0/(0.1*TILTSIG))
          IPT = IPT + NP + 1
        END IF
        IF (.NOT.FIXPAR(7)) THEN
          TWISTSIG = SQRT(RFINV(IPT))/FDIST
          ITWISTSIG = NINT(TWISTSIG)
C
C---- damping factor = min(1.0, 1.0/(10*error_in_deg))
C
          IF (DAMPREF) TWISTFAC = MIN(1.0, 1.0/(0.1*TWISTSIG))
        END IF
C
C---- Print
C
        IF (DEBUG(11)) THEN
          WRITE(IOUT,FMT=6050) XCENSIG,YCENSIG,OMEGASIG,
     +     YSCALSIG,XTOFRASIG,TILTSIG,TWISTSIG,R(6)/FDIST,
     +     R(7)/FDIST,TILTFAC,TWISTFAC
          IF (ONLINE) WRITE(ITOUT,FMT=6050) XCENSIG,YCENSIG,OMEGASIG,
     +     YSCALSIG,XTOFRASIG,TILTSIG,TWISTSIG,R(6)/FDIST,R(7)/FDIST,
     +     TILTFAC,TWISTFAC
 6050     FORMAT(1X,'Sigmas',3F10.3,2F10.5,2F10.1,/,1X,
     +           ' shifts in tilt/twist',2F10.1,' damp factors',2F6.3)
        END IF
C
C---- Apply shifts
C
        IPT = 0
        IF (.NOT.FIXPAR(1)) THEN
          IPT = IPT + 1
          XCEN = R(IPT) + XCEN
        END IF
        IF (.NOT.FIXPAR(2)) THEN
          IPT = IPT + 1
          YCEN = R(IPT) + YCEN
        END IF
        IF (.NOT.FIXPAR(3)) THEN
          IPT = IPT + 1
          OMEGA0 = R(IPT) + OMEGA0
          SINOM0 = SIN(OMEGA0)
          COSOM0 = COS(OMEGA0)
        END IF
        IF (.NOT.FIXPAR(4)) THEN
          IPT = IPT + 1
          YSCAL = R(IPT) + YSCAL
        END IF
        IF (.NOT.FIXPAR(5)) THEN
          IPT = IPT + 1
          XTOFRA = R(IPT) + XTOFRA
        END IF
        IF (.NOT.FIXPAR(6)) THEN
          IPT = IPT + 1
          TILT = TILTFAC*R(IPT) + TILT
        END IF
        IF (.NOT.FIXPAR(7)) THEN
          IPT = IPT + 1
          TWIST = TWISTFAC*R(IPT) + TWIST
        END IF
        IF (.NOT.FIXPAR(8)) THEN
          IF (.NOT.IMGP) THEN
            IF (.NOT.CENTRE) THEN
              IPT = IPT + 1
              BULGE = BULGE + R(IPT)
            END IF
          ELSE
            IPT = IPT + 1
            ROFF = ROFF + R(IPT)
          END IF
        END IF
        IF (.NOT.FIXPAR(9)) THEN
          IPT = IPT + 1
          TOFF = TOFF + R(IPT)
        END IF
        IF ((.NOT.FIXPAR(10)).AND.(.NOT.CENTRE)) THEN
          IPT = IPT + 1
          RDTOFF = RDTOFF + R(IPT)
        END IF
        IF ((.NOT.FIXPAR(11)).AND.(.NOT.CENTRE)) THEN
          IPT = IPT + 1
          RDROFF = RDROFF + R(IPT)
        END IF
C
C
  110 CONTINUE
C
C---- End of non-linear refinement loop
C
C---- Calculate std.devs. and test residuals
C
      NOTRY = NOTRY + 1
      GO TO 20
C
C---- Print out
C
  120 IF (NOTRY.GT.1) THEN
C
C
        IF (LPRINT(2)) THEN
          WRITE (IOUT,FMT=6014) REFREJ
 6014 FORMAT (/,2X,'REJECTS (Error>',F4.1,'*rms RESID.) coords in mm',
     +    /,1X,'      X     DELX  DELX/SIGMA   Y    DELY  DELY/SIGMA')
          IF (ONLINE) WRITE (ITOUT,FMT=6014) REFREJ
        END IF
      END IF
C
C
      NREJS = 0
C
C
      DO 130 J = 1,NRS
C
C
        IF (BAD(J)) THEN
          NREJS = NREJS + 1
          DX = XRS(J) - CLCX(J)
          DY = YRS(J) - CLCY(J)
          WDX = DX/WXRS(J)
          WDY = DY/WYRS(J)
C
C
          IF (LPRINT(2)) THEN
            IDX = XRS(J) - XCEN
            IDY = YRS(J) - YCEN
            WRITE (IOUT,FMT=6016) 0.01*IDX,0.01*DX,WDX,
     +                            0.01*IDY,0.01*DY,WDY
 6016 FORMAT (2(F10.2,F7.2,F7.1))
            IF (ONLINE) WRITE (ITOUT,FMT=6016) 0.01*IDX,0.01*DX,WDX,
     +                            0.01*IDY,0.01*DY,WDY
          END IF
        END IF
  130 CONTINUE
C
C---- Now apply smoothing to parameters
C
C
      IF ((.NOT.CENTRE).AND.(.NOT.NOSMOOTH)) THEN

        IF (DEBUG(11)) THEN
          ITWISTSM = SMTWIST/FDIST
          ITILTSM = SMTILT/FDIST
          CALL SETDIS(ITILT,ITWIST,2)

          WRITE(IOUT,FMT=6100) IPACK,NIMGSM,NSM1,NSM2,ITWISTSM,ITWIST,
     +      ITILTSM,ITILT,SMOMEGA0*RTOD,OMEGA0*RTOD,SMXTOFRA,XTOFRA,
     +      SMYSCAL,YSCAL,0.01*SMROFF,0.01*ROFF,0.01*SMTOFF,0.01*TOFF
          IF (ONLINE) WRITE(ITOUT,FMT=6100) IPACK,NIMGSM,NSM1,NSM2,
     +        ITWISTSM,ITWIST,ITILTSM,ITILT,SMOMEGA0*RTOD,
     +        OMEGA0*RTOD,SMXTOFRA,XTOFRA,SMYSCAL,YSCAL,
     +        0.01*SMROFF,0.01*ROFF,0.01*SMTOFF,0.01*TOFF
 6100     FORMAT(/,/,1X,'Before smoothing, ipack=',I5,' NIMGSM=',I5,
     +         ' NSM1 (ccom,yscal,dist) =',I5,' NSM2 (rest) =',I5,
     +         /,1X,'current twist',I5,6X,'refined twist',I5,
     +         /,1X,'current tilt',I6,6X,'refined tilt',I6,
     +         /,1X,'current omega0',F8.3,'  refined value ',F8.3,
     +         /,1X,'current XTOFRA ',F8.5,' refined value ',F8.5,
     +         /,1X,'current YSCAL',F10.5,' refined value',F9.5,
     +         /,1X,'current ROFF',F8.3,'    refined value',F8.3,
     +         /,1X,'current TOFF',F8.3,'    refined value',F8.3)
        END IF
C
C---- NSM1 no of degrees for smoothing CCOM,YSCALE,XTOFRA
C---- NSM2 no of degrees for smoothing TILT,TWIST,ROFF,TOFF
C
        CALL PARSMOOTH(IPACK,NIMGSM,NSM2,SMTWIST,TWIST)
        CALL PARSMOOTH(IPACK,NIMGSM,NSM2,SMTILT,TILT)
        CALL PARSMOOTH(IPACK,NIMGSM,NSM2,SMROFF,ROFF)
        CALL PARSMOOTH(IPACK,NIMGSM,NSM2,SMTOFF,TOFF)
        OMEGA0 = CHKANG(SMOMEGA0,OMEGA0,5.0)
        CALL PARSMOOTH(IPACK,NIMGSM,NSM1,SMOMEGA0,OMEGA0)
        CALL PARSMOOTH(IPACK,NIMGSM,NSM1,SMYSCAL,YSCAL)
        CALL PARSMOOTH(IPACK,NIMGSM,NSM1,SMXTOFRA,XTOFRA)
        TWIST = SMTWIST
        TILT = SMTILT
        ROFF = SMROFF
        TOFF = SMTOFF
        OMEGA0 = SMOMEGA0
        SINOM0 = SIN(OMEGA0)
        COSOM0 = COS(OMEGA0)
        YSCAL = SMYSCAL
        XTOFRA = SMXTOFRA
      END IF
C
      IF (DEBUG(11)) THEN
        ITWISTSM = SMTWIST/FDIST
        ITILTSM = SMTILT/FDIST
        WRITE(IOUT,FMT=6110) ITWISTSM,ITILTSM,SMOMEGA0*RTOD
        IF (ONLINE) WRITE(ITOUT,FMT=6110) ITWISTSM,ITILTSM,
     +        SMOMEGA0*RTOD
 6110   FORMAT(/,1X,'Smoothed new twist',I5,' tilt',I5,' omega0 ',F8.3)
      END IF
C
C
c     this is where things start to get printed out. There are different versions
C     of the formats for weighted and unweighted refinement and for film and other
c     types of detector.
c

      IF (RWEIGHT) THEN
      REPT = ((ESTART.GT.WELIMIT) .OR. (RMSRES.GT.WELIMIT))
      ELSE
      REPT = ((ESTART.GT.ELIMIT2) .OR. (RMSRES.GT.ELIMIT3))
      END IF
      NXD = NINT(XTOFD*XTOFRA)
C      ITILT = TILT/FDIST
C      ITWIST = TWIST/FDIST
      CALL SETDIS(ITILT,ITWIST,2)
      IF (.NOT.IMGP) IBULGE = BULGE/FDIST
      IF (IMGP) THEN
        PXCEN = 0.01*XCEN
        PYCEN = 0.01*YCEN/YSCAL
        IF (INVERTX) PXCEN = NREC*RAST - PXCEN
C
C---- IP data
C
      IF (RWEIGHT) THEN
C
        IF ((BRIEF.AND.FINAL).OR.(BRIEF.AND.(BADSTART.OR.(.NOT.REPT))))
     +    WRITE (IBRIEF,FMT=6017) 0.01*RMSRES,WRMSRES,PXCEN,
     +    PYCEN,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*ROFF,
     +    0.01*TOFF,0.01*RDROFF,0.01*RDTOFF

        call dna_output_table_start('integration_results')
        call dna_output_list_start('final_residuals')
        call dna_output_real_item('rms', 0.01 * rmsres)
        call dna_output_real_item('weighted', wrmsres)
        call dna_output_real_item('xcen', pxcen)
        call dna_output_real_item('ycen', pycen)
        call dna_output_real_item('xtofra', xtofra)
        call dna_output_real_item('xtofd', 0.01 * nxd)
        call dna_output_real_item('yscale', yscal)
        call dna_output_list_end
        call dna_output_table_end

        IF (DEBUG(11)) THEN
          WRITE(IOUT,FMT=6032) RDROFF,ROFFPHI,RDTOFF,TOFFPHI,NODES,
     +                        SWDELSQ
          IF (ONLINE) WRITE(ITOUT,FMT=6032) RDROFF,ROFFPHI,RDTOFF,
     +                TOFFPHI,NODES,SWDELSQ
 6032     FORMAT(1X,'RDROFF',F8.2,'  ROFFPHI',F7.4,' RDTOFF',F8.2,
     +         '  TOFFPHI',F7.4,'   NODES=',I3,'  SWDELSQ',F10.2)
        END IF
C
        IF (SPIRAL) THEN
          WRITE (IOUT,FMT=6017) 0.01*RMSRES,WRMSRES,PXCEN,PYCEN,
     +     XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*ROFF,0.01*TOFF,
     +     0.01*RDROFF,0.01*RDTOFF,XCENSIG,YCENSIG,
     +     XTOFRASIG,XTOFRASIG*0.01*NXD,YSCALSIG,ITILTSIG,ITWISTSIG
 6017 FORMAT (' Final rms residual:',F8.3,'mm; Weighted residual',F7.1,
     +       /3X,'XCEN    YCEN  XTOFRA ',
     +       '  XTOFD  YSCALE  TILT TWIST   ROFF   TOFF RDROFF RDTOFF',
     +       /1X,F6.2,F8.2,F8.4,F8.2,F8.4,2I6,4F7.3,
     +       /1X,F6.2,F8.2,F8.4,F8.2,F8.4,2I6)
          IF (ONLINE) WRITE (ITOUT,FMT=6017) 0.01*RMSRES,WRMSRES,PXCEN,
     +      PYCEN,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*ROFF,
     +      0.01*TOFF,0.01*RDROFF,0.01*RDTOFF,XCENSIG,YCENSIG,
     +     XTOFRASIG,XTOFRASIG*0.01*NXD,YSCALSIG,ITILTSIG,ITWISTSIG
        ELSE      
          WRITE (IOUT,FMT=6030) 0.01*RMSRES,WRMSRES,PXCEN,PYCEN,
     +     XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,XCENSIG,YCENSIG,
     +     XTOFRASIG,XTOFRASIG*0.01*NXD,YSCALSIG,ITILTSIG,ITWISTSIG
 6030 FORMAT (' Final rms residual:',F8.3,'mm; Weighted residual',F7.1,
     +       /3X,'XCEN    YCEN  XTOFRA ',
     +       '  XTOFD  YSCALE  TILT TWIST',
     +       /1X,F6.2,F8.2,F8.4,F8.2,F8.4,2I6,
     +       /1X,F6.2,F8.2,F8.4,F8.2,F8.4,2I6)
          IF (ONLINE) WRITE (ITOUT,FMT=6030) 0.01*RMSRES,WRMSRES,PXCEN,
     +      PYCEN,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,XCENSIG,YCENSIG,
     +     XTOFRASIG,XTOFRASIG*0.01*NXD,YSCALSIG,ITILTSIG,ITWISTSIG
        END IF
      ELSE
C
C---- If NOT RWEIGHT
C
        IF ((BRIEF.AND.FINAL).OR.(BRIEF.AND.(BADSTART.OR.(.NOT.REPT))))
     +    WRITE (IBRIEF,FMT=6019) 0.01*RMSRES,PXCEN,
     +    PYCEN,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*ROFF,
     +    0.01*TOFF,0.01*RDROFF,0.01*RDTOFF

        call dna_output_table_start('integration_results')
        call dna_output_list_start('final_residuals')
        call dna_output_real_item('rms', 0.01 * rmsres)
        call dna_output_real_item('weighted', wrmsres)
        call dna_output_real_item('xcen', xcen)
        call dna_output_real_item('ycen', ycen)
        call dna_output_real_item('xtofra', xtofra)
        call dna_output_real_item('xtofd', 0.01 * nxd)
        call dna_output_real_item('yscale', yscal)
        call dna_output_list_end
        call dna_output_table_end



        IF (SPIRAL) THEN
          WRITE (IOUT,FMT=6019) 0.01*RMSRES,PXCEN,PYCEN,
     +      XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*ROFF,0.01*TOFF,
     +      0.01*RDROFF,0.01*RDTOFF
 6019 FORMAT (' Final rms residual:',F8.3,'mm',
     +       /3X,'XCEN    YCEN  XTOFRA ',
     +       '  XTOFD  YSCALE  TILT TWIST   ROFF   TOFF',
     +       ' RDROFF RDTOFF'/1X,F6.2,
     +       F8.2,F8.4,F8.2,F8.4,2I6,4F7.3)
          IF (ONLINE) WRITE (ITOUT,FMT=6019) 0.01*RMSRES,PXCEN,
     +      PYCEN,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*ROFF,
     +      0.01*TOFF,0.01*RDROFF,0.01*RDTOFF
        ELSE
          WRITE (IOUT,FMT=6034) 0.01*RMSRES,PXCEN,PYCEN,
     +      XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST
 6034 FORMAT (' Final rms residual:',F8.3,'mm',
     +       /3X,'XCEN    YCEN  XTOFRA ',
     +       '  XTOFD  YSCALE  TILT TWIST',/1X,F6.2,
     +       F8.2,F8.4,F8.2,F8.4,2I6)
          IF (ONLINE) WRITE (ITOUT,FMT=6034) 0.01*RMSRES,PXCEN,
     +      PYCEN,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST
        END IF
      END IF
C
      ELSE
C
C---- Film data
C
      IF (RWEIGHT) THEN
      WRITE (IOUT,FMT=6018) 0.01*RMSRES,WRMSRES,0.01*XCEN,
     +   0.01*YCEN/YSCAL,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*IBULGE
 6018 FORMAT (' Final rms residual:',F8.3,'mm; Weighted residual',F7.1,
     +       /6X,'XCEN    YCEN  XTOFRA ',
     +       '  XTOFD  YSCALE    TILT   TWIST   BULGE',/2X,2F8.2,F8.4,
     +       F8.2,F8.4,2I8,F8.2)
      IF (ONLINE) WRITE (ITOUT,FMT=6018) 0.01*RMSRES,WRMSRES,0.01*XCEN,
     +      0.01*YCEN/YSCAL,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,
     +      0.01*IBULGE
      ELSE
      WRITE (IOUT,FMT=6021) 0.01*RMSRES,0.01*XCEN,0.01*YCEN/YSCAL,
     +   XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,0.01*IBULGE
 6021 FORMAT (' Final rms residual:',F8.3,'mm',
     +       /6X,'XCEN    YCEN  XTOFRA ',
     +       '  XTOFD  YSCALE    TILT   TWIST   BULGE',/2X,2F8.2,F8.4,
     +       F8.2,F8.4,2I8,F8.2)
      IF (ONLINE) WRITE (ITOUT,FMT=6021) 0.01*RMSRES,0.01*XCEN,
     +      0.01*YCEN/YSCAL,XTOFRA,0.01*NXD,YSCAL,ITILT,ITWIST,
     +      0.01*IBULGE
      END IF
      END IF
C
C---- Print refined fiducial constants
C 
      CCX = XCEN - XCENF
      PCCX = CCX
      IF (INVERTX) PCCX = -PCCX
C
C---- CCY is in "pixels" rather than mm, so do NOT divide by YSCAL
C     here, but do divide when printing.
C
CAL      CCY = YCEN/YSCAL - YCENF
      CCY = YCEN - YCENF
C
C
      CCOM = (OMEGA0-OMEGAF)*RTOD
      IF (CCOM.LT.-180.0) CCOM = CCOM + 360.0
      WRITE (IOUT,FMT=6020) 0.01*PCCX,0.01*CCY/YSCAL,CCOM,
     +        XCENSIG,YCENSIG,OMEGASIG 
 6020 FORMAT (' Refined Fiducial constants (mm and degrees)',
     +   /,1X,' CCX: ',F8.2,'   CCY: ',F8.2,'  CCOM:',F10.4,/,
     +     1X,'sigmas:',F7.2,8X,F8.2,7X,F10.4)
C
C---- Only write xml for refinement over whole image
C
 150  socklo = ((setsocket.eq.1).or.socklo)
      IF (SOCKLO.AND.((.NOT.CENTRE).OR.XMLONLY)) THEN
         IF(SPIRAL)THEN
           WRITE(OUTLINE,FMT=7000)SHORTFN(1:LENSTR(SHORTFN)),
     $          TEMPLSAV(1:lenstr(templsav)),ID,
     $          PXCEN,PYCEN,pycen*yscal,0.01 * NXD,YSCAL,
     $          REAL(ITILT)*0.01,REAL(ITWIST)*0.01,0.01*TOFF,
     $          0.01*ROFF,CCOM,0.01*RMSRES,
     $          WRMSRES,0.01*CRMSRES
         ELSE
            WRITE(OUTLINE,FMT=7100)SHORTFN(1:LENSTR(SHORTFN)),
     $          TEMPLSAV(1:lenstr(templsav)),ID,
     $          PXCEN,PYCEN,pycen*yscal,0.01 * NXD,YSCAL,
     $           REAL(ITILT)*0.01,REAL(ITWIST)*0.01,
     $          0.01*RMSRES,WRMSRES,0.01*CRMSRES
         ENDIF
         CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE),
     $        OUTLINE)
         IF (XMLONLY) RETURN
      ENDIF
      IF (ONLINE) WRITE (ITOUT,FMT=6020) 0.01*PCCX,0.01*CCY/YSCAL,
     +        CCOM,XCENSIG,YCENSIG,OMEGASIG 
      IF ((BRIEF.AND.FINAL).OR.(BRIEF.AND.(BADSTART.OR.(.NOT.REPT))))
     +   THEN
           WRITE (IBRIEF,FMT=6020) 0.01*PCCX,0.01*CCY/YSCAL,CCOM
           IF (.NOT.GRAPH) CALL MPAUSE
         END IF
C
C
      IF (WINOPEN.AND.DISP_IO3.AND.(.NOT.CENTRE)) THEN
        WRITE(LINE,FMT=6040) 0.01*RMSRES,WRMSRES
 6040   FORMAT('Rms residual',F6.2,'mm, weighted residual',
     +         F6.1)
        CALL MXDWIO(LINE,22)
      END IF        
C
C---- Save value of residual for centre of image for writing to xml later.
C
      IF (CENTRE) CRMSRES = RMSRES

c     format statements for the writing out of the XML
c     these are down here so that they don't clutter up the code
C     ..
C     .. replacement XML for Geoff's GUI ... 
 6900 FORMAT ('<?xml version="1.0"?>',
     $     '<!DOCTYPE integration_positional_refinement_begin>',
     $     '<integration_positional_refinement_begin>',
     $     '<status>',
     $     '<code>ok</code>',
     $     '</status>',
     $     '<image_name>',A,'</image_name>',
     $     '<image_template>',A,'</image_template>',
     $     '<image_number>',I8,'</image_number>',
     $     '</integration_positional_refinement_begin>')
 7000 FORMAT ('<?xml version="1.0"?>',
     $     '<!DOCTYPE integration_positional_refinement>',
     $     '<integration_positional_refinement>',
     $     '<status><code>ok</code></status>',
     $     '<image_name>',A,'</image_name>',
     $     '<image_template>',A,'</image_template>',
     $     '<image_number>',I8,'</image_number>',
     $     '<beam_x>',F8.2,'</beam_x>',
     $     '<beam_y>',F8.2,'</beam_y>',
     $     '<beam_y_corrected>',F8.2,'</beam_y_corrected>',
     $     '<distance>',F7.1,'</distance>',
     $     '<yscale>',F8.4,'</yscale>',
     $     '<tilt>',F7.2,'</tilt>','<twist>',F7.2,'</twist>',
     $     '<tangential_offset>',F7.2,'</tangential_offset>',
     $     '<radial_offset>',F7.2,'</radial_offset>',
     $     '<ccomega>',F7.2,'</ccomega>',
     $     '<global_absolute_rms_residual>',F8.3,
     $     '</global_absolute_rms_residual>',
     $     '<global_weighted_rms_residual>',F7.2,
     $     '</global_weighted_rms_residual>',
     $     '<central_absolute_rms_residual>',F8.3,
     $     '</central_absolute_rms_residual>',
     $     '</integration_positional_refinement>')
C     ..
C     .. need to replace the "0.00" for ROFF & TOFF sometime with an "undefined" value.
 7100 FORMAT ('<?xml version="1.0"?>',
     $     '<!DOCTYPE integration_positional_refinement>',
     $     '<integration_positional_refinement>',
     $     '<status><code>ok</code></status>',
     $     '<image_name>',A,'</image_name>',
     $     '<image_template>',A,'</image_template>',
     $     '<image_number>',I8,'</image_number>',
     $     '<beam_x>',F8.2,'</beam_x>',
     $     '<beam_y>',F8.2,'</beam_y>',
     $     '<beam_y_corrected>',F8.2,'</beam_y_corrected>',
     $     '<distance>',F7.1,'</distance>',
     $     '<yscale>',F8.4,'</yscale>',
     $     '<tilt>',F7.2,'</tilt>','<twist>',F7.2,'</twist>',
     $     '<tangential_offset>  0.00</tangential_offset>',
     $     '<radial_offset>  0.00</radial_offset>',
     $     '<global_absolute_rms_residual>',F8.3,
     $     '</global_absolute_rms_residual>',
     $     '<global_weighted_rms_residual>',F7.2,
     $     '</global_weighted_rms_residual>',
     $     '<central_absolute_rms_residual>',F8.3,
     $     '</central_absolute_rms_residual>',
     $     '</integration_positional_refinement>')
      END
C $Id: refrt1.f,v 1.31 2016/01/18 17:45:06 harry Exp $
C==   REFRT1 ==
C     
      SUBROUTINE REFRT1(NADD,NPOINT,NIMAG,NOREFCELL,NEWPREF,RESCALE,
     $     ISTAT)
C     ===========================================================
      IMPLICIT NONE
C     
C    DEBUG(40) this subroutine, k/w DEBUG REFRT1.
C    also DEBUG(77) DEBUG STATS for histogram output.
C---- Refines orientation and cell parameters
C     either when data from only one image available or
C     if the missetting angles are refined separately for several images.
C     In these cases, the missetting angle around the X-ray beam (PSIX)
C     is not refined as it is not determined.
C     
C     Modifications to allow several images Feb 1992.
C     
C     Correct formulation of weighting in least squares. This will not
C     have any effect as in practice unit weights are always used.
C     2nd June 1994
C     
C    NADD....   For old-style post refinement:
C               Number of images to be added together for use in 
C               post-refinement. Note than when NADD>1 but NIMAG<NADD
C               then the value passed into idxref from postrefl is 1
C               rather than the true NADD.
C
C               For old-style post refinement (NEWPREF):
C               The number of parameters sets to be refined.
C
C     NPOINT...  Pointer to the first reflection to be used in this refinement
C               in the reflection arrays. This is only anything other
C               than 1 when NADD>1 but NIMAG<NADD with traditional
C               post-refinement. 
C               With new style post-refinement it is 1, unless doing 
C               POSTREF SEGMENT and NIMAG<NADD.
C     
C     NIMAG...  The number of images available when doing newstyle
C               post refinement (NEWPREF).
C     
C     The way in which the refined parameters are stored is somewhat complex.
C     The array PARM contains the following
C     
C     1               ThetaX(1)
C     2               ThetaY(1)    Missetting angles
C     3               ThetaZ(1)
C     4               Cell_1
C     5               Cell_2     These are the REFINED cell parameters
C     .                 .           (edges and angles)
C     .                 .
C     .                 .
C     NC+3            Cell_NC
C     NC+3+1          ThetaX(2)
C     NC+3+2          ThetaY(2)  Missets
C     NC+3+3          ThetaZ(2)
C     NC+3+4          ThetaX(3)         
C     NC+3+5          ThetaY(3)  Missets
C     NC+3+6          ThetaZ(3)
C     .
C     .
C     .
C     NC+(NADD-1)*3+1 ThetaX(NADD)
C     NC+(NADD-1)*3+2 ThetaY(NADD)
C     NC+(NADD-1)*3+3 ThetaZ(NADD)
C     Optional
C     NC+NADD*3+1     DIVH or EPS
C     NC+NADD*3+2     DIVV
C     
C     NC is the number of REFINED cell parameters
C     NADD is the number of images included in the refinement
C     Subscripts as in ThetaX(1) are:
C     1 refers to current image
C     2 refers to previous image
C     3 refers to image before that and so on
C     
C     Array DR (contains shifts)
C     1               PsiY(1)
C     2               PsiZ(1)    Missetting angles
C     3               Cell_1
C     4               Cell_2     These are the REFINED cell parameters
C     .                 .           (edges and angles)
C     .                 .
C     .                 .
C     NC+2            Cell_NC
C     NC+2+1          PsiY(2)
C     NC+2+2          PsiZ(2)
C     NC+2+3          PsiY(3)
C     NC+2+4          PsiZ(3)         
C     NC+2+5          PsiY(4)
C     NC+2+6          PsiZ(4)
C     .
C     .
C     .
C     NC+(NADD-1)*2+1 PsiY(NADD)
C     NC+(NADD-1)*2+2 PsiZ(NADD)
C     Optional
C     NC+NADD*2+1     DIVH or EPS
C     NC+NADD*2+2     DIVV
C     ..
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
