     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
      SAVE
C     .. Equivalences ..
      EQUIVALENCE (PARM(1),PHIX), (PARM(2),PHIY), (PARM(3),PHIZ)
      EQUIVALENCE (PARM(4),CELLX(1))
      EQUIVALENCE (PSI(1),PSIX), (PSI(2),PSIY), (PSI(3),PSIZ)
C     ..
C     
C 
C     .. initialize histogram of partialities
      DO 1789 I = 1,21
        NPARTIA(I) = 0
 1789 ENDDO
      ISTAT = 0
      NDBG = 0
C     
      LAST = .FALSE.
C     
      NP = NC + 2
      NPSTOR = NP           
      IF (IC.EQ.1) NP = 2
      IF (NOREFCELL) NP = 2
      NPP = NP + 1
C     
      IF (DEBUG(40)) THEN
        WRITE(IOUT,FMT=6040) NPOINT,IC,NC,NP,NADD,NIMAG,
     +                       (PHIIM(I),I=1,NIMAG)
        IF (ONLINE) WRITE(ITOUT,FMT=6040) NPOINT,IC,NC,NP,NADD, 
     +                   NIMAG,(PHIIM(I),I=1,NIMAG)
      END IF
 6040 FORMAT(/,1X,'IN REFRT1',/,1X,'NPOINT=',I5,' IC=',I2,' NC=',I2,
     +       ' NP=',I3,' NADD=',I3,' NIMAG=',I3,
     +       /,1X,'Phi values for NIMAG images',/,(1X,8F10.2))
C     
C     
C---- Start cycle
C     
      IF (IPRINT.GT.0 .OR. IC.EQ.ICMAX) THEN
         WRITE (IOUT,FMT=6000) IC
         IF (ONLINE) WRITE (ITOUT,FMT=6000) IC
      END IF
C     
      NCYC = 0
 30   CONTINUE
      NCYC = NCYC + 1
C     
C---- NPS is maximum number of parameters
C     
      NPS = NP + NS + 2*(NADD-1)
      IJ = 0
C     
C     
      DO 50 I = 1,NPS
         S(I) = 0.0
         DO 40 J = 1,NPS
            IJ = IJ + 1
            Q(IJ) = 0.0
            FILTER(IJ) = 0.0
            INVFILTER(IJ) = 0.0
 40      CONTINUE
 50   CONTINUE
C     
C---- Set up matrices
C     
      DO 70 I = 1,3
         DO 60 J = 1,3
            AMAT(J,I) = 0.0
            DO 58 K=1,6
               DUBDCC(J,I,K) = 0.0
 58         CONTINUE
 60      CONTINUE
 70   CONTINUE
C     
c      WRITE(iout,*),'CALLING MATSET, CELLX',CELLX
c      WRITE(iout,*),'NCYC,NPS,NP,NS,NPP',NCYC,NPS,NP,NS,NPP
c      WRITE(iout,*),'PHIX,Y,Z',PHIX,PHIY,PHIZ,PHIP
C     
C---- Calculate A matrix and derivatives wrt cell parameters.
C     
C     **********************
      CALL MATSET(CELLX,NC,IPRINT)
C     **********************
C     
      SIGRSQ = 0.0
      NANG = 0
C     
C     
      IF (IPRINT.GT.0 .OR. LAST) THEN
         WRITE (IOUT,FMT=6002) ANGLIM
         IF (ONLINE) WRITE (ITOUT,FMT=6002) ANGLIM
      END IF
C     
C     
      IF (IPRINT.GT.0) THEN
         WRITE (IOUT,FMT=6004)
         IF (ONLINE) WRITE (ITOUT,FMT=6004)
      END IF
C     
      KREJ = 0
      PHIOLD = 99999.0
      NRREF = 0
C     
C---- Loop over each reflection
C 
         IF(DEBUG(37).AND.DEBUG(40))THEN
            IF(ONLINE)WRITE(ITOUT,FMT=1341)NADD
            WRITE(IOUT,FMT=1341)NADD
 1341       FORMAT(/,'Reflections used in this round of refinement ',
     $           'with NADD(local) = ',I2)
         ENDIF

      DO 130 KP = 1,MREF
C     
C---- If only one image, set pointer to first reflection to be used. Jump
C     out of loop if this is past the end of the array
         IF (NADD.EQ.1) THEN
            K = KP + NPOINT -1
         ELSE
            K = KP
         END IF
         IF (NEWPREF) K = KP + NPOINT - 1
C
         IF (K.GT.MREF) GOTO 135
C         IF (K.GT.MREF/NADD) GOTO 135
C     
C---- Skip if no reflection stored
C     
         IF (F(K).LT.0.001) GOTO 130
c
c--- reject reflections with large offset (rolling shutter mode)
c    comment out for now
cal         IF (PHIOFF(K).GT.0.34) GOTO 130
C     
         NRREF = NRREF + 1
         PHIP = PHI(K)
         IF (ABS(PHIP-PHIOLD).GT.0.001) THEN
C     
C---- First reflection from a new image, extract missets convert to
C     PSI values and get sin/cos
C     
c            PHIOLD = PHIP
            NEWPHI = .TRUE.
            NDBG = 0
C     
C---- Which image is this set of reflections from ?
C     When NADD is one, assign all reflections to current image
C     
C
            NSEARCH = NADD
            IF (NEWPREF) NSEARCH = NIMAG
            DO 74 I = 1,NSEARCH
               IF (ABS(PHIP-PHIIM(I)).LT.0.005) THEN
                 NNPHI = I
C
C---- in new style post-refinement, get the pointer to the parameter
C     set number for this image from IPARPOINT (set up in POSTREFL)
C
                 IF (NEWPREF) NNPHI = IPARPOINT(NNPHI)
C
C---- Must trap reflections from images that are NOT to be used, eg
C     for the first image of a new segment where there are not yet
C     enough reflections for missets to be refined.
C
                 IF (NNPHI.LT.0) THEN
                   IF (DEBUG(40)) THEN
                     WRITE(IOUT,FMT=6080) I                   
                     IF (ONLINE) WRITE(ITOUT,FMT=6080) I
6080                FORMAT(1X,'Rejecting reflection on image',I3)
                   END IF
                   GOTO 130
                 END IF
                 GOTO 76
               END IF
 74         CONTINUE
            IF(NSEARCH.LE.10)THEN
              WRITE(IOUT,FMT=6050) PHIP,NSEARCH,(PHIIM(I),I=1,NSEARCH)
              IF (ONLINE) WRITE(ITOUT,FMT=6050) PHIP,
     +             NSEARCH,(PHIIM(I),I=1,NSEARCH)
 6050         FORMAT(//1X,'**** WARNING ****',/,1X,' In REFRT1, no p',
     +             'ack has the phi value (',F9.4,') of this reflection',
     +             /,1X,'NSEARCH = ',I3,'  phiim values:',10F9.4)
            ELSE
              WRITE(IOUT,FMT=6050) PHIP,NSEARCH,(PHIIM(I),I=1,10)
              IF (ONLINE) WRITE(ITOUT,FMT=6050) PHIP,
     +             NSEARCH,(PHIIM(I),I=1,10)
              NSEARCH10 = (NSEARCH/10) + 1
 6500         FORMAT(16X,10F9.4)
              DO 8000 I=1,NSEARCH10
                WRITE(IOUT,FMT=6500)(PHIIM(I),J=(10*I)+1,(11*I))
                IF(ONLINE)WRITE(ITOUT,FMT=6500)(PHIIM(I),
     $               J=(10*I)+1,(11*I))
 8000         ENDDO
            ENDIF  
C
C---- If in POSTREF SEG mode, and NIMAG<NADD (ie not on last image)
C     then only missets are being refined
            goto 130
C
c            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
C     
C---- Get pointer for phi values within array PARM
C     
 76         IF (NNPHI.EQ.1) THEN 
               PHIXX = PHIX
               PHIYY = PHIY
               PHIZZ = PHIZ
            ELSE            
               IPT = NC + (NNPHI-1)*3
               PHIXX = PARM(IPT+1)
               PHIYY = PARM(IPT+2)
               PHIZZ = PARM(IPT+3)
            END IF
chrp07.04.2014            NRREF = NRREF + 1
            PHIPAR(NNPHI) = PHIP
            IF (DEBUG(40)) THEN
               WRITE(IOUT,FMT=6052) K,NRREF,IH(K),IK(K),IL(K),PHIP,
     $             NNPHI,IPT,PHIXX,PHIYY,PHIZZ
               IF (ONLINE) WRITE(ITOUT,FMT=6052) K,NRREF,IH(K),IK(K),
     +              IL(K),PHIP,NNPHI,IPT,PHIXX,PHIYY,PHIZZ
 6052          FORMAT(1X,'Reflection',I5,I4,': HKL = ',3I4,
     $              ' phi value',
     +              F6.1,' Image no',I3,' Pointer IPT',I3,'   missets',
     +              3F8.2)
            END IF
            CPX = COS(DTOR*PHIXX)
            SPX = SIN(DTOR*PHIXX)
            CPY = COS(DTOR*PHIYY)
            SPY = SIN(DTOR*PHIYY)
            CPZ = COS(DTOR*PHIZZ)
            SPZ = SIN(DTOR*PHIZZ)
            CAVP = COS(DTOR*PHIP)
            SAVP = SIN(DTOR*PHIP)
C     
C---- Convert PHIXX,PHIYY,PHIZZ to PSI values
C     
C     ***********************************************************
            CALL PHTOPS(CPX,SPX,CPY,SPY,CPZ,SPZ,CAVP,SAVP,
     $           PSI(1+(NNPHI-1)*3))
C     ***********************************************************
C     
C---- For first cycle correct PSIX by change in CCOMEG calculated
C     from refinement and reset CCOM.
C     If there is more than one image in a virtual batch, must ensure
C     that this is done for all 
C     WRITE(6,*),'PSIX,Y,Z',PSIX,PSIY,PSIZ,PHIP
CAL            IF ((IC.EQ.1).AND.(NNPHI.EQ.1).AND.(.NOT.RESETCCOM)) THEN
            IF ((IC.EQ.1).AND.(NNPHI.EQ.1).AND.(NCYC.EQ.1)) THEN
              IF (RESETCCOM) THEN
                PSIXX = PSI(1) + DPSIX
                PSI(1) = PSIXX
                IF (DEBUG(40)) THEN
                  WRITE(IOUT,FMT=6102) DPSIX, PHIP
                  IF (ONLINE) WRITE(ITOUT,FMT=6102)DPSIX,PHIP
 6102             FORMAT(/,1X,'PSIX changed by',F8.3,
     +                   ' CCOMEGA not reset, phi is',F8.3)
                END IF
              ELSE
                RESETCCOM = .TRUE.
                OMEGA0 = ATAN2(SINOM0,COSOM0)
                CCOM = (OMEGA0-OMEGAF)*57.296
                DPSIX = CCOM - TRUECCOM
                OMEGA0 = OMEGAF
                SINOM0 = SIN(OMEGA0)
                COSOM0 = COS(OMEGA0)
                CCOM = TRUECCOM
CAL              PSIXX = PSIXX + DPSIX
                PSIXX = PSI(1) + DPSIX
                PSI(1) = PSIXX
                IF (DEBUG(40)) THEN
                  WRITE(IOUT,FMT=6100) DPSIX, TRUECCOM, NNPHI,PHIP
                  IF (ONLINE) WRITE(ITOUT,FMT=6100)DPSIX,TRUECCOM,
     +                    NNPHI,PHIP
 6100           FORMAT(/,1X,'PSIX changed by',F8.3,' and CCOMEGA',
     +           ' reset to',F8.3,'  for nnphi=',I2,'  phip=',F8.3)
                END IF
              END IF
            ELSE
              PSIXX = PSI(1+(NNPHI-1)*3)
            END IF
            PSIYY = PSI(2+(NNPHI-1)*3)
            PSIZZ = PSI(3+(NNPHI-1)*3)
            CFX = COS(DTOR*PSIXX)
            SFX = SIN(DTOR*PSIXX)
            CFY = COS(DTOR*PSIYY)
            SFY = SIN(DTOR*PSIYY)
            CFZ = COS(DTOR*PSIZZ)
            SFZ = SIN(DTOR*PSIZZ)
C     
C---- End of block for new image
C     
            PHIOLD = PHIP
         END IF
C
         IF(DEBUG(37).AND.DEBUG(40)) THEN
            NDBG = NDBG + 1
            IF (NDBG.LT.NDEBUG(40)) THEN
              IF(ONLINE)WRITE(ITOUT,FMT=1342)K,IH(K),IK(K),IL(K),
     $           F(K),PHI(K),PHIOFF(K),WW(K),NNPHI
              WRITE(IOUT,FMT=1342)K,IH(K),IK(K),IL(K),F(K),
     $           PHI(K),PHIOFF(K),WW(K),NNPHI
 1342       FORMAT('K = ',I5,', HKL = ',3I4,', Frac = ',F5.2,
     $           ' PHI = ',F7.2,', phioff',F7.2,', WW = ',F6.2,
     +           ' Parameter:',I3)
           ENDIF
         ENDIF
         IF(DEBUG(40).AND.DEBUG(77))THEN
           I = INT(20.*F(K))
           NPARTIA(I) = NPARTIA(I) + 1
         ENDIF
C     
C---- Zero out derivatives (assume 2 beam parameters)
C     
chrp07.04.2014         NRREF = NRREF + 1
         NTOTVAR = 2*NADD+NC+2
         DO 78 I = 1,NTOTVAR
            DR(I) = 0.0
 78      CONTINUE
         CP = COS(DTOR*PHIP)
         SP = SIN(DTOR*PHIP)
C
C---- The following two lines attempt to correct for the coordinate dependence
C     of PHISTART for rolling shutter mode operation, but this does not
C     work at present, so comment out.
C
CAL         CP = COS(DTOR*(PHIP+PHIOFF(K)))
CAL         SP = SIN(DTOR*(PHIP+PHIOFF(K)))
CAL        WRITE(6,*),'REFL,PHIP,phioff',K,PHIP,phioff(k)
C     
C---- Loop over each parameter. Note that I=1 is used to set things up
C     there is no actual parameter  for I=1. NPP = NC + 2 + 1 where NC is the
C     number of refined cell parameters, 2 is for PSIY,PSIZ and 1 is for
C     the setting up.
C     
         DO 90 I = 1,NPP
C     
C     *********
            CALL CLEAR(P)
            CALL CLEAR(CX)
            CALL CLEAR(CY)
            CALL CLEAR(CZ)
C     *********
C     
C---- Set up rotation matrices
C     
            CX(1,1) = 1.0
            CX(2,2) = CFX
            CX(2,3) = -SFX
            CX(3,2) = SFX
            CX(3,3) = CFX
            CY(1,1) = CFY
            CY(1,3) = SFY
            CY(2,2) = 1.0
            CY(3,1) = -SFY
            CY(3,3) = CFY
            CZ(1,1) = CFZ
            CZ(2,1) = SFZ
            CZ(1,2) = -SFZ
            CZ(2,2) = CFZ
            CZ(3,3) = 1.0
            P(1,1) = CP
            P(2,1) = SP
            P(1,2) = -SP
            P(2,2) = CP
            P(3,3) = 1.00
            IM = I
            IF (I.LE.3) IM = 1
C     
C     
            IF (I.EQ.3) THEN
C     
C     *********
               CALL CLEAR(CZ)
C     *********
C     
               CZ(1,1) = -SFZ
               CZ(2,1) = CFZ
               CZ(1,2) = -CFZ
               CZ(2,2) = -SFZ
            ELSE IF (I.EQ.2) THEN
C     
C---- Set up derivatives
C     
C     *********
               CALL CLEAR(CY)
C     *********
C     
               CY(1,1) = -SFY
               CY(1,3) = CFY
               CY(3,1) = -CFY
               CY(3,3) = -SFY
            END IF
C     
C     ****************
            CALL MATMUL3(PC,CX,P)
            CALL MATMUL3(C,CY,PC)
            CALL MATMUL3(PC,CZ,C)
C     ****************
C     
            IF (IM.GE.4) IM = IM - 2
C     
            IF (IM.EQ.1) THEN
C     ************************
               CALL MATMUL3(PCA,PC,AMAT(1,1))
C     ************************
            ELSE
C     ************************
               CALL MATMUL3(PCA,PC,DUBDCC(1,1,IM-1))
C     ************************
            END IF
C     
            DO 80 J = 1,3
               X(J) = PCA(J,1)*IH(K) + PCA(J,2)*IK(K) + PCA(J,3)*IL(K)
 80         CONTINUE
C     
            IF (I.NE.1) THEN
C     
C---- Deriv of rc w.r. to relevant ptr. The pointer calculation is complex.
C     The parameters are:
C     PSIY(1), PSIZ(1), REFINED CELL PARAMETERS, PSIY(2), PSIZ(2), PSIY(3),
C     PSIZ(3) .... PSIY(NADD), PSIZ(NADD), DIVH/EPS, DIVV
C     
C     Where (1) is the current image, (2) is the previous image, (3) is the
C     image before that etc.
C     All reflections contribute to derivatives wrt cell parameters and beam
C     parameters, but then only to the orientation parameters for that image.
C     
               NPLUS = 0
               IF ((I.LE.3).AND.(NNPHI.NE.1)) NPLUS = (NPP-1) +
     +                                                (NNPHI-2)*2
C     
               IF ((DEBUG(40).AND.NEWPHI).AND.(NDBG.LT.NDEBUG(40)))
     +                                                       THEN
                  WRITE(IOUT,FMT=6058) K,I,I-1+NPLUS,PHIP
                  IF (ONLINE) WRITE(ITOUT,FMT=6058) K,I,I-1+NPLUS,PHIP
 6058             FORMAT(1X,'Reflection ',I4,' Parameter ',I2,
     +                 ' Pointer ',I3,'  This phi ',F8.1)
               END IF
C     AL Re-write next two lines to clarify code
C     AL            DR(I-1+NPLUS) = (X(1)*XX+X(1)+X(2)*YY+X(3)*ZZ)/
C     AL     +                                           (RC)/DST*WW(K)
C     
               DR(I-1+NPLUS) = (X(1)*XX+X(1)+X(2)*YY+X(3)*ZZ)/
     +              (RC*DST)
            ELSE
               XX = X(1)
               YY = X(2)
               ZZ = X(3)
               XSQ = XX*XX
               YSQ = YY*YY
               ZSQ = ZZ*ZZ
               DSTSQ = XSQ + YSQ + ZSQ
               STEMP = 1.0 - DSTSQ*0.25
               IF (STEMP.LT.0.0) WRITE(6,8888) STEMP
 8888          FORMAT(' COSTH FROM REFRT1 = ',F20.10)
               COSTH = SQRT(STEMP)
               STEMP = DSTSQ
               IF (STEMP.LT.0.0) WRITE(6,8889) STEMP
 8889          FORMAT(' DST FROM REFRT1 = ',F20.10)
               DST = SQRT(STEMP)
C     
C---- Note change in next lines. If refining one beam parameter, then
C     it should be the mosaic spread, if two, then it is the beam
C     divergences. This does NOT depend on whether or not the data is from
C     a synchrotron.
C     
               IF  (NS.EQ.1) THEN
                  PARM(NC+NADD*3+1) = ETA
               ELSE IF (NS.EQ.2) THEN
                  PARM(NC+NADD*3+1)  = DIVH
                  PARM(NC+NADD*3+2) = DIVV
               END IF
               EH = DIVH*ZZ
               EV = DIVV*YY
C     
C---- Include the beam-divergence contribution from DELCOR
C     
               EH = EH + DELCOR*DSTSQ
               STEMP = (EH*EH + EV*EV)/ (YSQ + ZSQ)
               IF (STEMP.LT.0.0) WRITE(6,8887) STEMP
 8887          FORMAT(' DIVERG FROM REFRT1 = ',F20.10)
               DIVERG = SQRT(STEMP)
C     
               TWOEPS = ((DIVERG+ETA)*COSTH+DELAMB*DST*0.5)*DST
C     
C---- Calculate radius of point H,K,L from centre of sphere
C     
               STEMP = 2.0*XX + 1.0 + DSTSQ
               IF (STEMP.LT.0.0) WRITE(6,8855) STEMP
 8855          FORMAT(' RC FROM REFRT1 = ',F20.10)
               RC = SQRT(STEMP)
C     
C---- Correct for fraction recorded of spot
C     -ve frac denotes phi-start, +ve phi-end.
C     After making all fracs +ve, obsd radius of
C     refln (sphere-origin) is 1-(.5-f)*eps*2 for y-ve phi-end
C     or y+ve phi-start;  or 1+(.5+f)*eps*2 for the other
C     situations.
C     
               IF (YY.LT.0.0) THEN
                  IF (F(K).LT.0.0) THEN
                     AM = -F(K)
                  ELSE
                     AM = 1.0 - F(K)
                  END IF
               ELSE IF (F(K).LT.0.0) THEN
                  AM = F(K) + 1.0
               ELSE
                  AM = F(K)
               END IF
C     
C---- Observed radius set to 1.0 for extra ref
C     put eps term in rc, assume d(rc)/dx remains the same
C     
               FM = 1.0 - 2.0*AM
               IF (ABS(FM).GT.1.0) FM = SIGN(1.0,FM)
               RO = 1.0
               RC = RC - ASIN(FM)*TWOEPS/PI
C     
C     
               DANG(K) = (RO-RC)/DST
               ANG = DANG(K)*RTOD
c
               IF (DEBUG(40)) THEN
                  WRITE(IOUT,FMT=6110) K,IH(K),IK(K),IL(K),
     $           F(K),PHI(K),PHIOFF(K),ANG
 6110             FORMAT('K = ',I5,', HKL = ',3I4,', Frac = ',F5.2,
     $           ' PHI = ',F7.2,', phioff',F7.2,', residual',F7.2)
               END IF
c
               IF (ABS(ANG).LT.ANGLIM) THEN
                  NANG = NANG + 1
                  SIGRSQ = DANG(K)*DANG(K) + SIGRSQ
               ELSE
                  GO TO 120
               END IF
            END IF
 90      CONTINUE
C     
C---- Form least squares matrix
C     
C---- Extra ref only on second pass (ic>1)
C     set np to nnp for ref
C     
         NNP = NP + 2*(NADD-1)
         IF (IC.GT.1 .AND. NS.GT.0) THEN
            NNP = NP + NS + 2*(NADD-1)
C     
C---- Derivs for eta and divergence
C     
            TERM = -ASIN(FM)/PI
C     
C---- eta or DIVH = DIVV
C     
C     AL          DR(NP+1+2*(NADD-1)) = TERM*COSTH*WW(K)
c            IF(DEBUG(40))THEN
c              IF(ONLINE)WRITE(ITOUT,6038)IH(K),IK(K),IL(K),term*costh
c              WRITE(IOUT,6038)IH(K),IK(K),IL(K),term*costh
c            ENDIF
            DR(NP+1+2*(NADD-1)) = TERM*COSTH
C     WRITE(6,*),'NS,DR(NP+1)',NS,DR(NP+1)
C     
C---- DIVH and DIVV
C     sqrt(GH*GH*cos*cos + GV*GV*sin*sin)d*costh where
C     alpha = tan-1 yy/zz
C     
            IF (NS.EQ.2) THEN
C     AL            DR(NP+1+2*(NADD-1)) = 
C     AL     +                  TERM*COSTH*DIVH*ZSQ/ (YSQ+ZSQ)/DIVERG*WW(K)
C     AL            DR(NP+2+2*(NADD-1)) = 
C     AL     +                  TERM*COSTH*DIVV*YSQ/ (YSQ+ZSQ)/DIVERG*WW(K)
               DR(NP+1+2*(NADD-1)) = 
     +              TERM*COSTH*DIVH*ZSQ/ (YSQ+ZSQ)/DIVERG
               DR(NP+2+2*(NADD-1)) = 
     +              TERM*COSTH*DIVV*YSQ/ (YSQ+ZSQ)/DIVERG
            END IF
            IF (DEBUG(40).AND.(K.LE.2).AND.(NCYC.EQ.1)) THEN
               WRITE(IOUT,FMT=6064) K,NS,NP+1+2*(NADD-1)
               IF (ONLINE) WRITE(ITOUT,FMT=6064) K,NS,NP+1+2*(NADD-1)
 6064          FORMAT(1X,'Reflection',I2,'; ',I4,' beam parameters ',
     +              'derivs stored starting at position',I3)
            END IF
         END IF
C     
C---- Increment elements of normal matrix. Note that for any given
C     reflection many elements of DR (psiy,psiz for all other images)
C     will be zero
C     
         DO 110 I = 1,NNP
           S(I) = DANG(K)*DR(I)*WW(K) + S(I)
           DO 100 J = 1,NNP
             IJ = (I-1)*NNP + J
             Q(IJ) = WW(K)*DR(I)*DR(J) + Q(IJ)
             FILTER(IJ) = 0.0
 100       ENDDO
 110     ENDDO
         NEWPHI = .FALSE.
         GO TO 130
C     
 120     CONTINUE
         IF (IPRINT.GT.0) THEN
            WRITE (IOUT,FMT=6006) IH(K),IK(K),IL(K),ANG
            IF (ONLINE) WRITE (ITOUT,FMT=6006) IH(K),IK(K),IL(K),ANG
         END IF
C     
         KREJ = KREJ + 1
 130  CONTINUE
C
C---- Had to move 135 continue here, previously was after rescaling
C     of normal matrix which gave problems with multiseg post refinement
C     AGWL 21 Feb 2012
C
 135  CONTINUE
      IF(RESCALE)THEN
C     ..
C     .. set up rescaling matrices for filtering eigenvalues
        DO 133 I=1,NNP
          IJ = (I-1)*NNP + I
          IF(Q(IJ).GT.0.0)FILTER(IJ) = 1.0/SQRT(Q(IJ))
 133    ENDDO
C     ..
C     .. re-scale normal matrix
        CALL MATMULSQ(FWORK,Q,FILTER,NNP)
        CALL MATMULSQ(Q,FILTER,FWORK,NNP)
      ENDIF
      IF (DEBUG(40)) THEN
        WRITE(IOUT,FMT=6074) NRREF
        IF (ONLINE) WRITE(ITOUT,FMT=6074) NRREF
 6074   FORMAT(1X,'Number of reflections used in REFRT1',I5)
      END IF
      IF(DEBUG(40).AND.DEBUG(77))THEN
        WRITE(IOUT,FMT=6090)(FLOAT(I)*0.05-0.05,I=1,21),
     $       (NPARTIA(I),I=1,21)
        IF(ONLINE)WRITE(ITOUT,FMT=6090)(FLOAT(I)*0.05,I=1,21),
     $       (NPARTIA(I),I=1,21)
 6090   FORMAT(/,'**** DEBUG STATS **** ',/,
     $       ' Histogram of fractions of reflections used',/,
     $       ' Fraction ',21(1X,F4.2),/,' Count ',3X,21(1X,I4))
      ENDIF
      IF (DEBUG(40).AND.(NCYC.EQ.1)) THEN

C     
C---- Check no.of observations
C     
        if(online)write(iout,fmt=6038)NANG,NNP
        write(itout,fmt=6038)NANG,NNP
      END IF
C
      IF (NANG.LE.NNP) THEN
         GO TO 230
      ELSE
C     
C---- Invert Normal matrix (Q) and obtain eigenvalues - new code
C    
         CALL INVNOR(Q,NNP,QINV)
C     ..
         IF(RESCALE)THEN
C     ..
C     .. apply scaling to inverse normal matrix
           CALL MATMULSQ(FWORK,QINV,FILTER,NNP)
           CALL MATMULSQ(QINV,FILTER,FWORK,NNP)
         ENDIF
C     
C
C---- Solve least squares equations
C
C            ***************************
c         CALL MINV(Q,NNP,DET,IWRK1,IWRK2)
C            ***************************
C     
         IF (DEBUG(40)) THEN
           NPERLINE = 8
           IST = 1 - NPERLINE
           NBLOCKS = NNP/NPERLINE+1
           IF (MOD(NNP,NPERLINE).EQ.0) NBLOCKS = NBLOCKS - 1
           DO 137 NBLK = 1,NBLOCKS
             IST = IST + NPERLINE
             IEND = MIN(IST+NPERLINE-1,NNP)
             WRITE(IOUT,FMT=6070) IST,IEND,(I,I=IST,IEND)
             IF (ONLINE) WRITE(ITOUT,FMT=6070) IST,IEND,(I,I=IST,IEND)
 6070        FORMAT(/,1X,'Normal matrix elements',I3,' to',I3,
     +              /,3X,8(I10,1X))
             DO 138 NROW = 1,NNP
               IST2 = (NBLK-1)*NPERLINE + (NROW-1)*NNP + 1
               IEND2 = MIN(IST2+NPERLINE-1,NNP*NROW)
               WRITE(IOUT,FMT=6072) NROW,(Q(I),I=IST2,IEND2)
               IF (ONLINE) WRITE(ITOUT,FMT=6072)NROW,(Q(I),I=IST2,IEND2)
 6072          FORMAT(1X,I3,2X,8(E10.3,1X))
 138         CONTINUE
 137      CONTINUE

CAL            WRITE(IOUT,FMT=6055) (Q(ij),ij=1,nnp*nnp)
CAL            IF (ONLINE) WRITE(ITOUT,FMT=6055) 
CAL     $           (Q(ij),ij=1,nnp*nnp)
         ENDIF
C
c         IF (DET.EQ.0.0) THEN
c           GO TO 220
c         ELSE
         IJ = 0
         DO 150 I = 1,NNP
            R(I) = 0
            DO 140 J = 1,NNP
               IJ = IJ + 1
               R(I) = Qinv(IJ)*S(J) + R(I)
 140        CONTINUE
 150     CONTINUE
C     
C     IF (DEBUG(40).AND.(NCYC.EQ.1)) THEN
         IF (DEBUG(40)) THEN
            WRITE(IOUT,FMT=6060) (R(I),I=1,NNP)
            IF (ONLINE) WRITE(ITOUT,FMT=6060) (R(I),I=1,NNP)
 6060       FORMAT(/1X,'SHIFT VECTOR',/,(1X,8(E10.3,1X)))
            WRITE(IOUT,FMT=6062) (S(I),I=1,NNP)
            IF (ONLINE) WRITE(ITOUT,FMT=6062) (S(I),I=1,NNP)
 6062       FORMAT(/1X,'RHS VECTOR',/,(1X,8(E10.3,1X)))
         END IF
C     ..
C     .. NS is number of ETA parameters, i.e. mosaic spread or divergence.
C     .. scale of shifts for ETA seems to be very different to the other scales.
c         if(ic.gt.1.and.ns.gt.0)then
c           rtemp = 0.0
c           do i = 1,nnp-ns
c               rtemp = max(abs(r(i)),rtemp)
c             if (ns.eq.1)then
c             elseif(ns.eq.2)then
c             endif
c           enddo
c         endif
c           
c         IF (DEBUG(40)) THEN
c 6061      FORMAT(/1X,'NS = ',I1,', NC = ',I3,', NADD = ',I3,
c     $          /1X,'Shift VECTOR',/,(1X,8(E10.3,1X)))
c            WRITE(IOUT,FMT=6061) NS,NC,NADD,(R(I),I=1,NNP)
c            IF (ONLINE) WRITE(ITOUT,FMT=6061) NS,NC,NADD,(R(I),I=1,NNP)
c          endif
C     
         JJ = 1 
C     
C---- Reset angle limit to 3*RMS deviation
C     
         STEMP = SIGRSQ/REAL(NANG)
         IF (STEMP.LT.0.0) THEN
            WRITE(IOUT,FMT=6009) SIGRSQ,NANG
            IF (ONLINE) WRITE(ITOUT,FMT=6009)  SIGRSQ,NANG
C     WRITE(6,8844) STEMP
            GOTO 235
         END IF
C     IF (STEMP.LT.0.0) WRITE(6,8877) STEMP
 8877    FORMAT(' RMSR FROM REFRT1 = ',F20.10)
         RMSR = SQRT(STEMP)
         RMSR = RMSR*RTOD
         IF (3.0*RMSR.LT.ANGLIM) ANGLIM = 3.0*RMSR
CAL         if(online)write(itout,*)'anglim has been set to ',anglim,
CAL     $        ' RMSR = ',RMSR
CAL         write(iout,*)'anglim has been set to ',anglim,
CAL     $        ' RMSR = ',RMSR
C     
C---- Calculate standard deviations
C     
         DO 160 J = 1,NNP
            STEMP = Qinv(JJ)*SIGRSQ/ (NANG - NNP)
            IF (STEMP.LT.0.0) THEN
               WRITE(IOUT,FMT=6007) J,Qinv(JJ),SIGRSQ,NANG,NNP
               IF (ONLINE) WRITE(ITOUT,FMT=6007)J,Qinv(JJ),SIGRSQ,
     $              NANG,NNP
C     WRITE(6,8844) STEMP
               GOTO 235
 8844          FORMAT(' SIG(J) FROM REFRT1 = ',F20.10)
            END IF
            SIG(J) = SQRT(STEMP)
            JJ = JJ + NNP + 1
 160     CONTINUE
C     
C     
         IF (LAST .OR. IPRINT.GT.0) THEN
            WRITE (IOUT,FMT=6012) KREJ
            IF (ONLINE) WRITE (ITOUT,FMT=6012) KREJ
            IF (BRIEF) WRITE (IBRIEF,FMT=6012) KREJ
            WRITE (IOUT,FMT=6014) SIGRSQ,RMSR
            IF (ONLINE) WRITE (ITOUT,FMT=6014) SIGRSQ,RMSR
            IF (BRIEF) WRITE (IBRIEF,FMT=6015) RMSR
         END IF
C     
C---- Convert angle parameters to degrees
C     
         DO 170 I = 1,NP+2*(NADD-1)
            IF ((I.LE.2) .OR. I.GT. (2+(NP-2)-NA)) THEN
               R(I) = R(I)*RTOD
               SIG(I) = SIG(I)*RTOD
            END IF
 170     CONTINUE
C     
C---- First do phi + cell only
C     
         JJ = NC + 3
C     
C     
         IF (LAST .OR. IPRINT.GT.0) THEN
            WRITE (IOUT,FMT=6016) PSIX,PSIY,PSIZ, (PARM(I),I=4,JJ)
            IF (ONLINE) WRITE (ITOUT,FMT=6016) PSIX,PSIY,PSIZ,
     +           (PARM(I),I=4,JJ)
            WRITE (IOUT,FMT=6018) (R(I),I=1,NP)
            IF (ONLINE) WRITE (ITOUT,FMT=6018) (R(I),I=1,NP)
         END IF
C     
C---- Add parameter shifts for psi angles of image 1 (current image)
C     and cell parameters only. Do other angles below.
C     
         DO 180 I = 1,NP
C     
C     
            IF (I.GT.2) THEN
               J = I + 1
               PARM(J) = PARM(J) + R(I)
            ELSE
               PSI(I+1) = PSI(I+1) + R(I)
            END IF
 180     CONTINUE
C     
C     **********************************************
         CALL PSTOPH(PSIX,PSIY,PSIZ,PHIX,PHIY,PHIZ,PHIIM(1))
C     **********************************************
C     
         IF (DEBUG(40)) THEN
            I = 1
            WRITE(IOUT,FMT=6056) I,PSIX,PSIY,PSIZ,
     +           PHIX,PHIY,PHIZ,PHIIM(I)
            IF (ONLINE) WRITE(ITOUT,FMT=6056) I,PSIX,PSIY,PSIZ,
     +           PHIX,PHIY,PHIZ,PHIIM(I)
         END IF
C     
         IF (LAST .OR. IPRINT.GT.0) THEN
            WRITE (IOUT,FMT=6020) PSIX,PSIY,PSIZ, (CELLX(I),I=1,NC)
            IF (ONLINE) WRITE (ITOUT,FMT=6020) PSIX,PSIY,PSIZ,
     +           (CELLX(I),I=1,NC)
            WRITE (IOUT,FMT=6022) (SIG(J),J=1,NP)
            IF (ONLINE) WRITE (ITOUT,FMT=6022) (SIG(J),J=1,NP)
         END IF
C     
C---- Add in angle shifts for other images (if any)
C     
         IF (NADD.GT.1) THEN
            DO 182 I=2,NADD
               DO 184 K=2,3
                  PSI(K+(I-1)*3) = PSI(K+(I-1)*3) + R(NP +(I-2)*2 
     $                 +(K-1))
 184           CONTINUE
               PSIXX = PSI(1+(I-1)*3)
               PSIYY = PSI(2+(I-1)*3)
               PSIZZ = PSI(3+(I-1)*3)
C     *********************************************************
               CALL PSTOPH(PSIXX,PSIYY,PSIZZ,PHIXX,PHIYY,PHIZZ,
     $              PHIPAR(I))
CAL     $              PHIIM(I))
C     *********************************************************
C     
C---- Update PHI missets in PARM
C     
               PARM(NC+(I-1)*3+1) = PHIXX
               PARM(NC+(I-1)*3+2) = PHIYY
               PARM(NC+(I-1)*3+3) = PHIZZ
               IF (DEBUG(40)) THEN
                  WRITE(IOUT,FMT=6056) I,PSIXX,PSIYY,PSIZZ,
     +                 PHIXX,PHIYY,PHIZZ,PHIPAR(I)
                  IF (ONLINE) WRITE(ITOUT,FMT=6056) I,PSIXX,PSIYY,
     +                 PSIZZ,PHIXX,PHIYY,PHIZZ,PHIPAR(I)
 6056             FORMAT(1X,'IMAGE ',I7,' New PSI angles',3F10.2,
     +                 ' new phi values',3F10.2,' at phi',F10.2)
               END IF
 182        CONTINUE
         END IF
C     
C---- Extra ref output after second pass
C     
         IF (NS.GT.0 .AND. IC.GT.1) THEN
C     
C---- Write out old params
C     
            IF (LAST .OR. IPRINT.GT.0) THEN
               IF (NS.EQ.1) THEN
                  WRITE (IOUT,FMT=6024)
                  IF (ONLINE) WRITE (ITOUT,FMT=6024)
               ELSE
                  WRITE (IOUT,FMT=6028)
                  IF (ONLINE) WRITE (ITOUT,FMT=6028)
               END IF
               WRITE (IOUT,FMT=6030) (PARM(NC+NADD*3+I)*RTOD,I=1,NS)
               IF (ONLINE) WRITE (ITOUT,FMT=6030)
     +              (PARM(NC+NADD*3+I)*RTOD,I=1,NS)
               WRITE (IOUT,FMT=6032) (R(I)*RTOD,I=NP+(NADD-1)*2+1,
     +              NP+(NADD-1)*2+NS)
               IF (ONLINE) WRITE (ITOUT,FMT=6032)
     +              (R(I)*RTOD,I=NP+(NADD-1)*2+1,
     +              NP+(NADD-1)*2+NS)
            END IF
C     
C---- Add parameter shifts
C     
            DO 190 I = 1,NS
               PARM(I+NC+NADD*3) = PARM(I+NC+NADD*3) 
     $              + R(NP+(NADD-1)*2+I)
 190        CONTINUE
C     
            IF  (NS.EQ.1) THEN
               ETA = PARM(NC+NADD*3+1)
            ELSE IF (NS.EQ.2) THEN
               DIVH = PARM(NC+NADD*3+1)
               DIVV = PARM(NC+NADD*3+2)
            END IF
C     
C---- Now write out new extra params
C     
            IF (LAST .OR. IPRINT.GT.0) THEN
               WRITE (IOUT,FMT=6034) (PARM(I+NC+NADD*3)*RTOD,I=1,NS)
               IF (ONLINE) WRITE (ITOUT,FMT=6034)
     +              (PARM(I+NC+NADD*3)*RTOD,I=1,NS)
               WRITE (IOUT,FMT=6036) (SIG(J)*RTOD,
     +              J=NP+(NADD-1)*2+1,NP+(NADD-1)*2+NS)
               IF (ONLINE) WRITE (ITOUT,FMT=6036)(SIG(J)*RTOD,
     +              J=NP+(NADD-1)*2+1,NP+(NADD-1)*2+NS)
            END IF
         END IF
C     
C---- Here if no extra ref
C     
         IF (LAST) THEN
            GO TO 210
         ELSE
C     
C---- If after first cycle of refinement too many reflections
C     are rejected return to re-index
C     
            IF (HKL .OR. NCYC.LE.1 .OR. KREJ.LE.NR/5) THEN
C     
C---- Maximum of 5 cycles of REFRT1 - return to re-index
C     
               IF (NCYC.NE.3) THEN
C     
C---- Test size of shifts
C     
                  DO 200 I = 1,NNP
                     IF (SIG(I).EQ.0.0)SIG(I)=0.00001
                     IF (ABS(R(I)/SIG(I)).GT.0.1) GO TO 30
 200              CONTINUE
C     
C     
               END IF
            END IF
C     
C---- If last full cycle then repeat refinement printing stats
C     
            IF (IC.EQ.ICMAX) THEN
               LAST = .TRUE.
               GO TO 30
            END IF
         END IF
C      END IF
      END IF
      NP = NPSTOR
      RETURN
C     
C---- Finish, prepare for print
C     First deal with normal params
C     
 210  JJ = NC + 3
      RETURN
c     220 WRITE (IOUT,FMT=6010)
c     IF (ONLINE) WRITE (ITOUT,FMT=6010)
c     GOTO 235
 230  WRITE (IOUT,FMT=6008)NANG,NNP
      IF (ONLINE) WRITE (ITOUT,FMT=6008)NANG,NNP
 235  WRITE (IOUT,FMT=6011)
      IF (ONLINE) WRITE (ITOUT,FMT=6011)
      ISTAT = -1
C     
C---- Format statements
C     
 6000 FORMAT (1X,16 ('+++++'),//10X,'PARAMETER REFINEMENT PASS',I3)
 6002 FORMAT (/' Reflections rejected if angular error >',F6.2,' deg.',
     +     /)
 6004 FORMAT (/7X,'H   K   L   ANGERR(degrees)  ')
 6006 FORMAT (4X,3I4,F7.2)
 6007 FORMAT (/,1X,'*** Ill determined normal matrix ***',/,1X,
     +     'Variable',I3,' Diag element of inverse matrix',E10.3,
     +     /,1X,'SIGRSQ',E10.5,'  NANG',I5,'  NNP',I3)
 6008 FORMAT (/,1X,'***  Fewer data than parameters ***',/,
     $     'NANG = ',I6,' and NNP = ',I6)
 6009 FORMAT (/,1X,'*** Ill determined normal matrix ***',/,1X,
     +     'SIGRSQ',F12.6,'   NANG',I8)
 6010 FORMAT (/,1X,'*** Singular equations ***')
 6011 FORMAT (/,1X,'There are insufficient',
     +     ' data to refine all the parameters sensibly',/,1X,
     +     'This can happen if you are using far too small a value',
     +     ' for the mosaic spread.',/,1X,
     +     'Alternatively if you have only weak low resolution data',
     +     ', cell parameters',/,1X,'may not be well defined even',
     +     ' if you have a large number of reflections.',/,1X,
     +     'This will result in excessive parameter shifts which',
     +     ' will lead to the',/,1X,'rejection of many ',
     +     'reflections.',/,1X,
     +     'If you are using the refined beam parameters (USEBEAM) ',
     +     'first check that the',/,1X,'divergence (or mosaicity) ',
     +     'has not refined to either too large or ',
     +     'too small',/,1X,'a value.',/,1X,
     +     'If not the case try using ',
     +     ' more images by increasing WIDTH or ',/,1X,
     +     'NADD (POSTREF',
     +     ' keyword)',/,1X,'or FIX some or ALL  cell parameters.')
 6012 FORMAT (' Number of reflections rejected: ',I5)
 6014 FORMAT (' Sum of (RO-RC)/D*)**2 = ',F12.8,' Rms Resid = ',F8.3,
     +     ' degrees')
 6015 FORMAT (' Rms Resid = ',F8.3,' degrees')
 6016 FORMAT (/11X,'PSIX      PSIY      PSIZ    Refined reciprocal ce',
     +     'll parameters',/'   Old ',3F10.3,3F10.6,3F10.4)
 6018 FORMAT (' Shifts',10X,2F10.3,3F10.6,3F10.4)
 6020 FORMAT ('   New ',3F10.3,3F10.6,3F10.4)
 6022 FORMAT ('  S.D.',11X,2F10.3,3F10.6,3F10.4)
 6024 FORMAT (/9X,'Mosaic spread')
 6028 FORMAT (/10X,'DIVH     DIVV (Horizontal and vertical beam',
     +     ' divergences)')
 6030 FORMAT ('   Old ',F8.3,1X,F8.3)
 6032 FORMAT (' Shifts',F8.3,1X,F8.3)
 6034 FORMAT ('   New ',F8.3,1X,F8.3)
 6036 FORMAT ('  S.D. ',F8.3,1X,F8.3)
 6038 FORMAT (' Number of reflections passed to REFRT1 (NANG): ',I6,
     $     ', and number of parameters being refined (NNP): ',I3)
CAL 6055 FORMAT(//,1X,'Normal Matrix',/,(1X,8E10.3,/)) 
      END
C== ROTMAT ==
      SUBROUTINE ROTMAT(DELPHI,R,IMODE)
C     ===========================
      IMPLICIT NONE
C
C---- Forms rotation matrix R from the three angles in DELPHI
C     (angles in degrees (IMODE .eq.1) or radians (IMODE .ne. 1), corresponding
C     to
C
C     [R] = [phiz] . [phiy] . [phix]
C
C
C        | cz -sz   0 |   | cy   0  sy |   | 1   0   0 |
C  [R] = | sz  cz   0 | . |  0   1   0 | . | 0  cx -sx |
C        |  0   0   1 |   |-sy   0  cy |   | 0  sx  cx |
C
C     ..
C     .. Array Arguments ..
      REAL DELPHI(3),R(3,3)
C     ..
C     .. Scalar Arguments ..
      INTEGER IMODE
C     ..
C     .. Local Scalars ..
      INTEGER I
C     ..
C     .. Local Arrays ..
      DOUBLE PRECISION C(3),S(3),DELPHID(3)
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC COS,SIN
C     ..
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C
      DO 10 I = 1,3
        DELPHID(I) = DBLE(DELPHI(I))
         IF(IMODE.EQ.1)THEN
            C(I) = COS(DELPHID(I)*DTOR_DOUBLE)
            S(I) = SIN(DELPHID(I)*DTOR_DOUBLE)
         ELSE
            C(I) = COS(DELPHID(I))
            S(I) = SIN(DELPHID(I))
         ENDIF
 10   CONTINUE
C
C
      R(1,1) = REAL(C(2)*C(3))
      R(1,2) = REAL(-C(1)*S(3) + S(1)*S(2)*C(3))
      R(1,3) = REAL(C(1)*S(2)*C(3) + S(1)*S(3))
      R(2,1) = REAL(C(2)*S(3))
      R(2,2) = REAL(S(1)*S(2)*S(3) + C(1)*C(3))
      R(2,3) = REAL(-S(1)*C(3) + C(1)*S(2)*S(3))
      R(3,1) = REAL(-S(2))
      R(3,2) = REAL(S(1)*C(2))
      R(3,3) = REAL(C(1)*C(2))
C
C
      END
C $Id: setdis.f,v 1.11 2007/12/18 14:55:49 harry Exp $
      SUBROUTINE SETDIS(ITILT,ITWIST,IMODE)
      IMPLICIT NONE
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
